#include <stdlib.h>
#include <stdint.h>
#include <limits.h>

typedef struct {
    int value;
} record;

uint64_t xorshift128plus(uint64_t *s) {
    uint64_t x = s[0];
    uint64_t y = s[1];
    s[0] = y ^ (y << 29);
    s[1] = x ^ (x >> 55) ^ y;
    return x + y;
}

record* initialize_records(uint32_t count, int range_min, int range_max, uint64_t seed[2]) {
    if (count == 0 || range_min > range_max) {
        return NULL; // Handle invalid input
    }

    record *records = malloc(count * sizeof(record));
    if (!records) {
        return NULL; // Out of memory
    }

    for (uint32_t i = 0; i < count; ++i) {
        records[i].value = range_min + (xorshift128plus(seed) % (range_max - range_min + 1));
    }

    return records;
}

void free_records(record *records, uint32_t count) {
    if (records) {
        free(records);
    }
}
```

### Explanation:
- **xorshift128plus**: A fast pseudo-random number generator that produces high-quality randomness with good performance. It is suitable for non-cryptographic purposes and can generate numbers uniformly distributed within a specified range.

- **initialize_records**: This function initializes an array of `record` structures. It takes the count of records, the minimum and maximum values for the PRNG, and a seed for the PRNG. If any input is invalid or out of memory, it returns `NULL`.

- **free_records**: A simple function to free the allocated memory for the records.

### Usage:
To use this function, you need to provide the number of records you want to create, the range for the random values, and a seed for the PRNG. The function will return an array of `record` structures filled with pseudo-random numbers within the specified range. Remember to call `free_records` when you are done using the records to avoid memory leaks.

