#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000

// Helper function to find the largest integer in an array
int findLargest(int* arr, int size) {
    if (size <= 0 || arr == NULL) {
        printf("Error: Invalid input for finding largest element.\n");
        return -1; // Assuming -1 as an error value
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function to process input and find the largest integer
void processInput() {
    int* numbers = (int*)malloc(MAX_SIZE * sizeof(int));
    if (numbers == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    int count = 0;
    while (1) {
        int num;
        int result = scanf("%d", &num);
        if (result != 1) {
            break; // End of input or error
        }
        numbers[count++] = num;
        if (count >= MAX_SIZE) {
            printf("Error: Input size exceeds maximum limit.\n");
            break;
        }
    }

    int largestNumber = findLargest(numbers, count);
    if (largestNumber != -1) {
        printf("The largest number is: %d\n", largestNumber);
    }

    free(numbers); // Free allocated memory
}

int main() {
    processInput();
    return 0;
}
