import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Properties;

public class PokemonReportGenerator {

    private static final String CONFIG_FILE = "pokemonTypes.properties";
    private static Properties typeProperties = loadTypeProperties();

    public static String generateReport(Pokemon pokemon) {
        try {
            if (pokemon == null || pokemon.getPokemonName() == null) {
                System.err.println("Error: Pokemon object is null or name is not set.");
                return "Invalid input";
            }

            String type = pokemon.getPokemonType();
            String weaknesses = getPropertiesValue(type + ".weaknesses", "Generic Weakness");
            String resistances = getPropertiesValue(type + ".resistances", "Generic Resistance");

            return createJsonReport(weaknesses, resistances);
        } catch (Exception e) {
            System.err.println("Error generating report: " + e.getMessage());
            return "Error";
        }
    }

    private static Properties loadTypeProperties() {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream(CONFIG_FILE)) {
            properties.load(fis);
        } catch (IOException e) {
            System.err.println("Failed to load type properties: " + e.getMessage());
        }
        return properties;
    }

    private static String getPropertiesValue(String key, String defaultValue) {
        return properties.getProperty(key, defaultValue);
    }

    private static String createJsonReport(String weaknesses, String resistances) {
        return "{ \"weaknesses\": \"" + weaknesses + "\", \"resistances\": \"" + resistances + "\" }";
    }
}

interface Pokemon {
    String getPokemonType();
    String getPokemonName();
}
```

