    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_get_cipherbyname(algorithm);
    if (!cipher) {
        fprintf(stderr, "Unsupported algorithm: %s\n", algorithm);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (operationType == 0) { // Encryption
        if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
            ERR_print_errors_fp(stderr);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (operationType == 1) { // Decryption
        if (1 != EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv)) {
            ERR_print_errors_fp(stderr);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    // Perform the cryptographic operation
    // ...

    EVP_CIPHER_CTX_free(ctx);
    return ctx;
}
