#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>
#include <string.h>

#define SEM_NAME "/my_semaphore"
#define TEMP_FILE_PREFIX "/tmp/my_semaphore_"

sem_t* create_semaphore(const char* temp_file, int initial_value) {
    sem_t* semaphore;

    // Create a temporary file
    char temp_filename[1024];
    snprintf(temp_filename, sizeof(temp_filename), "%s%d", TEMP_FILE_PREFIX, getpid());
    int fd = mkstemp(temp_filename);
    if (fd == -1) {
        perror("mkstemp");
        return NULL;
    }

    // Write initial value to the temporary file
    write(fd, &initial_value, sizeof(initial_value));
    close(fd);

    // Remove the temporary file so it doesn't linger in the filesystem
    unlink(temp_filename);

    // Create a named semaphore associated with the temporary file
    semaphore = sem_open(SEM_NAME, O_CREAT | O_EXCL, 0644, initial_value);
    if (semaphore == SEM_FAILED) {
        perror("sem_open");
        return NULL;
    }

    return semaphore;
}

void use_semaphore(sem_t* semaphore, int increment) {
    sem_wait(semaphore); // Lock the semaphore
    // Critical section - modify shared data here
    sem_post(semaphore); // Unlock the semaphore
}

void delete_semaphore(sem_t* semaphore) {
    sem_close(semaphore);
    sem_unlink(SEM_NAME);
}
