use sqlx::postgres::{PgPoolOptions, PgRow};
use sqlx::Error;
use tracing;

#[tracing::instrument]
async fn construct_query(pool: &PgPoolOptions, query_template: &str, params: Vec<&str>) -> Result<Vec<PgRow>, Error> {
    let mut final_query = String::new();
    for (i, param) in params.iter().enumerate() {
        if i == 0 {
            final_query.push_str(query_template);
        } else {
            final_query.push_str(", ");
            final_query.push_str(param);
        }
    }

    tracing::info!("Generated query: {}", final_query);

    let rows = sqlx::query(final_query.as_str())
        .fetch_all(pool)
        .await?;

    Ok(rows)
}

#[tracing::instrument]
async fn main() -> Result<(), Error> {
    let pool = PgPoolOptions::new()
        .max_connections(50)
        .connect("postgres://username:password@localhost/database")
        .await?;

    let query_template = "SELECT * FROM users WHERE name = $1 AND age = $2";
    let params = vec!["John Doe", "30"];

    let rows = construct_query(&pool, query_template, params).await?;

    for row in rows {
        tracing::info!("User: {:?}", row);
    }

    Ok(())
}
```

