#include <iostream>
#include <vector>

class DynamicMatrix {
private:
    std::vector<std::vector<int>> matrix;
    size_t rows, cols;

public:
    // Constructor to initialize the matrix with given dimensions
    DynamicMatrix(size_t r, size_t c) : rows(r), cols(c), matrix(rows, std::vector<int>(cols)) {}

    // Method to update an element by its indices
    void updateElement(size_t row, size_t col, int value) {
        if (row >= rows || col >= cols) {
            std::cerr << "Error: Index out of bounds" << std::endl;
            return;
        }
        matrix[row][col] = value;
    }

    // Method to free memory for a specific row
    void freeRow(size_t row) {
        if (row >= rows) {
            std::cerr << "Error: Row index out of bounds" << std::endl;
            return;
        }
        matrix.erase(matrix.begin() + row);
        --rows;
    }

    // Method to insert a new row at a specified position
    void insertRow(size_t pos, const std::vector<int>& newRow) {
        if (newRow.size() != cols) {
            std::cerr << "Error: New row size does not match matrix columns" << std::endl;
            return;
        }
        if (pos > rows) {
            std::cerr << "Error: Insert position out of bounds" << std::endl;
            return;
        }
        matrix.insert(matrix.begin() + pos, newRow);
        ++rows;
    }

    // Method to print the current state of the matrix
    void printMatrix() const {
        for (const auto& row : matrix) {
            for (int elem : row) {
                std::cout << elem << " ";
            }
            std::cout << std::endl;
        }
    }
};

int main() {
    DynamicMatrix dm(3, 4);
    dm.updateElement(1, 2, 99);
    dm.printMatrix();
    dm.insertRow(1, {5, 6, 7, 8});
    dm.printMatrix();
    dm.freeRow(0);
    dm.printMatrix();
    return 0;
}
