using System.Data;
using System.Data.SqlClient;

public class DynamicSqlQueryExecutor
{
    public static IDataReader ExecuteDynamicQuery(List<FilterCriteria> filters, string connectionString, string baseSqlCommand)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            SqlCommand command = new SqlCommand(baseSqlCommand, connection);

            foreach (var filter in filters)
            {
                if (filter.ColumnType == SqlDbType.VarChar || filter.ColumnType == SqlDbType.NVarChar)
                {
                    command.Parameters.Add(new SqlParameter(filter.ParameterName, filter.Value)).SqlDbType = filter.ColumnType;
                }
                else
                {
                    command.Parameters.Add(new SqlParameter(filter.ParameterName, filter.Value));
                }
            }

            try
            {
                return command.ExecuteReader();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing query: {ex.Message}");
                // Handle error gracefully, possibly by returning a default empty reader or rethrowing the exception with custom message
                return new SqlDataReader(new DataTable());
            }
        }
    }

    public class FilterCriteria
    {
        public string ParameterName { get; set; }
        public object Value { get; set; }
        public SqlDbType ColumnType { get; set; }

        public FilterCriteria(string parameterName, object value, SqlDbType columnType)
        {
            ParameterName = parameterName;
            Value = value;
            ColumnType = columnType;
        }
    }
}
