public class ProjectSettingsParser
{
    private static readonly ILog _log = LogManager.GetLogger(typeof(ProjectSettingsParser));

    public string GetSetting(string xmlContent, string key)
    {
        try
        {
            XDocument doc = XDocument.Parse(xmlContent);
            var setting = doc.Descendants("setting")
                             .FirstOrDefault(s => s.Attribute("key")?.Value == key);

            if (setting != null)
            {
                return setting.Value;
            }
            else
            {
                _log.Warn($"Key '{key}' not found in the configuration file.");
                return "default_value";
            }
        }
        catch (XmlException ex)
        {
            _log.Error("Malformed XML encountered", ex);
            throw new ArgumentException("Invalid XML format", nameof(xmlContent), ex);
        }
    }
}
