import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class HashUtility {
    private static final Map<String, String> hashCache = new HashMap<>();

    public enum Algorithm {
        MD5,
        SHA_256
    }

    public static String computeHash(String input, Algorithm algorithm) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }
        String key = input + "_" + algorithm.name();
        if (hashCache.containsKey(key)) {
            return hashCache.get(key);
        }

        MessageDigest digest;
        switch (algorithm) {
            case MD5:
                digest = MessageDigest.getInstance("MD5");
                break;
            case SHA_256:
                digest = MessageDigest.getInstance("SHA-256");
                break;
            default:
                throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }

        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        hashCache.put(key, hexString.toString());
        return hexString.toString();
    }

    public static boolean isValidInput(String input) {
        // Add your validation logic here
        // Example: Check length and character set
        return input.length() <= 1024 && input.matches("[a-zA-Z0-9]+");
    }
}
