public class PageUpdater
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<PageUpdater> _logger;
    private static readonly ConcurrentDictionary<string, HtmlDocument> _cache = new ConcurrentDictionary<string, HtmlDocument>();

    public PageUpdater(HttpClient httpClient, ILogger<PageUpdater> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
        {
            _logger.LogError("Invalid input: pageSectionId, elementId, and htmlContent must not be null or empty.");
            throw new ArgumentException("Input cannot be null or empty");
        }

        var pageUrl = $"https://example.com/page/{pageSectionId}";
        var cachedDocument = _cache.GetOrAdd(pageUrl, async url =>
        {
            var response = await _httpClient.GetAsync(url);
            if (response.IsSuccessStatusCode)
            {
                return new HtmlDocument { LoadHtml(await response.Content.ReadAsStringAsync()) };
            }
            else
            {
                _logger.LogError($"Failed to fetch page: {url}");
                throw new InvalidOperationException("Failed to fetch page");
            }
        });

        var node = cachedDocument.DocumentNode.SelectSingleNode($"//*[@id='{elementId}']");
        if (node == null)
        {
            _logger.LogError($"Element with id '{elementId}' not found on the page.");
            throw new InvalidOperationException("Element not found");
        }

        node.InnerHtml = htmlContent;

        // Validate HTML
        var settings = HtmlAgilityPack.HtmlSettings.PreserveWhitespace;
        if (!new HtmlDocument().LoadHtml(node.OuterHtml, settings).IsValid)
        {
            _logger.LogError($"Invalid HTML content for element with id '{elementId}'.");
            throw new InvalidOperationException("Invalid HTML content");
        }

        // Update database or other storage
        try
        {
            await SaveUpdateAsync(pageSectionId, elementId, node.OuterHtml);
            _logger.LogInformation($"Successfully updated element with id '{elementId}' on page section '{pageSectionId}'.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to save update for element with id '{elementId}' on page section '{pageSectionId}'.");
        }
    }

    private async Task SaveUpdateAsync(string pageSectionId, string elementId, string htmlContent)
    {
