const path = require('path');
const fs = require('fs').promises;

async function processFilenames(directory, filenames) {
  const validFilenames = filenames.filter(filename => validateFilename(filename));

  const promises = validFilenames.map(async (filename) => {
    try {
      const fullPath = path.join(directory, filename);
      const content = await fs.readFile(fullPath, 'utf8');
      return { filename, content };
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.error(`File not found: ${filename}`);
      } else if (error.code === 'EACCES') {
        console.error(`Permission denied for file: ${filename}`);
      } else {
        console.error(`Error processing file ${filename}: ${error.message}`);
      }
    }
  });

  const results = await Promise.all(promises);
  return results.filter(result => result !== undefined); // Remove undefined results
}

function validateFilename(filename) {
  // Regular expression to prevent path traversal and allow valid filenames
  const pattern = /^[a-zA-Z0-9_.]+$/;
  if (!pattern.test(filename)) {
    console.error(`Invalid filename: ${filename}`);
    return false;
  }

  // Additional checks can be added here to restrict file types or size

  return true;
}

// Example usage:
(async () => {
  const directory = '/safe/directory';
  const filenames = ['file1.txt', 'file2.jpg', '../sensitive_file.txt'];

  try {
    const results = await processFilenames(directory, filenames);
    console.log(results);
  } catch (error) {
    console.error('Error processing files:', error.message);
  }
})();
```

