["```javascript
const fs = require('fs');
const path = require('path');
const child_process = require('child_process');

function loadModule(modulePath) {
  try {
    const sanitizedPath = path.resolve(path.normalize(modulePath));
    if (!sanitizedPath.startsWith(__dirname)) {
      throw new Error('Invalid module path');
    }
    return require(sanitizedPath);
  } catch (error) {
    console.error(`Failed to load module: ${error.message}`);
    process.exit(1);
  }
}

function executeTests(module, testFunction, timeout = 5000) {
  const testCases = Object.keys(module).filter(key => key.startsWith('test_'));
  const results = [];

  function runTest(testName, callback) {
    console.log(`Running test: ${testName}`);
    setTimeout(() => {
      try {
        module[testName]();
        results.push({ testName, passed: true });
      } catch (error) {
        results.push({ testName, passed: false, error });
      }
      callback();
    }, timeout);
  }

  let runningTests = testCases.length;
  testCases.forEach(testCase => {
    runTest(testCase, () => {
      if (--runningTests === 0) {
        generateReport(results);
      }
    });
  });
}

function generateReport(results) {
  const passed = results.filter(result => result.passed).length;
  const failed = results.filter(result => !result.passed).length;
  const skipped = results.length - (passed + failed);

  let averageDuration = 0;
  for (const result of results) {
    if (result.passed || !result.error) {
      averageDuration += result.duration || 0;
    }
  }
  averageDuration /= passed;

  console.log(`Tests executed: ${results.length}`);
  console.log(`Passed: ${passed}`);
  console.log(`Failed: ${failed}`);
  console.log(`Skipped: ${skipped}`);
  console.log(`Average duration: ${averageDuration}ms`);
}

function runTestSuite(modulePath, testFunction, timeout) {
  const module = loadModule(modulePath);
  executeTests(module, testFunction, timeout);
}

// Example usage:
runTestSuite('./my-module', function(test) {
  // Define your tests here
}, 5000);
```

This code provides a basic framework for managing a suite of tests for a given module in JavaScript. It includes functionality to load the module securely, execute tests with a timeout, reset a mocking library, handle test failures, and generate a summary report. The example usage at the end demonstrates how to call the `runTestSuite` function with a module path, test function, and timeout."]

