// Function to process email content and categorize programming languages
async function processEmailContent(emailContent) {
    try {
        // Fetching the list of commonly used programming languages from an external API
        const languageList = await fetchLanguages();

        // Creating a frequency map for each language
        const languageFrequency = {};

        // Regular expression to match whole words
        const wordRegex = /\b\w+\b/g;

        // Finding all words in the email content
        let match;
        while ((match = wordRegex.exec(emailContent)) !== null) {
            const word = match[0];
            // Checking if the word is a programming language
            for (const lang of languageList) {
                if (getLanguageRegex(lang).test(word)) {
                    if (!languageFrequency[lang]) {
                        languageFrequency[lang] = 1;
                    } else {
                        languageFrequency[lang]++;
                    }
                }
            }
        }

        return languageFrequency;
    } catch (error) {
        // Handling potential network errors gracefully
        console.error('Failed to fetch programming languages:', error);
        return {};
    }
}

// Function to fetch the list of commonly used programming languages from an external API
async function fetchLanguages() {
    try {
        const response = await fetch('https://api.example.com/languages');
        if (!response.ok) {
            throw new Error('Failed to load language data');
        }
        return response.json();
    } catch (error) {
        // Providing a fallback mechanism when the API is unavailable
        console.error('API is unavailable, using local fallback');
        return ['JavaScript', 'Python', 'Java', 'C++', 'Ruby', 'Go', 'PHP', 'Swift', 'Kotlin', 'Rust'];
    }
}

