// JavaScript code to dynamically load and execute JS files from CDN

const loadJS = (url, callback) => {
  const script = document.createElement('script');
  script.src = url;
  script.onload = callback;
  script.onerror = () => console.error(`Failed to load ${url}`);
  document.head.appendChild(script);
};

const loadMultipleJS = async (urls, retryCount = 3) => {
  for (let i = 0; i < urls.length; i++) {
    let attempts = 0;
    while (attempts < retryCount) {
      try {
        await new Promise((resolve, reject) =>
          loadJS(urls[i], resolve)
        );
        break;
      } catch (error) {
        attempts++;
        if (attempts >= retryCount) throw error;
      }
    }
  }
};

// Example usage
const jsFiles = [
  'https://cdn.example.com/file1.js',
  'https://cdn.example.com/file2.js'
];
loadMultipleJS(jsFiles);
