void modifyExtension(char *filename, char *extension) {
  int len = strlen(filename);
  if (len > 0 && filename[len - 1] != '.') {
    filename[len++] = '.';
  }
  if (strlen(extension) <= len - 2) {
    strncat(filename, extension, len - 1);
  } else {
    fprintf(stderr, "Error: Extension too long.\n");
  }
}

int main() {
  char filename[256] = "examplefile.js";
  modifyExtension(filename, ".v2.min.js");
  printf("Modified filename: %s\n", filename);
  return 0;
}
