import java.io.IOException;
import java.net.URL;
import java.util.concurrent.*;
import java.util.function.Function;

public class URLContentRetriever {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Cache<String, String> cache = CacheBuilder.newBuilder()
            .expireAfterWrite(1, TimeUnit.HOURS)
            .build();

    public String getContent(String url) {
        try {
            return cache.get(url, () -> fetchContentFromURL(url));
        } catch (ExecutionException e) {
            // Log error and handle gracefully
            return null;
        }
    }

    private String fetchContentFromURL(String urlStr) throws IOException {
        URL url = new URL(urlStr);
        if (!isValidPublicURL(url)) {
            throw new IllegalArgumentException("Invalid public URL");
        }

        int retries = 0;
        while (retries < 3) {
            try {
                return executor.submit(() -> {
                    // Simulate network request
                    Thread.sleep(100); // Assuming each fetch takes 100ms
                    return "Content from " + urlStr;
                }).get();
            } catch (InterruptedException | ExecutionException e) {
                retries++;
                if (retries == 3) throw new IOException("Failed to retrieve content", e);
                try {
                    Thread.sleep((long) Math.pow(2, retries)); // Exponential backoff
                } catch (InterruptedException ie) {}
            }
        }
        return null;
    }

    private boolean isValidPublicURL(URL url) {
        // Basic validation, real implementation would be more complex
        return !url.getHost().contains("internal");
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
```

