public class ThemeCacheManager {
    private static final String DEFAULT_THEME_DIR = "/default_theme";
    private static final String FALLBACK_PATH = "/fallback_path";

    private Cache<String, Bitmap> cache;
    private File themeDirectory;

    public ThemeCacheManager() {
        initializeCache();
        configureThemeDirectory();
    }

    private void initializeCache() {
        // Initialize caching framework
        cache = new LruCache<>(getMaxMemorySize());
    }

    private int getMaxMemorySize() {
        final ActivityManager am = (ActivityManager) getSystemService(Context.ACTIVITY_SERVICE);
        final int maxMemory = am.getLargeHeapSize();
        return maxMemory / 8; // Use 1/8th of the available heap size
    }

    private void configureThemeDirectory() {
        themeDirectory = new File(getDefaultThemeDir());
        if (!themeDirectory.exists()) {
            themeDirectory.mkdirs();
        }
    }

    public String getDefaultThemeDir() {
        final SharedPreferences preferences = getSharedPreferences("CachePrefs", Context.MODE_PRIVATE);
        return preferences.getString("THEME_DIR", FALLBACK_PATH);
    }

    public void setDefaultThemeDir(String dir) {
        final SharedPreferences preferences = getSharedPreferences("CachePrefs", Context.MODE_PRIVATE);
        preferences.edit().putString("THEME_DIR", dir).apply();
    }

    public Bitmap loadThemeBitmap(String themeName) throws IOException {
        File file = new File(themeDirectory, themeName + ".png");
        if (!file.exists()) {
            // Log and handle missing file
            return null;
        }
        Bitmap bitmap = BitmapFactory.decodeFile(file.getAbsolutePath());
        cache.put(themeName, bitmap);
        return bitmap;
    }

    public void recycleBitmap(String themeName) {
        Bitmap bitmap = cache.get(themeName);
        if (bitmap != null) {
            bitmap.recycle();
            cache.remove(themeName);
            bitmap = null;
        }
    }

    private void logCacheOperation(String operation, String themeName) {
        // Log caching operations
        Log.d("ThemeCache", "Operation: " + operation + ", Theme Name: " + themeName);
    }

    public void initThemeFiles() {
        // Initialize theme files with correct permissions
        try {
            File themeFile = new File(themeDirectory, "default_theme.png");
            if (!themeFile.exists()) {
                InputStream is = getAssets().open("default_theme.png");
                FileOutputStream fos = new FileOutputStream(themeFile);
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    fos.write(buffer, 0, bytesRead);
                }
                fos.close();
                is.close();
            }
        } catch (IOException e) {
            // Handle file creation error
        }
    }

    public void extendThemeCache() {
        // Extend caching strategy
        cache.setMaxSize(getMaxMemorySize() * 2); // Double the cache size for future growth
    }

