// Function to load environment variables from a file
function loadEnvironmentVariables($env) {
    $file = __DIR__ . '/config/' . $env . '.env';
    if (file_exists($file)) {
        foreach (parse_ini_file($file, true) as $section => $settings) {
            foreach ($settings as $key => $value) {
                putenv("$key=$value");
            }
        }
    }
}

// Function to validate environment variables using an external API
function validateEnvironmentVariables() {
    $apiUrl = 'https://api.example.com/validate-env';
    $options = [
        'http' => [
            'header'  => "Content-type: application/json\r\n",
            'method'  => 'POST',
            'content' => json_encode(getenv())
        ]
    ];
    $context  = stream_context_create($options);
    $response = file_get_contents($apiUrl, false, $context);

    if ($response === FALSE) {
        // Fallback mechanism in case of API failure
        return true; // Assume all variables are valid if API is not available
    }

    $result = json_decode($response, true);
    return $result['isValid'];
}

// Function to cache validation results to mitigate external API latency
function cacheValidationResult($valid) {
    file_put_contents(__DIR__ . '/cache/last_validation', json_encode(['isValid' => $valid]));
}

// Function to retrieve cached validation result
function getCachedValidation() {
    if (file_exists(__DIR__ . '/cache/last_validation')) {
        return json_decode(file_get_contents(__DIR__ . '/cache/last_validation'), true);
    }
    return null;
}

// Function to load the application configuration
function loadApplicationConfig($env) {
    $config = include __DIR__ . '/config/' . $env . '.php';
    return $config;
}

// Main execution flow
$env = getenv('APP_ENV') ?: 'development'; // Default to development if not set

if (isset($_GET['force_reload'])) {
    loadEnvironmentVariables($env);
    cacheValidationResult(validateEnvironmentVariables());
} else {
    $cachedValidation = getCachedValidation();
    if ($cachedValidation && time() - filemtime(__DIR__ . '/cache/last_validation') < 3600) { // Cache for 1 hour
        $isValid = $cachedValidation['isValid'];
    } else {
        $isValid = validateEnvironmentVariables();
        cacheValidationResult($isValid);
    }
}

if ($isValid === false) {
    error_log('Environment variables validation failed.');
    exit(500); // Internal server error
}

// Load vendor autoloader
require __DIR__ . '/vendor/autoload.php';

// Load application configuration
$config = loadApplicationConfig($env);

// Initialize the application with the config
