use reqwest::{ClientBuilder, Client, Error, HeaderMap};
use std::time::Duration;

#[derive(Clone)]
struct HttpClientConfig {
    base_url: String,
    headers: HeaderMap,
    disable_certificate_validation: bool,
    proxy: Option<String>,
    cache_certificates: bool,
}

impl HttpClientConfig {
    fn new(base_url: &str) -> Self {
        let mut headers = HeaderMap::new();
        headers.insert("User-Agent", "MyCustomClient".parse().unwrap());

        HttpClientConfig {
            base_url: base_url.to_string(),
            headers,
            disable_certificate_validation: false,
            proxy: None,
            cache_certificates: true,
        }
    }

    fn with_header(mut self, key: &str, value: &str) -> Self {
        self.headers.insert(key, value.parse().unwrap());
        self
    }

    fn disable_certificate_validation(mut self) -> Self {
        self.disable_certificate_validation = true;
        self
    }

    fn with_proxy(mut self, proxy_url: &str) -> Self {
        self.proxy = Some(proxy_url.to_string());
        self
    }

    fn cache_certificates(mut self) -> Self {
        self.cache_certificates = true;
        self
    }
}

fn create_http_client(config: HttpClientConfig) -> Result<Client, Error> {
    let mut builder = ClientBuilder::new();

    if config.disable_certificate_validation {
        builder = builder.dangerously_disable_hostname_verification();
        builder = builder.dangerously_disable_ssl_certificate_validation();
    }

    if let Some(proxy_url) = config.proxy {
        builder = builder.proxy(reqwest::Proxy::all(&proxy_url)?);
    }

    if config.cache_certificates {
        // Custom logic to cache certificates
        unimplemented!();
    }

    builder.timeout(Duration::from_secs(10))
           .default_headers(config.headers)
           .build()
}

fn main() -> Result<(), Error> {
    let config = HttpClientConfig::new("https://api.example.com")
        .with_header("Authorization", "Bearer token")
        .disable_certificate_validation()
        .with_proxy("http://proxy.example.com:8080")
        .cache_certificates();

    let client = create_http_client(config)?;

    let response = client.get("endpoint")
                          .send()?
                          .text()?;

    println!("Response: {}", response);

    Ok(())
}
