function updateProfile($newEmail) {
    // Authentication checks
    if (!isset($_SERVER['HTTP_AUTH_TOKEN']) || !isset($_SESSION['user_id'])) {
        return "Authentication failed: Missing headers or session data.";
    }

    $authToken = $_SERVER['HTTP_AUTH_TOKEN'];
    $userId = $_SESSION['user_id'];

    // Database connection and query to check user
    $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
    $stmt = $db->prepare("SELECT * FROM users WHERE id = ?");
    $stmt->execute([$userId]);
    $user = $stmt->fetch();

    if (!$user) {
        return "Authentication failed: User not found.";
    }

    // Check for recent login timestamp
    if (time() - $user['last_login'] > 3600) { // Assuming a valid session for one hour
        return "Authentication failed: Session too old.";
    }

    // Validate and sanitize new email
    if (!filter_var($newEmail, FILTER_VALIDATE_EMAIL)) {
        return "Invalid email format.";
    }

    // Check if the email is already in use by another user
    $stmt = $db->prepare("SELECT * FROM users WHERE email = ?");
    $stmt->execute([$newEmail]);
    $existingUser = $stmt->fetch();

    if ($existingUser && $existingUser['id'] != $userId) {
        return "Email already in use by another user.";
    }

    // Update user profile
    try {
        $db->beginTransaction();

        // Update email, last modified IP and date
        $stmt = $db->prepare("UPDATE users SET email = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
        $stmt->execute([$newEmail, $_SERVER['REMOTE_ADDR'], $userId]);

        // Log change (avoid sensitive info)
        error_log("User ID: {$user['id']} changed email to {$newEmail} from IP: {$_SERVER['REMOTE_ADDR']}");

        $db->commit();
        return "Profile updated successfully.";
    } catch (PDOException $e) {
        $db->rollBack();
        return "Error updating profile: " . $e->getMessage();
    }
}
?>
