    if not authenticated_user or authenticated_user["role"] != "admin":
        raise PermissionError("User does not have permission to access the API")

    role_mapping = fetch_user_roles()
    department_mapping = fetch_user_departments()

    if role and role not in role_mapping:
        raise ValueError(f"Invalid role: {role}")

    if department and department not in department_mapping:
        raise ValueError(f"Invalid department: {department}")

    params = {
        "page": 1,
        "per_page": 50,
        "role": role_mapping.get(role, ""),
        "department": department_mapping.get(department, "")
    }

    headers = {
        "Authorization": f"Bearer {user_token}"
    }

    try:
        response = requests.get(API_URL, params=params, headers=headers)
        response.raise_for_status()
        return response.json()
