function generateSecurePassword($length = 12, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $salt = '') {
    if ($length < 1 || empty($charset) || empty($salt)) {
        return false;
    }
    $password = substr(str_shuffle(str_repeat($charset, ceil($length / strlen($charset)))), 1, $length);
    $password .= $salt;
    return password_hash($password, PASSWORD_DEFAULT);
}
