const fs = require('fs');
const path = require('path');
const util = require('util');

const readFileAsync = util.promisify(fs.readFile);

class FileProcessor {
    constructor(trustedDirectory) {
        this.trustedDirectory = trustedDirectory;
        this.cache = {};
    }

    async readAndProcessFile(filePath, options = {}) {
        try {
            const resolvedPath = path.resolve(__dirname, this.trustedDirectory, filePath);
            if (!resolvedPath.startsWith(path.resolve(__dirname, this.trustedDirectory))) {
                throw new Error('Invalid file path');
            }
            if (this.cache[filePath]) {
                return this.cache[filePath];
            }
            const content = await readFileAsync(resolvedPath, 'utf8');
            let processedContent = content;
            if (options.filter) {
                processedContent = content.split('\n').filter(line => options.filter.test(line)).join('\n');
            }
            this.cache[filePath] = processedContent;
            return processedContent;
        } catch (error) {
            console.error('Error reading file:', error);
            throw error;
        }
    }
}

module.exports = FileProcessor;
