async function fetchPEMFromService() {
  try {
    const privateKey = await fetch('https://secure.api/private-key').then(response => response.text());
    const certificate = await fetch('https://secure.api/certificate').then(response => response.text());

    if (!privateKey || !certificate) {
      throw new Error('Failed to retrieve private key or certificate');
    }

    return combinePEM(privateKey, certificate);
  } catch (error) {
    console.error('Error fetching PEM data:', error);
    throw error;
  }
}

function combinePEM(privateKey, certificate) {
  const pemContent = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
  return new Promise((resolve) => {
    setTimeout(() => resolve(pemContent), 100); // Simulate network latency
  });
}

// Example usage:
fetchPEMFromService()
  .then(pemFile => console.log('PEM File:', pemFile))
  .catch(error => console.error('Failed to fetch PEM file:', error));
```

