#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_QUERY_SIZE 256
#define MAX_IP_SIZE 16

int resolveDNS(const char* hostname, u_char* ipAddress) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in* ipv4 = (struct sockaddr_in*)res->ai_addr;
    strcpy(ipAddress, inet_ntoa(ipv4->sin_addr));

    freeaddrinfo(res);
    return 0;
}

int main() {
    u_char ipAddress[MAX_IP_SIZE];
    if (resolveDNS("example.com", ipAddress) == 0) {
        printf("IP Address: %s\n", ipAddress);
    } else {
        printf("Failed to resolve DNS\n");
    }
    return 0;
}
