#include <iostream>
#include <stdexcept>

struct OctreeNode {
    // Define the structure of an octree node
};

class OctreeInitializer {
public:
    static OctreeInitializer* create(int featureSize, int numLeafNodes, size_t dataCapacity) {
        if (featureSize <= 0 || numLeafNodes <= 0) {
            throw std::invalid_argument("Feature size and number of leaf nodes must be positive.");
        }

        size_t requiredMemory = calculateRequiredMemory(featureSize, numLeafNodes);
        if (requiredMemory > dataCapacity) {
            throw std::runtime_error("Insufficient data capacity for the requested octree.");
        }

        // Allocate memory with a minimum increment factor of 1.5
        size_t allocatedMemory = std::max(requiredMemory, static_cast<size_t>(dataCapacity * 1.5));

        OctreeInitializer* initializer = new (std::nothrow) OctreeInitializer;
        if (!initializer) {
            throw std::bad_alloc();
        }

        initializer->featureSize_ = featureSize;
        initializer->numLeafNodes_ = numLeafNodes;
        initializer->dataCapacity_ = dataCapacity;
        initializer->allocatedMemory_ = allocatedMemory;

        // Dynamically allocate memory for nodes, prefixes, and data arrays
        initializer->nodes_ = new (std::nothrow) OctreeNode[numLeafNodes];
        if (!initializer->nodes_) {
            delete initializer;
            throw std::bad_alloc();
        }

        initializer->prefixes_ = new (std::nothrow) int[numLeafNodes];
        if (!initializer->prefixes_) {
            delete[] initializer->nodes_;
            delete initializer;
            throw std::bad_alloc();
        }

        initializer->data_ = new (std::nothrow) char[allocatedMemory];
        if (!initializer->data_) {
            delete[] initializer->prefixes_;
            delete[] initializer->nodes_;
            delete initializer;
            throw std::bad_alloc();
        }

        return initializer;
    }

    ~OctreeInitializer() {
        delete[] nodes_;
        delete[] prefixes_;
        delete[] data_;
    }

private:
    int featureSize_;
    int numLeafNodes_;
    size_t dataCapacity_;
    size_t allocatedMemory_;
    OctreeNode* nodes_;
    int* prefixes_;
    char* data_;

    static size_t calculateRequiredMemory(int featureSize, int numLeafNodes) {
        // Calculate the required memory based on feature size and number of leaf nodes
        // This is a placeholder for actual memory calculation logic
        return featureSize * numLeafNodes * sizeof(OctreeNode) + numLeafNodes * sizeof(int);
    }
};
