#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 1000

typedef struct {
    int id;
    time_t start_time;
    time_t last_interaction;
} Session;

Session sessions[MAX_SESSIONS];
int session_count = 0;

unsigned int generate_session_id() {
    static unsigned int seed = time(NULL);
    return (seed = seed * 214013 + 2531011) % MAX_SESSIONS;
}

void create_session() {
    if (session_count >= MAX_SESSIONS) return;
    sessions[session_count].id = generate_session_id();
    sessions[session_count].start_time = time(NULL);
    sessions[session_count].last_interaction = sessions[session_count].start_time;
    session_count++;
}

void interact_with_session(int id) {
    for (int i = 0; i < session_count; i++) {
        if (sessions[i].id == id) {
            sessions[i].last_interaction = time(NULL);
            return;
        }
    }
}

int expire_sessions() {
    int expired_count = 0;
    time_t now = time(NULL);
    for (int i = 0; i < session_count; i++) {
        if (now - sessions[i].start_time > 3600) { // Session timeout after 1 hour
            expired_count++;
        }
    }
    return expired_count;
}

void report_session_stats() {
    int total_sessions = session_count;
    time_t now = time(NULL);
    double total_duration = 0.0;
    for (int i = 0; i < session_count; i++) {
        total_duration += difftime(now, sessions[i].start_time);
    }
    double average_duration = total_duration / session_count;

    printf("Total active sessions: %d\n", total_sessions);
    printf("Average session duration: %.2f seconds\n", average_duration);

    int timeout_count = 0;
    for (int i = 0; i < session_count; i++) {
        if (now - sessions[i].start_time > 3600) { // Session timeout after 1 hour
            timeout_count++;
        }
    }
    printf("Session timeouts: %d\n", timeout_count);
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        create_session();
    }

    interact_with_session(sessions[0].id);

    int expired = expire_sessions();

    report_session_stats();

    return 0;
}
