int lastAttackTime = 0;
int attackCooldowns[] = {7, 9, 11}; // Cooldown periods for attacks 1, 2, 3

void selectRandomAttack() {
    static const int numAttacks = sizeof(attackCooldowns) / sizeof(attackCooldowns[0]);
    int currentTime = time(nullptr);

    if (currentTime - lastAttackTime < attackCooldowns[lastAttackTime % numAttacks]) {
        // If the last attack is still on cooldown, wait until it's ready
        std::cout << "Waiting for cooldown..." << std::endl;
        return;
    }

    int nextAttack = rand() % numAttacks + 1; // Randomly select an attack number (1 to 3)
    std::cout << "Selected attack: " << nextAttack << std::endl;

    lastAttackTime = currentTime;
}

int main() {
    srand(time(nullptr)); // Seed the random number generator

    for (int i = 0; i < 10; ++i) { // Simulate selecting attacks over time
        selectRandomAttack();
        sleep(2); // Simulate time passing between attacks
    }

    return 0;
}
