['```csharp
using System;
using System.Security.Cryptography;

public class DynamicValueGenerator
{
    private readonly RandomNumberGenerator _rng;
    private readonly int _lowerBoundInt;
    private readonly double _lowerBoundFloat;
    private readonly int _upperBoundInt;
    private readonly double _upperBoundFloat;

    public DynamicValueGenerator(int lowerBoundInt, int upperBoundInt, double lowerBoundFloat, double upperBoundFloat)
    {
        if (lowerBoundInt > upperBoundInt || lowerBoundFloat >= upperBoundFloat)
            throw new ArgumentException("Invalid range parameters.");

        _rng = RandomNumberGenerator.Create();
        _lowerBoundInt = lowerBoundInt;
        _upperBoundInt = upperBoundInt;
        _lowerBoundFloat = lowerBoundFloat;
        _upperBoundFloat = upperBoundFloat;
    }

    public int GenerateRandomInt()
    {
        byte[] buffer = new byte[4];
        _rng.GetBytes(buffer);
        return BitConverter.ToInt32(buffer, 0) % (_upperBoundInt - _lowerBoundInt + 1) + _lowerBoundInt;
    }

    public double GenerateRandomFloat()
    {
        byte[] buffer = new byte[8];
        _rng.GetBytes(buffer);
        long value = BitConverter.ToInt64(buffer, 0);
        return (value / ((long.MaxValue - long.MinValue) + 1)) * (_upperBoundFloat - _lowerBoundFloat) + _lowerBoundFloat;
    }

    public override string ToString()
    {
        return $"Integers: {_lowerBoundInt}-{_upperBoundInt}, Floats: {_lowerBoundFloat:F2}-{_upperBoundFloat:F2}";
    }
}
