#define MAX_LINE_SIZE 1024

int process_packet_log(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open log file");
        return -1;
    }

    int total_packets = 0;
    char line[MAX_LINE_SIZE];
    while (fgets(line, sizeof(line), file)) {
        // Example parsing logic: expecting format "<timestamp> <packet_id> <packet_size>"
        char* token = strtok(line, " ");
        if (!token) continue; // Skip empty lines

        int packet_size;
        if (sscanf(token + strlen("<packet_size>"), "%d", &packet_size) != 1) {
            continue; // Malformed packet size
        }

        if (packet_size <= 0) continue; // Ignore non-positive packet sizes

        total_packets++;
    }

    fclose(file);
    return total_packets;
}

int main() {
    const char* log_file = "network_log.txt";
    int total_processed_packets = process_packet_log(log_file);
    printf("Total packets processed: %d\n", total_processed_packets);
    return 0;
}
