    function validateString(str) {
        if (str == null || str.length > maxLength) {
            return false;
        }
        return true;
    }

    function traverse(node) {
        if (!node) return [];

        let elements = [];
        if (node.matches(selector)) {
            if (validateString(node.className) && validateString(node.id)) {
                elements.push(node);
            }
        }
        for (let child of node.children) {
            elements = elements.concat(traverse(child));
        }

        return elements;
    }

