#include <stdlib.h>
#include <string.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    long totalSamples;
    unsigned char hash[MD5_DIGEST_LENGTH];
} ImageMetadata;

ImageMetadata ProcessImageAndComputeHash(const char* imagePath, const char* stringToHash) {
    ImageMetadata result = {0};
    TIFF* tif = TIFFOpen(imagePath, "r");

    if (!tif) {
        return result; // Return empty metadata on file open failure
    }

    uint32_t bitsPerSample, samplesPerPixel;
    uint64_t stripOffsets[500]; // Adjust size as needed

    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) &&
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) &&
        TIFFGetField(tif, TIFFTAG_STRIPOFFSETS, stripOffsets)) {

        result.bitsPerSample = bitsPerSample;
        result.samplesPerPixel = samplesPerPixel;
        result.totalSamples = (bitsPerSample * stripOffsets[0]) / 8; // Simplified calculation

        if (!(bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 ||
              bitsPerSample == 8 || bitsPerSample == 16)) {
            return result; // Unsupported bit depth
        }
    } else {
        return result; // Missing metadata
    }

    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, stringToHash, strlen(stringToHash));
    MD5_Final(result.hash, &md5);

    TIFFClose(tif);
    return result;
}
