#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

const char* determineFileType(char firstChar) {
    if (isdigit(firstChar)) return ".dat";
    else if (strchr("aeiouAEIOU", firstChar)) return ".log";
    else if (isalpha(firstChar)) return ".csv";
    else return ".txt";
}

int countUniqueAlphanumericChars(const char* filename) {
    int count = 0;
    int chars[128] = {0}; // ASCII range
    for (const char* p = filename; *p != '\0'; ++p) {
        if (isalnum(*p)) {
            if (!chars[(int)*p]) {
                chars[(int)*p] = 1;
                count++;
            }
        }
    }
    return count;
}

char* generateNewFilename(const char* originalFilename, int maxLen) {
    if (!originalFilename || strlen(originalFilename) >= maxLen)
        return NULL;

    int uniqueCharsCount = countUniqueAlphanumericChars(originalFilename);
    const char* fileType = determineFileType(originalFilename[0]);

    size_t newFilenameSize = snprintf(NULL, 0, "%s%d%s", originalFilename, uniqueCharsCount, fileType) + 1;
    if (newFilenameSize > maxLen)
        return NULL;

    char* newFilename = (char*)malloc(newFilenameSize);
    if (!newFilename)
        return NULL;

    snprintf(newFilename, newFilenameSize, "%s%d%s", originalFilename, uniqueCharsCount, fileType);

    return newFilename;
}

void freeNewFilename(char* filename) {
    free(filename);
}

int main() {
    const char* original = "example.txt";
    char* newFilename = generateNewFilename(original, MAX_FILENAME_LENGTH);
    if (newFilename) {
        printf("New Filename: %s\n", newFilename);
        freeNewFilename(newFilename);
    } else {
        printf("Failed to generate filename.\n");
    }
    return 0;
}
