void initialize_aes_cipher(const char *password, EVP_CIPHER_CTX **ctx) {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Error generating IV\n");
        return;
    }

    // Derive the encryption key using a robust hashing mechanism
    unsigned char hash[EVP_MAX_MD_SIZE];
    unsigned int hash_len;
    EVP_DigestInit_ex(NULL, EVP_sha256(), NULL);
    EVP_DigestUpdate(NULL, password, strlen(password));
    EVP_DigestFinal_ex(NULL, hash, &hash_len);

    // Set the key and IV for AES-256-CBC
    if (AES_set_encrypt_key(hash, 256, &key) != 0 || AES_set_iv(&key, iv) != 0) {
        fprintf(stderr, "Error setting AES key or IV\n");
        return;
    }

    // Create and initialize the cipher context
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) {
        fprintf(stderr, "Error creating EVP_CIPHER_CTX\n");
        return;
    }

    if (EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, hash, iv) != 1) {
        fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(*ctx);
        *ctx = NULL;
        return;
    }
}

