    public bool InitializeWebSite()
    {
        if (!File.Exists(_webConfigPath))
        {
            Log("Error: web.config file not found in the specified directory.");
            return false;
        }

        string commandTemplate = "";
        string serverType = GetServerType();
        switch (serverType)
        {
            case "IIS":
                commandTemplate = "appcmd set site /site.name:\"{0}\" /physicalPath:\"{1}\"";
                break;
            case "Apache":
                commandTemplate = "httpd -c \"{0}\" restart";
                break;
            default:
                Log("Error: Unsupported server type.");
                return false;
        }

        string physicalPath = Path.GetFullPath(_serverPath);
        string args = string.Format(commandTemplate, GetUniqueSiteName(), physicalPath);

        try
        {
            using (Process process = new Process())
            {
                process.StartInfo.FileName = "cmd.exe";
                process.StartInfo.Arguments = "/c " + args;
                process.StartInfo.RedirectStandardOutput = true;
                process.StartInfo.RedirectStandardError = true;
                process.StartInfo.UseShellExecute = false;
                process.StartInfo.CreateNoWindow = true;

                process.OutputDataReceived += (sender, e) => Log("stdout: " + e.Data);
                process.ErrorDataReceived += (sender, e) => Log("stderr: " + e.Data);

                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();

                int exitCode = process.WaitForExit();
                if (exitCode == 0)
                {
                    Log("Website initialized successfully.");
                    return true;
