import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DiskUsageMonitor {
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(10);
    private static final Map<String, Long> cache = new HashMap<>();
    private static long lastRunTime;
    private static int monitoringFrequency = 60; // in seconds

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide a directory path.");
            return;
        }

        String directoryPath = args[0];
        File directory = new File(directoryPath);

        try {
            validateDirectory(directory);
            scheduleMonitoring();
        } catch (IOException e) {
            logError(e);
        }
    }

    private static void validateDirectory(File directory) throws IOException {
        if (!directory.exists()) {
            throw new IOException("Directory does not exist: " + directory.getAbsolutePath());
        }
        if (!directory.isDirectory()) {
            throw new IOException("Not a valid directory: " + directory.getAbsolutePath());
        }
    }

    private static void scheduleMonitoring() {
        scheduler.scheduleAtFixedRate(() -> {
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastRunTime > monitoringFrequency * 1000) {
                try {
                    String command = constructCommand(directory);
                    executeCommand(command);
                    cache.put(directory.getAbsolutePath(), currentTime);
                } catch (IOException e) {
                    logError(e);
                }
            }
        }, 0, monitoringFrequency, TimeUnit.SECONDS);
    }

    private static String constructCommand(File directory) {
        return "du -sh " + directory.getAbsolutePath();
    }

    private static void executeCommand(String command) throws IOException {
        Process process = Runtime.getRuntime().exec(command);
        try {
            int exitCode = process.waitFor();
            if (exitCode == 0) {
                logSuccess("Disk usage for " + directory.getAbsolutePath() + ": " + new String(process.getInputStream().readAllBytes()));
            } else {
                logError(new IOException("Command execution failed with exit code: " + exitCode));
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logError(e);
        }
    }

    private static void logSuccess(String message) {
        System.out.println("[SUCCESS] " + message);
    }

    private static void logError(Exception e) {
        System.err.println("[ERROR] " + e.getMessage());
        e.printStackTrace();
    }
}
```

