    void *connection_object;
    void (*callback_function)();
} SecureData;

int decryptPassword(SecureData *data, const char **decrypted_password) {
    if (data == NULL || data->base64_encoded_password == NULL || strlen(data->base64_encoded_password) == 0 ||
        data->connection_object == NULL || data->callback_function == NULL) {
        return -1; // Error: Invalid input
    }

    int connection_valid = 1; // Assume connection is valid for demonstration purposes
    if (!connection_valid) {
        return -2; // Error: Connection not valid
    }

    // Simulate secure storage retrieval (replace with actual implementation)
    const char *decryption_key = "secure_decryption_key";
    const char *iv = "secure_iv";

    // Decode Base64 and decrypt using Triple DES
    int decoded_len = strlen(data->base64_encoded_password) * 3 / 4;
    unsigned char *decoded_data = (unsigned char *)malloc(decoded_len);
    if (decoded_data == NULL) {
        return -3; // Error: Memory allocation failed
    }

    int ret = EVP_DecodeBase64(decoded_data, &decoded_len, data->base64_encoded_password, strlen(data->base64_encoded_password));
    if (ret != decoded_len) {
        free(decoded_data);
        return -4; // Error: Base64 decoding failed
    }

    unsigned char decrypted_output[1024];
    int decrypted_len = sizeof(decrypted_output);
    ret = EVP_DecryptInit_ex(NULL, EVP_des_ede3_cbc(), NULL, (unsigned char *)decryption_key, (unsigned char *)iv);
    if (!ret) {
        free(decoded_data);
        return -5; // Error: Encryption initialization failed
    }

    ret = EVP_DecryptUpdate(NULL, decrypted_output, &decrypted_len, decoded_data, decoded_len);
    if (!ret || decrypted_len >= sizeof(decrypted_output)) {
        free(decoded_data);
        return -6; // Error: Decryption update failed
    }

    ret = EVP_DecryptFinal_ex(NULL, decrypted_output + decrypted_len, &decrypted_len);
    if (!ret) {
        free(decoded_data);
        return -7; // Error: Decryption finalization failed
    }

    *decrypted_password = (char *)malloc(decrypted_len + 1);
    if (*decrypted_password == NULL) {
        free(decoded_data);
        return -8; // Error: Memory allocation failed
    }
    memcpy(*decrypted_password, decrypted_output, decrypted_len);
    (*decrypted_password)[decrypted_len] = '\0';

    free(decoded_data);
    return 0; // Success
}
