#include <libpq-fe.h>

typedef struct {
    bool success;
    char* errorMessage;
} ConnectionResult;

ConnectionResult initializeDatabaseConnection() {
    ConnectionResult result = {false, NULL};

    // Fetch environment variables for connection parameters
    const char* host = getenv("DB_HOST");
    const char* port = getenv("DB_PORT");
    const char* dbname = getenv("DB_NAME");
    const char* user = getenv("DB_USER");
    const char* password = getenv("DB_PASSWORD");

    if (host == NULL || port == NULL || dbname == NULL || user == NULL || password == NULL) {
        result.errorMessage = "Missing one or more required environment variables.";
        return result;
    }

    // Construct connection string
    char connectionString[256];
    snprintf(connectionString, sizeof(connectionString), 
             "host=%s port=%s dbname=%s user=%s password=%s", 
             host, port, dbname, user, password);

    // Attempt to establish connection up to three times with exponential backoff
    for (int attempt = 1; attempt <= 3; ++attempt) {
        PGconn* conn = PQconnectdb(connectionString);
        if (PQstatus(conn) == CONNECTION_OK) {
            result.success = true;
            PQfinish(conn);
            return result;
        } else {
            char error[256];
            snprintf(error, sizeof(error), "Connection attempt %d failed: %s", attempt, PQerrorMessage(conn));
            printf("%s\n", error);
            PQfinish(conn);

            // Exponential backoff
            sleep(attempt * 2);
        }
    }

    result.errorMessage = "Failed to connect to the database after multiple attempts.";
    return result;
}
