    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            SqlCommand command = new SqlCommand(query, connection);
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataSet dataSet = new DataSet();
            adapter.Fill(dataSet);

            return dataSet.CreateDataReader(CommandBehavior.CloseConnection);
        }
    }

    public static byte[] HashPassword(string password, string hashAlgorithm)
    {
        using (HashAlgorithm algorithm = HashAlgorithm.Create(hashAlgorithm))
        {
            return algorithm.ComputeHash(Encoding.UTF8.GetBytes(password));
        }
    }

    public static bool VerifyPassword(string password, byte[] storedHash, string hashAlgorithm)
    {
        byte[] computedHash = HashPassword(password, hashAlgorithm);
        return ByteArrayComparer(computedHash, storedHash);
    }

    private static bool ByteArrayComparer(byte[] a, byte[] b)
    {
        if (a.Length != b.Length) return false;

        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i]) return false;
        }

        return true;
    }
}
