public class Base64Decryptor
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly string _delimiter;

    public Base64Decryptor(string key, string iv, char delimiter)
    {
        _key = Encoding.UTF8.GetBytes(key);
        _iv = Encoding.UTF8.GetBytes(iv);
        _delimiter = delimiter.ToString();
    }

    public string DecryptAndConcatenateSegments(string input)
    {
        try
        {
            var segments = input.Split(_delimiter.ToCharArray());
            var decryptedStrings = new List<string>();

            foreach (var segment in segments)
            {
                if (!IsBase64Encoded(segment))
                {
                    throw new ArgumentException("Invalid Base64 format.");
                }

                byte[] encryptedBytes = Convert.FromBase64String(segment);
                string decryptedString = Decrypt(encryptedBytes);
                decryptedStrings.Add(decryptedString);
            }

            return string.Join("", decryptedStrings);
        }
        catch (Exception ex)
        {
            LogError(ex.Message);
            throw;
        }
    }

    private bool IsBase64Encoded(string input)
    {
        try
        {
            Convert.FromBase64String(input);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private string Decrypt(byte[] encryptedBytes)
    {
        using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
        {
            des.Key = _key;
            des.IV = _iv;
            des.Mode = CipherMode.CBC;

            ICryptoTransform decryptor = des.CreateDecryptor();
            using (MemoryStream ms = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader sr = new StreamReader(cs))
                    {
                        return sr.ReadToEnd();
                    }
                }
            }
        }
    }

    private void LogError(string message)
    {
        // Implement logging logic here
        Console.WriteLine("Error: " + message);
    }
