using System.Text;

public class AESCBCDecryptionLibrary
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AESCBCDecryptionLibrary(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public byte[] Decrypt(byte[] encryptedData)
    {
        using (Aes aes = Aes.Create())
        {
            aes.KeySize = GetKeySize(_key);
            aes.BlockSize = 128; // AES block size is always 128 bits
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.IV = _iv;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        csDecrypt.CopyTo(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private int GetKeySize(byte[] key)
    {
        // Implement logic to determine the AES key size based on the key length
        if (key.Length == 16) return 128;
        else if (key.Length == 24) return 192;
        else if (key.Length == 32) return 256;
        else throw new ArgumentException("Invalid AES key size");
    }
}

