import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashSet;
import java.util.Set;

public class CustomDeserializer {

    private static final Set<String> CLASS_WHITELIST = new HashSet<>();

    static {
        // Initialize the whitelist with trusted class signatures
        CLASS_WHITELIST.add("com.example.TrustedClass1");
        CLASS_WHITELIST.add("com.example.TrustedClass2");
    }

    public static <T> T deserialize(byte[] data, Class<T> targetType) {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Object obj = ois.readObject();
            if (verifyClassSignature(obj.getClass().getName())) {
                return targetType.cast(obj);
            } else {
                System.err.println("Unauthorized class signature: " + obj.getClass().getName());
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
            return null;
        }
    }

    private static boolean verifyClassSignature(String className) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(className.getBytes());
            String hash = bytesToHex(digest);
            return CLASS_WHITELIST.contains(hash);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return false;
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // Example usage
    public static void main(String[] args) {
        byte[] serializedData = ...; // Assume this is the serialized data
        MyInterface result = CustomDeserializer.deserialize(serializedData, MyInterface.class);
        if (result != null) {
            result.doSomething();
        }
    }
}
