}

// Function to free the memory allocated for a packet
void free_packet(Packet *packet) {
    free(packet->payload);
    free(packet);
}

// Function to process incoming packets and store them in a queue
Packet* process_packets(int *incoming_packets, int num_packets) {
    Packet *head = NULL;
    Packet *tail = NULL;

    for (int i = 0; i < num_packets; i++) {
        Packet *new_packet = create_packet(incoming_packets[i]);
        if (head == NULL) {
            head = new_packet;
            tail = new_packet;
        } else {
            tail->next = new_packet;
            tail = new_packet;
        }
    }

    return head;
}

// Function to write packets to a file
void write_packets_to_file(Packet *head, const char *filename) {
    FILE *file = fopen(filename, "wb");
    Packet *current = head;

    while (current != NULL) {
        fwrite(current->payload, 1, current->header_size + strlen(current->payload), file);
        current = current->next;
    }

    fclose(file);
}

// Function to upload a file to a remote server via HTTP API
const char* upload_file_to_server(const char *filename) {
    // Simulate file uploading logic here
    return "http://example.com/uploadedfile";
}

// Main function to process packets, write them to a file, and upload the file
const char* process_and_upload_packets(int *incoming_packets, int num_packets) {
    Packet *packet_queue = process_packets(incoming_packets, num_packets);
    const char *filename = "processed_packets.bin";

    write_packets_to_file(packet_queue, filename);

    // Free allocated memory for packets
    Packet *current = packet_queue;
    while (current != NULL) {
        Packet *next = current->next;
        free_packet(current);
        current = next;
    }

    return upload_file_to_server(filename);
}
