const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');

const app = express();
const port = 3000;

// Middleware to parse JSON body
app.use(express.json());

// Function to read configuration files
async function readConfig(filePath) {
    try {
        const data = await fs.readFile(filePath, 'utf8');
        return JSON.parse(data);
    } catch (error) {
        if (error.code === 'ENOENT') {
            return {};
        }
        throw error;
    }
}

// Function to write configuration files
async function writeConfig(filePath, config) {
    await fs.writeFile(filePath, JSON.stringify(config, null, 2), 'utf8');
}

// Endpoint to list all configuration files in a directory
app.get('/api/configs', async (req, res) => {
    try {
        const dir = req.query.dir || './config';
        const files = await fs.readdir(dir);
        const configs = await Promise.all(files.map(file => readConfig(path.join(dir, file))));
        res.json(configs);
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Failed to list configurations' });
    }
});

// Endpoint to get a specific configuration
app.get('/api/config', async (req, res) => {
    try {
        const { file } = req.query;
        if (!file) {
            return res.status(400).json({ error: 'File parameter is required' });
        }
        const config = await readConfig(file);
        res.json(config);
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Failed to get configuration' });
    }
});

// Endpoint to set a key-value pair in a configuration
app.post('/api/config', async (req, res) => {
    try {
        const { file, key, value } = req.body;
        if (!file || !key || typeof value === 'undefined') {
            return res.status(400).json({ error: 'File, key, and value parameters are required' });
        }
        let config = await readConfig(file);
        config[key] = value;
        await writeConfig(file, config);
        res.json({ message: 'Key-value pair updated successfully' });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Failed to update configuration' });
    }
});

// Endpoint to delete a key from a configuration
app.delete('/api/config', async (req, res) => {
    try {
        const { file, key } = req.body;
        if (!file || !key) {
            return res.status(400).json({ error: 'File and key parameters are required' });
        }
        let config = await readConfig(file);
        delete config[key];
        await writeConfig(file, config);
        res.json({ message: 'Key deleted successfully' });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Failed to delete key from configuration' });
    }
});

// Start the server
app.listen(port, () => {
    console.log(`Server is running on http://localhost:${port}`);
});
