use clap::{App, Arg};
use tokio::sync::mpsc;
use reqwest::Client;
use prometheus::{self, CollectorRegistry, IntCounterVec};
use std::time::Duration;

#[tokio::main]
async fn main() {
    let matches = App::new("Data Processor")
        .arg(
            Arg::with_name("task")
                .short('t')
                .long("task")
                .value_name("TASK")
                .takes_value(true)
                .required(true),
        )
        .get_matches();

    let task = matches.value_of("task").unwrap();
    let client = Client::new();
    let registry = CollectorRegistry::new();
    prometheus::register_int_counter_vec!("task_failures", "Task failure count by type", &["type"], &registry).unwrap();
    prometheus::register_int_counter_vec!("task_duration_seconds", "Task execution time in seconds by type", &["type"], &registry).unwrap();

    let (tx, mut rx) = mpsc::channel(32);

    for _ in 0..4 {
        tokio::spawn(async move {
            while let Some(task_type) = rx.recv().await {
                process_task(&client, &task_type, &registry).await;
            }
        });
    }

    match task.parse::<Task>() {
        Ok(Task::FetchData) => tx.send("fetch_data".to_string()).await.unwrap(),
        Ok(Task::ProcessData) => tx.send("process_data".to_string()).await.unwrap(),
        Err(_) => eprintln!("Invalid task type"),
    }
}

#[derive(Debug)]
enum Task {
    FetchData,
    ProcessData,
}

impl std::str::FromStr for Task {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "fetchdata" => Ok(Task::FetchData),
            "processdata" => Ok(Task::ProcessData),
            _ => Err(format!("Unknown task type: {}", s)),
        }
    }
}

async fn process_task(client: &Client, task_type: &str, registry: &CollectorRegistry) {
    let start_time = std::time::Instant::now();
    let mut retries = 0;
    let max_retries = 5;
    let initial_delay = Duration::from_secs(1);

    while retries < max_retries {
        match client.get("https://api.example.com/data").send().await {
            Ok(mut response) if response.status().is_success() => {
                let data: serde_json::Value = response.json().await.unwrap();
                // Process data
                prometheus::register_int_counter_vec!("task_duration_seconds", "Task execution time in seconds by type", &["type"], registry).unwrap().get_or_create(&[task_type]).inc_by(start_time.elapsed().as_secs() as u64);
                break;
            }
            _ => {
                retries += 1;
                let delay = initial_delay * 2u32.pow(retries as u32);
                tokio::time::sleep(delay).await;
            }
        }
    }

    if retries == max_retries {
        prometheus::register_int_counter_vec!("task_failures", "Task failure count by type", &["type"], registry).unwrap().get_or_create(&[task_type]).inc();
    }
}
