    fn get_root_directory(&self) -> Result<String, String> {
        // Simulate network request and potential failure
        Ok("/base/directory".to_string())
    }
}

fn is_valid_directory_name(name: &str) -> bool {
    name.chars().all(|c| VALID_CHARS.contains(c))
}

fn create_directory_with_timeout(root_dir: &str, dir_name: &str) -> Result<(), String> {
    let mut retries = 0;
    while retries < MAX_RETRIES {
        match fs::create_dir(&Path::new(root_dir).join(dir_name)) {
            Ok(_) => return Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => return Ok(()),
            Err(e) => {
                if retries >= MAX_RETRIES - 1 {
                    return Err(format!("Failed to create directory after {} attempts: {}", retries + 1, e));
                }
                retries += 1;
                std::thread::sleep(RETRY_DELAY);
            }
        }
    }
    unreachable!()
}

fn set_environment_variable(dir_path: &str) -> Result<(), String> {
    if env::var("MY_DIR_VAR").is_ok() {
        return Ok(());
    }
    match env::set_var("MY_DIR_VAR", dir_path) {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("Failed to set environment variable: {}", e)),
    }
}

fn main() {
    let config_service = ConfigService {};
    let root_dir = match config_service.get_root_directory() {
        Ok(path) => path,
        Err(e) => panic!("Failed to retrieve root directory: {}", e),
    };

    let dir_name = "my_directory";
    if !is_valid_directory_name(dir_name) {
        panic!("Invalid directory name");
    }

    if create_directory_with_timeout(&root_dir, dir_name).is_err() {
        panic!("Failed to create directory");
    }

    if set_environment_variable(&format!("{}/{}", root_dir, dir_name)).is_err() {
        panic!("Failed to set environment variable");
    }
}
