#define MAX_INPUT_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int read_integers(int **array, size_t *size) {
    char input[MAX_INPUT_SIZE];
    if (!fgets(input, sizeof(input), stdin)) {
        return -1; // Error or end of file
    }

    int count = 0;
    const char delimiters[] = " \n";
    char *token = strtok(input, delimiters);
    while (token != NULL) {
        long value = strtol(token, NULL, 10);
        if ((value == LONG_MAX || value == LONG_MIN) && errno == ERANGE) {
            return -2; // Integer overflow
        }
        int *new_array = realloc(*array, (count + 1) * sizeof(int));
        if (!new_array) {
            free(*array);
            return -3; // Memory allocation failed
        }
        (*array)[count++] = value;
        token = strtok(NULL, delimiters);
    }

    *size = count;
    return 0;
}

int find_largest_integer(const int *array, size_t size) {
    if (size == 0) {
        return INT_MIN; // No valid input integers
    }
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initialize_NFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand();
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);
    }
}

int main() {
    int *array = NULL;
    size_t size;

    if (read_integers(&array, &size) < 0) {
        fprintf(stderr, "Error reading integers.\n");
        free(array);
        return EXIT_FAILURE;
    }

    int largest_integer = find_largest_integer(array, size);
    printf("Largest integer: %d\n", largest_integer);

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(array);
        return EXIT_FAILURE;
    }

    initialize_NFAPI_CRC_INDICATION_PDU_T(pdus, size);

    // Use the pdus array as needed

    free(pdus);
    free(array);
    return EXIT_SUCCESS;
}
