        offsets[i] = rand();
        keys[i] = rand();

        if (!RAND_bytes((unsigned char*)&records[i].value, sizeof(int))) {
            fprintf(stderr, "Failed to generate random number\n");
            exit(EXIT_FAILURE);
        }
    }
}

void manage_data_source(record* records, size_t count) {
    // Simulate data source management
    for (size_t i = 0; i < count; ++i) {
        records[i].value += rand() % 10;
    }
}

int main() {
    const size_t count = 1000;

    long* offsets = malloc(count * sizeof(long));
    int* keys = malloc(count * sizeof(int));
    record* records = malloc(count * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_digest(EVP_sha256());

    initialize_arrays(offsets, keys, records, count);
    manage_data_source(records, count);

    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
```

**Design Choices and Assumptions:**
- **PRNG Algorithm:** AES-256-CBC is used for its cryptographic strength and computational efficiency.
- **Data Source Management:** A simple simulation of data source management is implemented. In a real scenario, this would involve integrating with an external system or handling incoming data streams.
- **Memory Allocation:** Dynamic memory allocation is used to handle arrays of varying sizes.
- **Error Handling:** Basic error handling is included for memory allocation and cryptographic operations.

**Trade-offs:**
- **Performance vs. Cryptographic Strength:** AES-256-CBC offers a good balance, but for extremely high-security requirements, more robust algorithms might be necessary at the cost of computational efficiency.
- **Resource Usage:** The example assumes sufficient resources for memory allocation and cryptographic operations. For constrained environments, additional optimizations would be required.

This code provides a foundation for integrating cryptographic and data management functionalities in a high-performance application. Further enhancements can be made based on specific requirements and resource constraints.']

