namespace NetworkLib {

    class PacketProcessor {
    public:
        static std::mt19937 rng;

        PacketProcessor() : running(true) {
            for (int i = 0; i < numThreads; ++i) {
                workers.emplace_back([this] {
                    while (true) {
                        std::function<void()> task;
                        {
                            std::unique_lock<std::mutex> lock(queue_mutex);
                            condition.wait(lock, [this] { return !tasks.empty() || !running; });
                            if (!running && tasks.empty()) {
                                return;
                            }
                            task = std::move(tasks.front());
                            tasks.pop();
                        }
                        task();
                    }
                });
            }
        }

        ~PacketProcessor() {
            {
                std::unique_lock<std::mutex> lock(queue_mutex);
                running = false;
            }
            condition.notify_all();
            for (std::thread& worker : workers) {
                worker.join();
            }
        }

        static void processPacket(const Packet& packet) {
            // Implement packet processing logic here
            std::cout << "Processing packet of size: " << packet.size() << std::endl;
        }

    private:
        struct Packet {
            size_t size;
            char* data;
        };

        static const int numThreads = 4;

        std::vector<std::thread> workers;
        std::queue<std::function<void()>> tasks;
        std::mutex queue_mutex;
        std::condition_variable condition;
        std::atomic<bool> running;

        static Packet createPacket(size_t size) {
            Packet packet{size, new char[size]};
            // Populate packet data here
            return packet;
        }

        static void destroyPacket(Packet& packet) {
            delete[] packet.data;
        }
    };

    std::mt19937 PacketProcessor::rng;

}

