#define ARRAY_SIZE 1000

typedef struct {
    char username[50];
    char email[100];
    int preferences;
    unsigned long session_id;
} user_profile;

unsigned long linear_congruential_generator(unsigned long seed) {
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

unsigned long xorshift_generator(unsigned long x) {
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return x;
}

unsigned long custom_prng(unsigned long seed, int range) {
    unsigned long lcg = linear_congruential_generator(seed);
    unsigned long xs = xorshift_generator(lcg);
    return (xs % range) + 1; // Adjust to desired range
}

void initialize_data_structures(user_profile **profiles, long **long_array, char ***string_array, int seed, int range) {
    *profiles = (user_profile *)malloc(ARRAY_SIZE * sizeof(user_profile));
    *long_array = (long *)malloc(ARRAY_SIZE * sizeof(long));
    *string_array = (char **)malloc(ARRAY_SIZE * sizeof(char *));

    for (int i = 0; i < ARRAY_SIZE; i++) {
        (*profiles)[i].session_id = custom_prng(seed + i, range);
        sprintf((*profiles)[i].username, "user%d", i);
        sprintf((*profiles)[i].email, "user%d@example.com", i);
        (*profiles)[i].preferences = rand() % 10;
        (*long_array)[i] = (long)i * (i + 1);
        (*string_array)[i] = (char *)malloc(256 * sizeof(char));
        sprintf((*string_array)[i], "String data for user %d", i);
    }

    srand(time(NULL)); // Seed for rand()
}

void free_data_structures(user_profile **profiles, long **long_array, char ***string_array) {
    for (int i = 0; i < ARRAY_SIZE; i++) {
        free((*string_array)[i]);
    }
    free(*profiles);
    free(*long_array);
    free(*string_array);
}
