["```c
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    long* offsets;
    int* keys;
    int** records;
    size_t record_count;
    size_t capacity;
    pthread_mutex_t mutex;
} DataStructure;

uint32_t xorshift128plus(uint32_t *x, uint32_t *y) {
    uint32_t s0 = x[0];
    uint32_t s1 = y[0];
    uint32_t result = s0 + s1;

    s0 ^= s0 << 23;
    x[0] = s0 ^ s1 ^ (s0 >> 17);
    y[0] = s1 ^ (s1 << 17);

    return result;
}

int initialize_data_structure(DataStructure *ds, size_t initial_capacity) {
    ds->offsets = malloc(initial_capacity * sizeof(long));
    if (!ds->offsets) return -1;

    ds->keys = malloc(initial_capacity * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        return -1;
    }

    ds->records = malloc(initial_capacity * sizeof(int*));
    if (!ds->records) {
        free(ds->keys);
        free(ds->offsets);
        return -1;
    }

    for (size_t i = 0; i < initial_capacity; i++) {
        ds->records[i] = malloc(sizeof(int));
        if (!ds->records[i]) {
            for (size_t j = 0; j < i; j++) free(ds->records[j]);
            free(ds->records);
            free(ds->keys);
            free(ds->offsets);
            return -1;
        }
    }

    ds->record_count = initial_capacity;
    ds->capacity = initial_capacity;
    pthread_mutex_init(&ds->mutex, NULL);

    uint32_t seed[2] = {0x12345678, 0x9abcdef0};
    for (size_t i = 0; i < initial_capacity; i++) {
        *ds->records[i] = xorshift128plus(&seed[0], &seed[1]);
    }

    return 0;
}

void destroy_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->mutex);
    for (size_t i = 0; i < ds->record_count; i++) free(ds->records[i]);
    free(ds->records);
    free(ds->keys);
    free(ds->offsets);
    pthread_mutex_unlock(&ds->mutex);
    pthread_mutex_destroy(&ds->mutex);
}

void resize_data_structure(DataStructure *ds, size_t new_capacity) {
    pthread_mutex_lock(&ds->mutex);

    long* new_offsets = realloc(ds->offsets, new_capacity * sizeof(long));
    if (!new_offsets) goto cleanup;

    int* new_keys = realloc(ds->keys, new_capacity * sizeof(int));
    if (!new_keys) goto cleanup;

    int** new_records = realloc(ds->records, new_capacity * sizeof(int*));
    if (!new_records) goto cleanup;

    for (size_t i = ds->record_count; i < new_capacity; i++) {
        new_records[i] = malloc(sizeof(int));
        if (!new_records[i]) {
            for (size_t j = ds->record_count; j <= i; j++) free(new_records[j]);
            goto cleanup;
        }
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;

cleanup:
    pthread_mutex_unlock(&ds->mutex);
}

void add_record(DataStructure *ds, int key) {
    pthread_mutex_lock(&ds->mutex);

    if (ds->record_count >= ds->capacity) resize_data_structure(ds, ds->capacity * 2);

    ds->offsets[ds->record_count] = ds->record_count * sizeof(int);
    ds->keys[ds->record_count] = key;
    *(ds->records[ds->record_count]) = xorshift128plus(&key, &key);
    ds->record_count++;

    pthread_mutex_unlock(&ds->mutex);
}
```

**Rationale for PRNG Selection:**
The XORShift128+ algorithm was chosen due to its simplicity and good statistical properties. It is efficient in terms of both time and space complexity, making it suitable for resource-constrained environments. The generator's period length of \(2^{128} - 1\) ensures a long cycle before repeating, which is beneficial for generating unique identifiers. Additionally, XORShift generators are designed to be fast, making them well-suited for performance-critical applications like this one."]

