#define NFAPI_CRC_INDICATION_PDU_T int
#define RX_UE_INFORMATION_TAG int
#define RNTI int
#define CRC_INDICATION_REL8_TAG int
#define MAX_CONNECTIONS 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int establishConnection(int N, const char* command) {
    if (N > MAX_CONNECTIONS || N <= 0) {
        printf("Error: Invalid number of connections\n");
        return 0;
    }

    NFAPI_CRC_INDICATION_PDU_T *connections = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!connections) {
        printf("Error: Memory allocation failed\n");
        return 0;
    }

    for (int i = 0; i < N; i++) {
        connections[i].ue_info_tag = rand() % 1000;
        connections[i].rnti = rand() % 1000;
        connections[i].crc_indication_rel8_tag = rand() % 1000;
        connections[i].crcflag = (rand() % 2 == 0) ? 1 : 0;
    }

    pid_t pid = fork();
    if (pid < 0) {
        printf("Error: Fork failed\n");
        free(connections);
        return 0;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        _exit(1); // Only reached if execl fails
    }

    int status;
    wait(&status);
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        printf("Error: Command execution failed\n");
        free(connections);
        return 0;
    }

    free(connections);
    return 1;
}
