['```c
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct packet {
    char header[64];
    size_t payload_size;
    char *payload;
    struct packet *next, *prev;
} Packet;

typedef struct {
    Packet *head, *tail;
    pthread_mutex_t lock;
    // Memory pool implementation
} PacketList;

void init_packet_list(PacketList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Packet* create_packet(const char *header, size_t payload_size, const char *payload) {
    if (payload_size > MAX_PACKET_SIZE) return NULL;

    Packet *p = malloc(sizeof(Packet));
    if (!p) return NULL;

    p->payload_size = payload_size;
    p->payload = malloc(payload_size);
    if (!p->payload) {
        free(p);
        return NULL;
    }

    strncpy(p->header, header, sizeof(p->header));
    memcpy(p->payload, payload, payload_size);

    return p;
}

void add_packet(PacketList *list, Packet *p) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = list->tail = p;
    } else {
        list->tail->next = p;
        p->prev = list->tail;
        list->tail = p;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroy_packet(Packet *p) {
    free(p->payload);
    free(p);
}

void destroy_packet_list(PacketList *list) {
    Packet *current = list->head;
    while (current != NULL) {
        Packet *next = current->next;
        destroy_packet(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
```

This code provides a basic implementation of a thread-safe, scalable doubly linked list for managing network packets. It includes functions to initialize the list, create packets with header and payload validation, add packets to the list, and destroy the list and its contents properly. The use of mutexes ensures that operations on the list are safe from concurrent access.']

