int findLargest(int* arr, int size) {
    if (size == 0) {
        printf("The list is empty.\n");
        return -1; // Assuming -1 is not a valid integer value
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function to read integers from input, store them in a dynamic array,
// and find the largest integer
void processIntegers() {
    int* numbers = NULL;
    int size = 0;
    char ch;

    printf("Enter integers separated by spaces or press Ctrl+D (EOF) to finish:\n");

    // Read integers from input
    while (scanf("%d", &ch) == 1) {
        // Resize array dynamically
        numbers = realloc(numbers, (size + 1) * sizeof(int));
        if (numbers == NULL) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        numbers[size++] = ch;
    }

    // Check for non-integer input
    if (!feof(stdin)) {
        printf("Invalid input detected. Please enter only integers.\n");
        while ((ch = getchar()) != '\n' && ch != EOF); // Clear the buffer
    } else if (size == 0) {
        printf("No integers entered.\n");
    } else {
        // Find and print the largest integer
        int largest = findLargest(numbers, size);
        printf("The largest integer is: %d\n", largest);
    }

    // Free dynamically allocated memory
    free(numbers);
}

int main() {
    processIntegers();
    return 0;
}
