        return -1; // IP too long
    }

    if (inet_pton(AF_INET, ip, config->ip) == 1) {
        // IPv4
        return 0;
    } else if (inet_pton(AF_INET6, ip, config->ip) == 1) {
        // IPv6
        return 0;
    }

    return -2; // Invalid IP format
}

int validate_subnet_mask(const char *mask, NetworkConfig *config) {
    struct in_addr subnet_mask_struct;
    if (inet_pton(AF_INET, mask, &subnet_mask_struct) == 1) {
        memcpy(config->subnet_mask, &subnet_mask_struct.s_addr, sizeof(subnet_mask_struct.s_addr));
        return 0;
    }

    return -3; // Invalid subnet mask
}

int update_network_config(const char *ip, const char *mask, NetworkConfig *config) {
    int result = validate_ip(ip, config);
    if (result != 0) {
        printf("Invalid IP address: %s\n", ip);
        return result;
    }

    if (mask != NULL) {
        result = validate_subnet_mask(mask, config);
        if (result != 0) {
            printf("Invalid subnet mask: %s\n", mask);
            return result;
        }
