['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.List;

public class HashProcessor {
    private static final int MAX_MAP_SIZE = 10000;
    private static final long CLEAR_INTERVAL = 30000; // 30 seconds
    private ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();
    private Thread cleanerThread;
    private boolean running;

    public HashProcessor() {
        startCleaner();
    }

    public void processBatch(List<String> strings) {
        for (String str : strings) {
            try {
                String md5Hash = generateMD5(str);
                hashMap.putIfAbsent(md5Hash, str);
                if (hashMap.size() > MAX_MAP_SIZE) {
                    cleanUp();
                }
            } catch (NoSuchAlgorithmException e) {
                e.printStackTrace();
            }
        }
    }

    private String generateMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void startCleaner() {
        running = true;
        cleanerThread = new Thread(() -> {
            while (running) {
                try {
                    Thread.sleep(CLEAR_INTERVAL);
                    cleanUp();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        cleanerThread.start();
    }

    private void cleanUp() {
        hashMap.clear();
    }

    public void stopProcessing() {
        running = false;
        try {
            cleanerThread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
