#define MAX_CRCFLAG 1

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* initialize_and_populate_pdu(int* count, sem_t** semaphore) {
    if (*count <= 0) {
        return NULL;
    }

    *semaphore = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, *count);
    if (*semaphore == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu_list == NULL) {
        perror("Failed to allocate memory for PDU list");
        sem_close(*semaphore);
        sem_unlink("/my_semaphore");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < *count; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
        pdu_list[i].CRC_INDICATION_REL8_TAG = MIN_CRCFLAG + rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1);
    }

    return pdu_list;
}

void cleanup(int* count, NFAPI_CRC_INDICATION_PDU_T** pdu_list, sem_t* semaphore) {
    if (*count > 0 && *pdu_list != NULL) {
        free(*pdu_list);
        *pdu_list = NULL;
    }
    if (semaphore != NULL) {
        sem_close(semaphore);
        sem_unlink("/my_semaphore");
    }
}

