#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PDU_COUNT 1000
#define PENDING_QUEUE_LIMIT 10

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t pdu_count;
    size_t max_pdu_count;
    sem_t semaphore;
} PduManager;

void initialize_pdu_manager(PduManager *manager, size_t initial_max_pdu_count) {
    manager->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_max_pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        perror("Memory allocation failed for PDU list");
        exit(EXIT_FAILURE);
    }
    manager->pdu_count = 0;
    manager->max_pdu_count = initial_max_pdu_count;
    sem_init(&manager->semaphore, 0, initial_max_pdu_count);
}

void destroy_pdu_manager(PduManager *manager) {
    free(manager->pdu_list);
    sem_destroy(&manager->semaphore);
}

int add_pdu_to_queue(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    int result = sem_wait(&manager->semaphore);
    if (result != 0) {
        perror("Failed to wait on semaphore");
        return -1;
    }

    if (manager->pdu_count >= manager->max_pdu_count) {
        fprintf(stderr, "PDU queue is full\n");
        sem_post(&manager->semaphore);
        return -1;
    }

    manager->pdu_list[manager->pdu_count++] = pdu;

    sem_post(&manager->semaphore);
    return 0;
}

void *network_data_handler(void *arg) {
    PduManager *manager = (PduManager *)arg;
    NFAPI_CRC_INDICATION_PDU_T new_pdu; // Populate this with actual data

    if (add_pdu_to_queue(manager, new_pdu) == 0) {
        printf("Successfully added PDU to queue\n");
    } else {
        printf("Failed to add PDU to queue\n");
    }

    return NULL;
}

int main() {
    PduManager pdu_manager;
    initialize_pdu_manager(&pdu_manager, MAX_PDU_COUNT);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, network_data_handler, &pdu_manager);
    pthread_create(&thread2, NULL, network_data_handler, &pdu_manager);

    pthread_join(thread1, NULL);
