#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct PacketHeader {
    int packetSize;
    char sourceIP[16];
    uint32_t timestamp;
} PacketHeader;

typedef struct Packet {
    PacketHeader header;
    char *payload;
    struct Packet *prev, *next;
    struct PacketList *list;
} Packet;

typedef struct PacketList {
    pthread_mutex_t lock;
    Packet *head, *tail;
    int count;
} PacketList;

void initPacketList(PacketList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->count = 0;
}

void insertPacketInOrder(PacketList *list, Packet *packet) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || packet->header.timestamp < list->head->header.timestamp) {
        packet->next = list->head;
        packet->prev = NULL;
        if (list->head != NULL) list->head->prev = packet;
        list->head = packet;
    } else {
        Packet *current = list->head;
        while (current->next != NULL && current->next->header.timestamp <= packet->header.timestamp) {
            current = current->next;
        }
        packet->next = current->next;
        packet->prev = current;
        if (current->next != NULL) current->next->prev = packet;
        current->next = packet;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

Packet* retrievePacketBySourceIP(PacketList *list, const char *sourceIP) {
    pthread_mutex_lock(&list->lock);
    Packet *current = list->head;
    while (current != NULL) {
        if (strcmp(current->header.sourceIP, sourceIP) == 0) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

