#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NFAPI_STRUCTURES 1000
#define MAX_SERVERS 5

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxue_info_tag;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int properties;
    struct Node* next[MAX_SERVERS];
} Node;

typedef struct {
    Node** nodes;
    int size;
    pthread_mutex_t mutex;
} GraphDatabase;

GraphDatabase* create_graph_database() {
    GraphDatabase* db = (GraphDatabase*)malloc(sizeof(GraphDatabase));
    if (!db) return NULL;

    db->nodes = (Node**)malloc(MAX_NFAPI_STRUCTURES * sizeof(Node*));
    if (!db->nodes) {
        free(db);
        return NULL;
    }

    for (int i = 0; i < MAX_NFAPI_STRUCTURES; i++) {
        db->nodes[i] = NULL;
    }
    db->size = 0;

    pthread_mutex_init(&db->mutex, NULL);

    return db;
}

void add_node(GraphDatabase* db, int properties) {
    pthread_mutex_lock(&db->mutex);
    if (db->size >= MAX_NFAPI_STRUCTURES) {
        pthread_mutex_unlock(&db->mutex);
        return; // Handle error: max nodes reached
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&db->mutex);
        return; // Handle error: memory allocation failed
    }

    new_node->properties = properties;
    for (int i = 0; i < MAX_SERVERS; i++) {
        new_node->next[i] = NULL;
    }

    db->nodes[db->size++] = new_node;
    pthread_mutex_unlock(&db->mutex);
}

void add_edge(GraphDatabase* db, int from, int to) {
    pthread_mutex_lock(&db->mutex);
    if (from < 0 || from >= db->size || to < 0 || to >= db->size) {
        pthread_mutex_unlock(&db->mutex);
        return; // Handle error: invalid indices
    }

    if (!db->nodes[from] || !db->nodes[to]) {
        pthread_mutex_unlock(&db->mutex);
        return; // Handle error: node does not exist
    }

    for (int i = 0; i < MAX_SERVERS; i++) {
        if (i % 2 == 0) { // Example partitioning logic
            db->nodes[from]->next[i] = db->nodes[to];
        } else {
            db->nodes[to]->next[i] = db->nodes[from];
        }
    }

    pthread_mutex_unlock(&db->mutex);
}

void free_graph_database(GraphDatabase* db) {
    for (int i = 0; i < db->size; i++) {
        Node* node = db->nodes[i];
        while (node) {
            Node* next = node->next[0]; // Example: only one server
            free(node);
            node = next;
        }
    }

    free(db->nodes);
    pthread_mutex_destroy(&db->mutex);
    free(db);
}

int main() {
    GraphDatabase* db = create_graph_database();
    if (!db) return 1;

    add_node(db, 42);
    add_node(db, 99);

    add_edge(db, 0, 1);

    free_graph_database(db);

    return 0;
}
