void addVertex(GraphDB* db) {
    if (db->node_count >= MAX_NFAPDU) {
        fprintf(stderr, "Graph size limit reached\n");
        return;
    }

    GraphNode* new_node = (GraphNode*)calloc(1, sizeof(GraphNode));
    if (!new_node) return;

    new_node->id = db->node_count++;
    char* props = (char*)calloc(MAX_PROPERTY_SIZE, sizeof(char));
    snprintf(props, MAX_PROPERTY_SIZE, "Property%d", rand() % 100);
    new_node->properties = props;
    new_node->next = NULL;

    for (int i = 0; i < db->node_count - 1; i++) {
        if (!db->nodes[i]->next) {
            db->nodes[i]->next = new_node;
            return;
        }
        db->nodes[i] = db->nodes[i]->next;
    }
}

void freeNFAPDUs(NFAPI_CRC_INDICATION_PDU_T* pfu, int N) {
    if (pfu) free(pfu);
}

void freeGraph(GraphDB* db) {
    if (db->nodes) {
        for (int i = 0; i < db->node_count; i++) {
            GraphNode* node = db->nodes[i];
            while (node) {
                GraphNode* next = node->next;
                free(node->properties);
                free(node);
                node = next;
            }
        }
        free(db->nodes);
    }
    free(db);
}
