typedef struct {
    int length;
} PacketHeader;

PacketHeader* processNetworkPackets(int headerCount, ...) {
    if (headerCount <= 0 || headerCount > MAX_HEADERS) {
        return NULL;
    }

    PacketHeader *headers = (PacketHeader*)malloc(headerCount * sizeof(PacketHeader));
    if (!headers) {
        return NULL;
    }

    va_list args;
    va_start(args, headerCount);

    for (int i = 0; i < headerCount; i++) {
        headers[i].length = va_arg(args, int);
    }

    va_end(args);

    // Simulate fetching packet data from a NIC
    int totalLength = 0;
    for (int i = 0; i < headerCount; i++) {
        totalLength += headers[i].length;
    }

    if (totalLength <= 0 || totalLength > MAX_HEADERS) {
        free(headers);
        return NULL;
    }

    char *packetBuffer = (char*)malloc(totalLength);
    if (!packetBuffer) {
        free(headers);
        return NULL;
    }

    // Simulate reading packet data into the buffer
    for (int i = 0; i < headerCount; i++) {
        // Assuming each packet has a dummy data pattern
        for (int j = 0; j < headers[i].length; j++) {
            packetBuffer[j] = 'A' + (i % 26);
        }
    }

    return headers;
}

void freePacketData(PacketHeader *headers, char *buffer) {
    if (headers) {
        free(headers);
    }
    if (buffer) {
        free(buffer);
    }
}

