#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 100
#define HEADER_SIZE sizeof(struct packet_header)

struct packet_header {
    int length;
};

int fetch_packet_headers(struct packet_header *headers, int *num_packets) {
    // Simulate fetching packet headers from an external data source
    srand(time(NULL));
    *num_packets = rand() % (MAX_PACKETS + 1);
    for (int i = 0; i < *num_packets; i++) {
        headers[i].length = rand() % 1500; // Simulate random packet length
    }
    return 0;
}

void* concatenate_packets(struct packet_header *headers, int num_packets, size_t *total_size) {
    if (num_packets <= 0 || headers == NULL) {
        return NULL;
    }

    size_t total_length = 0;
    for (int i = 0; i < num_packets; i++) {
        total_length += headers[i].length;
    }

    // Allocate buffer with robust allocation logic to prevent integer overflows
    if ((total_length / num_packets) != (headers[0].length)) {
        fprintf(stderr, "Error: Integer overflow detected\n");
        return NULL;
    }

    *total_size = total_length + num_packets * HEADER_SIZE; // Include space for header structures
    void *buffer = malloc(*total_size);
    if (buffer == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    char *ptr = buffer;
    for (int i = 0; i < num_packets; i++) {
        memcpy(ptr, &headers[i], HEADER_SIZE); // Copy header structure
        ptr += HEADER_SIZE;
        memcpy(ptr, headers[i].length, headers[i].length); // Copy packet data
        ptr += headers[i].length;
    }

    return buffer;
}

int main() {
    struct packet_header headers[MAX_PACKETS];
    int num_packets;
    size_t total_size;

    if (fetch_packet_headers(headers, &num_packets) != 0) {
        fprintf(stderr, "Error fetching packet headers\n");
        return 1;
    }

    void *buffer = concatenate_packets(headers, num_packets, &total_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error concatenating packets\n");
        return 1;
    }

    printf("Total buffer size: %zu bytes\n", total_size);

    free(buffer); // Free allocated memory

    return 0;
}
