#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IMAGE_RECORDS 1024

typedef struct {
    int width;
    int height;
    char format[50];
} ImageMetadata;

typedef struct {
    ImageMetadata *metadata[MAX_IMAGE_RECORDS];
    int count;
    pthread_mutex_t lock;
} ImagePool;

ImagePool *create_image_pool() {
    ImagePool *pool = (ImagePool *)malloc(sizeof(ImagePool));
    if (!pool) return NULL;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_image_pool(ImagePool *pool) {
    for (int i = 0; i < pool->count; ++i) {
        free(pool->metadata[i]);
    }
    free(pool);
}

void add_image_record(ImagePool *pool, ImageMetadata *record) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < MAX_IMAGE_RECORDS) {
        pool->metadata[pool->count++] = record;
    } else {
        printf("Image pool is full!\n");
    }
    pthread_mutex_unlock(&pool->lock);
}

int calculate_buffer_size(ImagePool *pool) {
    int total_pixels = 0;
    for (int i = 0; i < pool->count; ++i) {
        if (strcmp(pool->metadata[i]->format, "JPEG") == 0) {
            total_pixels += pool->metadata[i]->width * pool->metadata[i]->height * 3 / 2;
        } else if (strcmp(pool->metadata[i]->format, "PNG") == 0) {
            total_pixels += pool->metadata[i]->width * pool->metadata[i]->height * 4;
        }
    }
    return total_pixels;
}

void* ingest_data(void *arg) {
    ImagePool *pool = (ImagePool *)arg;
    // Simulate data ingestion from a digital camera
    ImageMetadata *record = malloc(sizeof(ImageMetadata));
    if (!record) return NULL;
    record->width = 1920;
    record->height = 1080;
    strcpy(record->format, "JPEG");
    add_image_record(pool, record);
    return NULL;
}

int main() {
    ImagePool *pool = create_image_pool();
    if (!pool) {
        printf("Failed to create image pool!\n");
        return 1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, ingest_data, pool)) {
            printf("Failed to create thread %d\n", i);
            break;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    int buffer_size = calculate_buffer_size(pool);
    printf("Total buffer size: %d bytes\n", buffer_size);

    destroy_image_pool(pool);
    return 0;
}
```

This code defines a simple image processing system with the required features. It includes functions for creating and destroying an image pool, adding image records to the pool, calculating the buffer size based on the image metadata, and simulating data ingestion from multiple digital cameras. The use of mutexes ensures thread safety during concurrent operations.']

