// Define a structure for the packet header
typedef struct PacketHeader {
    size_t payloadSize;
} PacketHeader;

// Define a structure for the linked list node
typedef struct ListNode {
    PacketHeader *header;
    char *payload;
    struct ListNode *next;
} ListNode;

// Function to create a new list node
ListNode* createListNode(size_t payloadSize) {
    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    node->header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (!node->header) {
        free(node);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    node->payload = (char*)malloc(payloadSize);
    if (!node->payload) {
        free(node->header);
        free(node);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    node->header->payloadSize = payloadSize;
    node->next = NULL;

    return node;
}

// Function to add a packet to the linked list
void addPacketToList(ListNode **head, size_t payloadSize) {
    ListNode *newNode = createListNode(payloadSize);
    if (!newNode) {
        fprintf(stderr, "Failed to create new packet node\n");
        return;
    }

    newNode->next = *head;
    *head = newNode;
}

// Function to process network packets and add them to a linked list
void processNetworkPackets(ListNode **head, size_t maxPacketSize, int maxPackets) {
    for (int i = 0; i < maxPackets; i++) {
        // Simulate packet processing logic here
        size_t payloadSize;
        // Assume payloadSize is obtained from network source
        // payloadSize should be validated to prevent buffer overflows

        if (payloadSize > maxPacketSize) {
            fprintf(stderr, "Payload size exceeds maximum allowed\n");
            continue;
        }

        addPacketToList(head, payloadSize);
    }
}

// Example usage
int main() {
    ListNode *packetList = NULL;

    processNetworkPackets(&packetList, 1024, 5); // Process up to 5 packets with a max size of 1024 bytes

    // Free the allocated memory
    while (packetList) {
        ListNode *temp = packetList;
        free(temp->header);
        free(temp->payload);
        free(temp);
        packetList = temp->next;
    }

    return 0;
}
