    size_t used_size;
} PacketResultsArray;

void initialize_packet_results_array(PacketResultsArray* array, size_t initial_size) {
    array->results = (PacketProcessingResult*)malloc(initial_size * sizeof(PacketProcessingResult));
    if (!array->results) {
        perror("Failed to allocate memory for packet results");
        exit(EXIT_FAILURE);
    }
    array->allocated_size = initial_size;
    array->used_size = 0;
}

void add_packet_result(PacketResultsArray* array, int packet_id, size_t payload_length, char status) {
    if (array->used_size == array->allocated_size) {
        size_t new_size = array->allocated_size * 2;
        PacketProcessingResult* new_results = (PacketProcessingResult*)realloc(array->results, new_size * sizeof(PacketProcessingResult));
        if (!new_results) {
            perror("Failed to reallocate memory for packet results");
            exit(EXIT_FAILURE);
        }
        array->results = new_results;
        array->allocated_size = new_size;
    }
    array->results[array->used_size].packet_id = packet_id;
    array->results[array->used_size].payload_length = payload_length;
    array->results[array->used_size].status = status;
    array->used_size++;
}

