NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t num_elements) {
    static size_t total_allocated = 0;
    static size_t recent_allocations[10] = {0};
    static int alloc_index = 0;

    // Calculate the available system memory
    FILE* mem_info = popen("free -m | awk '/Mem:/ {print $2}'", "r");
    if (!mem_info) {
        log_error("Failed to execute free command");
        return NULL;
    }
    unsigned long total_memory;
    fscanf(mem_info, "%lu", &total_memory);
    pclose(mem_info);

    // Calculate the maximum allowable memory usage
    size_t max_usage = (size_t)(total_memory * 0.5);

    // Check if the total allocated memory exceeds the limit
    if ((total_allocated + num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > max_usage) {
        log_error("Memory allocation would exceed allowed limit");
        return NULL;
    }

    // Implement a sliding window approach to adjust maximum allowable memory usage dynamically
    total_allocated += num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    recent_allocations[alloc_index] = num_elements;
    alloc_index = (alloc_index + 1) % 10;

