ImageFrame* create_image_pipeline(int N) {
    if (N <= 0 || N > MAX_FRAMES) {
        return NULL;
    }

    size_t totalSize = N * sizeof(ImageFrame);
    ImageFrame* frames = malloc(totalSize);
    if (!frames) {
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        frames[i].header.width = rand() % 1024 + 1;
        frames[i].header.height = rand() % 768 + 1;
        snprintf(frames[i].header.format, sizeof(frames[i].header.format), "RGB%d", (frames[i].header.width * frames[i].header.height) % 3);
        size_t dataSize = frames[i].header.width * frames[i].header.height * 3; // Simplified for RGB
        frames[i].imageData = malloc(dataSize);
        if (!frames[i].imageData) {
            free_frames(frames, i);
            return NULL;
        }
    }

    return frames;
}

void free_frames(ImageFrame* frames, int N) {
    for (int i = 0; i < N; ++i) {
        free(frames[i].imageData);
    }
    free(frames);
}

