import os
import subprocess
from cryptography.fernet import Fernet

def install_dependency(package):
    try:
        subprocess.check_call(["pip", "install", package])
    except subprocess.CalledProcessError:
        print(f"Failed to install {package}")

def read_template(template_path):
    with open(template_path, 'r') as file:
        return file.read()

def write_config(config_path, config_data):
    with open(config_path, 'w') as file:
        file.write(config_data)

def encrypt_passphrase(passphrase, key_length=32):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_passphrase = cipher_suite.encrypt(passphrase.encode())
    return key, encrypted_passphrase

def replace_placeholders(template, config_dict):
    for key, value in config_dict.items():
        template = template.replace(f"{{{key}}}", str(value))
    return template

def validate_ssh_config(config_path):
    try:
        subprocess.check_call(["ssh", "-F", config_path, "localhost", "echo", "Test"])
        print("SSH configuration is valid.")
    except subprocess.CalledProcessError as e:
        print(f"Failed to validate SSH configuration: {e}")

def apply_ssh_config(config_path):
    try:
        subprocess.run(["systemctl", "restart", "sshd"], check=True)
        print("SSH configuration applied successfully.")
    except subprocess.CalledProcessError as e:
        print(f"Failed to apply SSH configuration: {e}")

def main():
    template_path = 'ssh_config_template'
    config_path = 'custom_ssh_config'

    config_dict = {
        'ServerName': os.getenv('SERVER_NAME', 'example.com'),
        'Port': int(os.getenv('PORT', 22)),
        'EncryptionKey': os.getenv('ENCRYPTION_KEY', 'default_key')
    }

    template = read_template(template_path)
    config_data = replace_placeholders(template, config_dict)
    write_config(config_path, config_data)

    key, encrypted_passphrase = encrypt_passphrase(os.getenv('PASSPHRASE', 'default_passphrase'))
    with open('encrypted_passphrase.key', 'wb') as file:
        file.write(key)
    with open('encrypted_passphrase.enc', 'wb') as file:
        file.write(encrypted_passphrase)

    validate_ssh_config(config_path)
    apply_ssh_config(config_path)

if __name__ == "__main__":
    main()
```

