// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    // RX_UE_INFORMATION_TAG tag;
    int RNTI;
    // CRC_INDICATION_REL8_TAG crcTag;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Function to create a new node with random CRCFLAG
Node* createNewNode(int RNTI) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newNode->data.RNTI = RNTI;
    newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node into the linked list
bool insertNode(Node** head, int RNTI) {
    Node* newNode = createNewNode(RNTI);
    if (newNode == NULL) {
        // Handle memory allocation failure
        return false;
    }
    newNode->next = *head;
    *head = newNode;
    return true;
}

// Function to delete a node from the linked list
bool deleteNode(Node** head, int RNTI) {
    Node* current = *head;
    Node* prev = NULL;

    if (current != NULL && current->data.RNTI == RNTI) {
        *head = current->next; // Change head
        free(current);          // free old head
        return true;
    }

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        // Node not found
        return false;
    }

    prev->next = current->next; // Unlink the node from linked list
    free(current);              // Free memory
    return true;
}

// Function to free all allocated memory in the linked list
void freeList(Node** head) {
    Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
