int safe_mul(int a, int b) {
    if (b > 0 && INT_MAX / a < b) {
        log_error("Integer overflow in multiplication");
        return -1;
    }
    return a * b;
}

int safe_add(int a, int b) {
    if (b > 0 && INT_MAX - a < b) {
        log_error("Integer overflow in addition");
        return -1;
    }
    return a + b;
}

int calculate_total_memory_size(int num_structs) {
    const size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int total_size = safe_mul(num_structs, struct_size);
    if (total_size == -1) return -1;

    return total_size / 1024; // Convert bytes to kilobytes
}

int initialize_structures(int* num_structs, int memory_budget) {
    if (*num_structs < 1 || *num_structs > MAX_STRUCTS) {
        log_error("Invalid number of structures");
        return -1;
    }

    int total_memory = calculate_total_memory_size(*num_structs);
    if (total_memory == -1 || total_memory > memory_budget) {
        log_error("Memory budget exceeded");
        *num_structs = safe_div(memory_budget, struct_size);
        if (*num_structs == -1) return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structs) {
        log_error("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < *num_structs; ++i) {
        structs[i].rx_ue_information = (NFAPI_RX_UE_INFORMATION_T*)malloc(sizeof(NFAPI_RX_UE_INFORMATION_T));
        if (!structs[i].rx_ue_information) {
            log_error("Memory allocation failed for RX_UE_INFORMATION_TAG");
            free(structs);
            return -1;
        }
        structs[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    *num_structs = *num_structs > 0 ? *num_structs : 1; // Ensure at least one structure is initialized
    return 0;
}

int main() {
    int num_structs = 500; // Example input from external data source
    int memory_budget = MEMORY_BUDGET;

    if (initialize_structures(&num_structs, memory_budget) == 0) {
        printf("Successfully initialized %d structures within the budget.\n", num_structs);
    }

    return 0;
}
