void manageForwardList(std::forward_list<std::string>& list, const std::string& target, const std::string& insert) {
    auto it = list.before_begin();
    for (; it != list.end(); ++it) {
        if (*it == target) {
            list.insert_after(it, insert);
            return;
        }
    }
    list.push_back(insert);
}

