#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <pthread.h>

#define MAX_TASKS 1000
#define TASK_SIZE sizeof(ImageProcessingTask)
#define CACHE_LINE_SIZE 64

typedef struct {
    int task_id;
    int width;
    int height;
    long file_size;
} ImageProcessingTask;

typedef struct {
    ImageProcessingTask tasks[MAX_TASKS];
    int count;
    pthread_mutex_t lock;
} TaskManager;

void initialize_task_manager(TaskManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_task(TaskManager *manager, va_list args) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_TASKS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Task limit reached
    }
    ImageProcessingTask task = { va_arg(args, int), va_arg(args, int),
                                 va_arg(args, int), va_arg(args, long) };
    manager->tasks[manager->count++] = task;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

long calculate_total_memory(TaskManager *manager) {
    long total_memory = manager->count * TASK_SIZE;
    // Align to cache line size for better performance
    total_memory = (total_memory + CACHE_LINE_SIZE - 1) & ~(CACHE_LINE_SIZE - 1);
    return total_memory;
}

void handle_task_manager(TaskManager *manager, ...) {
    va_list args;
    va_start(args, manager);
    int result = add_task(manager, args);
    va_end(args);
    if (result == -1) {
        printf("Task limit reached. Unable to add more tasks.\n");
    } else {
        long total_memory = calculate_total_memory(manager);
        printf("Total memory consumed: %ld bytes\n", total_memory);
    }
}

int main() {
    TaskManager manager;
    initialize_task_manager(&manager);

    // Example usage
    handle_task_manager(&manager, 1, 800, 600, 500000L); // Add task with ID 1 and dimensions width=800, height=600, file_size=500KB

    return 0;
}
