#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_HEADERS_PER_PACKET 100
#define MAX_TOTAL_HEADERS 5000

typedef struct Header {
    int id;
    char data[256];
} Header;

typedef struct Packet {
    int id;
    Header* headers[MAX_HEADERS_PER_PACKET];
    int header_count;
    char source[64];
    char destination[64];
} Packet;

Packet** packet_list = NULL;
int packet_count = 0;
int total_headers = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_packet(int id, Header* headers, int header_count, const char* source, const char* destination) {
    pthread_mutex_lock(&lock);

    if (packet_count >= MAX_TOTAL_HEADERS || total_headers + header_count > MAX_TOTAL_HEADERS) {
        fprintf(stderr, "Memory overflow error\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet));
    new_packet->id = id;
    for (int i = 0; i < header_count; i++) {
        new_packet->headers[i] = (Header*)malloc(sizeof(Header));
        *new_packet->headers[i] = headers[i];
    }
    new_packet->header_count = header_count;
    strcpy(new_packet->source, source);
    strcpy(new_packet->destination, destination);

    packet_list[packet_count++] = new_packet;
    total_headers += header_count;

    pthread_mutex_unlock(&lock);
}

void delete_packets(const int* ids, int count) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; i++) {
        for (int j = 0; j < packet_count; j++) {
            if (packet_list[j]->id == ids[i]) {
                for (int k = 0; k < packet_list[j]->header_count; k++) {
                    free(packet_list[j]->headers[k]);
                }
                free(packet_list[j]);
                for (int l = j; l < packet_count - 1; l++) {
                    packet_list[l] = packet_list[l + 1];
                }
                packet_count--;
                total_headers -= packet_list[j]->header_count;
                break;
            }
        }
    }

    pthread_mutex_unlock(&lock);
}
```

This code provides a basic structure for managing network packets with headers in a multi-threaded environment. It includes functions to add and delete packets, handling concurrency with mutex locks and ensuring safe memory management. The solution is designed to manage limited system resources and scale effectively under high load by avoiding buffer overflows and excessive memory consumption.']

