#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_MEMORY_KB 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    size_t max_size;
} ListT;

ListT* list_create(size_t initial_capacity) {
    ListT* list = (ListT*)malloc(sizeof(ListT));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for ListT\n");
        return NULL;
    }
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Memory allocation failed for data array\n");
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    list->max_size = UINT_MAX / (initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return list;
}

void list_destroy(ListT* list) {
    if (!list) return;
    free(list->data);
    free(list);
}

bool list_append(ListT* list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, bool CRC_INDICATION_REL8_TAG) {
    if (list->size >= list->max_size) {
        fprintf(stderr, "Maximum list size reached\n");
        return false;
    }
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > list->max_size) {
            new_capacity = list->max_size;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Memory allocation failed for new data array\n");
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->size].RNTI = RNTI;
    list->data[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;
    return true;
}

bool list_serialize(ListT* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filename);
        return false;
    }
    size_t written = fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->size, file);
    fclose(file);
    return written == list->size;
}

int main() {
    ListT* list = list_create(100);
    if (!list) return 1;

    for (size_t i = 0; i < 200; i++) {
        bool success = list_append(list, i, i * 100, i % 2 == 0);
        if (!success) {
            fprintf(stderr, "Failed to append element at index %zu\n", i);
            break;
        }
    }

    if (list->size > 150) {
        printf("Warning: Memory limit reached, only appended %zu elements out of %zu\n", list->size, 200);
    }

    bool serialized = list_serialize(list, "crc_indication_list.bin");
    if (!serialized) {
        fprintf(stderr, "Failed to serialize the list\n");
    } else {
        printf("List successfully serialized to crc_indication_list.bin\n");
    }

    list_destroy(list);
    return 0;
}
