#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>

typedef struct {
    int width;
    int height;
    size_t file_size;
} ImageMetadata;

ImageMetadata* process_jpeg_directory(const char* directory, int max_entries, int* out_count) {
    DIR *dir;
    struct dirent *entry;
    ImageMetadata *metadata_list = NULL;
    int count = 0;

    dir = opendir(directory);
    if (dir == NULL) {
        perror("Error opening directory");
        return NULL;
    }

    metadata_list = malloc(max_entries * sizeof(ImageMetadata));
    if (metadata_list == NULL) {
        perror("Memory allocation failed");
        closedir(dir);
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL && count < max_entries) {
        if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg")) {
            char file_path[1024];
            snprintf(file_path, sizeof(file_path), "%s/%s", directory, entry->d_name);

            FILE *file = fopen(file_path, "rb");
            if (file == NULL) {
                perror("Error opening file");
                continue;
            }

            fseek(file, 0, SEEK_END);
            metadata_list[count].file_size = ftell(file);
            fseek(file, 163, SEEK_SET); // JPEG SOI marker plus some bytes
            fread(&metadata_list[count].width, sizeof(int), 1, file);
            fread(&metadata_list[count].height, sizeof(int), 1, file);

            fclose(file);
            count++;
        }
    }

    closedir(dir);
    *out_count = count;
    return metadata_list;
}

// Example usage
int main() {
    const char* directory_path = "path/to/jpegs";
    int max_entries = 100;
    int actual_count = 0;

    ImageMetadata *metadata = process_jpeg_directory(directory_path, max_entries, &actual_count);
    if (metadata != NULL) {
        for (int i = 0; i < actual_count; i++) {
            printf("Image %d: Width=%d, Height=%d, File Size=%zu\n", i+1, metadata[i].width, metadata[i].height, metadata[i].file_size);
        }
        free(metadata);
    }

    return 0;
}
