List* createList() {
    List* list = (List*)malloc(sizeof(List));
    if (list) {
        list->head = list->tail = NULL;
        list->count = 0;
        list->memoryUsage = 0;
    }
    return list;
}

void freeList(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
