#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct PacketHeader {
    uint16_t headerLength;
    uint32_t payloadLength;
    uint8_t *payload;
    struct PacketHeader *next;
} PacketHeader;

typedef struct {
    pthread_mutex_t lock;
    PacketHeader *head;
} PacketList;

void initializePacketList(PacketList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void destroyPacketList(PacketList *list) {
    pthread_mutex_lock(&list->lock);
    while (list->head != NULL) {
        PacketHeader *current = list->head;
        list->head = current->next;
        free(current->payload);
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void addPacketToQueue(PacketList *list, uint16_t headerLength, uint32_t payloadLength, const uint8_t *payload) {
    PacketHeader *newNode = (PacketHeader *)malloc(sizeof(PacketHeader));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    newNode->headerLength = headerLength;
    newNode->payloadLength = payloadLength;
    newNode->payload = (uint8_t *)malloc(payloadLength);
    if (newNode->payload == NULL) {
        free(newNode);
        // Handle memory allocation failure
        return;
    }
    memcpy(newNode->payload, payload, payloadLength);
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        PacketHeader *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

PacketHeader *removePacketFromQueue(PacketList *list) {
    pthread_mutex_lock(&list->lock);
    PacketHeader *packet = list->head;
    if (packet != NULL) {
        list->head = packet->next;
    }
    pthread_mutex_unlock(&list->lock);
    return packet;
}
```

This code snippet provides a basic implementation of a thread-safe linked list for managing network packets. The `PacketList` structure uses a mutex to protect access, ensuring that multiple components can safely interact with the list concurrently without causing race conditions. The functions `initializePacketList`, `destroyPacketList`, `addPacketToQueue`, and `removePacketFromQueue` handle initialization, cleanup, adding packets, and removing packets from the queue, respectively.']

