typedef struct MemoryPoolManager {
    void* pool_start;
    size_t total_size;
    size_t block_size;
    pthread_mutex_t lock;
} MemoryPoolManager;

MemoryPoolManager memory_pool;

int init_memory_pool(size_t total_size, size_t block_size) {
    memory_pool.pool_start = malloc(total_size);
    if (!memory_pool.pool_start) return -1;
    memory_pool.total_size = total_size;
    memory_pool.block_size = block_size;
    pthread_mutex_init(&memory_pool.lock, NULL);
    return 0;
}

void* allocate_from_pool(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&memory_pool.lock);
    if (size <= memory_pool.block_size) {
        ptr = memory_pool.pool_start + memory_pool.block_size * (memory_pool.total_size / memory_pool.block_size - 1);
        memory_pool.pool_start = (char*)memory_pool.pool_start - size;
    }
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void free_to_pool(void* ptr) {
    pthread_mutex_lock(&memory_pool.lock);
    if ((char*)ptr >= (char*)memory_pool.pool_start && (char*)ptr <= memory_pool.pool_start + memory_pool.total_size) {
        char* block_end = (char*)memory_pool.pool_start + memory_pool.block_size * (memory_pool.total_size / memory_pool.block_size - 1);
        while (block_end < ptr) block_end += memory_pool.block_size;
        memory_pool.pool_start = block_end;
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

void log_memory_event(const char* event, const char* details) {
    FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", event, details);
        fclose(log_file);
    }
}

int populate_nfaapi_crc_indications(int num_structures) {
    if (num_structures <= 0) return -1;
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures;
    if ((total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) != num_structures) return -2; // Check for integer overflow

    void* memory_block = allocate_from_pool(total_size);
    if (!memory_block) {
        log_memory_event("ERROR", "Out of memory");
        return -3;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)memory_block;
    for (int i = 0; i < num_structures; ++i) {
        // Initialize each structure with valid values and a randomly set CRCFLAG
        pdus[i].ue_info = get_valid_rx_ue_information_tag();
        pdus[i].rnti = generate_rnti();
        pdus[i].crc_indication.flag = (rand() % 2 == 0) ? CRCFLAG_SET : CRCFLAG_CLEAR;
    }

    log_memory_event("INFO", "NFAPI CRC Indications populated successfully");
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <number_of_structures>\n", argv[0]);
        return -1;
    }

    int num_structures = atoi(argv[1]);
    if (num_structures <= 0) {
        printf("Error: Number of structures must be a positive integer.\n");
        return -1;
    }

    // Initialize memory pool with a predefined size and block size
    init_memory_pool(1024 * 1024, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int result = populate_nfaapi_crc_indications(num_structures);
    if (result != 0) {
        printf("Failed to populate NFAPI CRC Indications. Error code: %d\n", result);
    }

    return 0;
}
