typedef struct BufferPool {
    size_t max_size;
    size_t used_size;
    Packet* packets;
    size_t packet_count;
    size_t max_packets;
} BufferPool;

BufferPool* create_buffer_pool(size_t max_size, size_t max_packets) {
    BufferPool* pool = (BufferPool*)malloc(sizeof(BufferPool));
    if (!pool) return NULL;

    pool->max_size = max_size;
    pool->used_size = 0;
    pool->packets = (Packet*)malloc(max_packets * sizeof(Packet));
    if (!pool->packets) {
        free(pool);
        return NULL;
    }

    pool->packet_count = 0;
    pool->max_packets = max_packets;

    return pool;
}

bool validate_packet_size(size_t size, size_t used_size, size_t max_size) {
    // Implement packet size validation logic here
    return (used_size + size <= max_size);
}

int allocate_buffer(BufferPool* pool, Packet* packets, size_t packet_count) {
    size_t total_required = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        if (!validate_packet_size(packets[i].size, pool->used_size, pool->max_size)) {
            return -1; // Packet too large
        }
        total_required += packets[i].size;
    }

    if (pool->used_size + total_required > pool->max_size) {
        return -2; // Insufficient pool capacity
    }

    for (size_t i = 0; i < packet_count; ++i) {
        pool->packets[pool->packet_count++] = packets[i];
        pool->used_size += packets[i].size;
    }

    return 0; // Success
}

void destroy_buffer_pool(BufferPool* pool) {
    for (size_t i = 0; i < pool->packet_count; ++i) {
        free(pool->packets[i].data);
    }
    free(pool->packets);
    free(pool);
}
