#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024
#define MAX_POOL_SIZE 100

typedef struct {
    size_t length;
    char payload[MAX_PACKET_SIZE];
} PacketHeader;

typedef struct Node {
    PacketHeader data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
} PoolAllocator;

void init_pool(PoolAllocator* allocator) {
    allocator->head = NULL;
    allocator->tail = NULL;
    allocator->count = 0;
}

Node* allocate_node(PoolAllocator* allocator) {
    if (allocator->count < MAX_POOL_SIZE) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node != NULL) {
            allocator->count++;
            if (allocator->head == NULL) {
                allocator->head = allocator->tail = new_node;
                new_node->next = NULL;
            } else {
                allocator->tail->next = new_node;
                allocator->tail = new_node;
                new_node->next = NULL;
            }
            return new_node;
        }
    }
    return NULL;
}

void free_pool(PoolAllocator* allocator) {
    Node* current = allocator->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    allocator->head = allocator->tail = NULL;
    allocator->count = 0;
}

PacketHeader* process_packet(PoolAllocator* allocator, char* packet_data, size_t data_size) {
    if (data_size > MAX_PACKET_SIZE) return NULL;

    PacketHeader* header = &allocator->head->data;
    header->length = data_size;
    memcpy(header->payload, packet_data, data_size);

    Node* temp = allocator->head;
    allocator->head = allocator->head->next;
    if (allocator->head == NULL) {
        allocator->tail = NULL;
    }

    return header;
}

void log_memory_usage(PoolAllocator* allocator) {
    printf("Memory Usage: %zu out of %zu nodes allocated.\n", allocator->count, MAX_POOL_SIZE);
}
