typedef struct {
    int length;
    char sourceIP[MAX_IP_LEN];
    char destinationIP[MAX_IP_LEN];
} PacketHeader;

int processPacketHeaders(char* packetData, size_t dataLength, PacketHeader* headers, size_t maxHeaders) {
    if (dataLength > MAX_PACKETS * sizeof(PacketHeader)) {
        printf("Error: Excessive data length.\n");
        return -1;
    }

    char* buffer = packetData;
    size_t numHeaders = 0;

    while (buffer < packetData + dataLength && numHeaders < maxHeaders) {
        PacketHeader header;
        memcpy(&header.length, buffer, sizeof(header.length));
        buffer += sizeof(header.length);

        if (header.length > sizeof(PacketHeader)) {
            printf("Error: Malformed packet header.\n");
            return -1;
        }

        if (buffer + header.length > packetData + dataLength) {
            printf("Error: Insufficient data for packet header.\n");
            return -1;
        }

        if (header.length < sizeof(PacketHeader)) {
            printf("Warning: Short packet header, some fields may be zeroed out.\n");
        }

        memcpy(header.sourceIP, buffer, header.length);
        buffer += header.length;

        if (buffer + header.length > packetData + dataLength) {
            printf("Error: Insufficient data for packet header.\n");
            return -1;
        }

        memcpy(header.destinationIP, buffer, header.length);
        buffer += header.length;

        headers[numHeaders++] = header;
    }

    return numHeaders;
}

int main() {
    // Example usage
    char packetData[MAX_PACKETS * sizeof(PacketHeader)];
    PacketHeader headers[MAX_PACKETS];

    size_t dataLength = 1024; // Simulated data length

    int numHeaders = processPacketHeaders(packetData, dataLength, headers, MAX_PACKETS);

    if (numHeaders >= 0) {
        printf("Processed %d packet headers successfully.\n", numHeaders);
    }

    return 0;
}
