} ImageMetadata;

int validate_and_sanitize_path(const char *path, const char *directory) {
    if (strncmp(path, directory, strlen(directory)) != 0) {
        return -1; // Path is not within the specified directory
    }
    struct stat file_stat;
    if (stat(path, &file_stat) == -1) {
        return -2; // File does not exist or cannot be accessed
    }
    return 0;
}

int calculate_total_size(const ImageMetadata *metadata, int count, size_t *total_size) {
    for (int i = 0; i < count; ++i) {
        if ((INT_MAX - metadata[i].size) / sizeof(ImageMetadata) < count - i - 1) {
            return -1; // Integer overflow
        }
        *total_size += metadata[i].size + sizeof(ImageMetadata);
    }
    return 0;
}

void load_images(const ImageMetadata *metadata, int count, void *memory_buffer) {
    char *buffer_ptr = memory_buffer;
    for (int i = 0; i < count; ++i) {
        // Load image data into buffer
        // Example: memcpy(buffer_ptr + metadata[i].offset, image_data, metadata[i].size);
        buffer_ptr += metadata[i].size + sizeof(ImageMetadata);
    }
}

void process_image_batch(const char *directory, const char **file_paths, int count) {
    ImageMetadata *metadata = (ImageMetadata *)malloc(count * sizeof(ImageMetadata));
    if (!metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Populate metadata
    for (int i = 0; i < count; ++i) {
        int status = validate_and_sanitize_path(file_paths[i], directory);
        if (status != 0) {
            fprintf(stderr, "Invalid file path: %s\n", file_paths[i]);
            continue;
        }
        struct stat file_stat;
        if (stat(file_paths[i], &file_stat) == -1) {
            fprintf(stderr, "Failed to get file size for: %s\n", file_paths[i]);
            continue;
        }
        metadata[i].size = file_stat.st_size;
        // Populate other metadata fields here
    }

    size_t total_size;
    int status = calculate_total_size(metadata, count, &total_size);
    if (status != 0) {
        fprintf(stderr, "Total size calculation failed\n");
        free(metadata);
        return;
    }

    void *memory_buffer = malloc(total_size);
    if (!memory_buffer) {
        fprintf(stderr, "Memory allocation for images failed\n");
        free(metadata);
        return;
    }

    load_images(metadata, count, memory_buffer);

    // Use memory_buffer as needed
    // ...

    // Free allocated resources
    free(memory_buffer);
    free(metadata);
}

int main() {
    const char *directory = "/path/to/images";
    const char *file_paths[] = {"image1.jpg", "image2.png"};
    int count = sizeof(file_paths) / sizeof(file_paths[0]);

    process_image_batch(directory, file_paths, count);

    return 0;
}
