#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CrcIndicationSystem;

CrcIndicationSystem* create_system(size_t initial_capacity) {
    CrcIndicationSystem *system = malloc(sizeof(CrcIndicationSystem));
    if (system == NULL) return NULL;

    system->array = realloc(NULL, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (system->array == NULL) {
        free(system);
        return NULL;
    }

    system->count = 0;
    system->capacity = initial_capacity;
    pthread_mutex_init(&system->lock, NULL);

    return system;
}

void destroy_system(CrcIndicationSystem *system) {
    pthread_mutex_lock(&system->lock);
    free(system->array);
    pthread_mutex_unlock(&system->lock);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

int add_structure(CrcIndicationSystem *system, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&system->lock);

    if (system->count >= system->capacity) {
        size_t new_capacity = system->capacity == 0 ? 1 : system->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(system->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            pthread_mutex_unlock(&system->lock);
            return -1; // Memory allocation failed
        }
        system->array = new_array;
        system->capacity = new_capacity;
    }

    system->array[system->count++] = pdu;

    pthread_mutex_unlock(&system->lock);
    return 0;
}

void remove_structure(CrcIndicationSystem *system, size_t index) {
    pthread_mutex_lock(&system->lock);

    if (index >= system->count) {
        pthread_mutex_unlock(&system->lock);
        return; // Index out of bounds
    }

    for (size_t i = index; i < system->count - 1; i++) {
        system->array[i] = system->array[i + 1];
    }
    system->count--;

    pthread_mutex_unlock(&system->lock);
}

void modify_structure(CrcIndicationSystem *system, size_t index, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&system->lock);

    if (index >= system->count) {
        pthread_mutex_unlock(&system->lock);
        return; // Index out of bounds
    }

    system->array[index] = new_pdu;

    pthread_mutex_unlock(&system->lock);
}

void serialize_binary(CrcIndicationSystem *system, FILE *file) {
    pthread_mutex_lock(&system->lock);

    fwrite(&system->count, sizeof(size_t), 1, file);
    fwrite(system->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), system->count, file);

    pthread_mutex_unlock(&system->lock);
}

void deserialize_binary(CrcIndicationSystem *system, FILE *file) {
    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&system->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(system->array, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        pthread_mutex_unlock(&system->lock);
        return; // Memory allocation failed
    }
    system->array = new_array;
    system->capacity = new_count;

    fread(system->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), new_count, file);
    system->count = new_count;

    pthread_mutex_unlock(&system->lock);
}

void serialize_text(CrcIndicationSystem *system, FILE *file) {
    pthread_mutex_lock(&system->lock);

    fprintf(file, "%zu\n", system->count);
    for (size_t i = 0; i < system->count; i++) {
        fprintf(file, "%d %d %d\n",
                system->array[i].RX_UE_INFORMATION_TAG,
                system->array[i].RNTI,
                system->array[i].CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&system->lock);
}

void deserialize_text(CrcIndicationSystem *system, FILE *file) {
    size_t new_count;
    fscanf(file, "%zu", &new_count);

    pthread_mutex_lock(&system->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(system->array, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        pthread_mutex_unlock(&system->lock);
        return; // Memory allocation failed
    }
    system->array = new_array;
    system->capacity = new_count;

    for (size_t i = 0; i < new_count; i++) {
        fscanf(file, "%d %d %d",
                &system->array[i].RX_UE_INFORMATION_TAG,
                &system->array[i].RNTI,
                &system->array[i].CRC_INDICATION_REL8_TAG);
    }
    system->count = new_count;

    pthread_mutex_unlock(&system->lock);
}
