NFAPI_CRC_INDICATION_PDU_T** create_dynamic_list(size_t N) {
    if (N > MAX_N) {
        log_error("Requested size exceeds maximum allowed.");
        return NULL;
    }

    size_t required_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T*);
    void* allocated_memory = malloc(required_size);
    if (!allocated_memory) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)allocated_memory;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            log_error("Memory allocation failed for individual element.");
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(allocated_memory);
            return NULL;
        }

        if (!initialize_structure(pdu)) {
            log_error("Initialization failed for individual element.");
            // Free previously allocated memory
            for (size_t j = 0; j <= i; ++j) {
                free(list[j]);
            }
            free(allocated_memory);
            return NULL;
        }

        list[i] = pdu;
    }

    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        log_error("Memory allocation failed for mutex.");
        // Free previously allocated memory
        for (size_t i = 0; i < N; ++i) {
            free(list[i]);
        }
        free(allocated_memory);
        return NULL;
    }

    pthread_mutex_init(mutex, NULL);

    NFAPI_CRC_INDICATION_PDU_T** aligned_list = realloc(allocated_memory, required_size + sizeof(pthread_mutex_t));
    if (!aligned_list) {
        log_error("Memory reallocation failed for alignment.");
        // Free previously allocated memory
        pthread_mutex_destroy(mutex);
        free(list[0]);
        for (size_t i = 1; i < N; ++i) {
            free(list[i]);
        }
        free(allocated_memory);
        return NULL;
    }

    aligned_list[N] = mutex;

    return aligned_list;
}

void destroy_dynamic_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t N) {
    if (list && list[N]) {
        pthread_mutex_t* mutex = (pthread_mutex_t*)list[N];
        pthread_mutex_destroy(mutex);
        free(mutex);

        for (size_t i = 0; i < N; ++i) {
            free(list[i]);
        }

        free(list[0]);
    }
}
