using System;
using System.Net.Http;
using Newtonsoft.Json.Linq;

public class GameConfigLoader
{
    private HttpClient httpClient = new HttpClient();

    public async Task<GameConfig> LoadConfigAsync(string apiUrl)
    {
        try
        {
            HttpResponseMessage response = await httpClient.GetAsync(apiUrl);
            response.EnsureSuccessStatusCode();
            string jsonContent = await response.Content.ReadAsStringAsync();
            JObject configJson = JObject.Parse(jsonContent);

            return new GameConfig
            {
                TileSize = (int)configJson["TileSize"],
                WorldWidth = (int)configJson["WorldWidth"],
                CameraSpeed = (float)configJson["CameraSpeed"]
            };
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine($"Error loading config: {ex.Message}");
            throw;
        }
    }
}

public class GameConfig
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public float CameraSpeed { get; set; }
}
