        return -3; // Memory limit exceeded
    }

    PacketMetadata* new_packet = (PacketMetadata*)realloc(packet_metadata_list, (current_size + 1) * sizeof(PacketMetadata));
    if (!new_packet) {
        return -4; // Memory allocation failed
    }

    packet_metadata_list = new_packet;
    current_size++;

    return 0; // Success
}

