int create_and_populate_pdus(int N, size_t alignment, uint8_t *log_buffer, size_t log_size) {
    if (N <= 0 || N > MAX_N) {
        snprintf(log_buffer, log_size, "Invalid value for N: %d", N);
        return -1;
    }

    if (alignment < sizeof(void *) || alignment > 4096) {
        snprintf(log_buffer, log_size, "Invalid alignment requirement: %zu", alignment);
        return -2;
    }

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) + alignment - 1;
    size_t aligned_structure_size = (structure_size / alignment + 1) * alignment;

    if ((N * aligned_structure_size) > SIZE_MAX / N) {
