        pdus[i].rnti = rand() % UINT16_MAX;  // Example initialization
        memset(&pdus[i].ue_info_tag, 0, sizeof(pdus[i].ue_info_tag));
        pdus[i].crc_ind_rel8_tag.crcflag = (rand() % 2 == 0) ? true : false;

        // Add padding for alignment
        size_t struct_end = ((size_t)&pdus[i] + sizeof(NFAPI_CRC_INDICATION_PDU_T)) & ~(alignment - 1);
        pdus[i].padding = (uint8_t)(struct_end - ((size_t)&pdus[i] + sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    }

    pthread_mutex_unlock(&allocation_lock);

    snprintf(log_buffer, log_size, "Successfully allocated and initialized %d PDUs", N);
    return 0;
}
