size_t safe_multiply(size_t a, size_t b) {
    if (b == 0 || a > (SIZE_MAX / b)) return SIZE_MAX;
    return a * b;
}

NFAPI_CRC_INDICATION_PDU_T* populate_crc_indication_list(size_t max_memory, size_t max_elements, size_t current_elements, NFAPI_CRC_INDICATION_PDU_T* current_list) {
    if (max_memory == 0 || max_elements == 0 || current_elements > max_elements) return current_list;

    size_t new_size = safe_multiply(current_elements + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_size > max_memory || new_size == SIZE_MAX) {
        // Log error or warning
        return current_list;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(current_list, new_size);
    if (!new_list) {
        // Handle memory allocation failure
        return current_list;
    }

    // Populate the new element with random values
    uint32_t rx_tag = rand();
    uint16_t rnti = (uint16_t)(rand() % 0xFFFF);
