#define MEMORY_LIMIT (1024 * 1024 * 10) // 10 MB

typedef struct {
    char path[MAX_PATH_LENGTH];
    int width;
    int height;
    long long pixel_count; // Use long long to handle very large numbers of pixels
} ImageMetadata;

ImageMetadata* image_metadata_list = NULL;
int current_image_count = 0;
int allocated_image_count = 0;

void allocate_memory(int new_size) {
    if (new_size > MAX_IMAGE_COUNT) {
        fprintf(stderr, "Error: Attempting to allocate more images than the maximum allowed.\n");
        return;
    }

    // Check for integer overflow
    if ((long long)new_size * sizeof(ImageMetadata) / sizeof(ImageMetadata) != new_size) {
        fprintf(stderr, "Error: Integer overflow detected during memory allocation calculation.\n");
        return;
    }

    ImageMetadata* new_list = realloc(image_metadata_list, new_size * sizeof(ImageMetadata));
    if (new_list == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for image metadata.\n");
        return;
    }

    image_metadata_list = new_list;
    allocated_image_count = new_size;

    // Initialize newly allocated elements
    for (int i = current_image_count; i < new_size; ++i) {
        memset(&image_metadata_list[i], 0, sizeof(ImageMetadata));
    }
}

void add_image(const char* path, int width, int height) {
    if (current_image_count >= allocated_image_count) {
        allocate_memory(current_image_count * 2 + 1); // Double the size or add one if it's zero
        if (image_metadata_list == NULL) {
            fprintf(stderr, "Error: Unable to allocate memory for image metadata.\n");
            return;
        }
    }

    if ((long long)width * height > LLONG_MAX / sizeof(ImageMetadata)) {
        fprintf(stderr, "Error: Integer overflow detected during pixel count calculation.\n");
        return;
    }

    strcpy(image_metadata_list[current_image_count].path, path);
    image_metadata_list[current_image_count].width = width;
    image_metadata_list[current_image_count].height = height;
    image_metadata_list[current_image_count].pixel_count = (long long)width * height;

    current_image_count++;
}

void free_memory() {
    free(image_metadata_list);
    image_metadata_list = NULL;
    current_image_count = 0;
    allocated_image_count = 0;
}

int main() {
    // Example usage
    add_image("image1.jpg", 2560, 1440); // Full HD
    add_image("image2.png", 3840, 2160); // 4K

    printf("Total pixel count: %lld\n", image_metadata_list[0].pixel_count + image_metadata_list[1].pixel_count);

    free_memory();
    return 0;
}
