    int RNTI;
    struct {
        unsigned char CRCFLAG : 1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* processNfareData(int N, const char* filename) {
    if (N < 0 || N > MAX_N) {
        fprintf(stderr, "Invalid value for N\n");
        return NULL;
    }

    size_t total_size = (size_t)N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) != (size_t)N) {
        fprintf(stderr, "Integer overflow in memory allocation\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize the array
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand();
        data[i].RNTI = rand();
        data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 1);
    }

    // Read binary data from the file
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        free(data);
        return NULL;
    }

    size_t bytes_read = fread(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);

    if (bytes_read != N) {
        fprintf(stderr, "Error reading file: expected %zu elements, got %zu\n", N, bytes_read);
        free(data);
        return NULL;
    }

    // Validate the structures
    for (int i = 0; i < N; ++i) {
        if (data[i].RX_UE_INFORMATION_TAG == 0 || data[i].RNTI == 0) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI\n");
            free(data);
            return NULL;
        }
    }

    return data;
}
