        if (strcmp(file_path, ".") != 0 && strcmp(file_path, "..") != 0) {
            image_data_t* image = read_image(file_path, max_memory);
            if (image == NULL) {
                closedir(dir);
                return -1;
            }
            // Process the image
            free_image(image); // Free memory after processing
        }
    }

    closedir(dir);
    return 0;
}
