from flask import Flask, request, jsonify
from functools import wraps
import requests
import time

app = Flask(__name__)

# Configuration
IDP_URL = 'https://api.idp.com/login'
SESSION_TTL = 3600  # Token expiration time in seconds (1 hour)
ROTATION_INTERVAL = SESSION_TTL / 2  # Half of TTL for token rotation
CACHING_ENABLED = True

session_cache = {}
last_rotation_time = time.time()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_token = request.headers.get('Authorization')
        if not auth_token:
            return jsonify({'error': 'Unauthorized'}), 401
        if auth_token not in session_cache or time.time() - session_cache[auth_token]['last_updated'] > SESSION_TTL:
            return jsonify({'error': 'Session expired'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    # Simulate IDP call
    response = requests.post(IDP_URL, json={'username': username, 'password': password})
    if response.status_code != 200:
        return jsonify({'error': 'Authentication failed'}), 401

    auth_token = response.json().get('token')
    session_cache[auth_token] = {'last_updated': time.time()}
    return jsonify({'token': auth_token}), 200

@app.route('/rotate', methods=['POST'])
@require_auth
def rotate():
    global last_rotation_time, session_cache
    if time.time() - last_rotation_time < ROTATION_INTERVAL:
        return jsonify({'error': 'Rotation too frequent'}), 429

    for token in list(session_cache.keys()):
        session_cache[token]['last_updated'] = time.time()

    last_rotation_time = time.time()
    return jsonify({'message': 'Tokens rotated successfully'}), 200

@app.route('/protected', methods=['GET'])
@require_auth
def protected():
    return jsonify({'message': 'Access granted to protected resource'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
