#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1500
#define EXTRA_BUFFER_SIZE 1024

typedef struct {
    size_t payload_size;
    char* payload;
} Packet;

typedef struct {
    pthread_mutex_t lock;
    size_t total_buffer_size;
    char* buffer;
} BufferManager;

void init_buffer_manager(BufferManager* manager, size_t initial_size) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_buffer_size = initial_size + EXTRA_BUFFER_SIZE;
    manager->buffer = (char*)malloc(manager->total_buffer_size);
}

void cleanup_buffer_manager(BufferManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->buffer);
}

int process_packet(BufferManager* manager, Packet packet) {
    pthread_mutex_lock(&manager->lock);

    if (packet.payload_size > MAX_PACKET_SIZE || 
        packet.payload_size + manager->total_buffer_size > SIZE_MAX - EXTRA_BUFFER_SIZE) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Invalid or too large payload size
    }

    size_t new_total_buffer_size = manager->total_buffer_size + packet.payload_size;
    if (new_total_buffer_size > manager->total_buffer_size) {
        char* new_buffer = realloc(manager->buffer, new_total_buffer_size);
        if (!new_buffer) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Error: Memory allocation failed
        }
        manager->buffer = new_buffer;
        manager->total_buffer_size = new_total_buffer_size;
    }

    memcpy(manager->buffer + (manager->total_buffer_size - packet.payload_size), packet.payload, packet.payload_size);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}
