    if (num_files > MAX_IMAGES) {
        fprintf(stderr, "Error: Exceeds maximum number of images (%d)\n", MAX_IMAGES);
        return -1;
    }

    size_t total_size = 0;
    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_names[i], "rb");
        if (!file) {
            fprintf(stderr, "Error: Unable to open file %s\n", file_names[i]);
            return -1;
        }

        ImageHeader header;
        if (fread(&header, sizeof(ImageHeader), 1, file) != 1) {
            fprintf(stderr, "Error: Unable to read header from file %s\n", file_names[i]);
            fclose(file);
            return -1;
        }

        size_t image_size = header.width * header.height * /* bytes per pixel */;
        if (image_size > SIZE_MAX / num_files) {
            fprintf(stderr, "Error: Image size exceeds maximum allowed by system\n");
            fclose(file);
            return -1;
        }
        total_size += image_size;

        // Allocate memory for the image data
        unsigned char* image_data = malloc(image_size * sizeof(unsigned char));
        if (!image_data) {
            fprintf(stderr, "Error: Memory allocation failed for file %s\n", file_names[i]);
            fclose(file);
            return -1;
        }

        if (fread(image_data, 1, image_size, file) != image_size) {
            fprintf(stderr, "Error: Unable to read data from file %s\n", file_names[i]);
            free(image_data);
            fclose(file);
            return -1;
        }

        // Process the image data here
        // ...

        // Free the allocated memory for this image
        free(image_data);

        fclose(file);
    }

    // Allocate the total buffer to hold all images
    unsigned char* total_buffer = malloc(total_size * sizeof(unsigned char));
    if (!total_buffer) {
        fprintf(stderr, "Error: Memory allocation failed for total buffer\n");
        return -1;
    }

    // Copy image data into the total buffer
    size_t offset = 0;
    for (int i = 0; i < num_files; ++i) {
        ImageHeader header;
        FILE* file = fopen(file_names[i], "rb");
        if (!file) {
            fprintf(stderr, "Error: Unable to open file %s\n", file_names[i]);
            free(total_buffer);
            return -1;
        }

        if (fread(&header, sizeof(ImageHeader), 1, file) != 1) {
            fprintf(stderr, "Error: Unable to read header from file %s\n", file_names[i]);
            fclose(file);
            free(total_buffer);
            return -1;
        }

        size_t image_size = header.width * header.height * /* bytes per pixel */;
        if (offset + image_size > total_size) {
            fprintf(stderr, "Error: Offset exceeds allocated buffer size\n");
            fclose(file);
            free(total_buffer);
            return -1;
        }

        unsigned char* image_data = malloc(image_size * sizeof(unsigned char));
        if (!image_data) {
            fprintf(stderr, "Error: Memory allocation failed for file %s\n", file_names[i]);
            fclose(file);
            free(total_buffer);
            return -1;
        }

        if (fread(image_data, 1, image_size, file) != image_size) {
            fprintf(stderr, "Error: Unable to read data from file %s\n", file_names[i]);
            free(image_data);
            fclose(file);
            free(total_buffer);
            return -1;
        }

        memcpy(total_buffer + offset, image_data, image_size);

        // Free the allocated memory for this image
        free(image_data);

        fclose(file);
        offset += image_size;
    }

    // Process the total buffer here
    // ...

    // Free the total buffer when done
    free(total_buffer);

    return 0;
}
