#define MAX_EXPECTED_SIZE 1024
#define BUFFER_EXTENSION 1024

typedef struct {
    size_t payload_size;
    unsigned char *payload;
} PacketHeader;

typedef struct {
    pthread_mutex_t lock;
    size_t buffer_size;
    unsigned char *buffer;
} BufferManager;

BufferManager buffer_manager = {PTHREAD_MUTEX_INITIALIZER, 0, NULL};

size_t calculate_total_buffer_size(size_t payload_size) {
    return payload_size + BUFFER_EXTENSION;
}

int process_packet_header(PacketHeader header) {
    pthread_mutex_lock(&buffer_manager.lock);

    if (header.payload_size > MAX_EXPECTED_SIZE) {
        printf("Payload size exceeds expected limit.\n");
        pthread_mutex_unlock(&buffer_manager.lock);
        return -1;
    }

    size_t total_buffer_size = calculate_total_buffer_size(header.payload_size);

    if (total_buffer_size > buffer_manager.buffer_size) {
        if (buffer_manager.buffer != NULL) {
            free(buffer_manager.buffer);
        }
        buffer_manager.buffer_size = total_buffer_size;
        buffer_manager.buffer = (unsigned char *)realloc(buffer_manager.buffer, buffer_manager.buffer_size);
        if (buffer_manager.buffer == NULL) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(&buffer_manager.lock);
            return -1;
        }
    }

    memcpy(buffer_manager.buffer, header.payload, header.payload_size);

    pthread_mutex_unlock(&buffer_manager.lock);
    return 0;
}

int main() {
    // Example usage
    PacketHeader packet = {500, (unsigned char *)"example_payload"};

    if (process_packet_header(packet) == 0) {
        printf("Packet processed successfully.\n");
    }

    return 0;
}
