['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    Node* tail;
    size_t max_size;
    size_t current_size;
    pthread_mutex_t lock;
} List;

List* create_list(size_t max_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->max_size = max_size;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int add_to_list(List* list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    new_node->data.ue_info_tag = ue_info_tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRC flag

    if (!list->head) {
        list->head = list->tail = new_node;
        new_node->next = NULL;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->current_size++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
