#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Function to calculate required buffer size safely
size_t calculate_buffer_size(size_t packet_count, size_t *payload_sizes) {
    size_t total_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        if (payload_sizes[i] > SIZE_MAX - total_size) {
            fprintf(stderr, "Integer overflow detected in payload size calculation.\n");
            return 0;
        }
        total_size += payload_sizes[i];
    }
    return total_size;
}

// Function to process packets and allocate buffer
void *process_packets(size_t packet_count, size_t *payload_sizes, size_t *allocated_bytes) {
    *allocated_bytes = calculate_buffer_size(packet_count, payload_sizes);
    if (*allocated_bytes == 0) {
        return NULL; // Allocation failed due to overflow or other reasons
    }

    void *buffer = malloc(*allocated_bytes);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        *allocated_bytes = 0;
        return NULL;
    }

    char *ptr = buffer;
    for (size_t i = 0; i < packet_count; ++i) {
        memcpy(ptr, payload_sizes[i], payload_sizes[i]);
        ptr += payload_sizes[i];
    }

    return buffer;
}

// Example usage
int main() {
    size_t payload_sizes[] = {1024, 2048, 512};
    size_t packet_count = sizeof(payload_sizes) / sizeof(payload_sizes[0]);
    size_t allocated_bytes;

    void *buffer = process_packets(packet_count, payload_sizes, &allocated_bytes);
    if (buffer != NULL) {
        printf("Buffer allocated successfully with %zu bytes.\n", allocated_bytes);
        free(buffer); // Don't forget to free the buffer when done
    } else {
        printf("Failed to allocate buffer.\n");
    }

    return 0;
}
```

