// Define metadata structure
typedef struct {
    char* name;
    size_t size;
    time_t last_modified;
} FileMetadata;

// Function to get file metadata
FileMetadata* getFileMetadata(const char* path, int* count) {
    // Simulate large number of files for demonstration
    const int maxFiles = 1024 * 1024; // 1 million
    FileMetadata* metadata = (FileMetadata*)malloc(maxFiles * sizeof(FileMetadata));
    if (!metadata) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    DIR* dir;
    struct dirent* ent;
    *count = 0;

    if ((dir = opendir(path)) != NULL) {
        while ((ent = readdir(dir)) != NULL && *count < maxFiles) {
            char filePath[1024];
            snprintf(filePath, sizeof(filePath), "%s/%s", path, ent->d_name);

            struct stat st;
            if (stat(filePath, &st) == 0) {
                metadata[*count].name = strdup(ent->d_name);
                metadata[*count].size = st.st_size;
                metadata[*count].last_modified = st.st_mtime;
                (*count)++;
            }
        }
        closedir(dir);
    } else {
        perror("Failed to open directory");
        free(metadata);
        exit(EXIT_FAILURE);
    }

    return metadata;
}

// Example usage
int main() {
    int count;
    FileMetadata* metadata = getFileMetadata(".", &count);

    for (int i = 0; i < count; i++) {
        printf("File: %s, Size: %zu bytes, Last Modified: %ld\n", 
               metadata[i].name, metadata[i].size, metadata[i].last_modified);
        free(metadata[i].name);
    }

    free(metadata);
    return 0;
}
```

