            pdus[total_pdus].RX_UE_INFORMATION_TAG = i * max_elements + j;
            pdus[total_pdus].RNTI = i * 100 + j;
            pdus[total_pdus].CRC_INDICATION_REL8_TAG = i * 50 + j;
            pdus[total_pdus].CRCFLAG = rand() % 2;
            total_pdus++;
        }
    }

    json_object_put(config);
    return pdus;
}

