#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define CHECKSUM_SIZE sizeof(uint32_t)

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* create_and_populate_pdus(int num_entries) {
    if (num_entries <= 0 || num_entries > MAX_ENTRIES) {
        fprintf(stderr, "Invalid number of entries: %d\n", num_entries);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for %d entries\n", num_entries);
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < num_entries; i++) {
        pthread_mutex_lock(&lock);
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 65536; // Random tag value
        pdus[i].RNTI = rand() % 16384; // Random RNTI value
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) == 0 ? 0 : 1; // Random CRCFLAG value
        pthread_mutex_unlock(&lock);
    }

    uint32_t checksum = 0;
    for (int i = 0; i < num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        checksum += ((unsigned char*)&pdus)[i];
    }
    memcpy((char*)pdus + num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T), &checksum, CHECKSUM_SIZE);

    pthread_mutex_destroy(&lock);
    return pdus;
}

void* serialize_pdus(void* data, int num_entries) {
    if (!data) {
        fprintf(stderr, "Invalid data pointer\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)data;

    FILE* file = fopen("pdus.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return NULL;
    }

    size_t written = fwrite(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_entries, file);
    if (written != num_entries) {
        fprintf(stderr, "Error during serialization: %zu entries written instead of %d\n", written, num_entries);
        fclose(file);
        return NULL;
    }

    fclose(file);
    return data;
}

void* deserialize_pdus(void** data, int* num_entries) {
    FILE* file = fopen("pdus.bin", "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *num_entries = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*num_entries == 0) {
        fprintf(stderr, "Empty file or invalid file format\n");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed for %d entries\n", *num_entries);
        fclose(file);
        return NULL;
    }

    size_t read = fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), *num_entries, file);
    if (read != *num_entries) {
        fprintf(stderr, "Error during deserialization: %zu entries read instead of %d\n", read, *num_entries);
        free(pdus);
        fclose(file);
        return NULL;
    }

    uint32_t received_checksum = 0;
    memcpy(&received_checksum, (char*)pdus + size - CHECKSUM_SIZE, CHECKSUM_SIZE);

    uint32_t calculated_checksum = 0;
    for (int i = 0; i < size - CHECKSUM_SIZE; i++) {
        calculated_checksum += ((unsigned char*)&pdus)[i];
    }

    if (received_checksum != calculated_checksum) {
        fprintf(stderr, "Checksum mismatch during deserialization\n");
        free(pdus);
        fclose(file);
        return NULL;
    }

    fclose(file);
    *data = pdus;
    return pdus;
}

int main() {
    int num_entries = 100;
    void* data = create_and_populate_pdus(num_entries);
    if (!data) {
        fprintf(stderr, "Failed to create and populate PDUs\n");
        return EXIT_FAILURE;
    }

    serialize_pdus(data, num_entries);

    void* deserialized_data = NULL;
    int deserialized_num_entries = 0;
    deserialize_pdus(&deserialized_data, &deserialized_num_entries);
    if (!deserialized_data) {
        fprintf(stderr, "Failed to deserialize PDUs\n");
        free(data);
        return EXIT_FAILURE;
    }

    // Process the deserialized data as needed
    // ...

    free(data);
    free(deserialized_data);

    return EXIT_SUCCESS;
}
