    NFAPI_CRC_INDICATION_PDU_T data;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode* head;
    DoublyLinkedListNode* tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DoublyLinkedList;

void initDoublyLinkedList(DoublyLinkedList* list, size_t initialCapacity) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroyDoublyLinkedList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    while (list->head != NULL) {
        DoublyLinkedListNode* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

void addElementToDoublyLinkedList(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        // Handle capacity exceeded scenario
        // Optionally reallocate memory or drop the oldest element
        printf("Capacity exceeded. Dropping oldest element.\n");
        DoublyLinkedListNode* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    DoublyLinkedListNode* newNode = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (newNode == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

