int add_image_metadata(ImageStore *store, int width, int height, size_t file_size) {
    if (store->count >= MAX_IMAGES) {
        fprintf(stderr, "Too many images\n");
        return -1;
    }
    pthread_mutex_lock(&store->mutex);
    store->metadata[store->count].width = width;
    store->metadata[store->count].height = height;
    store->metadata[store->count].file_size = file_size;
    store->count++;
    pthread_mutex_unlock(&store->mutex);
