    for (int i = 0; i < store.count; i++) {
        if (pthread_create(&threads[i], NULL, process_image_thread, &store) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < store.count; i++) {
        pthread_join(threads[i], NULL);
    }

    free_image_store(&store);
