            $response = $this->makeOAuthRequest('token', [
                'grant_type' => 'password',
                'username' => $username,
                'password' => $password
            ]);

            if ($response['status'] == 200) {
                $this->accessToken = $response['data']['access_token'];
                $_SESSION['access_token'] = $this->accessToken;
                return $this->getUserInfo();
            } else {
                log_error("Authentication failed: " . json_encode($response));
                return false;
            }
        } catch (Exception $e) {
            log_error("Error during authentication: " . $e->getMessage());
            return false;
        }
