        // Log errors and performance metrics
        // Handle transient failures gracefully
    }

    private function getUserInfo() {
        if (!isset($_SESSION['access_token'])) {
            return null;
        }

        try {
            $response = $this->makeOAuthRequest('userinfo');
            if ($response['status'] == 200) {
                return $response['data'];
            } else {
                log_error("Failed to retrieve user info: " . json_encode($response));
                return null;
            }
        } catch (Exception $e) {
            log_error("Error retrieving user info: " . $e->getMessage());
            return null;
        }
    }
