#define MAX_STRUCTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* generate_nfapi_cnf_pdu_list(void* params) {
    int N = ((int*)params)[0];
    int min_crc_tag = ((int*)params)[1];
    int max_crc_tag = ((int*)params)[2];
    int min_rnti = ((int*)params)[3];
    int max_rnti = ((int*)params)[4];
    unsigned int seed = ((unsigned int*)params)[5];

    if (N < 1 || N > MAX_STRUCTS) {
        printf("Invalid number of structures. Must be between 1 and %d.\n", MAX_STRUCTS);
        return NULL;
    }

    if (min_crc_tag >= max_crc_tag || min_rnti >= max_rnti) {
        printf("CRC and RNTI ranges must be valid.\n");
        return NULL;
    }

    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Memory allocation calculation overflow detected.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_memory);
    if (!pdu_list) {
        printf("Failed to allocate memory for %d structures.\n", N);
        return NULL;
    }

    srand(seed);
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        pdu_list[i].RX_UE_INFORMATION_TAG = min_crc_tag + rand() % (max_crc_tag - min_crc_tag + 1);
        pdu_list[i].RNTI = min_rnti + rand() % (max_rnti - min_rnti + 1);
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return pdu_list;
}

void free_nfapi_cnf_pdu_list(void* list) {
    if (list) {
        free(list);
    }
}
