void insertCrcTagAfterRnti(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, int rnti, RX_UE_INFORMATION_TAG tag) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    if (list.empty()) {
        NFAPI_CRC_INDICATION_PDU_T newPdu = {rnti};
