    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (it->RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T newPdu = {rnti};
            newPdu.tag = tag;
            newPdu.CRCFLAG = dis(gen);
            list.insert_after(prev, newPdu);
            return;
        }
        prev = it;
    }

    NFAPI_CRC_INDICATION_PDU_T newPdu = {rnti};
    newPdu.tag = tag;
    newPdu.CRCFLAG = dis(gen);
    list.push_back(newPdu);
