typedef struct {
    ImageMetaData data[MAX_CACHE_SIZE];
    int count;
    pthread_mutex_t lock;
} MetaDataCache;

MetaDataCache cache = { .lock = PTHREAD_MUTEX_INITIALIZER };

void initialize_cache() {
    cache.count = 0;
}

int add_to_cache(ImageMetaData metadata) {
    pthread_mutex_lock(&cache.lock);
    if (cache.count >= MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&cache.lock);
        return -1; // Cache full
    }
    cache.data[cache.count++] = metadata;
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

int find_in_cache(char* file_path, ImageMetaData *result) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.count; ++i) {
        if (strcmp(cache.data[i].file_path, file_path) == 0) {
            *result = cache.data[i];
            pthread_mutex_unlock(&cache.lock);
            return 1; // Cache hit
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return 0; // Cache miss
}

int process_image_metadata(char* file_path, ImageMetaData** result, int* count) {
    ImageMetaData metadata;
    if (find_in_cache(file_path, &metadata)) {
        *result = malloc(sizeof(ImageMetaData));
        **result = metadata;
        (*count)++;
    } else {
        // Simulate processing
        metadata.width = 1920;
        metadata.height = 1080;
        strcpy(metadata.file_path, file_path);
        if (add_to_cache(metadata) == 0) {
            *result = malloc(sizeof(ImageMetaData));
            **result = metadata;
            (*count)++;
        } else {
            return -1; // Cache full
        }
    }
    return 0;
}

