#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, unsigned short rnti) {
    Node* new_node = (Node*)calloc(1, sizeof(Node));
    if (new_node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    return new_node;
}

int add_to_list(Node** head, int rx_tag, unsigned short rnti) {
    if (*head == NULL) {
        *head = create_node(rx_tag, rnti);
        if (*head == NULL) {
            return -1; // Handle memory allocation failure
        }
        return 0;
    }

    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = create_node(rx_tag, rnti);
    if (current->next == NULL) {
        return -1; // Handle memory allocation failure
    }

    return 0;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    Node* head = NULL;

    for (int i = 0; i < MAX_LIST_SIZE; ++i) {
        int rx_tag = rand() % 100; // Random RX_UE_INFORMATION_TAG
        unsigned short rnti = rand() % 65536; // Random RNTI

        if (add_to_list(&head, rx_tag, rnti) != 0) {
            free_list(head);
            return -1; // Handle memory allocation failure
        }
    }

    free_list(head);

    return 0;
}
