void insertCrcTagAfterRnti(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, int rnti, const RX_UE_INFORMATION_TAG& tag) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    for (auto it = list.begin(); it != list.end(); ++it) {
        if (it->rnti == rnti) {
            // Insert new CRC tag after found RNTI
            CRC_INDICATION_REL8_TAG newTag;
            newTag.CRCFLAG = static_cast<uint8_t>(rand()); // Randomly set CRCFLAG
            it = list.insert_after(it, NFAPI_CRC_INDICATION_PDU_T{tag.RNTI, newTag});
            return;
        }
    }

    // If no matching RNTI is found, append the new tag to the end
    CRC_INDICATION_REL8_TAG newTag;
    newTag.CRCFLAG = static_cast<uint8_t>(rand()); // Randomly set CRCFLAG
    list.push_back(NFAPI_CRC_INDICATION_PDU_T{tag.RNTI, newTag});
}
