ImageLibrary* create_image_library() {
    ImageLibrary *lib = (ImageLibrary*)malloc(sizeof(ImageLibrary));
    if (!lib) return NULL;
    lib->images = NULL;
    lib->count = 0;
    lib->capacity = 0;
    pthread_mutex_init(&lib->lock, NULL);
    return lib;
}

void destroy_image_library(ImageLibrary *lib) {
    for (size_t i = 0; i < lib->count; ++i) {
        free(lib->images[i]->data);
        free(lib->images[i]);
    }
    free(lib->images);
    pthread_mutex_destroy(&lib->lock);
    free(lib);
}

int add_image_to_library(ImageLibrary *lib, Image *img) {
    // Lock the library for thread safety
    pthread_mutex_lock(&lib->lock);

    // Ensure there's enough capacity in the library
    if (lib->count >= lib->capacity) {
        size_t new_capacity = lib->capacity ? lib->capacity * 2 : 8;
        Image **new_images = realloc(lib->images, new_capacity * sizeof(Image*));
        if (!new_images) {
            pthread_mutex_unlock(&lib->lock);
            return -1; // Memory allocation failed
        }
        lib->images = new_images;
        lib->capacity = new_capacity;
    }

    // Add the image to the library
    lib->images[lib->count++] = img;

    // Unlock the library after operation
    pthread_mutex_unlock(&lib->lock);
    return 0;
}

int remove_image_from_library(ImageLibrary *lib, size_t index) {
    if (index >= lib->count) return -1; // Invalid index

    // Lock the library for thread safety
    pthread_mutex_lock(&lib->lock);

    // Free the image data and remove the image from the library
    free(lib->images[index]->data);
    free(lib->images[index]);

    // Shift elements to fill the gap
    for (size_t i = index; i < lib->count - 1; ++i) {
        lib->images[i] = lib->images[i + 1];
    }
    --lib->count;

    // Unlock the library after operation
    pthread_mutex_unlock(&lib->lock);
    return 0;
}

// Additional functions for managing images and optimizing memory usage can be added here
