#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RETRIES 10
#define RETRY_DELAY_BASE 2000
#define FAILOVER_PATH "/path/to/secondary/service"

typedef struct {
    char *connection_state;
    int retry_count;
    clock_t last_attempt_time;
} ConnectionState;

ConnectionState* establishAndMaintainConnection(const char *service_address, const char *log_file) {
    ConnectionState *conn = (ConnectionState *)malloc(sizeof(ConnectionState));
    if (!conn) {
        fprintf(stderr, "Failed to allocate memory for connection state\n");
        return NULL;
    }

    conn->retry_count = 0;
    conn->last_attempt_time = clock();

    while (1) {
        // Simulate connection attempt
        int result = connectToService(service_address);
        if (result == 0) {
            // Connection successful
            conn->connection_state = strdup("ESTABLISHED");
            logConnectionStatus(log_file, "Success", service_address, NULL);
            break;
        } else {
            // Connection failed
            conn->retry_count++;
            clock_t current_time = clock();
            double elapsed_time = (double)(current_time - conn->last_attempt_time) / CLOCKS_PER_SEC;
            if (elapsed_time < RETRY_DELAY_BASE * pow(2, conn->retry_count)) {
                logConnectionStatus(log_file, "Retry", service_address, NULL);
                sleep(RETRY_DELAY_BASE * pow(2, conn->retry_count));
            } else {
                // Attempt failover
                char *failover_service = getFailoverService(FAILOVER_PATH);
                if (connectToService(failover_service) == 0) {
                    conn->connection_state = strdup("ESTABLISHED");
                    logConnectionStatus(log_file, "Success", failover_service, NULL);
                    break;
                } else {
                    logConnectionStatus(log_file, "Failover Failure", failover_service, NULL);
                    free(failover_service);
                }
            }
        }
    }

    return conn;
}

int connectToService(const char *service_address) {
    // Simulated connection attempt
    printf("Attempting to connect to %s\n", service_address);
    // Replace with actual connection logic
    return 1; // Return 0 on success, non-zero on failure
}

char* getFailoverService(const char *failover_path) {
    FILE *file = fopen(failover_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open failover path: %s\n", failover_path);
        return NULL;
    }

    char *service_address = (char *)malloc(256);
    if (!service_address) {
        fclose(file);
        fprintf(stderr, "Failed to allocate memory for service address\n");
        return NULL;
    }

    if (fgets(service_address, 256, file)) {
        service_address[strcspn(service_address, "\n")] = 0; // Remove newline character
    } else {
        free(service_address);
        fprintf(stderr, "Failed to read failover address from file\n");
        fclose(file);
        return NULL;
    }

    fclose(file);
    return service_address;
}

void logConnectionStatus(const char *log_file, const char *status, const char *service_address, const char *error) {
    FILE *file = fopen(log_file, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file);
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(file, "%s %s %s %s %s\n", asctime(tm_info), status, service_address, error ? error : "", strerror(errno));
    fclose(file);
}

void freeConnectionState(ConnectionState *conn) {
    if (conn->connection_state) {
        free(conn->connection_state);
    }
    free(conn);
}
