int loadAndPopulateCRCIndications(const char* path, NFAPI_CRC_INDICATION_PDU_T* indications, int maxSize) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0 || fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T) > maxSize) {
        fclose(file);
        return -2; // Invalid file size or too many items
    }

    NFAPI_CRC_INDICATION_PDU_T* bundle = (NFAPI_CRC_INDICATION_PDU_T*)malloc((size_t)fileSize);
    if (!bundle) {
        fclose(file);
        return -3; // Memory allocation failed
    }

    size_t bytesRead = fread(bundle, sizeof(NFAPI_CRC_INDICATION_PDU_T), fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    fclose(file);

    if (bytesRead != fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        free(bundle);
        return -4; // Failed to read the entire file
    }

    for (int i = 0; i < bytesRead; ++i) {
        indications[i] = bundle[i];
        indications[i].tag = RX_UE_INFORMATION_TAG;
        indications[i].RNTI = generateRandomRNTI(); // Assume a function generateRandomRNTI() exists
        indications[i].CRCFLAG = rand() % 256; // Randomly set CRCFLAG between 0 and 255
    }

    free(bundle);
    return 0; // Success
}
