#include <stdlib.h>
#include <string.h>

typedef struct {
    int width;
    int height;
    void *pixelData;
} img_t;

enum ErrorCode {
    SUCCESS,
    INVALID_PATH,
    INSUFFICIENT_MEMORY,
    CORRUPTED_IMAGE
};

int processImageBundle(const char *directoryPath, size_t maxMemoryUsage, img_t *imageArray, size_t *imageCount) {
    DIR *dir;
    struct dirent *entry;
    dir = opendir(directoryPath);
    if (dir == NULL) {
        return INVALID_PATH;
    }

    int imageIndex = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char filePath[1024];
        snprintf(filePath, sizeof(filePath), "%s/%s", directoryPath, entry->d_name);

        FILE *file = fopen(filePath, "rb");
        if (file == NULL) {
            continue;
        }

        // Simulate reading image header
        int width, height;
        fread(&width, sizeof(int), 1, file);
        fread(&height, sizeof(int), 1, file);

        size_t pixelDataSize = width * height * 3; // Assuming RGB images
        if (pixelDataSize > maxMemoryUsage - (size_t)imageIndex * sizeof(img_t)) {
            fclose(file);
            closedir(dir);
            return INSUFFICIENT_MEMORY;
        }

        img_t *img = &imageArray[imageIndex];
        img->width = width;
        img->height = height;

        // Reuse existing buffer if possible
        if (imageIndex > 0 && imageArray[imageIndex - 1].pixelData != NULL) {
            img->pixelData = imageArray[imageIndex - 1].pixelData;
        } else {
            img->pixelData = malloc(pixelDataSize);
            if (img->pixelData == NULL) {
                fclose(file);
                closedir(dir);
                return INSUFFICIENT_MEMORY;
            }
        }

        fread(img->pixelData, pixelDataSize, 1, file);
        fclose(file);

        imageIndex++;
    }

    *imageCount = imageIndex;
    closedir(dir);
    return SUCCESS;
}
