#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STREAMS 1000

typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t array_size;
} StreamData;

StreamData streams[MAX_STREAMS];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;
int memory_usage[MAX_STREAMS] = {0};

void initialize_streams() {
    for (int i = 0; i < MAX_STREAMS; ++i) {
        pthread_mutex_init(&streams[i].mutex, NULL);
        streams[i].array = NULL;
        streams[i].array_size = 0;
    }
}

void cleanup_stream(int stream_id) {
    pthread_mutex_lock(&global_lock);
    if (streams[stream_id].array != NULL) {
        free(streams[stream_id].array);
        streams[stream_id].array = NULL;
        streams[stream_id].array_size = 0;
    }
    memory_usage[stream_id] = 0;
    pthread_mutex_unlock(&global_lock);
}

int allocate_memory_for_stream(int stream_id, size_t num_elements) {
    if (num_elements > 1000000) return -1; // Prevent excessive allocation
    size_t required_memory = num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > get_system_memory_limit()) return -2; // Check system memory limit

    pthread_mutex_lock(&streams[stream_id].mutex);
    if (streams[stream_id].array != NULL) free(streams[stream_id].array);

    streams[stream_id].array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_memory);
    if (streams[stream_id].array == NULL) {
        pthread_mutex_unlock(&streams[stream_id].mutex);
        return -3; // Memory allocation failed
    }

    for (size_t i = 0; i < num_elements; ++i) {
        streams[stream_id].array[i].RNTI = generate_valid_RNTI(); // Function to generate a valid RNTI
    }

    memory_usage[stream_id] += required_memory;
    pthread_mutex_unlock(&streams[stream_id].mutex);
    return 0; // Success
}

void *process_stream(void *arg) {
    int stream_id = *(int *)arg;
    size_t num_elements = calculate_num_elements_for_stream(stream_id); // Function to calculate the number of elements for a stream

    if (allocate_memory_for_stream(stream_id, num_elements) != 0) {
        printf("Failed to allocate memory for stream %d\n", stream_id);
        return NULL;
    }

    // Process stream data
    // ...

    cleanup_stream(stream_id);
    return NULL;
}

void periodic_cleanup() {
    pthread_mutex_lock(&global_lock);
    for (int i = 0; i < MAX_STREAMS; ++i) {
        if (memory_usage[i] == 0 && streams[i].array != NULL) {
            free(streams[i].array);
            streams[i].array = NULL;
            streams[i].array_size = 0;
        }
    }
    pthread_mutex_unlock(&global_lock);
}

int main() {
    initialize_streams();
    // Create and start threads for processing streams
    pthread_t threads[MAX_STREAMS];
    int stream_ids[MAX_STREAMS];
    for (int i = 0; i < MAX_STREAMS; ++i) {
        stream_ids[i] = i;
        pthread_create(&threads[i], NULL, process_stream, &stream_ids[i]);
    }

    // Periodically clean up unused memory
    while (1) {
        periodic_cleanup();
        sleep(60); // Clean up every 60 seconds
    }

    return 0;
}
```

