#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct packet_data_t {
    void *payload;
    size_t length;
} packet_data_t;

packet_data_t* process_packets(packet_data_t *packets, int packet_count, size_t max_size) {
    if (max_size == 0 || packets == NULL || packet_count <= 0) {
        return NULL;
    }

    packet_data_t *result = malloc(sizeof(packet_data_t));
    if (result == NULL) {
        return NULL;
    }
    result->payload = NULL;
    result->length = 0;

    size_t current_size = sizeof(packet_data_t);
    for (int i = 0; i < packet_count; ++i) {
        if ((current_size + packets[i].length * sizeof(char)) > max_size) {
            break;
        }

        void *new_payload = realloc(result->payload, current_size + packets[i].length * sizeof(char));
        if (new_payload == NULL) {
            free(result->payload);
            free(result);
            return NULL;
        }
        result->payload = new_payload;

        memcpy((char *)result->payload + current_size - sizeof(packet_data_t), &packets[i], sizeof(packet_data_t));
        memcpy((char *)result->payload + current_size, packets[i].payload, packets[i].length);

        current_size += packets[i].length * sizeof(char);
    }
    result->length = (current_size - sizeof(packet_data_t)) / sizeof(packet_data_t);

    return result;
}

int main() {
    // Example usage
    packet_data_t packets[] = {
        { "Data1", 5 },
        { NULL, 0 },
        { "Data2", 5 }
    };
    int packet_count = 3;
    size_t max_size = 24;

    packet_data_t *result = process_packets(packets, packet_count, max_size);
    if (result != NULL) {
        for (size_t i = 0; i < result->length; ++i) {
            printf("Packet %zu: Data=%s Length=%zu\n", i, ((packet_data_t *)((char *)result->payload + i * sizeof(packet_data_t)))->payload,
                   ((packet_data_t *)((char *)result->payload + i * sizeof(packet_data_t)))->length);
        }
        free(result->payload);
        free(result);
    } else {
        printf("Failed to process packets\n");
    }

    return 0;
}
