        (*actual_entries)++;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return list;
}

JPEG_IMAGE_METADATA_T* process_jpeg_directory(const char *directory, int max_images, int *actual_entries) {
    if (max_images > MAX_ENTRIES || actual_entries == NULL) return NULL;

    JPEG_IMAGE_METADATA_T *list = malloc(max_images * sizeof(JPEG_IMAGE_METADATA_T));
    if (list == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    DIR *dir;
    struct dirent *ent;
    int count = 0;

    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char filepath[256];
            snprintf(filepath, sizeof(filepath), "%s/%s", directory, ent->d_name);

            FILE *file = fopen(filepath, "rb");
            if (file == NULL) continue;

            struct jpeg_decompress_struct cinfo;
            struct jpeg_error_mgr jerr;
            cinfo.err = jpeg_std_error(&jerr);
            jpeg_create_decompress(&cinfo);
            jpeg_stdio_src(&cinfo, file);
            jpeg_read_header(&cinfo, TRUE);
            jpeg_start_decompress(&cinfo);

            list[count].width = cinfo.output_width;
            list[count].height = cinfo.output_height;
            fseek(file, 0, SEEK_END);
            list[count].filesize = ftell(file) - sizeof(struct jpeg_header);
            fclose(file);

            jpeg_finish_decompress(&cinfo);
            jpeg_destroy_decompress(&cinfo);

            pthread_mutex_t lock;
            pthread_mutex_init(&lock, NULL);

            pthread_mutex_lock(&lock);
            if (count < max_images) {
                strcpy(list[count].filepath, filepath);
                (*actual_entries)++;
            }
            pthread_mutex_unlock(&lock);

            count++;
        }
        closedir(dir);
    } else perror("Could not open directory");

    return list;
}

void free_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) free(list);
}

void free_jpeg_metadata(JPEG_IMAGE_METADATA_T *list) {
    if (list != NULL) free(list);
}
