typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t used_memory;
} MemoryPool;

void init_memory_pool(MemoryPool* pool, size_t size) {
    pool->memory_pool = malloc(size);
    pool->pool_size = size;
    pool->used_memory = 0;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->used_memory + size > pool->pool_size) {
        return NULL; // Memory allocation failed
    }
    void* ptr = (char*)pool->memory_pool + pool->used_memory;
    pool->used_memory += size;
    return ptr;
}

void deallocate_from_pool(MemoryPool* pool, void* ptr, size_t size) {
    // Assuming the memory is contiguous and in order of allocation
    if ((char*)ptr == (char*)pool->memory_pool + pool->used_memory - size) {
        pool->used_memory -= size;
    } else {
        fprintf(stderr, "Deallocate failed: Invalid pointer\n");
    }
}

