#define MAX_MEMORY_LIMIT 1024 * 1024 * 1024 // 1GB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        return NULL; // Memory allocation failed
    }
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list == NULL) {
        return NULL; // Memory allocation failed
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    return list;
}

void free_list(DoublyLinkedList* list) {
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free_node(temp);
    }
    free(list);
}

int insert_at_end(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        return -1; // Memory allocation failed
    }
    if (list->tail != NULL) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
    return 0;
}

// Other doubly linked list operations (delete, traverse) can be implemented similarly

int initialize_and_populate_list(DoublyLinkedList* list, size_t N) {
    pthread_mutex_lock(&list_mutex); // Lock to prevent concurrent access
    size_t total_size = N * sizeof(Node) + N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > MAX_MEMORY_LIMIT) {
        N = MAX_MEMORY_LIMIT / (sizeof(Node) + sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    for (size_t i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // Initialize data fields with valid values
        data.RX_UE_INFORMATION_TAG = rand();
        data.RNTI = rand() % 65536;
        data.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0 : 1;
        if (insert_at_end(list, data) != 0) {
            pthread_mutex_unlock(&list_mutex); // Unlock on error
            return -1; // Failed to insert node
        }
    }
    pthread_mutex_unlock(&list_mutex); // Unlock after successful insertion
    return 0;
}
