#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 * 500 // 500MB

typedef struct {
    int width;
    int height;
    unsigned char* pixelData;
} THUMBNAIL_DATA;

typedef struct {
    size_t totalMemoryAllocated;
    pthread_mutex_t lock;
} MemoryManager;

void initMemoryManager(MemoryManager* manager) {
    manager->totalMemoryAllocated = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int allocateThumbnail(MemoryManager* manager, int width, int height) {
    size_t pixelDataSize = width * height * sizeof(unsigned char);
    size_t totalNeeded = sizeof(THUMBNAIL_DATA) + pixelDataSize;

    pthread_mutex_lock(&manager->lock);

    if (manager->totalMemoryAllocated + totalNeeded > MAX_MEMORY_LIMIT) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Insufficient resources
    }

    THUMBNAIL_DATA* thumbnail = malloc(totalNeeded);
    if (!thumbnail) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    thumbnail->width = width;
    thumbnail->height = height;
    thumbnail->pixelData = (unsigned char*)((char*)thumbnail + sizeof(THUMBNAIL_DATA));
    manager->totalMemoryAllocated += totalNeeded;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

void freeThumbnail(THUMBNAIL_DATA* thumbnail) {
    if (!thumbnail) return;
    size_t totalSize = sizeof(THUMBNAIL_DATA) + thumbnail->width * thumbnail->height * sizeof(unsigned char);
    free(thumbnail);
}

int processImageFiles(int N, MemoryManager* manager) {
    for (int i = 0; i < N; ++i) {
        int width = rand() % 1024 + 1;
        int height = rand() % 768 + 1;

        int result = allocateThumbnail(manager, width, height);
        if (result == -1) {
            printf("Insufficient resources to generate thumbnail for file %d\n", i);
            // Optionally truncate N or handle in another way
            break;
        } else if (result == -2) {
            printf("Failed to allocate memory for thumbnail for file %d\n", i);
            return -1; // General failure
        }
    }

    return 0; // Success
}

int main() {
    MemoryManager manager;
    initMemoryManager(&manager);

    int N = 1000; // Example number of files to process
    if (processImageFiles(N, &manager) != 0) {
        printf("Failed to process all image files.\n");
    } else {
        printf("Processed %d image files successfully.\n", N);
    }

    return 0;
}
