    if (max_structures == 0) {
        return NULL; // Invalid input
    }

    NFAPI_RESOURCE_MANAGEMENT_STRUCT* resource = malloc(sizeof(NFAPI_RESOURCE_MANAGEMENT_STRUCT));
    if (!resource) {
