    }

    resource->structures = malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!resource->structures) {
        free(resource);
        return NULL; // Memory allocation failed
    }

    resource->max_structures = max_structures;
    resource->current_count = 0;
    pthread_mutex_init(&resource->lock, NULL);

    srand(time(NULL));

