#include <string.h>

// Define the structure for a network packet
typedef struct NetworkPacket {
    int payload_size;
    char* payload;
    struct NetworkPacket* next;
} NetworkPacket;

// Function to parse incoming network packets and allocate memory
NetworkPacket* parse_packets(int* packet_sizes, int num_packets, size_t max_memory) {
    NetworkPacket dummy_head = {0};
    NetworkPacket* current = &dummy_head;
    size_t total_allocated = 0;

    for (int i = 0; i < num_packets && total_allocated <= max_memory; ++i) {
        if (packet_sizes[i] > INT_MAX - total_allocated) {
            // Handle potential integer overflow
            fprintf(stderr, "Packet size too large for remaining memory\n");
            break;
        }

        NetworkPacket* new_packet = malloc(sizeof(NetworkPacket));
        if (!new_packet) {
            perror("Failed to allocate memory for new packet");
            break;
        }

        new_packet->payload_size = packet_sizes[i];
        new_packet->payload = malloc(packet_sizes[i]);
        if (!new_packet->payload) {
            perror("Failed to allocate memory for payload");
            free(new_packet);
            break;
        }
        total_allocated += sizeof(NetworkPacket) + packet_sizes[i];

        current->next = new_packet;
        current = new_packet;
    }

    // If the loop breaks due to memory limits, clean up allocated memory
    while (dummy_head.next != NULL) {
        NetworkPacket* temp = dummy_head.next;
        dummy_head.next = temp->next;
        free(temp->payload);
        free(temp);
    }

    return dummy_head.next; // Return the head of the linked list
}

int main() {
    int packet_sizes[] = {1024, 512, 2048};
    int num_packets = sizeof(packet_sizes) / sizeof(packet_sizes[0]);
    size_t max_memory = 8 * 1024 * 1024; // Example limit of 8MB

    NetworkPacket* packets = parse_packets(packet_sizes, num_packets, max_memory);

    // Print allocated packet sizes for verification
    NetworkPacket* current = packets;
    while (current != NULL) {
        printf("Allocated payload size: %d\n", current->payload_size);
        current = current->next;
    }

    return 0;
}
