#define MAX_STRUCTURES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures;
    size_t count;
    size_t capacity;
    int *hash_table;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_POOL_T;

void initialize_pool(NFAPI_CRC_INDICATION_POOL_T *pool, size_t initial_capacity) {
    pool->structures = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->count = 0;
    pool->capacity = initial_capacity;
    pool->hash_table = (int *)calloc(1024, sizeof(int)); // Simplified hash table for demonstration
    pthread_mutex_init(&pool->mutex, NULL);
}

void resize_pool(NFAPI_CRC_INDICATION_POOL_T *pool) {
    if (pool->count < pool->capacity) return;
    size_t new_capacity = pool->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_structures = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_structures) {
        perror("Memory reallocation failed");
        return;
    }
    pool->structures = new_structures;
    pool->capacity = new_capacity;
}

void add_structure(NFAPI_CRC_INDICATION_POOL_T *pool, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count == pool->capacity) resize_pool(pool);
    pool->structures[pool->count++] = pdu;
    pthread_mutex_unlock(&pool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_structure_by_rnti(NFAPI_CRC_INDICATION_POOL_T *pool, int rnti) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->structures[i].RNTI == rnti) {
            pthread_mutex_unlock(&pool->mutex);
            return &pool->structures[i];
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;
}

void free_pool(NFAPI_CRC_INDICATION_POOL_T *pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->structures);
    free(pool->hash_table);
}
