// Define the NFAPI CRC_INDICATION_PDU_T structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a memory pool structure
typedef struct MemoryPool {
    size_t block_size;
    size_t max_blocks;
    void* blocks;
    size_t free_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Initialize the memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t max_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->block_size = block_size;
    pool->max_blocks = max_blocks;
    pool->blocks = malloc(max_blocks * block_size);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }
    pool->free_blocks = max_blocks;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_blocks == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // No more blocks available
    }
    void* block = (char*)pool->blocks + (pool->max_blocks - pool->free_blocks) * pool->block_size;
    pool->free_blocks--;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Free memory back to the pool
void free_to_pool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)block - (char*)pool->blocks) / pool->block_size;
    if (index >= pool->max_blocks || index < pool->max_blocks - pool->free_blocks) {
        pthread_mutex_unlock(&pool->lock);
        return; // Invalid block
    }
    pool->free_blocks++;
    pthread_mutex_unlock(&pool->lock);
}

