#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKETS 1000
#define MEM_BUDGET 1024 * 1024 // 1 MB

typedef struct Packet {
    int type;
    long timestamp;
    int payload_len;
    char payload[1];
} Packet;

typedef struct BufferPool {
    Packet packets[MAX_PACKETS];
    int head, tail;
    size_t total_memory_used;
    pthread_mutex_t mutex;
} BufferPool;

void init_buffer_pool(BufferPool *pool) {
    pool->head = 0;
    pool->tail = 0;
    pool->total_memory_used = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

int add_packet(BufferPool *pool, int type, long timestamp, const char *payload, int payload_len) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->total_memory_used + sizeof(Packet) + payload_len > MEM_BUDGET) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Memory overflow
    }

    Packet *packet = &pool->packets[pool->tail];
    packet->type = type;
    packet->timestamp = timestamp;
    packet->payload_len = payload_len;

    memcpy(packet->payload, payload, payload_len);

    pool->total_memory_used += sizeof(Packet) + payload_len;
    pool->tail = (pool->tail + 1) % MAX_PACKETS;

    pthread_mutex_unlock(&pool->mutex);
    return 0; // Success
}

Packet* get_packet(BufferPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->head == pool->tail) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL; // No packets available
    }

    Packet *packet = &pool->packets[pool->head];
    pool->total_memory_used -= sizeof(Packet) + packet->payload_len;
    pool->head = (pool->head + 1) % MAX_PACKETS;

    pthread_mutex_unlock(&pool->mutex);
    return packet;
}

void free_buffer_pool(BufferPool *pool) {
    pthread_mutex_destroy(&pool->mutex);
}
