    pthread_mutex_init(&list->lock, NULL);
    list->log_level = log_level;
}

void dynamic_list_add(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > list->max_element_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            new_capacity = list->max_element_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Initialize the new element with random values
    NFAPI_CRC_INDICATION_PDU_T* new_element = &list->elements[list->count];
    new_element->RX_UE_INFORMATION_TAG = rand();
    new_element->RNTI = rand() % 65536; // Random RNTI
    new_element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;

    list->count++;

    if (list->log_level > 0) {
        printf("Added element, total elements: %zu, capacity: %zu\n", list->count, list->capacity);
    }

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_destroy(DynamicList* list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}
