Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory = 0;

void log_allocation(size_t size) {
    pthread_mutex_lock(&mutex);
    total_memory += size;
    printf("Allocated %zu bytes. Total memory usage: %zu bytes\n", size, total_memory);
    pthread_mutex_unlock(&mutex);
}

void log_deallocation(size_t size) {
    pthread_mutex_lock(&mutex);
    if (total_memory < size) {
        printf("Error: Attempting to deallocate more than allocated\n");
    } else {
        total_memory -= size;
        printf("Deallocated %zu bytes. Total memory usage: %zu bytes\n", size, total_memory);
    }
    pthread_mutex_unlock(&mutex);
}

void* allocate_struct() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    log_allocation(sizeof(Node));
    return new_node;
}

void free_struct(void* ptr) {
    log_deallocation(sizeof(Node));
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T* create_new_structure() {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
