    pthread_mutex_lock(&mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    log_allocation(sizeof(Node));
    new_node->data = *new_struct;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&mutex);
}

void clean_up_list() {
    Node* current = head;
    Node* next;
    while (current) {
        next = current->next;
        free_struct(current);
        current = next;
    }
    head = NULL;
    total_memory = 0;
}

void manage_structures(size_t memory_limit) {
    size_t used_memory = 0;
    int count = 0;

    pthread_mutex_lock(&mutex);
    while (used_memory < memory_limit && count < MAX_STRUCTURES) {
        NFAPI_CRC_INDICATION_PDU_T* new_struct = create_new_structure();
        if (!new_struct) break;
        add_structure_to_list(new_struct);
        used_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        count++;
    }
    pthread_mutex_unlock(&mutex);

    printf("Created %d structures. Total memory usage: %zu bytes\n", count, total_memory);

    if (used_memory >= memory_limit) {
        clean_up_list();
        printf("Cleaned up list due to memory limit.\n");
    }
}

