bool resolveHostname(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; /* IPv4 */
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return false;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), sizeof(in_addr_t));

    freeaddrinfo(res);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* createAndPopulateNfapiPduList(int numPDUs, const char *hostname, u_char ip[4], bool *dnsSuccess) {
    if (numPDUs <= 0 || numPDUs > MAX_PDUS) {
        fprintf(stderr, "Invalid number of PDUs\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(numPDUs, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srandom(time(NULL)); // Seed random number generator

    *dnsSuccess = resolveHostname(hostname, ip);
    if (!*dnsSuccess) {
        free(pdus);
        return NULL;
    }

    for (int i = 0; i < numPDUs; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = (unsigned short)(random() % 65536);
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = random() % 2;
    }

    return pdus;
}
