        // Log error message: packet_id, requested_memory_size
        printf("Error: Failed to allocate memory for Packet ID %d. Requested size: %zu\n", id, sizeof(PacketHeader));
        return NULL;
    }

    header->id = id;
    time(&header->timestamp);
    strncpy(header->src_ip, src_ip, 15);
    strncpy(header->dst_ip, dst_ip, 15);
    header->data_length = data_length;

    // Allocate memory for packet_data
    header->packet_data = malloc(data_length + 1024); // Add some extra space to avoid fragmentation
    if (!header->packet_data) {
        // Log error message: packet_id, requested_memory_size
        printf("Error: Failed to allocate data memory for Packet ID %d. Requested size: %zu\n", id, data_length);
        free(header);
        return NULL;
    }

    memset(header->packet_data, 0, data_length + 1024); // Initialize to zero

    return header;
}

// Function to free the memory allocated for a PacketHeader
void free_packet_header(PacketHeader* header) {
    if (header->packet_data) {
        free(header->packet_data);
    }
    free(header);
}
