typedef struct {
    PacketHeader *queue;
    int front, rear;
    size_t capacity;
} PriorityQueue;

void initialize_priority_queue(PriorityQueue *pq, size_t initial_capacity) {
    pq->capacity = initial_capacity;
    pq->front = -1;
    pq->rear = -1;
    pq->queue = (PacketHeader *)malloc(initial_capacity * sizeof(PacketHeader));
}

int is_empty(PriorityQueue *pq) {
    return pq->front == -1;
}

void enqueue(PriorityQueue *pq, PacketHeader packet) {
