typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t size;
    size_t capacity;
} DoublyLinkedList;

DoublyLinkedList* createList(size_t capacity) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (list == NULL) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = capacity;
    return list;
}

void freeList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int insertPacket(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T packet) {
    if (list->size >= list->capacity) return -1; // List is full
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) return -2; // Memory allocation failed
    newNode->data = packet;
    newNode->next = NULL;
    newNode->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->size++;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* retrievePacket(DoublyLinkedList* list, size_t index) {
    if (index >= list->size) return NULL; // Index out of bounds
