int processNetworkPackets(unsigned char* buffer, size_t bufferSize, PacketHeader** headers, size_t* headerCount) {
    if (buffer == NULL || bufferSize <= 0) {
        fprintf(stderr, "Error: Invalid buffer or buffer size.\n");
        return -1;
    }

    *headerCount = 0;
    for (size_t i = 0; i < bufferSize;) {
        PacketHeader header;
        if (i + sizeof(header.headerSize) > bufferSize) {
            fprintf(stderr, "Error: Malformed packet at position %zu.\n", i);
            return -1;
        }
        memcpy(&header.headerSize, buffer + i, sizeof(header.headerSize));
        if (header.headerSize > UINT_MAX - sizeof(PacketHeader)) {
            fprintf(stderr, "Error: Packet header size too large at position %zu.\n", i);
            return -1;
        }
        if (i + header.headerSize > bufferSize) {
            fprintf(stderr, "Error: Malformed packet at position %zu.\n", i);
            return -1;
        }

        // Allocate memory for the full packet
        PacketHeader* newHeaders = realloc(*headers, (*headerCount + 1) * sizeof(PacketHeader));
        if (newHeaders == NULL) {
            fprintf(stderr, "Error: Memory allocation failed at position %zu.\n", i);
            return -1;
        }
        *headers = newHeaders;

        // Copy header and increment count
        memcpy(*headers + *headerCount, buffer + i, sizeof(PacketHeader));
        (*headerCount)++;
        i += sizeof(header.headerSize) + header.headerSize;
    }

    return 0;
}
