#define N 1000000

typedef struct RX_UE_INFORMATION_TAG {
    uint32_t ue_id;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_packet(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T packet) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = packet;
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_packet(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* packet = &list->head->data;
    Node* node_to_remove = list->head;
    list->head = list->head->next;

    if (list->head != NULL) {
        list->head->prev = NULL;
    } else {
        list->tail = NULL;
    }
    free(node_to_remove);
    pthread_mutex_unlock(&list->lock);
    return packet;
}

void* monitor_memory_usage(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        // Simulate memory usage monitoring
        size_t current_size = /* Get current allocated size */;
        if (current_size > 0.7 * /* Total available RAM */) {
            printf("Memory usage exceeded 70%%\n");
        }
        sleep(1);
    }
}

void* packet_reassembly(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* packet = retrieve_packet(list);
        if (packet != NULL) {
            // Simulate packet reassembly
            if (/* Reassembly fails */) {
                printf("Packet reassembly failed for 1%% of incoming packets\n");
            }
        } else {
            sleep(1); // No packet available
        }
    }
}

int main() {
    DoublyLinkedList* list = create_list();

    pthread_t memory_monitor, reassembly_thread;
    pthread_create(&memory_monitor, NULL, monitor_memory_usage, list);
    pthread_create(&reassembly_thread, NULL, packet_reassembly, list);

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        RX_UE_INFORMATION_TAG rx_ue_information;
        rx_ue_information.ue_id = rand() % 1000;
        CRC_INDICATION_REL8_TAG crc_indication_rel8;
        crc_indication_rel8.crcflag = rand() & 0x01;

        NFAPI_CRC_INDICATION_PDU_T packet = {
            .rx_ue_information = rx_ue_information,
            .rnti = i % 65536,
            .crc_indication_rel8 = crc_indication_rel8
        };

        insert_packet(list, packet);
    }

    pthread_join(memory_monitor, NULL);
    pthread_join(reassembly_thread, NULL);

    destroy_list(list);
    return 0;
}
