#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFapiCrcIndicationPduT;

typedef struct Node {
    NFapiCrcIndicationPduT data;
    struct Node* next;
} Node;

void initializeLinkedList(Node** head) {
    *head = NULL;
}

int insertNode(Node** head, int RX_UE_INFORMATION_TAG, int RNTI, char CRC_INDICATION_REL8_TAG) {
    if (*head == NULL || *head->next == NULL) { // Check for list full or empty
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) return -1; // Memory allocation failed

        newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        newNode->data.RNTI = RNTI;
        newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        newNode->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (*head == NULL) {
            *head = newNode;
        } else {
            Node* temp = *head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = newNode;
        }

        newNode->next = NULL;

        return 0; // Success
    } else {
        return -1; // List is full
    }
}

void freeLinkedList(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    Node* head = NULL;
    initializeLinkedList(&head);

    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        if (insertNode(&head, i, i + 100, 'A') != 0) {
            printf("Failed to insert node at index %d\n", i);
            break;
        }
    }

    freeLinkedList(&head);

    return 0;
}
