#define MAX_IMAGE_SIZE 1024 * 1024 * 10 // 10 MB

typedef struct Image {
    char* filename;
    size_t size;
    void* data;
} Image;

Image* load_images(const char* filenames[], int num_files, size_t max_memory) {
    Image* images = (Image*)malloc(num_files * sizeof(Image));
    if (!images) {
        fprintf(stderr, "Failed to allocate memory for image list.\n");
        return NULL;
    }

    size_t total_memory_used = 0;

    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", filenames[i]);
            continue;
        }

        fseek(file, 0, SEEK_END);
        size_t reported_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (reported_size > MAX_IMAGE_SIZE || reported_size == 0) {
            fprintf(stderr, "Invalid file size for: %s\n", filenames[i]);
            fclose(file);
            continue;
        }

        if ((total_memory_used + reported_size) > max_memory) {
            fprintf(stderr, "Memory limit exceeded for image: %s\n", filenames[i]);
            fclose(file);
            continue;
        }

        images[i].filename = strdup(filenames[i]);
        images[i].size = reported_size;
        images[i].data = malloc(reported_size);
        if (!images[i].data) {
            fprintf(stderr, "Failed to allocate memory for image data: %s\n", filenames[i]);
            fclose(file);
            continue;
        }

        fread(images[i].data, 1, reported_size, file);
        fclose(file);

        total_memory_used += reported_size;
    }

    return images;
}

void free_images(Image* images, int num_files) {
    for (int i = 0; i < num_files; ++i) {
        free(images[i].filename);
        free(images[i].data);
    }
    free(images);
}
