#define DEFAULT_MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    int some_data;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t memory_limit;
    size_t current_memory_usage;
    pthread_mutex_t mutex;
} MemoryManager;

MemoryManager memory_manager = {DEFAULT_MEMORY_LIMIT, 0, PTHREAD_MUTEX_INITIALIZER};

int allocate_nfaip_crc_indication_pdu(size_t num_structs) {
    if (num_structs == 0 || num_structs > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Invalid number of structures requested\n");
        return -1;
    }

    size_t required_memory = num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory + memory_manager.current_memory_usage > memory_manager.memory_limit) {
        fprintf(stderr, "Warning: Memory limit exceeded. Not enough memory available.\n");
        return -2;
    }

    pthread_mutex_lock(&memory_manager.mutex);
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(required_memory);
    if (!pdu_list) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        pthread_mutex_unlock(&memory_manager.mutex);
        return -3;
    }

    // Initialize structures here
    for (size_t i = 0; i < num_structs; i++) {
        pdu_list[i].some_data = i; // Example initialization
    }

    memory_manager.current_memory_usage += required_memory;
    pthread_mutex_unlock(&memory_manager.mutex);

    return (int)pdu_list;
}

void free_nfaip_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_list, size_t num_structs) {
    if (!pdu_list || num_structs == 0) {
        fprintf(stderr, "Error: Invalid input for freeing structures\n");
        return;
    }

    pthread_mutex_lock(&memory_manager.mutex);
    free(pdu_list);
    memory_manager.current_memory_usage -= num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&memory_manager.mutex);
}

void set_memory_limit(size_t new_limit) {
    pthread_mutex_lock(&memory_manager.mutex);
    memory_manager.memory_limit = new_limit;
    pthread_mutex_unlock(&memory_manager.mutex);
}
