unsigned long simpleHash(char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

char* randomStringHash(int length, char* value) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = malloc(length + 1);
    if (randomString == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (int i = 0; i < length; ++i) {
        randomString[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    randomString[length] = '\0';
    unsigned long hashValue = simpleHash(value);
    // Assuming the output buffer is large enough to hold the hash and string
    char *output = malloc(strlen(randomString) + 20); // Adjust size as necessary
    if (output == NULL) {
        // Handle memory allocation failure
        free(randomString);
        return NULL;
    }
    snprintf(output, strlen(randomString) + 20, "%s: %lu", randomString, hashValue);
    free(randomString);
    return output;
}

NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCList(int N, char *charset, char *value) {
    if (N <= 0 || charset == NULL || value == NULL) {
        // Handle invalid input
        return NULL;
    }
    size_t totalSize = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (totalSize / N != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Check for integer overflow
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *crcList = malloc(totalSize);
    if (crcList == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        snprintf(crcList[i].RX_UE_INFORMATION_TAG, sizeof(crcList[i].RX_UE_INFORMATION_TAG), "Tag%d", rand() % 10);
        crcList[i].RNTI = rand();
        snprintf(crcList[i].CRC_INDICATION_REL8_TAG, sizeof(crcList[i].CRC_INDICATION_REL8_TAG), "%dFlag", rand() % 2);
    }
    return crcList;
}
