#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 500000
#define CACHE_SIZE 10000

typedef struct {
    uint32_t packetID;
    time_t timestamp;
    char sourceIP[16];
    char destIP[16];
    size_t length;
} PacketHeader;

typedef struct {
    PacketHeader *packets[MAX_PACKETS];
    int head, tail, count;
    pthread_mutex_t lock;
} Queue;

Queue *createQueue() {
    Queue *q = malloc(sizeof(Queue));
    q->head = q->tail = q->count = 0;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(Queue *q, PacketHeader *packet) {
    pthread_mutex_lock(&q->lock);
    if (q->count < MAX_PACKETS) {
        q->packets[q->tail] = packet;
        q->tail = (q->tail + 1) % MAX_PACKETS;
        q->count++;
    }
    pthread_mutex_unlock(&q->lock);
}

PacketHeader *dequeue(Queue *q) {
    pthread_mutex_lock(&q->lock);
    if (q->count > 0) {
        PacketHeader *packet = q->packets[q->head];
        q->head = (q->head + 1) % MAX_PACKETS;
        q->count--;
        return packet;
    }
    pthread_mutex_unlock(&q->lock);
    return NULL;
}

int main() {
    Queue *queue = createQueue();

    // Example usage
    PacketHeader packet;
    memset(&packet, 0, sizeof(PacketHeader));
    enqueue(queue, &packet);

    PacketHeader *dequeuedPacket = dequeue(queue);
    if (dequeuedPacket != NULL) {
        free(dequeuedPacket);
    }

    free(queue);
    return 0;
}
