pthread_cond_t queueCond = PTHREAD_COND_INITIALIZER;

void initModule() {
    packetBuffer = (PacketHeader *)malloc(MAX_PACKETS * sizeof(PacketHeader));
    if (!packetBuffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void destroyModule() {
