    if (currentPacketCount < CACHE_SIZE) {
        packetBuffer[currentPacketCount++] = packet;
    } else {
        // Implement cache replacement strategy
    }
    pthread_mutex_unlock(&bufferMutex);
}

int removePacketFromCache(int packetID, PacketHeader *packet) {
    pthread_mutex_lock(&bufferMutex);
    for (int i = 0; i < currentPacketCount; ++i) {
        if (packetBuffer[i].packetID == packetID) {
            *packet = packetBuffer[i];
            memmove(&packetBuffer[i], &packetBuffer[i + 1], (currentPacketCount - i - 1) * sizeof(PacketHeader));
            --currentPacketCount;
            pthread_mutex_unlock(&bufferMutex);
            return 0; // Packet found and removed
        }
    }
    pthread_mutex_unlock(&bufferMutex);
    return -1; // Packet not found in cache
}

void processPacket(ProcessedPacket packet) {
    // Implement packet processing logic
}

int enqueueProcessedPacket(ProcessedPacket packet) {
    pthread_mutex_lock(&queueMutex);
    if (front == -1) {
        front = rear = 0;
    } else if ((rear + 1) % QUEUE_CAPACITY == front) {
        pthread_mutex_unlock(&queueMutex);
        return -1; // Queue is full
    }
    queue[rear] = packet;
    rear = (rear + 1) % QUEUE_CAPACITY;
    pthread_cond_signal(&queueCond);
    pthread_mutex_unlock(&queueMutex);
    return 0; // Packet enqueued successfully
}

ProcessedPacket dequeueProcessedPacket() {
    ProcessedPacket packet;
    pthread_mutex_lock(&queueMutex);
    while (front == -1) {
        pthread_cond_wait(&queueCond, &queueMutex);
    }
    packet = queue[front];
    if (front == rear) {
        front = rear = -1;
    } else {
        front = (front + 1) % QUEUE_CAPACITY;
    }
    pthread_mutex_unlock(&queueMutex);
    return packet; // Packet dequeued
}

