#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MAX_BUFFER_LIMIT 5 * 1024 * 1024 // 5MB
#define BUFFER_RESIZE_THRESHOLD 0.95

typedef struct {
    void* buffer;
    size_t buffer_size;
    size_t used_space;
    pthread_mutex_t lock;
} NetworkBuffer;

NetworkBuffer network_buffer;

void initialize_network_buffer() {
    network_buffer.buffer = malloc(MAX_BUFFER_LIMIT);
    if (network_buffer.buffer == NULL) {
        fprintf(stderr, "Failed to allocate initial buffer.\n");
        exit(EXIT_FAILURE);
    }
    network_buffer.buffer_size = MAX_BUFFER_LIMIT;
    network_buffer.used_space = 0;
    pthread_mutex_init(&network_buffer.lock, NULL);
}

void resize_network_buffer() {
    size_t new_size = (size_t)(network_buffer.buffer_size * 2);
    if (new_size > MAX_BUFFER_LIMIT) {
        fprintf(stderr, "Buffer resizing would exceed limit.\n");
        return;
    }
    void* new_buffer = realloc(network_buffer.buffer, new_size);
    if (new_buffer == NULL) {
        fprintf(stderr, "Failed to resize buffer.\n");
        return;
    }
    network_buffer.buffer = new_buffer;
    network_buffer.buffer_size = new_size;
}

int process_packet(const char* packet_data, size_t packet_size) {
    pthread_mutex_lock(&network_buffer.lock);
    if (network_buffer.used_space + packet_size > network_buffer.buffer_size * BUFFER_RESIZE_THRESHOLD) {
        resize_network_buffer();
    }
    if (network_buffer.used_space + packet_size > network_buffer.buffer_size) {
        pthread_mutex_unlock(&network_buffer.lock);
        fprintf(stderr, "Buffer overflow detected.\n");
        return -1;
    }
    memcpy((char*)network_buffer.buffer + network_buffer.used_space, packet_data, packet_size);
    network_buffer.used_space += packet_size;
    pthread_mutex_unlock(&network_buffer.lock);
    return 0;
}

void report_performance() {
    printf("Memory Usage: %zu/%zu\n", network_buffer.used_space, network_buffer.buffer_size);
    // Additional performance metrics can be added here
}

int main() {
    initialize_network_buffer();
    // Simulate packet processing
    char packets[10][MAX_PACKET_SIZE];
    for (int i = 0; i < 10; i++) {
        snprintf(packets[i], MAX_PACKET_SIZE, "Packet %d", i);
        process_packet(packets[i], strlen(packets[i]));
    }
    report_performance();
    pthread_mutex_destroy(&network_buffer.lock);
    free(network_buffer.buffer);
    return 0;
}
