NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(uint32_t max_elements, double crc_flags, size_t memory_threshold) {
    if (max_elements == 0 || crc_flags < 0 || crc_flags > 1) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (uint32_t i = 0; i < max_elements; ++i) {
        size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (required_memory > memory_threshold - (*current == NULL ? 0 : sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_memory);
        if (!new_node) {
            free_list(head); // Free all previously allocated nodes
            return NULL;
        }

        new_node->rx_ue_info = RX_UE_INFORMATION_TAG(rand() % 100); // Example initialization
        new_node->rnti = (uint16_t)(rand() % 65536);
        new_node->crc_indication.crcflag = (rand() < crc_flags * RAND_MAX) ? 1 : 0;

        *current = new_node;
        current = &new_node->next;
    }

    *current = NULL; // Null-terminate the list
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    uint32_t max_elements = 1000;
    double crc_flags = 0.5;
    size_t memory_threshold = (max_elements + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    NFAPI_CRC_INDICATION_PDU_T* list = create_and_populate_list(max_elements, crc_flags, memory_threshold);
    if (list != NULL) {
        // Use the list
        free_list(list);
    }

    return 0;
}
