    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu(int count, int max_structures) {
    if (count > max_structures || count <= 0) {
        return NULL; // Invalid input or exceeding maximum structures
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (int i = 0; i < count; i++) {
        if (i == 0) {
            head = current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            current->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current = current->next;
        }

        if (!current) {
            // Handle memory allocation failure
            while (head) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL; // Out of memory
        }

        current->rx_ue_info.RX_UE_INFORMATION_TAG = rand();
        current->rx_ue_info.RNTI = rand() % 65535;
        current->crc_indication.CRCFLAG = (rand() % 2) ? 1 : 0;

        if (i != count - 1) {
            current->next = NULL;
        }
    }

    return head;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
}
