#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint8_t tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint16_t value;
} RNTI;

typedef struct {
    uint8_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t allocated_size;
    size_t used_size;
    uint32_t crc_errors;
    pthread_mutex_t mutex;
} CRC_INDICATOR_MANAGER;

void init_crc_indicator_manager(CRC_INDICATOR_MANAGER* manager, size_t max_size) {
    if (max_size == 0) return;
    manager->list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (manager->list == NULL) return; // Handle memory allocation failure
    manager->allocated_size = max_size;
    manager->used_size = 0;
    manager->crc_errors = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void destroy_crc_indicator_manager(CRC_INDICATOR_MANAGER* manager) {
    free(manager->list);
    pthread_mutex_destroy(&manager->mutex);
}

bool add_crc_indication(CRC_INDICATOR_MANAGER* manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->used_size >= manager->allocated_size) {
        pthread_mutex_unlock(&manager->mutex);
        return false; // List is full
    }
    NFAPI_CRC_INDICATION_PDU_T* new_item = &manager->list[manager->used_size];
    new_item->rx_tag.tag = 1; // Example initialization
    new_item->rnti.value = rand() % 65536; // Random RNTI value
    new_item->crc_flag.crcflag = (rand() % 2 == 0) ? 0 : 1; // Random CRC flag
    manager->used_size++;
    pthread_mutex_unlock(&manager->mutex);
    return true;
}

void report_crc_errors(CRC_INDICATOR_MANAGER* manager) {
    pthread_mutex_lock(&manager->mutex);
    uint32_t errors = manager->crc_errors;
    pthread_mutex_unlock(&manager->mutex);
    printf("CRC Errors: %u\n", errors);
}

// Example usage
int main() {
    CRC_INDICATOR_MANAGER manager;
    init_crc_indicator_manager(&manager, 1000);

    srand(time(NULL));
    for (size_t i = 0; i < 500; i++) {
        if (!add_crc_indication(&manager)) {
            printf("Failed to add CRC indication\n");
        }
    }

    report_crc_errors(&manager);
    destroy_crc_indicator_manager(&manager);

    return 0;
}
```

