typedef struct IMAGE_METADATA_RECORD {
    char fileName[256];
    int resolution;
    int pixelDepth;
} IMAGE_METADATA_RECORD;

int processDirectory(const char* directoryPath, IMAGE_METADATA_RECORD** records) {
    DIR* dir = opendir(directoryPath);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    struct dirent* entry;
    int recordCount = 0;
    *records = NULL;

    while ((entry = readdir(dir)) != NULL) {
        if (recordCount >= MAX_RECORDS) {
            printf("Maximum number of records reached\n");
            break;
        }

        // Check for file extension and read metadata
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        IMAGE_METADATA_RECORD* record = realloc(*records, (recordCount + 1) * sizeof(IMAGE_METADATA_RECORD));
        if (!record) {
            perror("Memory allocation failed");
            closedir(dir);
            return -1;
        }
        *records = record;

        // Populate metadata (simplified example)
        strcpy((*records)[recordCount].fileName, entry->d_name);
        (*records)[recordCount].resolution = 1920; // Example value
        (*records)[recordCount].pixelDepth = 24; // Example value

        recordCount++;
    }

    closedir(dir);

    if (recordCount * sizeof(IMAGE_METADATA_RECORD) > MEMORY_LIMIT) {
        printf("Memory limit exceeded\n");
        free(*records);
        *records = NULL;
        return -1;
    }

    return recordCount;
}

void cleanupRecords(IMAGE_METADATA_RECORD* records, int count) {
    for (int i = 0; i < count; i++) {
        // Perform any necessary cleanup for each record
    }
    free(records);
}

int main() {
    IMAGE_METADATA_RECORD* records = NULL;
    int count = processDirectory("path/to/images", &records);

    if (count >= 0) {
        printf("Processed %d records\n", count);
        cleanupRecords(records, count);
    }

    return 0;
}
