#include <stdlib.h>
#include <pthread.h>
#include <limits.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    size_t max_size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

void init_crc_array(NFAPI_CRC_ARRAY_T* array, size_t initial_capacity, size_t max_size) {
    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->data == NULL) {
        // Handle memory allocation failure
        return;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    array->max_size = max_size < INT_MAX / initial_capacity ? max_size : INT_MAX / initial_capacity - 1;
    pthread_mutex_init(&array->mutex, NULL);
}

void add_to_crc_array(NFAPI_CRC_ARRAY_T* array, NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->max_size) {
        // Handle maximum size exceeded
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Handle memory reallocation failure
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = new_data;
    pthread_mutex_unlock(&array->mutex);
}

void destroy_crc_array(NFAPI_CRC_ARRAY_T* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->data);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}
