    size_t free_blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t pool_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->block_size = block_size;
    pool->pool_size = pool_size * block_size;
    pool->free_blocks = pool_size;
    pthread_mutex_init(&pool->lock, NULL);
    pool->pool = malloc(pool->pool_size);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    void* block = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_blocks > 0) {
        block = (char*)pool->pool + (pool->pool_size - pool->block_size * pool->free_blocks);
        pool->free_blocks--;
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void memory_pool_free(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index >= pool->free_blocks && index < pool->pool_size / pool->block_size) {
        pool->free_blocks++;
    }
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* read_and_populate_array(const char* filename, MemoryPool* pool) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    int num_structures;
    if (fread(&num_structures, sizeof(int), 1, file) != 1 || num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = memory_pool_alloc(pool);
    if (!array) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < num_structures; ++i) {
        if (fread(&array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) != 1) {
            memory_pool_free(pool, array);
            fclose(file);
            return NULL;
        }
    }

    fclose(file);
    return array;
}

NFAPI_CRC_INDICATION_PDU_T* generate_array(size_t num_structures, MemoryPool* pool) {
    NFAPI_CRC_INDICATION_PDU_T* array = memory_pool_alloc(pool);
    if (!array) return NULL;

    for (size_t i = 0; i < num_structures; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = (uint16_t)(rand() % 4096);
        array[i].CRC_INDICATION_REL8_TAG = rand() % 3 + 1; // Constrained to 1, 2, or 3
    }

    return array;
}
