typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTURES];
    int pool_size;
    int next_index;
} MemoryPoolManager;

MemoryPoolManager memory_pool;

void initialize_memory_pool() {
    pthread_mutex_init(&memory_pool.lock, NULL);
    memory_pool.pool_size = 0;
    memory_pool.next_index = 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = NULL;

    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.next_index < memory_pool.pool_size) {
        new_struct = memory_pool.pool[memory_pool.next_index++];
    } else {
        if (memory_pool.pool_size >= MAX_STRUCTURES) {
            // Handle error, pool is full
            printf("Memory pool full\n");
        } else {
            new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_struct != NULL) {
                memory_pool.pool[memory_pool.pool_size++] = new_struct;
                new_struct->RX_UE_INFORMATION_TAG = 0; // Initialize fields
                new_struct->RNTI = 0;
                new_struct->CRC_INDICATION_REL8_TAG = 0;
            } else {
                printf("Memory allocation failed\n");
            }
        }
    }
    pthread_mutex_unlock(&memory_pool.lock);

    return new_struct;
}

void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *struct_to_free) {
    pthread_mutex_lock(&memory_pool.lock);
    if (struct_to_free != NULL) {
        // Add the structure back to the pool
        memory_pool.pool[memory_pool.next_index++] = struct_to_free;
    }
    pthread_mutex_unlock(&memory_pool.lock);
}

void* generate_structures(void *arg) {
    int N = *(int*)arg;
    if (N <= 0 || N > MAX_STRUCTURES) {
        printf("Invalid number of structures\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_struct = allocate_structure();
        if (new_struct != NULL) {
            // Populate the structure with random CRCFLAG values
            new_struct->CRCFLAG = rand() % 10 + 1;
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    initialize_memory_pool();

    int N = 5000; // Example number of structures to generate

