    if (pthread_create(&thread, NULL, generate_structures, &N) != 0) {
        printf("Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    // Deallocate all structures
    for (int i = 0; i < memory_pool.next_index; i++) {
        deallocate_structure(memory_pool.pool[i]);
    }

    pthread_mutex_destroy(&memory_pool.lock);
    return 0;
}
