#include <time.h>

#define MAX_MEMORY 1024 * 1024 * 1024 // 1GB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_NFAPI_packet(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* packet = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (packet == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    packet->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    packet->RNTI = RNTI;
    packet->CRCFLAG = rand() % 256; // Using a pseudo-random number generator
    packet->next = NULL;
    return packet;
}

void process_NFAPI_packets(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG < 0 || current->RNTI < 0) {
            fprintf(stderr, "Invalid data encountered\n");
            free(current);
            current = (*head)->next;
            *head = current;
            continue;
        }
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        if (next != NULL && (unsigned long)(next - current) > MAX_MEMORY) {
            fprintf(stderr, "Memory limit exceeded\n");
            free(current);
            current = next;
            *head = current;
            continue;
        }
        // Process the packet
        current = next;
    }
}

void serialize_NFAPI_packets(NFAPI_CRC_INDICATION_PDU_T* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fwrite(&current->CRCFLAG, sizeof(unsigned char), 1, file);
        current = current->next;
    }
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_NFAPI_packets(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;
    while (!feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T* packet = create_NFAPI_packet(0, 0);
        if (packet == NULL) {
            break;
        }
        fread(&packet->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&packet->RNTI, sizeof(int), 1, file);
        fread(&packet->CRCFLAG, sizeof(unsigned char), 1, file);
        packet->next = NULL;
        *current = packet;
        current = &packet->next;
    }
    fclose(file);
    return head;
}

int main() {
    srand(time(NULL)); // Seed the pseudo-random number generator
    NFAPI_CRC_INDICATION_PDU_T* head = create_NFAPI_packet(1, 2);
    if (head != NULL) {
        head->next = create_NFAPI_packet(3, 4);
        process_NFAPI_packets(&head);
        serialize_NFAPI_packets(head, "packets.bin");
        NFAPI_CRC_INDICATION_PDU_T* deserialized_head = deserialize_NFAPI_packets("packets.bin");
        // Process the deserialized linked list
        free_all_packets(deserialized_head);
    }
    return 0;
}

void free_all_packets(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}
