typedef struct PacketHeader {
    int payload_length;
    void* payload_data;
} PacketHeader;

void process_packet_headers(PacketHeader* headers, int num_headers) {
    if (num_headers <= 0) {
        printf("No packets to process.\n");
        return;
    }

    size_t total_payload_size = 0;
    for (int i = 0; i < num_headers; ++i) {
        // Calculate total payload size without overflow
        if (total_payload_size > SIZE_MAX - headers[i].payload_length) {
            fprintf(stderr, "Integer overflow detected.\n");
            return;
        }
        total_payload_size += headers[i].payload_length;
    }

    // Allocate buffer for all payloads
    void* combined_buffer = malloc(total_payload_size);
    if (combined_buffer == NULL) {
        perror("Failed to allocate buffer.");
        return;
    }

    // Copy payloads into the buffer
    char* write_ptr = combined_buffer;
    for (int i = 0; i < num_headers; ++i) {
        memcpy(write_ptr, headers[i].payload_data, headers[i].payload_length);
        write_ptr += headers[i].payload_length;
    }

    // Use the combined buffer as needed
    printf("Total payload size: %zu\n", total_payload_size);

    // Free the allocated buffer when done
    free(combined_buffer);
}

int main() {
    // Example usage
    PacketHeader headers[] = {
        {10, (void*)"Packet 1"},
        {20, (void*)"Packet 2"},
        {30, (void*)"Packet 3"}
    };
    int num_headers = sizeof(headers) / sizeof(headers[0]);

    process_packet_headers(headers, num_headers);

    return 0;
}
