#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Define the maximum packet size that can be handled by the system
#define MAX_PACKET_SIZE 1500

// Define the structure for a network packet
typedef struct {
    uint64_t timestamp;
    uint32_t length;
    char *payload;
} Packet;

// Function to dynamically allocate memory for an array of packets
Packet* allocate_packets(uint32_t num_packets, size_t max_memory) {
    // Calculate the total required memory for packets and payloads
    size_t packets_memory = num_packets * sizeof(Packet);
    size_t payload_memory = num_packets * MAX_PACKET_SIZE;

    // Check for potential integer overflow in memory calculation
    if ((packets_memory > SIZE_MAX - payload_memory) || (payload_memory > max_memory)) {
        return NULL;
    }

    // Allocate memory for the array of packet structures
    Packet* packets = malloc(packets_memory);
    if (packets == NULL) {
        return NULL;
    }

    // Initialize each packet structure
    for (uint32_t i = 0; i < num_packets; i++) {
        packets[i].timestamp = 0;
        packets[i].length = 0;
        packets[i].payload = malloc(MAX_PACKET_SIZE);
        if (packets[i].payload == NULL) {
            // Free previously allocated memory before returning NULL
            for (uint32_t j = 0; j < i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL;
        }
    }

    return packets;
}

// Function to free the memory allocated for an array of packets
void free_packets(Packet* packets, uint32_t num_packets) {
    if (packets == NULL) {
        return;
    }

    // Free each packet's payload buffer and then the packet structures themselves
    for (uint32_t i = 0; i < num_packets; i++) {
        if (packets[i].payload != NULL) {
            free(packets[i].payload);
        }
    }

    free(packets);
}

int main() {
    uint32_t num_packets = 10;
    size_t max_memory = 10 * 1024 * 1024; // 10 MB

    Packet* packets = allocate_packets(num_packets, max_memory);
    if (packets != NULL) {
        printf("Successfully allocated memory for %u packets\n", num_packets);

        // Process the packets...

        free_packets(packets, num_packets);
        printf("Memory freed successfully\n");
    } else {
        printf("Failed to allocate memory for packets\n");
    }

    return 0;
}
```

