#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKET_SIZE 1500
#define MIN_MEMORY_LIMIT 1024 * 1024

typedef struct {
    uint8_t* data;
    size_t length;
} Packet;

typedef struct {
    Packet* packets;
    size_t count;
    size_t capacity;
    size_t memory_used;
} PacketList;

Packet* create_packet(size_t size) {
    if (size > MAX_PACKET_SIZE) return NULL;
    Packet* packet = malloc(sizeof(Packet));
    if (!packet) return NULL;
    packet->data = malloc(size);
    if (!packet->data) {
        free(packet);
        return NULL;
    }
    packet->length = size;
    return packet;
}

void destroy_packet(Packet* packet) {
    free(packet->data);
    free(packet);
}

PacketList* create_packet_list(size_t initial_capacity, size_t memory_limit) {
    if (memory_limit < MIN_MEMORY_LIMIT) return NULL;
    PacketList* list = malloc(sizeof(PacketList));
    if (!list) return NULL;
    list->packets = malloc(initial_capacity * sizeof(Packet));
    if (!list->packets) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;
    list->memory_used = 0;
    return list;
}

void destroy_packet_list(PacketList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        destroy_packet(&list->packets[i]);
    }
    free(list->packets);
    free(list);
}

int add_packet_to_list(PacketList* list, Packet packet) {
    if (list->memory_used + packet.length > list->memory_limit) return -1;
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Packet* new_packets = realloc(list->packets, new_capacity * sizeof(Packet));
        if (!new_packets) return -1;
        list->packets = new_packets;
        list->capacity = new_capacity;
    }
    list->packets[list->count++] = packet;
