    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
    int insert_success;
    int insert_failure;
} LinkedList;

LinkedList* create_linked_list(size_t max_size) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;

    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->insert_success = 0;
    list->insert_failure = 0;

    return list;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        list->insert_failure++;
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        list->insert_failure++;
        return -1;
    }

    memcpy(&new_node->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    list->insert_success++;
    return 0;
}

void* fetch_and_update(void* arg) {
    LinkedList* list = (LinkedList*)arg;

    // Simulate fetching data from a remote source
    NFAPI_CRC_INDICATION_PDU_T new_data;
    if (fetch_new_data(&new_data)) {
        insert_node(list, new_data);
    }

    return NULL;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}
