// Function to allocate memory for packet payloads
void* allocate_payloads(PacketHeader* headers, int num_headers, size_t max_memory) {
    void* total_payloads = NULL;
    size_t total_required_memory = 0;

    // Calculate the total required memory for payloads
    for (int i = 0; i < num_headers; ++i) {
        // Check for integer overflow and ignore header if it's invalid
        uint64_t payload_mem = (uint64_t)headers[i].payload_size * sizeof(uint8_t);
        if (payload_mem > SIZE_MAX || total_required_memory + payload_mem < total_required_memory) {
            continue; // Skip this header due to potential overflow or invalid size
        }
        total_required_memory += payload_mem;
    }

    // Allocate memory only if the total required memory is within the limit
    if (total_required_memory <= max_memory) {
        total_payloads = malloc(total_required_memory);
        if (total_payloads == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
    } else {
        // Handle case where required memory exceeds the limit
        // Optionally, log an error or handle as needed
        return NULL;
    }

    return total_payloads;
}

// Example usage:
int main() {
    PacketHeader headers[] = {{1, 1024}, {2, 512}, {3, 768}};
    int num_headers = sizeof(headers) / sizeof(headers[0]);
    size_t max_memory = 4096; // Example maximum memory limit

