#define MAX_PACKETS 1024

typedef struct {
    int id;
} record;

typedef struct packet {
    size_t payload_size;
    char *payload;
    struct packet *next;
} packet;

unsigned int custom_prng() {
    // Implement a custom pseudo-random number generator
    static unsigned int state = time(NULL);
    state ^= (state << 13) | (state >> 9);
    return state & 0x7FFFFFFF;
}

void process_packets(packet **head, record *ids) {
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (*head == NULL) break;

        packet *current = *head;
        *head = current->next;

        size_t payload_size = *(size_t *)current->payload;
        char *new_payload = malloc(payload_size);
        if (new_payload == NULL) {
            fprintf(stderr, "Memory allocation failed for packet payload\n");
            free(current->payload);
            free(current);
            continue;
        }

        memcpy(new_payload, current->payload + sizeof(size_t), payload_size);

        // Ensure no integer overflow
        if ((size_t)(current->payload + sizeof(size_t)) - (size_t)current->payload != payload_size) {
            fprintf(stderr, "Potential integer overflow detected\n");
            free(new_payload);
            free(current->payload);
            free(current);
            continue;
        }

        packet *new_packet = malloc(sizeof(packet));
        if (new_packet == NULL) {
            fprintf(stderr, "Memory allocation failed for new packet structure\n");
            free(new_payload);
            free(current->payload);
            free(current);
            continue;
        }

        new_packet->payload_size = payload_size;
        new_packet->payload = new_payload;
        new_packet->next = NULL;

        // Allocate unique identifier
        ids[i].id = custom_prng();

        // Log packet processing information (placeholder)
        printf("Packet processed with ID: %d, Payload Size: %zu\n", ids[i].id, payload_size);

        free(current);
    }
}

int main() {
    record ids[MAX_PACKETS];
    packet *packet_head = NULL;

    // Simulate adding packets to the linked list
    for (int i = 0; i < MAX_PACKETS; ++i) {
        packet *new_packet = malloc(sizeof(packet));
        if (new_packet == NULL) break;
        new_packet->payload_size = rand() % 1024 + 1;
        new_packet->payload = malloc(new_packet->payload_size + sizeof(size_t));
        if (new_packet->payload == NULL) {
            free(new_packet);
            break;
        }
        *(size_t *)new_packet->payload = new_packet->payload_size;
        // Populate payload with random data
        for (size_t j = 0; j < new_packet->payload_size; ++j) {
            ((char *)new_packet->payload)[j + sizeof(size_t)] = rand() % 256;
        }
        new_packet->next = packet_head;
        packet_head = new_packet;
    }

    process_packets(&packet_head, ids);

    // Free allocated memory
    while (packet_head != NULL) {
        packet *temp = packet_head;
        free(temp->payload);
        free(temp);
        packet_head = temp->next;
    }

    return 0;
}
