NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N, size_t total_memory) {
    if (total_memory < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Error: Not enough memory to allocate %d structures\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
