        new_node->RNTI = rand() % 256;                 // Simulate random RNTI
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2;   // Randomly set CRCFLAG

        if (!head) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
