typedef struct PacketHeader {
    size_t payloadSize;
} PacketHeader;

typedef struct AggregatedPacket {
    size_t totalPayloadSize;
    char* aggregatedData;
} AggregatedPacket;

AggregatedPacket* processPacketHeaders(PacketHeader headers[], size_t numPackets) {
    // Calculate the total size of all payloads
    size_t totalPayloadSize = 0;
    for (size_t i = 0; i < numPackets; ++i) {
        totalPayloadSize += headers[i].payloadSize;
    }

    // Allocate memory for the aggregated packet data
    char* aggregatedData = (char*)malloc(totalPayloadSize);
    if (!aggregatedData) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize aggregated packet structure
    AggregatedPacket* aggregatedPacket = (AggregatedPacket*)malloc(sizeof(AggregatedPacket));
    if (!aggregatedPacket) {
        perror("Memory allocation failed");
        free(aggregatedData);
        return NULL;
    }
    aggregatedPacket->totalPayloadSize = totalPayloadSize;
    aggregatedPacket->aggregatedData = aggregatedData;

    // Copy payload data into the aggregated packet
    size_t offset = 0;
    for (size_t i = 0; i < numPackets; ++i) {
        memcpy(aggregatedPacket->aggregatedData + offset, /* source payload data */, headers[i].payloadSize);
        offset += headers[i].payloadSize;
    }

    return aggregatedPacket;
}

void freeAggregatedPacket(AggregatedPacket* packet) {
    if (packet) {
        free(packet->aggregatedData);
        free(packet);
    }
}
