typedef struct {
    char filename[256];
    int width;
    int height;
    size_t file_size;
} ImageMetadata;

typedef struct {
    ImageMetadata *metadata_array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicImageArray;

void initialize_dynamic_image_array(DynamicImageArray *array, size_t initial_capacity) {
    array->metadata_array = (ImageMetadata *)malloc(initial_capacity * sizeof(ImageMetadata));
    if (array->metadata_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for dynamic image array\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
}

void free_dynamic_image_array(DynamicImageArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->metadata_array);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

int add_metadata_to_array(DynamicImageArray *array, const char *filename, int width, int height, size_t file_size) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        ImageMetadata *new_metadata = realloc(array->metadata_array, array->capacity * 2 * sizeof(ImageMetadata));
        if (new_metadata == NULL) {
            fprintf(stderr, "Failed to allocate memory for dynamic image array\n");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->metadata_array = new_metadata;
        array->capacity *= 2;
    }
    strncpy(array->metadata_array[array->count].filename, filename, sizeof(array->metadata_array[array->count].filename) - 1);
    array->metadata_array[array->count].width = width;
    array->metadata_array[array->count].height = height;
    array->metadata_array[array->count].file_size = file_size;
    array->count++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void populate_image_metadata(DynamicImageArray *array, const char *directory_path, size_t max_memory) {
    DIR *dir;
    struct dirent *entry;
    dir = opendir(directory_path);
    if (dir == NULL) {
        fprintf(stderr, "Failed to open directory: %s\n", directory_path);
        return;
    }
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char full_path[512];
        snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);
        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            fprintf(stderr, "Failed to get file stats: %s\n", full_path);
            continue;
        }
        if (S_ISREG(file_stat.st_mode)) {
            ImageMetadata new_metadata;
            // Extract metadata for the image here
            // For example:
            new_metadata.width = ...; // Calculate width
            new_metadata.height = ...; // Calculate height
            new_metadata.file_size = file_stat.st_size;
            strncpy(new_metadata.filename, entry->d_name, sizeof(new_metadata.filename) - 1);
            if (add_metadata_to_array(array, full_path, new_metadata.width, new_metadata.height, new_metadata.file_size) != 0) {
                fprintf(stderr, "Failed to add metadata for: %s\n", full_path);
                break;
            }
        }
    }
    closedir(dir);
}
