#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_MEMORY 1024 * 1024 // Example limit

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields for CRC indication PDU
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketMetadata {
    // Define the structure fields for packet metadata
} PacketMetadata;

typedef enum IdentifierType { RX_UE_INFORMATION_TAG, RNTI } IdentifierType;

typedef struct Node {
    void* data;
    IdentifierType type;
    int identifier;
    struct Node* prev;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t total_size;
    pthread_rwlock_t rw_lock;
    size_t max_memory;
} DoublyLinkedList;

DoublyLinkedList* create_doubly_linked_list(size_t max_memory) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->total_size = 0;
    list->max_memory = max_memory;
    pthread_rwlock_init(&list->rw_lock, NULL);

    return list;
}

void free_node(Node* node) {
    if (node->data && node->type == RX_UE_INFORMATION_TAG || node->type == RNTI) {
        // Free the NFAPI_CRC_INDICATION_PDU_T or PacketMetadata data
        free(node->data);
    }
    pthread_mutex_destroy(&node->lock);
    free(node);
}

void delete_node(DoublyLinkedList* list, int identifier, IdentifierType type) {
    pthread_rwlock_wrlock(&list->rw_lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->identifier == identifier && current->type == type) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            size_t node_size = sizeof(Node) + ((current->type == RX_UE_INFORMATION_TAG || current->type == RNTI) ? sizeof(NFAPI_CRC_INDICATION_PDU_T) : sizeof(PacketMetadata));
            list->total_size -= node_size;

            free_node(current);
            break;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->rw_lock);
}

void process_identifiers(DoublyLinkedList* list, int* identifiers, IdentifierType type, size_t count) {
    pthread_rwlock_wrlock(&list->rw_lock);

    for (size_t i = 0; i < count; ++i) {
        delete_node(list, identifiers[i], type);
    }

    pthread_rwlock_unlock(&list->rw_lock);
}

void destroy_doubly_linked_list(DoublyLinkedList* list) {
    pthread_rwlock_wrlock(&list->rw_lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    pthread_rwlock_destroy(&list->rw_lock);
    free(list);
}

// Example usage:
int main() {
    DoublyLinkedList* list = create_doubly_linked_list(MAX_MEMORY);
    if (list == NULL) {
        printf("Failed to create doubly linked list\n");
        return 1;
    }

    // Add nodes and process identifiers as needed

    destroy_doubly_linked_list(list);
    return 0;
}
