typedef struct {
    uint32_t header;
    uint16_t payload_length;
    uint8_t* payload_data;
} Packet;

Packet* process_packets(uint8_t** packets, int packet_count, size_t max_payload_size, size_t* total_memory_used) {
    if (packet_count < 0 || max_payload_size == 0) {
        return NULL;
    }

    Packet* packet_array = (Packet*)malloc(packet_count * sizeof(Packet));
    if (!packet_array) {
        return NULL;
    }

    size_t current_total_memory_used = 0;
    for (int i = 0; i < packet_count; i++) {
        uint16_t payload_length = *(uint16_t*)(packets[i]);
        packets[i] += sizeof(uint16_t);

        if (payload_length > max_payload_size) {
            free(packet_array);
            return NULL;
        }

        size_t required_memory = current_total_memory_used + payload_length;
        if (required_memory < current_total_memory_used || required_memory > SIZE_MAX - sizeof(Packet)) {
            free(packet_array);
            return NULL;
        }

        packet_array[i].header = i; // Example header value
        packet_array[i].payload_length = payload_length;

        packet_array[i].payload_data = (uint8_t*)malloc(payload_length);
        if (!packet_array[i].payload_data) {
            for (int j = 0; j < i; j++) {
                free(packet_array[j].payload_data);
            }
            free(packet_array);
            return NULL;
        }

        memcpy(packet_array[i].payload_data, packets[i], payload_length);

        current_total_memory_used += sizeof(Packet) + payload_length;
    }

    *total_memory_used = current_total_memory_used;
    return packet_array;
}

void free_packets(Packet* packets, int packet_count) {
    for (int i = 0; i < packet_count; i++) {
        free(packets[i].payload_data);
    }
    free(packets);
}
