#define MAX_CONFIG_LINE_LENGTH 256

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

ListNode* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

int populateLinkedList(const char* configFilePath, int systemMemoryLimit, ListNode** head) {
    FILE* file = fopen(configFilePath, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        return -1;
    }

    ListNode* current = *head;
    int totalMemoryUsed = 0;

    while (fgets(buffer, MAX_CONFIG_LINE_LENGTH, file)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        if (sscanf(buffer, "%d %d %d", &pdu.RX_UE_INFORMATION_TAG, &pdu.RNTI, &pdu.CRC_INDICATION_REL8_TAG) != 3) {
            fprintf(stderr, "Invalid configuration format in file\n");
            continue;
        }

        pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        ListNode* newNode = createNode(pdu);
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed while creating new node\n");
            fclose(file);
            return -1;
        }

        totalMemoryUsed += sizeof(ListNode) + sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (totalMemoryUsed > systemMemoryLimit) {
            fprintf(stderr, "System memory limit exceeded\n");
            free(newNode); // Free the node as we couldn't add it to the list
            fclose(file);
            return -1;
        }

        if (*head == NULL) {
            *head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    fclose(file);
    return 0;
}

void freeLinkedList(ListNode** head) {
    ListNode* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
