NFAPI_CRC_LIST_T* create_napi_crc_list(size_t max_pdu_count) {
    if (max_pdu_count == 0 || max_pdu_count > 1000) {
        return NULL; // Invalid max_pdu_count
    }

    NFAPI_CRC_LIST_T *list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    list->pdu_list = calloc(max_pdu_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        free(list);
        return NULL; // Memory allocation failed
    }

    list->count = 0;
    list->max_count = max_pdu_count;
