        pthread_mutex_lock(&list->lock);
        free(list->pdu_list);
        list->pdu_list = NULL;
        list->count = 0;
        list->max_count = 0;
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_napi_crc_pdu(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t RNTI) {
    if (!list || list->count >= list->max_count) {
        return -1; // Invalid or full list
    }

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdu_list[list->count];
    new_pdu->ue_info_tag = ue_info_tag;
    new_pdu->RNTI = RNTI;
    new_pdu->crc_indication.CRCFLAG = (rand() % 2); // Random CRCFLAG
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}
