double calculate_current_load(double recent_memory_usage[]) {
    double total = 0;
    for (int i = 0; i < SLIDING_WINDOW_SIZE; i++) {
        total += recent_memory_usage[i];
    }
    return total / SLIDING_WINDOW_SIZE;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu(int N) {
    static double recent_memory_usage[SLIDING_WINDOW_SIZE];
    static int index = 0;

    // Get current system memory
    int system_memory = get_system_memory();

    // Calculate the maximum allowed memory usage based on sliding window
    double max_allowed_memory = MAX_MEMORY_USAGE * calculate_current_load(recent_memory_usage);

    // Calculate required memory for NFAPI CRC indications
    size_t required_memory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory > system_memory) {
        log_error("Insufficient system memory");
        return NULL;
    }

    // Check if the allocation would exceed the allowed memory usage
    if (system_memory - required_memory < max_allowed_memory) {
        log_error("Memory allocation would exceed allowed limit");
        return NULL;
    }

    // Allocate memory for NFAPI CRC indications
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_memory);
    if (!pdu_array) {
