        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        pdu_array[i].CRCFLAG = rand() % 2;
    }

    // Update sliding window with current memory usage
    recent_memory_usage[index] = required_memory / system_memory;
    index = (index + 1) % SLIDING_WINDOW_SIZE;

    return pdu_array;
}

int main() {
