#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define TOTAL_MEMORY_LIMIT 10 * 1024 * 1024 // 10MB

typedef struct {
    int size;
    unsigned char data[MAX_PACKET_SIZE];
} Packet;

Packet* packetArray = NULL;
size_t allocatedMemory = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int processPackets(int sockfd, struct sockaddr_in* addr) {
    pthread_mutex_lock(&mutex);

    while (1) {
        socklen_t addrlen = sizeof(*addr);
        char buffer[MAX_PACKET_SIZE];
        ssize_t bytesReceived = recvfrom(sockfd, buffer, MAX_PACKET_SIZE, 0, (struct sockaddr*)addr, &addrlen);

        if (bytesReceived < 0) {
            perror("recvfrom");
            break;
        } else if (bytesReceived == 0) {
            printf("Connection closed by peer\n");
            break;
        }

        int payloadSize = ntohl(*(int*)buffer); // Assuming the first 4 bytes are the packet size

        if (payloadSize <= 0 || payloadSize > MAX_PACKET_SIZE) {
            fprintf(stderr, "Invalid packet size: %d\n", payloadSize);
            continue;
        }

        if (allocatedMemory + payloadSize > TOTAL_MEMORY_LIMIT) {
            fprintf(stderr, "Memory limit exceeded\n");
            break;
        }

        Packet* newPacket = realloc(packetArray, allocatedMemory + sizeof(Packet));

        if (!newPacket) {
            perror("realloc");
            break;
        }

        packetArray = newPacket;
        memcpy(&packetArray[allocatedMemory / sizeof(Packet)], buffer, payloadSize);
        allocatedMemory += sizeof(Packet);
    }

    pthread_mutex_unlock(&mutex);
    free(packetArray);
    return 0;
}

int main() {
    int sockfd;
    struct sockaddr_in addr;

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        return 1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(8080);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sockfd);
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, processPackets, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return 1;
    }

    pthread_join(thread, NULL);
    close(sockfd);
    return 0;
}
