int allocate_NFAPI_CRC_INDICATIONs(int requested_num, uint32_t seed) {
    static NFAPI_CRC_INDICATION_PDU_T *cache[MAX_STRUCTS] = {0};
    static int cache_size = 0;

    if (requested_num <= 0 || requested_num > MAX_STRUCTS) {
        return -1;
    }

    // Check cache first
    for (int i = 0; i < cache_size; i++) {
        if (cache[i] != NULL && requested_num == 1) {
            return i + 1;
        }
    }

    // Calculate memory size
    uintptr_t total_size = (uintptr_t)(requested_num * STRUCT_SIZE);
    if (total_size > MEM_LIMIT || total_size / requested_num != STRUCT_SIZE) {
        printf("Error: Memory overflow or calculation error\n");
        return -1;
    }

    // Allocate memory
    NFAPI_CRC_INDICATION_PDU_T *ptr = malloc(total_size);
    if (ptr == NULL) {
        printf("Error: Failed to allocate memory\n");
        return -1;
    }

    // Populate structure fields
    srand(seed);
    for (int i = 0; i < requested_num; i++) {
        ptr[i].rx_info.RX_UE_INFORMATION_TAG = rand();
        ptr[i].rx_info.RNTI = rand() % 65536;
        ptr[i].crc_ind_rel8.CRCFLAG = rand() & 1;
    }

    // Cache the allocation
    if (cache_size < MAX_STRUCTS) {
        cache[cache_size++] = ptr;
    } else {
        free(ptr); // Cache is full, discard new allocation
    }

    return requested_num;
}
