int currentSize = 0;
int allocatedSize = 0;

void addCRCIndication(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    if (currentSize >= allocatedSize) {
        if ((allocatedSize == 0 && MAX_STRUCTURES > 1) || allocatedSize * 4 / 3 < MAX_STRUCTURES) {
            NFAPI_CRC_INDICATION_PDU_T** newDynamicList = realloc(dynamicList, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (allocatedSize + 1));
            if (newDynamicList == NULL) {
                printf("Memory reallocation failed.\n");
                return;
            }
            dynamicList = newDynamicList;
            allocatedSize++;
        } else {
            printf("Maximum number of structures reached.\n");
            return;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
