    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRCFLAG;

    dynamicList[currentSize++] = pdu;
}

void freeDynamicList() {
    for (int i = 0; i < currentSize; i++) {
        free(dynamicList[i]);
    }
    free(dynamicList);
    dynamicList = NULL;
    currentSize = allocatedSize = 0;
}

int main() {
