    *out_width = rand() % 1920 + 1;
    *out_height = rand() % 1080 + 1;
    unsigned char* data = (unsigned char*)malloc(*out_width * *out_height);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for image\n");
        return NULL;
    }
    // Simulate loading data
    memset(data, rand() % 256, *out_width * *out_height);
    IMAGE_PROCESSOR_T* img = (IMAGE_PROCESSOR_T*)malloc(sizeof(IMAGE_PROCESSOR_T));
    if (!img) {
        fprintf(stderr, "Failed to allocate memory for image struct\n");
        free(data);
        return NULL;
    }
    img->width = *out_width;
    img->height = *out_height;
    img->data = data;
    return img;
}

void unload_image(IMAGE_PROCESSOR_T* img) {
    if (img) {
        free(img->data);
        free(img);
    }
}

int process_images(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "No image files provided\n");
        return 1;
    }

    unsigned long total_memory = 0;
    for (int i = 1; i < argc; ++i) {
        int width, height;
        IMAGE_PROCESSOR_T* img = load_image(argv[i], &width, &height);
        if (!img) {
            fprintf(stderr, "Failed to load image %s\n", argv[i]);
            continue;
        }

        unsigned long required_memory = (unsigned long)width * height * sizeof(unsigned char);
        if (ULONG_MAX - total_memory < required_memory) {
            fprintf(stderr, "Memory overflow detected for image %s\n", argv[i]);
            unload_image(img);
            continue;
        }

        total_memory += required_memory;

        // Simulate processing
        printf("Processing image %s with resolution %dx%d\n", argv[i], width, height);

        // Unload the image after processing to simulate lazy loading
        unload_image(img);
    }

    return 0;
}
