#include <fcntl.h>
#include <time.h>

#define MAX_IMAGE_SIZE (1024 * 1024 * 10) // Example: 10 MB
#define MAX_CRC_INDICATIONS 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* process_images_and_crc(const char* directory_path, size_t seed) {
    DIR* dir = opendir(directory_path);
    if (!dir) return NULL;

    struct dirent* entry;
    size_t total_size = 0;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_CRC_INDICATIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        closedir(dir);
        return NULL;
    }

    time_t t = time(NULL);
    srand(seed);

    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);

        struct stat st;
        if (stat(path, &st) == -1) continue;

        if (S_ISLNK(st.st_mode)) {
            char target_path[256];
            ssize_t len = readlink(path, target_path, sizeof(target_path) - 1);
            if (len != -1) {
                target_path[len] = '\0';
                strncpy(path, target_path, sizeof(path));
            }
        }

        if (!S_ISREG(st.st_mode)) continue;

        FILE* file = fopen(path, "rb");
        if (!file) continue;

        fseek(file, 0, SEEK_END);
        size_t file_size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (total_size + file_size > MAX_IMAGE_SIZE) {
            fclose(file);
            free(crc_indications);
            closedir(dir);
            return NULL;
        }

        // Allocate memory for image data
        char* image_data = malloc(file_size);
        if (!image_data) {
            fclose(file);
            free(crc_indications);
            closedir(dir);
            return NULL;
        }

        fread(image_data, 1, file_size, file);
        fclose(file);

        // Process image and update CRC indication
        crc_indications[crc_indication_count].RX_UE_INFORMATION_TAG = rand_r(&seed) % 0xFFFFFFFF;
        crc_indications[crc_indication_count].RNTI = (uint16_t)(rand_r(&seed) % 0xFFFF);
        crc_indications[crc_indication_count].CRCFLAG = (uint8_t)(rand_r(&seed) % 2);

        total_size += file_size;
        free(image_data);
    }

    closedir(dir);
    return crc_indications;
}
