        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_init(&crc_indications[i].lock, NULL);
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
        crc_indications[i].RNTI = (unsigned short)(rand() % 65536); // Random value
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random value
    }

    return crc_indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int N) {
    for (int i = 0; i < N; ++i) {
        pthread_mutex_destroy(&crc_indications[i].lock);
    }
    free(crc_indications);
}
