### DNS Resolution with Rate Limiting

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DOMAIN_LENGTH 256
#define REQUEST_LIMIT 10
#define TIME_WINDOW 60 // in seconds

typedef struct {
    char domain[MAX_DOMAIN_LENGTH];
    time_t last_request_time;
    int request_count;
} DNS_REQUEST_STATE_T;

DNS_REQUEST_STATE_T dns_requests[REQUEST_LIMIT];

int is_domain_allowed(const char* domain) {
    for (int i = 0; i < REQUEST_LIMIT; ++i) {
        if (strcmp(dns_requests[i].domain, domain) == 0) {
            time_t current_time = time(NULL);
            if ((current_time - dns_requests[i].last_request_time) > TIME_WINDOW) {
                dns_requests[i].request_count = 1;
                dns_requests[i].last_request_time = current_time;
                return 1;
            } else if (dns_requests[i].request_count < REQUEST_LIMIT) {
                ++dns_requests[i].request_count;
                return 1;
            }
            break;
        }
    }

    return 0;
}

void record_dns_request(const char* domain) {
    for (int i = 0; i < REQUEST_LIMIT; ++i) {
        if (strcmp(dns_requests[i].domain, "") == 0) {
            strcpy(dns_requests[i].domain, domain);
            dns_requests[i].last_request_time = time(NULL);
            dns_requests[i].request_count = 1;
            break;
        }
    }
}
```

