    if (image_frames == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for image frames.\n");
        return -2;
    }

    // Simulate processing each file and frame
    for (int i = 0; i < num_files; ++i) {
        int frames_in_file = rand() % (avg_frames_per_file + 5) + 1; // Varying number of frames per file

        for (int j = 0; j < frames_in_file; ++j) {
            image_frames[i * avg_frames_per_file + j].width = rand() % 1024 + 1;
            image_frames[i * avg_frames_per_file + j].height = rand() % 768 + 1;

            // Allocate memory for frame data
            size_t frame_size = image_frames[i * avg_frames_per_file + j].width * 
                               image_frames[i * avg_frames_per_file + j].height;
            image_frames[i * avg_frames_per_file + j].data = malloc(frame_size);

            if (image_frames[i * avg_frames_per_file + j].data == NULL) {
                fprintf(stderr, "Error: Failed to allocate memory for frame data.\n");

                // Free previously allocated memory
                for (int k = 0; k < i * avg_frames_per_file + j; ++k) {
                    free(image_frames[k].data);
                }
                free(image_frames);

                return -3;
            }
        }
    }

    // Simulate processing the frames...

    // Free allocated memory
