#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define ImageMetaData structure
typedef struct {
    char filename[256];
    int width;
    int height;
    char format[10];
} ImageMetaData;

// Memory pool for ImageMetaData structures
#define POOL_SIZE 1000
ImageMetaData image_pool[POOL_SIZE];
int pool_index = 0;

// Mutex for thread-safe access to memory pool
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to safely allocate from the memory pool
ImageMetaData* safe_malloc() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;  // Pool full, cannot allocate more
    }
    ImageMetaData* meta = &image_pool[pool_index++];
    pthread_mutex_unlock(&pool_mutex);
    return meta;
}

// Function to process image files
int process_images(char** filenames, int num_files) {
    if (num_files <= 0 || !filenames) {
        return -1;  // Invalid input
    }

    ImageMetaData* metadata[num_files];
    for (int i = 0; i < num_files; ++i) {
        metadata[i] = safe_malloc();
        if (!metadata[i]) {
            printf("Memory allocation failed\n");
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                pthread_mutex_lock(&pool_mutex);
                pool_index--;
                pthread_mutex_unlock(&pool_mutex);
            }
            return -1;
        }

        // Simulate image metadata processing
        strcpy(metadata[i]->filename, filenames[i]);
        metadata[i]->width = rand() % 2048;  // Random width between 0 and 2047
        metadata[i]->height = rand() % 2048;  // Random height between 0 and 2047
        strcpy(metadata[i]->format, "JPEG");  // Example format

        if (metadata[i]->width > MAX_WIDTH || metadata[i]->height > MAX_HEIGHT) {
            printf("Image dimensions out of bounds\n");
            pthread_mutex_lock(&pool_mutex);
            pool_index--;
            pthread_mutex_unlock(&pool_mutex);
            return -1;
        }
    }

    // Simulate writing to a file
    FILE* output_file = fopen("image_metadata.txt", "w");
    if (!output_file) {
        printf("Failed to open output file\n");
        for (int i = 0; i < num_files; ++i) {
            pthread_mutex_lock(&pool_mutex);
            pool_index--;
            pthread_mutex_unlock(&pool_mutex);
        }
        return -1;
    }

    for (int i = 0; i < num_files; ++i) {
        fprintf(output_file, "Filename: %s, Width: %d, Height: %d, Format: %s\n",
                metadata[i]->filename, metadata[i]->width, metadata[i]->height, metadata[i]->format);
    }

    fclose(output_file);

    return 0;
}

// Example usage
int main() {
    char* filenames[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);

    if (process_images(filenames, num_files) == 0) {
        printf("Image metadata processed successfully\n");
    } else {
        printf("Error processing image metadata\n");
    }

    return 0;
}
```

This code snippet provides a basic implementation of the specified task, focusing on memory management, error handling, and thread safety. It uses a simple memory pool to manage `ImageMetaData` structures, ensuring efficient allocation and deallocation. The `process_images` function demonstrates how to process image files, validate dimensions, and write metadata to a file. The example usage in the `main` function shows how to call the `process_images` function with an array of filenames.']

