typedef struct {
    int width;
    int height;
    char *file_path;
} image_data_t;

int process_images(const char *directory, image_data_t **image_array) {
    DIR *dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        return -1; // Error code for directory not found
    }

    struct dirent *entry;
    int count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".jpg") != NULL) {
            count++;
        }
    }

    closedir(dir);

    if (count == 0) {
        fprintf(stderr, "No image files found in the directory.\n");
        return -2; // Error code for no image files
    }

    *image_array = malloc(count * sizeof(image_data_t));
    if (!*image_array) {
        perror("Failed to allocate memory");
        return -3; // Error code for memory allocation failure
    }

    dir = opendir(directory);
    int index = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".jpg") != NULL) {
            (*image_array)[index].width = 800; // Example width
            (*image_array)[index].height = 600; // Example height
            (*image_array)[index].file_path = strdup(entry->d_name);
            if (!(*image_array)[index].file_path) {
                perror("Failed to allocate memory for file path");
                // Free previously allocated memory before returning error
                while (index > 0) {
                    free((*image_array)[--index].file_path);
                }
                free(*image_array);
                return -3; // Error code for memory allocation failure
            }
            index++;
        }
    }

    closedir(dir);

    printf("Successfully loaded %d images.\n", count);
    return count;
}
