// Function to safely allocate memory for an array of ImageMetaData structures
ImageMetaData* allocate_image_metadata(int rows, int cols) {
    if (rows <= 0 || cols <= 0) {
        return NULL; // Handle edge cases for zero-sized images
    }

    // Check for integer overflow before allocation
    size_t total_size = (size_t)rows * (size_t)cols * sizeof(ImageMetaData);
    if ((total_size / rows != (size_t)cols) || (total_size / cols != sizeof(ImageMetaData))) {
        return NULL; // Handle integer overflow vulnerability
    }

