#include <stdio.h>
#include <stdlib.h>

#define MAX_LAYERS 1024

typedef struct ImageLayer {
    int width;
    int height;
    size_t pixel_data_size;
    char* pixel_data;
} ImageLayer;

typedef struct LayerNode {
    ImageLayer layer;
    struct LayerNode* next;
} LayerNode;

typedef struct LayerManager {
    LayerNode* head;
    LayerNode* tail;
    size_t current_layers;
} LayerManager;

LayerManager* create_layer_manager() {
    LayerManager* manager = (LayerManager*)malloc(sizeof(LayerManager));
    if (!manager) {
        fprintf(stderr, "Memory allocation failed for LayerManager\n");
        return NULL;
    }
    manager->head = NULL;
    manager->tail = NULL;
    manager->current_layers = 0;
    return manager;
}

void add_layer(LayerManager* manager, ImageLayer layer) {
    if (manager->current_layers >= MAX_LAYERS) {
        fprintf(stderr, "Maximum number of layers reached\n");
        return;
    }
    LayerNode* new_node = (LayerNode*)malloc(sizeof(LayerNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new layer node\n");
        return;
    }
    new_node->layer = layer;
    new_node->next = NULL;

    if (manager->head == NULL) {
        manager->head = new_node;
        manager->tail = new_node;
    } else {
        manager->tail->next = new_node;
        manager->tail = new_node;
    }
    manager->current_layers++;
}

void free_layer_manager(LayerManager* manager) {
    LayerNode* current = manager->head;
    while (current != NULL) {
        LayerNode* next = current->next;
        free(current->layer.pixel_data);
        free(current);
        current = next;
    }
    free(manager);
}

int main() {
    LayerManager* manager = create_layer_manager();
    if (!manager) {
        return 1;
    }

    ImageLayer layer1 = {640, 480, 640 * 480 * sizeof(char), malloc(640 * 480 * sizeof(char))};
    ImageLayer layer2 = {320, 240, 320 * 240 * sizeof(char), malloc(320 * 240 * sizeof(char))};

    add_layer(manager, layer1);
    add_layer(manager, layer2);

    free_layer_manager(manager);

    return 0;
}
