int validate_input(int N, size_t max_memory) {
    // Check for integer overflow
    if (N <= 0 || (size_t)N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_memory) {
        return -1;
    }
    return 0;
}

int generate_unique_rnti(int count, unsigned short* rntis) {
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        do {
            rntis[i] = rand() % 65536; // Assuming RNTI is a 16-bit unsigned integer
        } while (i > 0 && rntis[i - 1] == rntis[i]);
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N, size_t max_memory) {
    if (validate_input(N, max_memory) != 0) {
        printf("Invalid input or memory constraints exceeded.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node == NULL) {
            printf("Memory allocation failed.\n");
            // Clean up previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        new_node->RX_UE_INFORMATION_TAG = i + 1; // Example initialization
        unsigned short rntis[N];
        generate_unique_rnti(N, rntis);
        new_node->RNTI = rntis[i];
        new_node->CRC_INDICATION_REL8_TAG = i + 2; // Example initialization
        new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (head == NULL) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    while (head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int N;
    size_t max_memory;

    printf("Enter the number of structures to create: ");
    scanf("%d", &N);

    printf("Enter the maximum memory limit (in bytes): ");
    scanf("%zu", &max_memory);

    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(N, max_memory);
    if (list != NULL) {
        printf("Linked list created successfully.\n");
        free_linked_list(list);
    }

    return 0;
}
