#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 // Initial max memory in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG;
    unsigned long CRCFLAG;
    time_t timestamp;
    int unique_id;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T** allocate_NFAPdu(int N) {
    pthread_mutex_lock(&allocation_mutex);

    if (N > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pthread_mutex_unlock(&allocation_mutex);
        return NULL; // Under-allocation error
    }

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) {
        pthread_mutex_unlock(&allocation_mutex);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            pthread_mutex_unlock(&allocation_mutex);
            return NULL; // Memory allocation failed
        }

        array[i]->RX_UE_INFORMATION_TAG = rand();
        array[i]->RNTI = rand() % 65536;
        array[i]->CRC_INDICATION_REL8_TAG = (char)(rand() % 256);
        array[i]->CRCFLAG = rand();
        array[i]->timestamp = time(NULL);
        array[i]->unique_id = i;
    }

    pthread_mutex_unlock(&allocation_mutex);
    return array;
}

void free_NFAPdu(NFAPI_CRC_INDICATION_PDU_T** array, int N) {
    pthread_mutex_lock(&allocation_mutex);

    for (int i = 0; i < N; i++) {
        if (array[i]) {
            free(array[i]);
        }
    }

    free(array);
    pthread_mutex_unlock(&allocation_mutex);
}
