typedef struct AudioMetadata {
    char filename[256];
    uint32_t sample_rate;
    uint16_t channels;
    uint32_t duration_seconds;
} AudioMetadata;

AudioMetadata** allocate_audio_metadata_array(size_t rows, size_t cols) {
    if (rows == 0 || cols == 0) {
        errno = EINVAL;
        return NULL;
    }

    // Check for potential integer overflow
    size_t total_elements = rows * cols;
    if ((total_elements / rows) != cols) {
        errno = EOVERFLOW;
        return NULL;
    }

    AudioMetadata** metadata_array = (AudioMetadata**)malloc(rows * sizeof(AudioMetadata*));
    if (!metadata_array) {
        perror("Failed to allocate memory for metadata array");
        return NULL;
    }

    for (size_t i = 0; i < rows; ++i) {
