#include <stdint.h>

typedef struct {
    uint16_t length;
    char payload[256]; // Assuming maximum payload size of 256 bytes
} PacketHeaderInfo;

void processNetworkPackets(uint32_t numInterfaces, uint16_t *maxPacketSizes, char **packetData, uint32_t *numPacketsReceived) {
    uint32_t totalNumPackets = 0;
    for (uint32_t i = 0; i < numInterfaces; ++i) {
        totalNumPackets += numPacketsReceived[i];
    }

    // Calculate total memory required
    size_t totalMemoryRequired = sizeof(PacketHeaderInfo) * totalNumPackets;
    if (totalMemoryRequired > UINT32_MAX - sizeof(uint32_t)) { // Check for potential overflow
        printf("Error: Memory allocation would exceed system limits.\n");
        return;
    }

    PacketHeaderInfo *packetHeaders = (PacketHeaderInfo *)malloc(totalMemoryRequired + sizeof(uint32_t));
    if (!packetHeaders) {
        printf("Error: Failed to allocate memory for packet headers.\n");
        return;
    }

    // Populate packet header array
    uint32_t offset = 0;
    for (uint32_t i = 0; i < numInterfaces; ++i) {
        for (uint32_t j = 0; j < numPacketsReceived[i]; ++j) {
            if (maxPacketSizes[i] > sizeof(PacketHeaderInfo) - offsetof(PacketHeaderInfo, payload)) {
                printf("Error: Packet size exceeds maximum allowed.\n");
                free(packetHeaders);
                return;
            }
            packetHeaders[offset].length = maxPacketSizes[i];
            memcpy(packetHeaders[offset].payload, packetData[i], maxPacketSizes[i]);
            ++offset;
        }
    }

    // Store total number of packets
    ((uint32_t *)packetHeaders)[-1] = totalNumPackets;

    // Process the packet headers as needed
    printf("Processed %u packets across %u interfaces.\n", totalNumPackets, numInterfaces);

    // Free allocated memory when done
    free(packetHeaders);
}
