#include <stdlib.h>
#include <pthread.h>

#define MAX_N 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool pool;

void init_pool(size_t initial_size) {
    if (initial_size > MAX_N) {
        fprintf(stderr, "Initial size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    pool.pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool.pool) {
        perror("Failed to allocate memory for pool.");
        exit(EXIT_FAILURE);
    }
    pool.size = initial_size;
    pool.used = 0;
    pthread_mutex_init(&pool.mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu() {
    pthread_mutex_lock(&pool.mutex);
    if (pool.used == pool.size) {
        size_t new_size = pool.size * 2;
        if (new_size > MAX_N) {
            fprintf(stderr, "Memory pool exhausted.\n");
            pthread_mutex_unlock(&pool.mutex);
            return NULL;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool.pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            perror("Failed to reallocate memory for pool.");
            pthread_mutex_unlock(&pool.mutex);
            return NULL;
        }
        pool.pool = new_pool;
        pool.size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool.pool[pool.used++];
    pthread_mutex_unlock(&pool.mutex);
    return pdu;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // In a real-world scenario, you might want to mark the memory as reusable
    // instead of actually freeing it. For simplicity, we'll just decrement the used count.
    pthread_mutex_lock(&pool.mutex);
    if (pdu < pool.pool || pdu >= &pool.pool[pool.size]) {
        fprintf(stderr, "Invalid PDU pointer.\n");
        pthread_mutex_unlock(&pool.mutex);
        return;
    }
    --pool.used;
    pthread_mutex_unlock(&pool.mutex);
}

void destroy_pool() {
    free(pool.pool);
    pthread_mutex_destroy(&pool.mutex);
}
```

This code provides a basic implementation of a memory pool for NFAPI_CRC_INDICATION_PDU_T structures, including initialization, allocation, and deallocation. It ensures thread safety using mutexes and includes input validation to prevent out-of-range values for the size parameter.']

