typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_structures(int *numStructs, int memoryBudgetKB) {
    if (memoryBudgetKB <= 0) {
        printf("Invalid memory budget. Must be greater than zero.\n");
        return NULL;
    }

    size_t structSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if ((structSize * MAX_STRUCTS) > (size_t)(memoryBudgetKB * 1024)) {
        printf("Memory budget is insufficient for the maximum number of structures.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = malloc(structSize * MAX_STRUCTS);
    if (!structs) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    int totalSizeKB = 0;

    for (*numStructs = 0; *numStructs < MAX_STRUCTS; (*numStructs)++) {
        structs[*numStructs].RX_UE_INFORMATION_TAG = rand() % 1000;
        structs[*numStructs].RNTI = rand() % 256;
        structs[*numStructs].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;

        size_t newSizeKB = totalSizeKB + structSize / 1024;
        if ((newSizeKB * 1024) > memoryBudgetKB) {
            (*numStructs)--;
            break;
        }

        totalSizeKB = newSizeKB;
    }

    printf("Allocated %d structures within budget of %d KB.\n", *numStructs, memoryBudgetKB);
    return structs;
}

int main() {
    int numStructs;
    NFAPI_CRC_INDICATION_PDU_T* structs = allocate_and_populate_structures(&numStructs, MEMORY_BUDGET);

    if (structs) {
        // Use the allocated structures
        free(structs);
    }

    return 0;
}
