NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(int max_pdu_count, int ue_count, int rnti_count) {
    static NFAPI_CRC_INDICATION_PDU_T** pdu_chunks = NULL;
    static int current_chunk_size = MIN_CHUNK_SIZE;
    static int total_pdus_allocated = 0;

    if (total_pdus_allocated + ue_count * rnti_count > max_pdu_count) {
        log_message(LOG_ERROR, "Attempt to allocate more PDUs than allowed.");
        return NULL;
    }

    while (current_chunk_size < ue_count * rnti_count) {
        current_chunk_size *= 2;
        if (current_chunk_size > MAX_CHUNK_SIZE) {
            current_chunk_size = MAX_CHUNK_SIZE;
        }
    }

    int chunks_needed = (ue_count * rnti_count + current_chunk_size - 1) / current_chunk_size;

    pdu_chunks = realloc(pdu_chunks, chunks_needed * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_chunks) {
        log_message(LOG_ERROR, "Memory allocation failed.");
        return NULL;
    }

    for (int i = 0; i < chunks_needed; ++i) {
        pdu_chunks[i] = malloc(current_chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_chunks[i]) {
            log_message(LOG_ERROR, "Failed to allocate memory for PDU chunk.");
            return NULL;
        }
    }

    for (int i = 0; i < ue_count; ++i) {
        for (int j = 0; j < rnti_count; ++j) {
            int index = total_pdus_allocated + i * rnti_count + j;
            pdu_chunks[index / current_chunk_size][index % current_chunk_size].rx_ue_information_tag = i;
            pdu_chunks[index / current_chunk_size][index % current_chunk_size].rnti = j;
            pdu_chunks[index / current_chunk_size][index % current_chunk_size].crc_indication_rel8_tag = 0; // Placeholder
            pdu_chunks[index / current_chunk_size][index % current_chunk_size].crcflag = rand() % 2; // Random CRCFLAG
        }
    }

    total_pdus_allocated += ue_count * rnti_count;
    log_message(LOG_INFO, "Successfully allocated and populated PDUs.");
    return (NFAPI_CRC_INDICATION_PDU_T*)pdu_chunks[0];
}

void cleanup_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (!pdus) return;

    for (int i = 0; i < MAX_PDU_COUNT / MIN_CHUNK_SIZE; ++i) {
        free(pdus + i * MIN_CHUNK_SIZE);
    }

    free(pdus);
    log_message(LOG_INFO, "All PDUs and associated resources have been freed.");
}

// Example usage
int main() {
    srand(time(NULL));
    int max_pdu_count = 500;
    int ue_count = 10;
    int rnti_count = 10;

    NFAPI_CRC_INDICATION_PDU_T* pdus = create_and_populate_pdus(max_pdu_count, ue_count, rnti_count);
    if (pdus) {
        // Process PDUs
        cleanup_pdus(pdus);
    }

    return 0;
}
