#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t sequence_number;
    uint16_t payload_length;
    char* payload_data;
} NetworkPacket;

NetworkPacket* read_network_packets(const char* filename, size_t* packet_count) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    NetworkPacket* packets = (NetworkPacket*)malloc(file_size * sizeof(NetworkPacket));
    if (!packets) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t packet_index = 0;
    while (fread(&packets[packet_index].sequence_number, sizeof(uint32_t), 1, file) == 1 &&
           fread(&packets[packet_index].payload_length, sizeof(uint16_t), 1, file) == 1) {
        if (packets[packet_index].payload_length > 0) {
            packets[packet_index].payload_data = (char*)malloc(packets[packet_index].payload_length);
            if (!packets[packet_index].payload_data) {
                perror("Failed to allocate memory for payload");
                fclose(file);
                return NULL;
            }
            fread(packets[packet_index].payload_data, 1, packets[packet_index].payload_length, file);
        } else {
            packets[packet_index].payload_data = NULL;
        }

        packet_count[0]++;
    }

    fclose(file);
    return packets;
}

void free_network_packets(NetworkPacket* packets, size_t packet_count) {
    for (size_t i = 0; i < packet_count; i++) {
        if (packets[i].payload_data) {
            free(packets[i].payload_data);
        }
    }
    free(packets);
}
