#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_PACKETS 10000
#define MAX_MEMORY_LIMIT (1024 * 1024 * 1024) // 1GB

typedef struct {
    int metadata;
    char payload[256];
} Packet;

Packet* packetPool[MAX_PACKETS];
int poolIndex = 0;

sem_t memorySemaphore;
pthread_mutex_t mutex;

void initPacketProcessing() {
    sem_init(&memorySemaphore, 0, MAX_MEMORY_LIMIT);
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < MAX_PACKETS; i++) {
        packetPool[i] = (Packet*)malloc(sizeof(Packet));
        if (!packetPool[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

void* processPacket(void* arg) {
    int* packetSize = (int*)arg;
    Packet* packet;

    sem_wait(&memorySemaphore);

    pthread_mutex_lock(&mutex);
    if (poolIndex >= MAX_PACKETS) {
        pthread_mutex_unlock(&mutex);
        sem_post(&memorySemaphore);
        return NULL;
    }
    packet = packetPool[poolIndex++];
    pthread_mutex_unlock(&mutex);

    // Simulate metadata retrieval and payload processing
    packet->metadata = *packetSize;
    snprintf(packet->payload, sizeof(packet->payload), "Payload of size %d", *packetSize);

    sem_post(&memorySemaphore);
    return NULL;
}

int main() {
    initPacketProcessing();

    int packetSizes[] = {1024, 2048, 4096, 8192};
    pthread_t threads[4];

    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, processPacket, &packetSizes[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < MAX_PACKETS; i++) {
        free(packetPool[i]);
    }

    sem_destroy(&memorySemaphore);
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

This code snippet provides a basic structure for processing network packets with dynamic memory allocation and thread safety. It includes a semaphore to manage memory usage, a mutex for protecting shared resources, and simulates packet metadata retrieval and payload processing. The main function demonstrates creating threads to process packets concurrently. Additional features like logging, monitoring resource usage, and error handling are left as exercises for the developer to implement based on specific requirements.']

