typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** createPduArray(int count, size_t* totalSize) {
    if (count > MAX_PDU_COUNT) {
        fprintf(stderr, "Error: Exceeded maximum PDU count.\n");
        return NULL;
    }

    size_t requiredMemory = count * sizeof(NFAPI_CRC_INDICATION_PDU_T*);
    if (requiredMemory + *totalSize > MAX_MEM_SIZE) {
        fprintf(stderr, "Error: Insufficient memory available.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** pduArray = (NFAPI_CRC_INDICATION_PDU_T**)malloc(requiredMemory);
    if (!pduArray) {
        fprintf(stderr, "Error: Failed to allocate memory for PDU array.\n");
        return NULL;
    }

    *totalSize += requiredMemory;

    for (int i = 0; i < count; i++) {
        pduArray[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pduArray[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for PDU structure.\n");
            for (int j = 0; j < i; j++) {
                free(pduArray[j]);
            }
            free(pduArray);
            return NULL;
        }

        pduArray[i]->RX_UE_INFORMATION_TAG = rand();
        pduArray[i]->RNTI = rand() % 65536; // Random RNTI value
        pduArray[i]->CRC_INDICATION_REL8_TAG = (rand() & 0x01) ? 0x01 : 0x02; // Random CRCFLAG value
    }

    return pduArray;
}

void freePduArray(NFAPI_CRC_INDICATION_PDU_T** pduArray, int count, size_t* totalSize) {
    for (int i = 0; i < count; i++) {
        if (pduArray[i]) {
            free(pduArray[i]);
        }
    }

    if (pduArray) {
        free(pduArray);
    }

    *totalSize -= count * sizeof(NFAPI_CRC_INDICATION_PDU_T*);
}
