    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int populate_nfaapi_crc_indications(int num_elements, char* log_file) {
    if (num_elements <= 0) {
        return -1; // Invalid input
    }

    size_t total_size = num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size / num_elements != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -2; // Integer overflow detected
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (!pdus) {
        return -3; // Memory allocation failed
    }

    for (int i = 0; i < num_elements; i++) {
        pdus[i].ue_info_tag.tag = i + 1;
        pdus[i].rnti.rnti = (uint16_t)(rand() % UINT16_MAX);
        pdus[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG
    }

    // Log allocation event asynchronously
    FILE* logfp = fopen(log_file, "a");
    if (logfp) {
        fprintf(logfp, "Allocated memory for %d NFAPI CRC indications\n", num_elements);
        fclose(logfp);
    }

    return 0; // Success
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        printf("Usage: %s <num_elements> <log_file>\n", argv[0]);
        return 1;
    }

    int num_elements = atoi(argv[1]);
    char* log_file = argv[2];

    return populate_nfaapi_crc_indications(num_elements, log_file);
}
