#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <string.h>

typedef struct {
    char *filename;
    int width;
    int height;
} ImageMetaData;

ImageMetaData* process_directory(const char *directory_path, size_t *metadata_count) {
    DIR *dir;
    struct dirent *entry;
    ImageMetaData *meta_data = NULL;
    size_t count = 0;
    size_t capacity = 10; // Initial capacity

    dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return NULL;
    }

    while ((entry = readdir(dir)) != NULL) {
        char path[256];
        snprintf(path, sizeof(path), "%s/%s", directory_path, entry->d_name);

        // Check if it's a file and not a directory
        if (entry->d_type == DT_REG) {
            FILE *file = fopen(path, "rb");
            if (file != NULL) {
                // Assume the metadata is at the beginning of the file
                int width, height;
                size_t bytes_read = fread(&width, sizeof(int), 1, file);
                bytes_read += fread(&height, sizeof(int), 1, file);

                if (bytes_read == 2) {
                    if (count >= capacity) {
                        capacity *= 1.15; // Increase capacity by 15%
                        meta_data = realloc(meta_data, capacity * sizeof(ImageMetaData));
                        if (meta_data == NULL) {
                            perror("Failed to reallocate memory");
                            fclose(file);
                            closedir(dir);
                            return NULL;
                        }
                    }

                    ImageMetaData new_meta = {strdup(entry->d_name), width, height};
                    meta_data[count++] = new_meta;
                } else {
                    printf("Invalid metadata in file: %s\n", path);
                }

                fclose(file);
            }
        }
    }

    closedir(dir);

    *metadata_count = count;
    return realloc(meta_data, count * sizeof(ImageMetaData));
}

int main() {
    size_t metadata_count;
    ImageMetaData *meta_data = process_directory(".", &metadata_count);

    if (meta_data != NULL) {
        printf("Processed %zu image files.\n", metadata_count);
        for (size_t i = 0; i < metadata_count; ++i) {
            printf("File: %s, Width: %d, Height: %d\n", meta_data[i].filename, meta_data[i].width, meta_data[i].height);
            free(meta_data[i].filename); // Free dynamically allocated strings
        }
        free(meta_data); // Free the array of ImageMetaData structures
    }

    return 0;
}
```

This code provides a basic implementation for processing an image directory and reading metadata from each file. It uses dynamic memory allocation to handle a potentially large number of files, includes error handling for directory opening, file operations, and memory reallocation, and manages memory for dynamically allocated strings in the `ImageMetaData` structures.']

