void populateNfadumpPduList(int num_elements) {
    if (num_elements <= 0 || num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid number of elements\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory for PDU list");
        return;
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    rusage start_rusage, end_rusage;
    getrusage(RUSAGE_SELF, &start_rusage);

    // Populate the list with valid data
