        pdu_list[i].ue_tag = generate_valid_rx_ue_information_tag();
        pdu_list[i].rnti = generate_random_rnti();
        pdu_list[i].crc_indication.crcflag = generate_random_crcflag();
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    getrusage(RUSAGE_SELF, &end_rusage);

    free(pdu_list);

    printf("Time taken: %ld.%09ld seconds\n", end_time.tv_sec - start_time.tv_sec, end_time.tv_nsec - start_time.tv_nsec);
    printf("Memory usage: %ld bytes\n", end_rusage.ru_maxrss - start_rusage.ru_maxrss);

    // Dynamically load shared library
    void *handle = dlopen("libexample.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        return;
    }

    // Install ice hook using SyncLazy module
    int (*install_ice_hook)(void) = (int (*)(void))dlsym(handle, "SyncLazyInstallIceHook");
    if (!install_ice_hook || install_ice_hook() != 0) {
        fprintf(stderr, "Failed to install ice hook\n");
        dlclose(handle);
        return;
    }

    // Catch errors using robust error handling techniques
    int (*catch_errors)(void) = (int (*)(void))dlsym(handle, "CatchErrors");
    if (!catch_errors || catch_errors() != 0) {
        fprintf(stderr, "Failed to catch errors\n");
        dlclose(handle);
        return;
    }

    dlclose(handle);
}

int main(int argc, char *argv[]) {
    int num_elements = atoi(argv[1]);
    populateNfadumpPduList(num_elements);
    return 0;
}
