    if (nfapi_crc_indication_pdu_count < MAX_NF_API_ENTRIES) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_entry != NULL) {
            nfapi_crc_indication_pdu_list[nfapi_crc_indication_pdu_count++] = new_entry;
            pthread_mutex_unlock(&nfapi_mutex);
            return new_entry;
        }
    }
    pthread_mutex_unlock(&nfapi_mutex);
    printf("Error: Memory allocation failed or maximum entries reached.\n");
    return NULL;
}

void free_all_entries(void) {
