DynamicArray *create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->data);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    if (new_capacity > array->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data) {
            array->data = new_data;
            array->capacity = new_capacity;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

