#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024
#define MIN_PAYLOAD_SIZE 64

typedef struct Packet {
    int id;
    time_t timestamp;
    char payload[MAX_PAYLOAD_SIZE];
} Packet;

Packet* packet_cache[1024];
int cache_size = 0;

Packet* allocate_packet(int size) {
    if (size < MIN_PAYLOAD_SIZE || size > MAX_PAYLOAD_SIZE) {
        return NULL; // Invalid size
    }

    if (cache_size > 0) {
        // Reuse from cache
        Packet* packet = packet_cache[--cache_size];
        packet->id = rand();
        packet->timestamp = time(NULL);
        return packet;
    } else {
        // Allocate new memory
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        if (packet == NULL) {
            return NULL; // Memory allocation failed
        }
        packet->id = rand();
        packet->timestamp = time(NULL);
        return packet;
    }
}

void free_packet(Packet* packet) {
    if (cache_size < 1024) {
        packet_cache[cache_size++] = packet;
    } else {
        // Handle cache overflow, e.g., by freeing the memory
        free(packet);
    }
}

int process_packets(int num_packets) {
    for (int i = 0; i < num_packets; i++) {
        int payload_size = rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE + 1) + MIN_PAYLOAD_SIZE;
        Packet* packet = allocate_packet(payload_size);
        if (packet != NULL) {
            // Process the packet
            free_packet(packet);
        } else {
            // Handle allocation failure
            fprintf(stderr, "Failed to allocate packet of size %d\n", payload_size);
        }
    }
    return 0;
}

int main() {
    srand(time(NULL));
    process_packets(100); // Simulate processing 100 packets
    return 0;
}
```

