#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PACKET_SIZE 4096
#define MIN_PACKET_SIZE 128
#define CACHE_SIZE 512

typedef struct {
    int id;
    time_t timestamp;
    unsigned char payload[MAX_PACKET_SIZE];
} Packet;

Packet cache[CACHE_SIZE];
int cacheIndex = 0;
size_t totalMemoryUsage = 0;
size_t maxMemoryLimit = 1048576; // 1MB

Packet* allocate_packet(int id, size_t payload_size) {
    if (totalMemoryUsage + payload_size > maxMemoryLimit) {
        printf("Resource exhaustion: Memory limit reached\n");
        return NULL;
    }

    Packet* packet;
    if (cacheIndex < CACHE_SIZE && cache[cacheIndex].id == 0) {
        packet = &cache[cacheIndex++];
    } else {
        for (int i = 0; i < CACHE_SIZE; ++i) {
            if (cache[i].id == 0) {
                packet = &cache[i];
                break;
            }
        }
        if (packet == NULL) {
            printf("Resource exhaustion: Cache overflow\n");
            return NULL;
        }
    }

    packet->id = id;
    packet->timestamp = time(NULL);
    totalMemoryUsage += payload_size;

    // Simulate payload allocation
    for (size_t i = 0; i < payload_size; ++i) {
        packet->payload[i] = i % 256;
    }

    return packet;
}

void free_packet(Packet* packet) {
    if (packet == NULL || packet->id == 0) {
        printf("Error: Attempting to free an invalid or already freed packet\n");
        return;
    }

    // Simulate payload deallocation
    for (size_t i = 0; i < sizeof(packet->payload); ++i) {
        packet->payload[i] = 0;
    }

    packet->id = 0;
    totalMemoryUsage -= sizeof(packet->payload);
}

int main() {
    srand(time(NULL));

    // Simulate network packets
    for (int i = 0; i < 1000; ++i) {
        size_t payload_size = MIN_PACKET_SIZE + rand() % (MAX_PACKET_SIZE - MIN_PACKET_SIZE);
        Packet* packet = allocate_packet(i, payload_size);

        if (packet != NULL) {
            printf("Allocated packet with ID: %d and payload size: %zu\n", packet->id, payload_size);
        }

        // Simulate packet processing
        // ...

        free_packet(packet);
    }

    return 0;
}
