    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    char source_ip[INET_ADDRSTRLEN];
    pthread_mutex_t mutex;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex;

void insert_node(const NFAPI_CRC_INDICATION_PDU_T* pdu, const char* source_ip) {
    pthread_mutex_lock(&list_mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    strcpy(new_node->source_ip, source_ip);
    new_node->next = head;
    new_node->prev = NULL;
    if (head != NULL) {
        head->prev = new_node;
    }
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

Node* retrieve_node(const char* source_ip) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->source_ip, source_ip) == 0) {
            pthread_mutex_unlock(&list_mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

