#include <stdlib.h>
#include <stdint.h>

typedef struct PacketInfo {
    size_t payload_length;
    uint8_t* payload_data;
    uint32_t checksum;
    struct PacketInfo* next;
} PacketInfo;

uint32_t calculate_checksum(uint8_t* data, size_t length) {
    // Simplified checksum calculation
    uint32_t sum = 0;
    for (size_t i = 0; i < length; i++) {
        sum += data[i];
    }
    return sum;
}

PacketInfo* process_packets(const uint8_t** payloads, size_t* payload_lengths, size_t packet_count) {
    PacketInfo* head = NULL;
    PacketInfo* current = NULL;

    for (size_t i = 0; i < packet_count; i++) {
        size_t payload_length = payload_lengths[i];
        uint8_t* payload_data = payloads[i];

        // Allocate memory for the new PacketInfo node
        PacketInfo* new_node = (PacketInfo*)malloc(sizeof(PacketInfo));
        if (!new_node) {
            // Handle memory allocation failure
            return head; // Return the list up to this point
        }

        // Calculate required memory size for payload and checksum
        size_t required_size = sizeof(PacketInfo) + payload_length;
        if (required_size < payload_length) {
            free(new_node);
            return head; // Handle integer overflow
        }

        new_node->payload_length = payload_length;
        new_node->payload_data = (uint8_t*)malloc(payload_length);
        if (!new_node->payload_data) {
            free(new_node);
            return head; // Handle memory allocation failure for payload
        }

        // Copy payload data and calculate checksum
        memcpy(new_node->payload_data, payload_data, payload_length);
        new_node->checksum = calculate_checksum(new_node->payload_data, payload_length);

        new_node->next = NULL;

        if (!head) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

// Example usage
int main() {
    // Assume payloads and payload_lengths are properly initialized
    const uint8_t* payloads[] = {...};
    size_t payload_lengths[] = {...};
    size_t packet_count = sizeof(payloads) / sizeof(payloads[0]);

    PacketInfo* packet_list = process_packets(payloads, payload_lengths, packet_count);

    // Process the packet list as needed

    // Clean up
    while (packet_list != NULL) {
        PacketInfo* temp = packet_list;
        free(temp->payload_data);
        free(temp);
        packet_list = temp->next;
    }

    return 0;
}
