#define MAX_NODES 1000

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
int nodeCount = 0;
time_t lastModified;

void addNode(NFAPI_CRC_INDICATION_PDU_T newData) {
    if (nodeCount >= MAX_NODES) return; // Prevent memory exhaustion
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return; // Check for memory allocation failure
    memcpy(&newNode->data, &newData, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = head;
    head = newNode;
    nodeCount++;
    lastModified = time(NULL);
}

void displayList() {
    Node* current = head;
    while (current != NULL) {
        // Display each node's contents
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", 
               current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI, 
               current->data.CRC_INDICATION_REL8_TAG.CRCFLAG);
        current = current->next;
    }
}

void removeDuplicates() {
    Node* current = head;
    while (current != NULL) {
        Node* runner = current;
        while (runner->next != NULL) {
            if (runner->next->data.RNTI == current->data.RNTI) {
                Node* temp = runner->next;
                runner->next = runner->next->next;
                free(temp);
                nodeCount--;
            } else {
                runner = runner->next;
            }
        }
        current = current->next;
    }
    lastModified = time(NULL);
}

