    return newStr;
}

NFAPI_PDULIST_T createNfadPduList(size_t count, size_t maxSize) {
    if (count == 0 || maxSize < strlen(RX_UE_INFORMATION_TAG) + 1 || maxSize < strlen(CRC_INDICATION_REL8_TAG) + 1) {
        return NULL; // Handle invalid parameters
    }

    NFAPI_PDULIST_T head = NULL;
    Node *current = NULL;

    for (size_t i = 0; i < count; ++i) {
        Node *newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            // Free previously allocated nodes
            while (head != NULL) {
                Node *temp = head;
                head = head->next;
                free(temp);
            }
