    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    size_t size;
} LinkedList;

LinkedList* createLinkedList(size_t N) {
    if (N == 0 || N > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL; // Handle integer overflow
    }
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            freeLinkedList(list); // Clean up on failure
            return NULL;
        }
        node->data = 0; // Initialize data
        node->prev = list->tail;
        node->next = NULL;
        if (list->tail) {
            list->tail->next = node;
        } else {
            list->head = node;
        }
        list->tail = node;
        ++list->size;
    }
    return list;
}

void freeLinkedList(LinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* node, size_t index) {
    if (index >= list->size) {
        return; // Handle invalid index
    }
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    node->prev = current;
    node->next = current->next;
    if (current->next) {
        current->next->prev = node;
    } else {
        list->tail = node;
    }
    current->next = node;
    ++list->size;
}

void deleteNode(LinkedList* list, size_t index) {
    if (index >= list->size) {
        return; // Handle invalid index
    }
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }
    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }
    free(current);
    --list->size;
}

void printList(LinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        printf("%d ", current->data);
        current = current->next;
    }
    printf("\n");
}
