#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    void* buffer;
    size_t size;
} Buffer;

typedef struct {
    Buffer* buffers;
    size_t buffer_count;
    size_t max_size;
    pthread_mutex_t lock;
} BufferPool;

BufferPool* create_buffer_pool(size_t max_size, size_t initial_count) {
    BufferPool* pool = (BufferPool*)malloc(sizeof(BufferPool));
    if (pool == NULL) return NULL;

    pool->buffers = (Buffer*)malloc(initial_count * sizeof(Buffer));
    if (pool->buffers == NULL) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < initial_count; i++) {
        pool->buffers[i].buffer = malloc(max_size);
        pool->buffers[i].size = max_size;
        if (pool->buffers[i].buffer == NULL) {
            for (size_t j = 0; j < i; j++) {
                free(pool->buffers[j].buffer);
            }
            free(pool->buffers);
            free(pool);
            return NULL;
        }
    }

    pool->buffer_count = initial_count;
    pool->max_size = max_size;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_buffer_pool(BufferPool* pool) {
    for (size_t i = 0; i < pool->buffer_count; i++) {
        free(pool->buffers[i].buffer);
    }
    free(pool->buffers);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Buffer* get_buffer(BufferPool* pool, size_t payload_size) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->buffer_count; i++) {
        if (payload_size <= pool->buffers[i].size) {
            Buffer* buffer = &pool->buffers[i];
            buffer->size = payload_size;
            pthread_mutex_unlock(&pool->lock);
            return buffer;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return NULL; // No suitable buffer found
}

void return_buffer(BufferPool* pool, Buffer* buffer) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->buffer_count; i++) {
        if (&pool->buffers[i] == buffer) {
            buffer->size = pool->max_size;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}
