typedef struct {
    uint32_t width;
    uint32_t height;
    uint64_t file_offset;
} ImageMetadata;

int process_image_batch(int batch_size, FILE *metadata_file) {
    if (batch_size <= 0 || metadata_file == NULL) {
        return -1; // Invalid input
    }

    size_t total_memory = batch_size * sizeof(ImageMetadata);
    if ((total_memory / sizeof(ImageMetadata)) != batch_size) {
        return -2; // Integer overflow detected
    }

    ImageMetadata *image_metadata = (ImageMetadata *)malloc(total_memory);
    if (image_metadata == NULL) {
        return -3; // Memory allocation failed
    }

    for (int i = 0; i < batch_size; ++i) {
        size_t bytes_read = fread(&image_metadata[i], sizeof(ImageMetadata), 1, metadata_file);
        if (bytes_read != 1) {
            free(image_metadata);
            return -4; // Failed to read image metadata
        }

        if (image_metadata[i].width == 0 || image_metadata[i].height == 0) {
            free(image_metadata);
            return -5; // Invalid image size
        }
    }

    // Process each image using third-party libraries
    for (int i = 0; i < batch_size; ++i) {
        // Image processing code here
    }

    free(image_metadata);
    return 0; // Success
}

// Example usage
int main() {
    FILE *metadata_file = fopen("image_metadata.bin", "rb");
    if (metadata_file == NULL) {
        perror("Failed to open metadata file");
        return EXIT_FAILURE;
    }

    int batch_size;
    printf("Enter the number of images in the batch: ");
    scanf("%d", &batch_size);

    int result = process_image_batch(batch_size, metadata_file);
    if (result != 0) {
        switch (result) {
            case -1:
                fprintf(stderr, "Invalid input\n");
                break;
            case -2:
                fprintf(stderr, "Integer overflow detected\n");
                break;
            case -3:
                fprintf(stderr, "Memory allocation failed\n");
                break;
            case -4:
                fprintf(stderr, "Failed to read image metadata\n");
                break;
            case -5:
                fprintf(stderr, "Invalid image size\n");
                break;
            default:
                fprintf(stderr, "Unknown error occurred\n");
                break;
        }
    }

    fclose(metadata_file);
    return EXIT_SUCCESS;
}
