ImageData* load_images(ImageMetadata** metadata, int count) {
    if (count <= 0 || metadata == NULL) {
        return NULL;
    }

    // Calculate total memory requirement
    size_t total_size = 0;
    for (int i = 0; i < count; i++) {
        if (metadata[i]->reported_size > SIZE_MAX - total_size) {
            fprintf(stderr, "Integer overflow detected during memory allocation.\n");
            return NULL;
        }
        total_size += metadata[i]->reported_size;
    }

    // Allocate memory for the array of image data
    ImageData* images = malloc(count * sizeof(ImageData));
    if (images == NULL) {
        perror("Failed to allocate memory for image data.");
        return NULL;
    }

    // Load each image into memory
    for (int i = 0; i < count; i++) {
        images[i].data = malloc(metadata[i]->reported_size);
        if (images[i].data == NULL) {
            perror("Failed to allocate memory for an individual image.");
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(images[j].data);
            }
            free(images);
            return NULL;
        }

        // Simulate loading the image data from disk or another source
        // For demonstration, we just copy a dummy pattern into each image's data
        memset(images[i].data, 0x55, metadata[i]->reported_size);
    }

    images->size = count * sizeof(ImageData);
    return images;
}

