    if (images != NULL) {
        printf("Images loaded successfully.\n");
        for (int i = 0; i < 2; i++) {
            free(images[i].data);
        }
        free(images);
        for (int i = 0; i < 2; i++) {
            free(metadata[i]);
        }
    }

    return 0;
}
