#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024 * 1024 // Example maximum buffer size

typedef struct {
    char *buffer;
    size_t total_size;
    size_t used_size;
    pthread_mutex_t mutex;
} BufferPool;

void init_buffer_pool(BufferPool *pool, size_t initial_size) {
    pool->total_size = initial_size;
    pool->used_size = 0;
    pool->buffer = (char *)malloc(initial_size);
    pthread_mutex_init(&pool->mutex, NULL);
}

void destroy_buffer_pool(BufferPool *pool) {
    pthread_mutex_destroy(&pool->mutex);
    free(pool->buffer);
}

int allocate_payload(BufferPool *pool, size_t payload_size) {
    pthread_mutex_lock(&pool->mutex);

    if (payload_size + pool->used_size > pool->total_size) {
        pthread_mutex_unlock(&pool->mutex);
        return -1; // Not enough space
    }

    void *ptr = pool->buffer + pool->used_size;
    pool->used_size += payload_size;

    pthread_mutex_unlock(&pool->mutex);
    return 0; // Allocation successful
}

void free_payload(BufferPool *pool, size_t payload_size) {
    pthread_mutex_lock(&pool->mutex);

    if (payload_size > pool->used_size) {
        pthread_mutex_unlock(&pool->mutex);
        return; // Invalid operation
    }

    pool->used_size -= payload_size;

    pthread_mutex_unlock(&pool->mutex);
}

int main() {
    BufferPool pool;
    init_buffer_pool(&pool, MAX_BUFFER_SIZE);

    size_t payload1 = 512;
    size_t payload2 = 768;

    if (allocate_payload(&pool, payload1) == 0) {
        printf("Payload of %zu bytes allocated successfully.\n", payload1);
    } else {
        printf("Failed to allocate payload of %zu bytes.\n", payload1);
    }

    if (allocate_payload(&pool, payload2) == 0) {
        printf("Payload of %zu bytes allocated successfully.\n", payload2);
    } else {
        printf("Failed to allocate payload of %zu bytes.\n", payload2);
    }

    free_payload(&pool, payload1);

    if (allocate_payload(&pool, payload1) == 0) {
        printf("Reallocated Payload of %zu bytes successfully.\n", payload1);
    } else {
        printf("Failed to reallocate payload of %zu bytes.\n", payload1);
    }

    destroy_buffer_pool(&pool);

    return 0;
}
