#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for packet header details
typedef struct HeaderDetails {
    int detailID;
    char* detailData;
    struct HeaderDetails* next;
} HeaderDetails;

// Define the structure for packet header information
typedef struct PacketHeaderInfo {
    PacketHeader* header;
    HeaderDetails* headers;
} PacketHeaderInfo;

// Function to process a batch of network packets
int processPacketBatch(PacketHeader** packets, int numPackets, int maxHeaders) {
    int totalHeaders = 0;
    for (int i = 0; i < numPackets && totalHeaders <= maxHeaders; i++) {
        PacketHeader* packet = packets[i];
        HeaderDetails* currentHeader = packet->headers;

        // Validate the number of headers
        if (currentHeader == NULL) {
            printf("Error: Malformed packet.\n");
            return -1;
        }

        while (currentHeader != NULL && totalHeaders <= maxHeaders) {
            PacketHeaderInfo* headerInfo = malloc(sizeof(PacketHeaderInfo));
            if (headerInfo == NULL) {
                printf("Memory allocation failed.\n");
                return -1;
            }

            // Initialize the packet header information
            headerInfo->header = currentHeader;

            // Process and link header details
            HeaderDetails* detail = currentHeader->details;
            HeaderDetails* prevDetail = NULL;
            while (detail != NULL) {
                HeaderDetails* newDetail = malloc(sizeof(HeaderDetails));
                if (newDetail == NULL) {
                    printf("Memory allocation failed.\n");
                    return -1;
                }

                // Initialize the header detail
                newDetail->detailID = detail->detailID;
                newDetail->detailData = strdup(detail->detailData);
                newDetail->next = NULL;

                if (prevDetail == NULL) {
                    headerInfo->headers = newDetail;
                } else {
                    prevDetail->next = newDetail;
                }
                prevDetail = newDetail;

                // Move to the next detail
                HeaderDetails* temp = detail;
                detail = detail->next;
                free(temp);
            }

            // Add the packet header information to the list
            if (totalHeaders == 0) {
                packets[i]->packetHeaderInfos = headerInfo;
            } else {
                PacketHeaderInfo* lastInfo = packets[i-1]->lastPacketHeaderInfo;
                lastInfo->next = headerInfo;
            }

            // Update the total number of headers processed
            totalHeaders++;
        }
    }

    return 0;
}

// Function to free memory allocated for packet header information
void freePacketHeaderInfo(PacketHeader** packets, int numPackets) {
    for (int i = 0; i < numPackets; i++) {
        PacketHeader* packet = packets[i];
        PacketHeaderInfo* currentInfo = packet->packetHeaderInfos;
        while (currentInfo != NULL) {
            HeaderDetails* header = currentInfo->header;
            HeaderDetails* detail = header->details;

            // Free the header details
            while (detail != NULL) {
                HeaderDetails* temp = detail;
                detail = detail->next;
                free(temp->detailData);
                free(temp);
            }

            // Free the packet header information
            PacketHeaderInfo* tempInfo = currentInfo;
            currentInfo = currentInfo->next;
            free(tempInfo);
        }
    }
}
