typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int allocateNFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T** pdus, int requestedCount) {
    static const size_t structureSize = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    static const size_t alignment = __alignof__(NFAPI_CRC_INDICATION_PDU_T);

    if (pdus == NULL || requestedCount <= 0) {
        return -1; // Invalid input
    }

    *pdus = NULL;
    int count = 0;

    while (count < requestedCount) {
        size_t alignedSize = ((structureSize + alignment - 1) / alignment) * alignment;
        void* allocatedMemory = malloc(alignedSize);

        if (allocatedMemory == NULL) {
            break; // Memory allocation failed, stop further allocations
        }

        if (((size_t)allocatedMemory % alignment) != 0) {
            free(allocatedMemory); // Free the misaligned memory
            continue;
        }

        (*pdus)[count] = *(NFAPI_CRC_INDICATION_PDU_T*)allocatedMemory; // Copy to array

        count++;
    }

    return count;
}

int main() {
    srand(time(NULL));

    int requestedCount = 1000; // Example request
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    int actualCount = allocateNFAPICRCIndicationPDUs(&pdus, requestedCount);

    if (actualCount > 0) {
        printf("Allocated %d structures.\n", actualCount);

        // Initialize CRCFLAG randomly
        for (int i = 0; i < actualCount; i++) {
            pdus[i].CRCFLAG = rand() % 2;
        }

        // Free allocated memory
        free(pdus);
    } else {
        printf("Failed to allocate structures.\n");
    }

    return 0;
}
