typedef struct PacketNode {
    struct PacketNode* prev;
    struct PacketNode* next;
    char data[MAX_PACKET_SIZE];
    int size;
} PacketNode;

typedef struct {
    PacketNode* head;
    PacketNode* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* createPacketList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freePacketList(DoublyLinkedList* list) {
    PacketNode* current = list->head;
    while (current != NULL) {
        PacketNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void addPacketToTail(DoublyLinkedList* list, const char* data, int size) {
    pthread_mutex_lock(&list->lock);
    PacketNode* newNode = (PacketNode*)malloc(sizeof(PacketNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(newNode->data, data, size);
    newNode->size = size;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL)
        list->tail->next = newNode;
    else
        list->head = newNode;
    list->tail = newNode;
    pthread_mutex_unlock(&list->lock);
}

// Add other necessary functions for processing, error handling, and synchronization

