#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_RECORD_SIZE 1024
#define GARBAGE_COLLECTION_THRESHOLD 50

typedef struct {
    char *data;
    size_t size;
} ImageMetadata;

typedef struct {
    ImageMetadata *records;
    size_t count;
    size_t capacity;
    size_t max_memory;
    size_t current_memory;
} MetadataStore;

MetadataStore* create_metadata_store(size_t initial_capacity, size_t max_memory) {
    MetadataStore *store = (MetadataStore*)malloc(sizeof(MetadataStore));
    if (!store) return NULL;

    store->records = (ImageMetadata*)calloc(initial_capacity, sizeof(ImageMetadata));
    if (!store->records) {
        free(store);
        return NULL;
    }

    store->count = 0;
    store->capacity = initial_capacity;
    store->max_memory = max_memory;
    store->current_memory = 0;

    return store;
}

void destroy_metadata_store(MetadataStore *store) {
    if (store->records) {
        for (size_t i = 0; i < store->count; ++i) {
            free(store->records[i].data);
        }
        free(store->records);
    }
    free(store);
}

int insert_metadata_record(MetadataStore *store, const char *metadata, size_t size) {
    if (store->current_memory + size > store->max_memory) return -1;

    if (store->count == store->capacity) {
        ImageMetadata *new_records = (ImageMetadata*)realloc(store->records, store->capacity * 2 * sizeof(ImageMetadata));
        if (!new_records) return -1;

        store->records = new_records;
        store->capacity *= 2;
    }

    store->records[store->count].data = (char*)malloc(size);
    if (!store->records[store->count].data) return -1;

    memcpy(store->records[store->count].data, metadata, size);
    store->records[store->count].size = size;

    store->current_memory += size;
    ++store->count;

    printf("Record inserted successfully.\n");

    // Heuristic for garbage collection
    if (store->count % GARBAGE_COLLECTION_THRESHOLD == 0) {
        collect_garbage(store);
    }

    return 0;
}

void collect_garbage(MetadataStore *store) {
    size_t new_capacity = store->capacity;
    while (new_capacity > store->count + GARBAGE_COLLECTION_THRESHOLD) {
        new_capacity /= 2;
    }

    ImageMetadata *new_records = (ImageMetadata*)realloc(store->records, new_capacity * sizeof(ImageMetadata));
    if (!new_records) return;

    memcpy(new_records, store->records, store->count * sizeof(ImageMetadata));
    free(store->records);
    store->records = new_records;
    store->capacity = new_capacity;
}

void configure_metadata_store(MetadataStore *store, size_t max_memory, int log_level) {
    store->max_memory = max_memory;

    // Configure logging level
    if (log_level == 1) {
        printf("Logging enabled for debugging.\n");
    } else if (log_level == 2) {
        printf("Logging enabled for monitoring.\n");
    }
}

int main() {
    MetadataStore *store = create_metadata_store(10, 1024 * 1024); // Initial capacity of 10 records, max memory of 1MB
    if (!store) return -1;

    configure_metadata_store(store, 2 * 1024 * 1024, 1); // Configure for debugging with a new max memory of 2MB

    const char *metadata = "Sample metadata";
    insert_metadata_record(store, metadata, strlen(metadata));

    destroy_metadata_store(store);

    return 0;
}
