#define MAX_IMAGE_SIZE 10000

typedef struct ImageMetadata {
    char *fileName;
    int resolutionX;
    int resolutionY;
    int fileSize;
    unsigned char *thumbnail;
    struct ImageMetadata *next;
} ImageMetadata;

pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;

ImageMetadata* createImageMetadata(const char *fileName, int resolutionX, int resolutionY, int fileSize) {
    ImageMetadata *metadata = (ImageMetadata *)malloc(sizeof(ImageMetadata));
    if (metadata == NULL) {
        perror("Failed to allocate memory for image metadata");
        return NULL;
    }
    metadata->fileName = strdup(fileName);
    metadata->resolutionX = resolutionX;
    metadata->resolutionY = resolutionY;
    metadata->fileSize = fileSize;
    metadata->thumbnail = NULL; // Placeholder for thumbnail data
    metadata->next = NULL;
    return metadata;
}

void freeImageMetadata(ImageMetadata *metadata) {
    if (metadata != NULL) {
        free(metadata->fileName);
        free(metadata->thumbnail);
        free(metadata);
    }
}

int addImageToLinkedlist(ImageMetadata **head, ImageMetadata *newNode) {
    pthread_mutex_lock(&listMutex);
    newNode->next = *head;
    *head = newNode;
    pthread_mutex_unlock(&listMutex);
    return 0;
}

void processImages(char *fileNames[], int numFiles) {
    if (numFiles > MAX_IMAGE_SIZE) {
        fprintf(stderr, "Too many files specified. Maximum allowed: %d\n", MAX_IMAGE_SIZE);
        return;
    }

    ImageMetadata *head = NULL;

    for (int i = 0; i < numFiles; i++) {
        // Simulate image processing
        int resolutionX = rand() % 2048 + 1; // Random width between 1 and 2048 pixels
        int resolutionY = rand() % 2048 + 1; // Random height between 1 and 2048 pixels
        int fileSize = rand() % (10 * 1024 * 1024) + 1; // Random file size up to 10MB

        ImageMetadata *newNode = createImageMetadata(fileNames[i], resolutionX, resolutionY, fileSize);
        if (newNode != NULL) {
            addImageToLinkedlist(&head, newNode);
        } else {
            fprintf(stderr, "Failed to process image: %s\n", fileNames[i]);
        }
    }

    // Clean up the linked list
    ImageMetadata *current = head;
    while (current != NULL) {
        ImageMetadata *next = current->next;
        freeImageMetadata(current);
        current = next;
    }
}

int main() {
    char *fileNames[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int numFiles = sizeof(fileNames) / sizeof(fileNames[0]);

    processImages(fileNames, numFiles);

    return 0;
}
