} NFAPI_CRC_INDICATION_PDU_T;

int process_image_files(int num_files, char *file_names[], ImageMetadata **metadata_list) {
    if (num_files > MAX_IMAGE_FILES) {
        fprintf(stderr, "Error: Maximum number of image files exceeded.\n");
        return -1;
    }

    *metadata_list = malloc(num_files * sizeof(ImageMetadata));
    if (*metadata_list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for metadata list.\n");
        return -2;
    }

    // Populate the metadata list with example data
    for (int i = 0; i < num_files; i++) {
        strncpy((*metadata_list)[i].file_name, file_names[i], MAX_METADATA_SIZE);
        (*metadata_list)[i].resolution = rand() % 1920 + 720;
        (*metadata_list)[i].file_size = (size_t)rand() * rand();
    }

    return num_files;
}

void generate_crc_indications(int max_size, NFAPI_CRC_INDICATION_PDU_T **crc_list) {
    if (max_size > MAX_IMAGE_FILES) {
        fprintf(stderr, "Error: Maximum number of CRC indications exceeded.\n");
        return;
    }

    *crc_list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for CRC list.\n");
        return;
    }

    // Populate the CRC list with example data
    for (int i = 0; i < max_size; i++) {
        (*crc_list)[i].rx_ue_info_tag = RX_UE_INFORMATION_TAG(rand() % 1024);
        (*crc_list)[i].rnti = RNTI(rand());
        (*crc_list)[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG(rand() % 256);
        (*crc_list)[i].crcflag = (uint8_t)rand();
    }
}

void free_resources(ImageMetadata *metadata_list, NFAPI_CRC_INDICATION_PDU_T *crc_list, int num_files, int max_size) {
    if (metadata_list != NULL) {
        free(metadata_list);
    }

    if (crc_list != NULL) {
        free(crc_list);
    }
}
