typedef struct PacketMetadata {
    int unique_id;
    time_t timestamp;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} PacketMetadata;

typedef struct DoublyLinkedListNode {
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
    PacketMetadata* data;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode* head;
    DoublyLinkedListNode* tail;
} DoublyLinkedList;

void initialize_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
}

DoublyLinkedListNode* create_node(PacketMetadata* data) {
    DoublyLinkedListNode* node = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(DoublyLinkedList* list, PacketMetadata* data) {
    DoublyLinkedListNode* new_node = create_node(data);
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }
    if (list->head == NULL) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
}

void free_list(DoublyLinkedList* list) {
    while (list->head != NULL) {
        DoublyLinkedListNode* temp = list->head;
        list->head = list->head->next;
        free(temp->data);
        free(temp);
    }
    list->tail = NULL;
}

