        new_packet->pdu.RNTI = rand() % 100;
        new_packet->pdu.CRC_INDICATION_REL8_TAG = rand() % 2;

        insert_node(&packet_list, new_packet);
    }

    // Free the list when done
    free_list(&packet_list);

