typedef struct PacketHeader {
    int packetID;
    time_t timestamp;
    struct PacketHeader* next;
} PacketHeader;

PacketHeader* processPackets(int* packetIDs, size_t numPackets) {
    if (numPackets == 0) return NULL;

    // Initialize the linked list
    PacketHeader* head = NULL;
    PacketHeader* current = NULL;

    for (size_t i = 0; i < numPackets; ++i) {
        PacketHeader* newPacket = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (newPacket == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed.\n");
            return head;
        }

        newPacket->packetID = packetIDs[i];
        newPacket->timestamp = time(NULL);
        newPacket->next = NULL;

        if (head == NULL) {
            head = newPacket;
        } else {
            current->next = newPacket;
        }
        current = newPacket;
    }

    return head;
}

// Example usage
int main() {
    int packetIDs[] = {1, 2, 3, 4, 5};
    size_t numPackets = sizeof(packetIDs) / sizeof(packetIDs[0]);

    PacketHeader* packets = processPackets(packetIDs, numPackets);

    // Print the linked list
    for (PacketHeader* p = packets; p != NULL; p = p->next) {
        printf("Packet ID: %d, Timestamp: %ld\n", p->packetID, p->timestamp);
    }

    // Free the allocated memory
    PacketHeader* temp;
    while (packets != NULL) {
        temp = packets;
        packets = packets->next;
        free(temp);
    }

    return 0;
}
