#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKETS 1024
#define BUFFER_SIZE 8192

typedef struct {
    uint32_t length;
    uint32_t id;
} PacketHeader;

uint32_t process_packets(uint8_t *buffer, size_t buffer_size, PacketHeader *packet_headers) {
    static uint32_t packet_id = 0;
    size_t offset = 0;
    uint32_t processed_packets = 0;

    while (offset < buffer_size && processed_packets < MAX_PACKETS) {
        if (offset + sizeof(uint32_t) > buffer_size) {
            break; // Not enough space for the length field
        }

        uint32_t packet_length;
        memcpy(&packet_length, buffer + offset, sizeof(packet_length));
        offset += sizeof(packet_length);

        if (packet_length == 0 || packet_length > buffer_size - offset) {
            continue; // Skip invalid or zero-length packets
        }

        if (offset + packet_length > buffer_size) {
            break; // Not enough data for the packet
        }

        if (processed_packets >= MAX_PACKETS) {
            break; // Reached maximum number of packets to process
        }

        packet_headers[processed_packets].length = packet_length;
        packet_headers[processed_packets].id = packet_id++;
        processed_packets++;
    }

    return processed_packets;
}
