#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_NFAPI_STRUCTS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    size_t count;
} LinkedList;

int generate_random_crcflag() {
    return rand() % 2; // Simplified for example purposes
}

void add_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= MAX_NFAPI_STRUCTS) {
        printf("Cannot add more nodes. Maximum reached.\n");
        return;
    }

    struct Node* new_node = malloc(sizeof(struct Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

void serialize_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return;
    }

    struct Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

void free_list(LinkedList* list) {
    struct Node* current = list->head;
    while (current) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    srand(time(NULL));

    LinkedList my_list = {NULL, 0};

    NFAPI_CRC_INDICATION_PDU_T new_data;
    for (size_t i = 0; i < MAX_NFAPI_STRUCTS; ++i) {
        new_data.RX_UE_INFORMATION_TAG = i + 1;
        new_data.RNTI = i * 2;
        new_data.CRC_INDICATION_REL8_TAG = generate_random_crcflag();
        add_node(&my_list, new_data);
    }

    serialize_list(&my_list, "nfaapi_data.bin");

    free_list(&my_list);

    return 0;
}
