    size_t capacity;
    size_t count;
    size_t allocated_size;
} MemoryPool;

int init_memory_pool(MemoryPool *mp, size_t initial_capacity) {
    if (initial_capacity > MAX_STRUCTURES || initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) > TOTAL_MEMORY) {
        return -1; // Invalid capacity
    }

    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        return -2; // Memory allocation failed
    }

    mp->capacity = initial_capacity;
    mp->count = 0;
    mp->allocated_size = initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return 0; // Success
}

int resize_memory_pool(MemoryPool *mp, size_t new_capacity) {
    if (new_capacity > MAX_STRUCTURES || new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T) > TOTAL_MEMORY) {
        return -1; // Invalid capacity
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T *)realloc(mp->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) {
        return -2; // Memory reallocation failed
