    mp->pool = new_pool;
    mp->capacity = new_capacity;
    mp->allocated_size = new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return 0; // Success
}

void destroy_memory_pool(MemoryPool *mp) {
