#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} CRC_POOL_T;

CRC_POOL_T *create_crc_pool(size_t initial_capacity) {
    CRC_POOL_T *pool = malloc(sizeof(CRC_POOL_T));
    if (!pool) return NULL;

    pool->pool = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_crc_ind(CRC_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used == pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *indication = &pool->pool[pool->used++];
    pthread_mutex_unlock(&pool->lock);

    // Initialize structure with random CRCFLAG
    indication->crc_ind.CRCFLAG = rand() % 2;

    return indication;
}

void free_crc_pool(CRC_POOL_T *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}
```

This code provides a basic framework for managing an array of `NFAPI_CRC_INDICATION_PDU_T` structures dynamically using a thread-safe pool. The `create_crc_pool` function initializes the pool with a specified capacity, `allocate_crc_ind` allocates a new structure from the pool and initializes it with a random CRCFLAG, and `free_crc_pool` frees all allocated memory when done. This design includes basic synchronization to ensure safe concurrent access and handles dynamic resizing to accommodate varying workloads.']

