#include <errno.h>

#define MAX_MEMORY_SIZE 1024 * 1024 * 1024 // 1GB
#define MIN_SIZEOF_NFAPI_CRC_INDICATION_PDU_T sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_LIST_NODE_T {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct NFAPI_LIST_NODE_T* next;
} NFAPI_LIST_NODE_T;

typedef struct NFAPI_LIST_T {
    NFAPI_LIST_NODE_T* head;
    NFAPI_LIST_NODE_T* tail;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

int init_list(NFAPI_LIST_T* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    return pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(NFAPI_LIST_T* list) {
    NFAPI_LIST_NODE_T* current = list->head;
    while (current != NULL) {
        NFAPI_LIST_NODE_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_to_list(NFAPI_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    size_t new_size = list->count * MIN_SIZEOF_NFAPI_CRC_INDICATION_PDU_T;
    if (new_size >= MAX_MEMORY_SIZE) {
        errno = ENOMEM;
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    NFAPI_LIST_NODE_T* new_node = malloc(sizeof(NFAPI_LIST_NODE_T));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

