}

int validateImageDimensions(int width, int height) {
    // Validation logic for image dimensions
    if (width <= 0 || height <= 0 || width > MAX_DIMENSION || height > MAX_DIMENSION) {
        return -1;
    }
    return 0; // Return 0 on success
}

int processImages(int maxMemory, const char **fileNames, int fileCount, ImageHeader **headers) {
    uint64_t totalSize = 0;

    for (int i = 0; i < fileCount; i++) {
        ImageHeader header;

        // Validate image dimensions
        if (validateImageDimensions(header.width, header.height)) {
            return -1; // Invalid dimensions
        }

        // Calculate SHA-256 and generate identifier
        if (calculateSHA256(fileNames[i], header.identifier) != 0) {
            return -1; // Failed to calculate SHA-256
        }

        // Calculate size of memory required for this image header
        uint64_t imageSize = sizeof(ImageHeader);

        // Check for potential integer overflow during total size calculation
        if (totalSize > UINT64_MAX - imageSize) {
            return -1; // Integer overflow
        }
        totalSize += imageSize;

        // Check if the required memory exceeds the maximum allowed
        if (totalSize > maxMemory) {
            return -1; // Exceeds memory limit
        }
    }

    *headers = malloc(totalSize);
    if (*headers == NULL) {
        return -1; // Memory allocation failed
    }

    totalSize = 0;
    for (int i = 0; i < fileCount; i++) {
        ImageHeader header;

        // Populate the headers array
        memcpy((*headers) + totalSize, &header, sizeof(ImageHeader));
        totalSize += sizeof(ImageHeader);
    }

    return 0; // Success
}
