#include <stdlib.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500 // Example maximum packet size

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* cache = NULL;
int cache_size = 0;
const int cache_limit = 1000; // Example cache limit

Node* allocate_node() {
    if (cache != NULL) {
        Node* temp = cache;
        cache = cache->next;
        cache_size--;
        return temp;
    } else {
        return (Node*)malloc(sizeof(Node));
    }
}

void free_node(Node* node) {
    node->next = cache;
    cache = node;
    cache_size++;
    if (cache_size > cache_limit) {
        Node* temp = cache;
        cache = cache->next;
        free(temp);
        cache_size--;
    }
}

Node* create_list(int N, int packet_size) {
    srand(time(NULL));
    Node* head = NULL;
    Node* current = NULL;

    for (int i = 0; i < N; i++) {
        Node* new_node = allocate_node();
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        if (packet_size <= MAX_PACKET_SIZE) {
            new_node->data.RX_UE_INFORMATION_TAG = rand() % 100;
            new_node->data.RNTI = rand() % 256;
            new_node->data.CRC_INDICATION_REL8_TAG = rand() % 2;
        } else {
            fprintf(stderr, "Packet size exceeds maximum limit\n");
            free_node(new_node);
            exit(1);
        }

        if (head == NULL) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
    }

    return head;
}

void destroy_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free_node(temp);
    }
}
