#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_pool(int N) {
    pthread_mutex_lock(&pool_mutex);

    if (N > 10000 || N <= 0) {
        fprintf(stderr, "Error: Invalid number of structures requested.\n");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    size_t required_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    if (required_memory > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Error: Requested memory exceeds the maximum allowed.\n");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(required_memory);
