int calculate_total_payload_size(int packet_sizes[], int num_packets, int *total_size) {
    if (num_packets > MAX_PACKETS || total_size == NULL) return -1;

    *total_size = 0;
    for (int i = 0; i < num_packets; i++) {
        if (packet_sizes[i] > MAX_PAYLOAD_SIZE) return -2;
        if (*total_size + packet_sizes[i] < *total_size) return -3; // Check for integer overflow
        *total_size += packet_sizes[i];
    }

    return 0;
}

int process_packets(int packet_sizes[], int num_packets, void **buffer, PacketInfo *info) {
    if (num_packets > MAX_PACKETS || info == NULL || buffer == NULL) return -1;

    int total_payload_size = 0;
    if (calculate_total_payload_size(packet_sizes, num_packets, &total_payload_size) != 0) return -2;

    *buffer = malloc(total_payload_size);
    if (*buffer == NULL) return -3; // Memory allocation failed

    info->num_packets = num_packets;
    info->total_payload_size = total_payload_size;

    int offset = 0;
    for (int i = 0; i < num_packets; i++) {
        memcpy((char *)*buffer + offset, &packet_sizes[i], sizeof(int));
        offset += sizeof(int);
    }

    return 0;
}

void free_packet_buffer(void *buffer) {
    if (buffer != NULL) free(buffer);
}
