bool add_element(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= list->max_size) {
        // Resize the list if it's 90% full
        size_t new_max_size = list->max_size * 2;
        Node** new_nodes = realloc(list->head, new_max_size * sizeof(Node));
        if (!new_nodes) return false; // Memory allocation failed
        list->head = new_nodes;
        list->max_size = new_max_size;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false; // Memory allocation failed

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    list->count++;
    return true;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
