#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 * 512 // 512 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t allocated;
    size_t used;
    pthread_mutex_t lock;
    size_t peak_memory;
    size_t total_allocated;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T* create_crc_pool(size_t initial_size) {
    NFAPI_CRC_POOL_T* pool = (NFAPI_CRC_POOL_T*)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;

    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pool->allocated = initial_size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->peak_memory = 0;
    pool->total_allocated = 0;

    return pool;
}

void destroy_crc_pool(NFAPI_CRC_POOL_T* pool) {
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int allocate_crc_pdu(NFAPI_CRC_POOL_T* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used >= pool->allocated) {
        size_t new_size = pool->allocated * 2;
        while (new_size < pool->used + 1 && new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY)
            new_size /= 2;

        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }

        pool->data = new_data;
        pool->allocated = new_size;

        // Update peak memory usage
        size_t current_memory_usage = pool->allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (current_memory_usage > pool->peak_memory)
            pool->peak_memory = current_memory_usage;

        pool->total_allocated += current_memory_usage - pool->used * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pool->data[pool->used++] = *pdu;
    pthread_mutex_unlock(&pool->lock);

    return 0;
