NFAPI_CRC_INDICATION_PDU_T* manage_array(int N, size_t max_memory) {
    static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    static size_t allocated_memory = 0;
    time_t now = time(NULL);
    unsigned int seed = (unsigned int)(now ^ (size_t)&NFAPI_CRC_INDICATION_PDU_T);

    // Reallocate if necessary
    if (N > MAX_STRUCTURES || N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_memory) {
        if (array) free(array);
        allocated_memory = 0;
    }

    if (!array) {
        array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) return NULL; // Allocation failed
        allocated_memory += N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    } else {
        if (allocated_memory + N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > max_memory) {
            N = (max_memory - allocated_memory) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
            array = realloc(array, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array) return NULL; // Reallocation failed
        }
    }

    srand(seed);

    for (int i = 0; i < N; i++) {
