typedef struct {
    int width;
    int height;
} ImageMetadata;

int calculateMemoryRequirement(int imageCount, int minDimension, int maxDimension) {
    long long totalSize = (long long)imageCount * sizeof(ImageMetadata);
    if (totalSize > INT_MAX || totalSize / imageCount != sizeof(ImageMetadata)) {
        return -1; // Overflow detected
    }
    return (int)totalSize;
}

ImageMetadata* processImages(int imageCount, int retryAttempts, int minDimension, int maxDimension) {
    ImageMetadata* images = NULL;
    int attempt = 0;

    while (attempt < retryAttempts + 1) {
        int memoryRequirement = calculateMemoryRequirement(imageCount, minDimension, maxDimension);
        if (memoryRequirement == -1 || (images = malloc(memoryRequirement)) != NULL) {
            break; // Success or no more retries left
        }
        attempt++;
    }

    if (!images && retryAttempts > 0) {
        printf("Failed to allocate memory after %d attempts\n", retryAttempts);
        return NULL;
    }

    for (int i = 0; i < imageCount; i++) {
        images[i].width = rand() % (maxDimension - minDimension + 1) + minDimension;
        images[i].height = rand() % (maxDimension - minDimension + 1) + minDimension;
    }

    return images;
}
