#include <pthread.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
}

#define MAX_STRUCTS 1024

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_STRUCTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->used = 0;
    da->size = MAX_STRUCTS;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da->array) free(da->array);
    free(da);
}

int add_to_dynamic_array(DynamicArray *da, int rx_tag, uint16_t rnti, int crc_tag) {
    pthread_mutex_lock(&da->mutex);
    if (da->used >= da->size) {
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, da->size * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Out of memory
        }
        da->array = new_array;
        da->size *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_item = &da->array[da->used++];
    new_item->RX_UE_INFORMATION_TAG = rx_tag;
    new_item->RNTI = rnti;
    new_item->CRC_INDICATION_REL8_TAG = crc_tag;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int validate_structure_size(size_t size) {
    if (size > SIZE_MAX / 2) return -1; // Check for integer overflow
    return 0;
}
