typedef struct {
    uint16_t header;
    uint32_t payload_length;
    char *payload_buffer;
} Packet;

int process_packets(uint8_t **packet_stream, size_t stream_size, uint32_t max_memory, int (*log_function)(const char*), void (*filter_packet)(Packet*)) {
    if (stream_size == 0 || max_memory == 0) return -1; // Invalid input

    Packet *packets = NULL;
    size_t packet_count = 0;
    size_t total_memory_used = 0;

    uint8_t *current_position = *packet_stream;

    while (current_position < (*packet_stream + stream_size)) {
        if (total_memory_used >= max_memory) break; // Exceeded memory limit

        Packet new_packet;
        memcpy(&new_packet.header, current_position, sizeof(uint16_t));
        current_position += sizeof(uint16_t);

        memcpy(&new_packet.payload_length, current_position, sizeof(uint32_t));
        current_position += sizeof(uint32_t);

        if (new_packet.payload_length > UINT32_MAX - total_memory_used) {
            log_function("Payload size exceeds memory limit");
            break;
        }

        new_packet.payload_buffer = malloc(new_packet.payload_length);
        if (!new_packet.payload_buffer) {
            log_function("Memory allocation failed");
            for (size_t i = 0; i < packet_count; ++i) free(packets[i].payload_buffer);
            free(packets);
            return -1;
        }

        memcpy(new_packet.payload_buffer, current_position, new_packet.payload_length);
        current_position += new_packet.payload_length;

        packets = realloc(packets, (packet_count + 1) * sizeof(Packet));
        if (!packets) {
            log_function("Memory allocation failed");
            for (size_t i = 0; i <= packet_count; ++i) free(packets[i].payload_buffer);
            free(new_packet.payload_buffer);
            return -1;
        }

        packets[packet_count++] = new_packet;
        total_memory_used += sizeof(Packet) + new_packet.payload_length;

        filter_packet(&packets[packet_count - 1]);
    }

    *packet_stream = current_position;
    return packet_count;
}
