#include <stdlib.h>
#include <stdio.h>

#define RX_UE_INFORMATION_TAG 1
#define RNTI 2
#define CRC_INDICATION_REL8_TAG 3

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int tag;
    int value;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

int allocateLinkedList(LinkedList** list, size_t maxElements) {
    *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (*list == NULL) {
        return -1; // Allocation failed
    }
    (*list)->head = (*list)->tail = NULL;
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->mutex, NULL);
    return 0;
}

int populateList(LinkedList* list, size_t maxElements) {
    for (size_t i = 0; i < maxElements; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            // Handle allocation failure
            return -1;
        }
        newNode->data.tag = RX_UE_INFORMATION_TAG;
        newNode->data.value = RNTI + rand() % 10; // Randomly set value for RNTI
        newNode->next = NULL;
        newNode->prev = list->tail;

        if (list->tail != NULL) {
            list->tail->next = newNode;
        } else {
            list->head = newNode;
        }
        list->tail = newNode;
        ++list->size;
    }
    return 0;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int main() {
    LinkedList* myList;
    size_t maxElements = 1000;

    if (allocateLinkedList(&myList, maxElements) != 0) {
        printf("Failed to allocate linked list\n");
        return 1;
    }

    if (populateList(myList, maxElements) != 0) {
        printf("Failed to populate linked list\n");
        freeLinkedList(myList);
        return 1;
    }

    // Use the list...

    freeLinkedList(myList);
    return 0;
}
```

