#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_FRAMES 100

typedef struct FrameMetadata {
    time_t timestamp;
    int resolution;
    unsigned long checksum;
    struct FrameMetadata *next;
} FrameMetadata;

FrameMetadata* insert_frame_metadata(FrameMetadata **head, time_t timestamp, int resolution, unsigned long checksum) {
    if (*head == NULL || (*head)->timestamp < timestamp) {
        FrameMetadata *new_frame = (FrameMetadata *)malloc(sizeof(FrameMetadata));
        new_frame->timestamp = timestamp;
        new_frame->resolution = resolution;
        new_frame->checksum = checksum;
        new_frame->next = *head;
        *head = new_frame;

        // Remove frames beyond MAX_FRAMES limit
        FrameMetadata **current = &(*head);
        for (int i = 0; i < MAX_FRAMES - 1 && (*current)->next != NULL; i++) {
            current = &(*current)->next;
        }
        if ((*current)->next != NULL) {
            *current = NULL;
        }

        return new_frame;
    } else {
        insert_frame_metadata(&(*head)->next, timestamp, resolution, checksum);
        return *head;
    }
}

void clean_up_frames(FrameMetadata **head) {
    FrameMetadata *current = *head;
    FrameMetadata *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    FrameMetadata *frame_head = NULL;
    time_t timestamp;
    int resolution;
    unsigned long checksum;

    // Simulate incoming frames
    for (int i = 0; i < MAX_FRAMES + 5; i++) {
        timestamp = time(NULL) - i;
        resolution = rand() % 1080 + 720;
        checksum = rand();
        insert_frame_metadata(&frame_head, timestamp, resolution, checksum);
    }

    // Clean up allocated memory
    clean_up_frames(&frame_head);

    return 0;
}
