        free(image_array);
        return NULL;
    }

    for (int i = 0; i < rows; ++i) {
        image_array[i].pixel_data = malloc(pixel_data_size);
        if (image_array[i].pixel_data == NULL) {
            perror("Failed to allocate memory for pixel data");
            for (int j = 0; j < i; ++j) {
                free(image_array[j].pixel_data);
            }
