        image_array[i].width = cols;
        image_array[i].height = rows;
        // Simulate random pixel data generation
        for (size_t j = 0; j < pixel_data_size; ++j) {
            image_array[i].pixel_data[j] = rand() % 256;
        }
    }

    return image_array;
}

