#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MIN_DIMENSION 1
#define MAX_DIMENSION 1024
#define MEMORY_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct {
    int width;
    int height;
    unsigned char* pixel_data;
} ImageData;

ImageData** allocate_images(int num_images) {
    if (num_images < 0 || num_images > MEMORY_THRESHOLD / (MAX_DIMENSION * MAX_DIMENSION)) {
        fprintf(stderr, "Error: Invalid number of images.\n");
        return NULL;
    }

    ImageData** image_array = malloc(num_images * sizeof(ImageData*));
    if (!image_array) {
        fprintf(stderr, "Error: Memory allocation failed for image array.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_images; ++i) {
        int width = MIN_DIMENSION + rand() % (MAX_DIMENSION - MIN_DIMENSION + 1);
        int height = MIN_DIMENSION + rand() % (MAX_DIMENSION - MIN_DIMENSION + 1);

        image_array[i] = malloc(sizeof(ImageData));
        if (!image_array[i]) {
            fprintf(stderr, "Error: Memory allocation failed for ImageData structure.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(image_array[j]->pixel_data);
                free(image_array[j]);
            }
            free(image_array);
            return NULL;
        }

        image_array[i]->width = width;
        image_array[i]->height = height;

        size_t buffer_size = width * height * sizeof(unsigned char);
        if (buffer_size > SIZE_MAX / num_images) {
            fprintf(stderr, "Error: Integer overflow in pixel data buffer size calculation.\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(image_array[j]->pixel_data);
                free(image_array[j]);
            }
            free(image_array);
            return NULL;
        }

        image_array[i]->pixel_data = malloc(buffer_size);
        if (!image_array[i]->pixel_data) {
            fprintf(stderr, "Error: Memory allocation failed for pixel data buffer.\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(image_array[j]->pixel_data);
                free(image_array[j]);
            }
            free(image_array);
            return NULL;
        }

        // Initialize pixel data with random values for demonstration purposes
        for (size_t k = 0; k < buffer_size; ++k) {
            image_array[i]->pixel_data[k] = rand() % 256;
        }
    }

    return image_array;
}

void free_images(ImageData** images, int num_images) {
    if (!images) {
        return;
    }

    for (int i = 0; i < num_images; ++i) {
        if (images[i]) {
            free(images[i]->pixel_data);
            free(images[i]);
        }
    }

    free(images);
}

int main() {
    int num_images = 100; // Example number of images
    ImageData** image_array = allocate_images(num_images);

    if (image_array) {
        printf("Images allocated successfully.\n");
        free_images(image_array, num_images);
        printf("Memory freed successfully.\n");
    }

    return 0;
}
