    const uint32_t MAX_ADDITIONAL_COUNT = 10000;
    const uint32_t RNTI_RANGE_START = 1;
    const uint32_t RNTI_RANGE_END = 1000000;

    if (initial_count > UINT_MAX - MAX_ADDITIONAL_COUNT) {
        // Handle integer overflow
        return NULL;
    }

    uint32_t total_needed = initial_count + MAX_ADDITIONAL_COUNT;
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(total_needed * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        // Handle memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    uint32_t rnti_pool[RNTI_RANGE_END - RNTI_RANGE_START + 1];
    for (uint32_t i = 0; i < RNTI_POOL_SIZE; ++i) {
        rnti_pool[i] = RNTI_RANGE_START + i;
    }

    for (uint32_t i = 0; i < initial_count; ++i) {
        uint32_t random_index = rand() % (total_needed - i);
        array[i].ue_info_tag = RX_UE_INFORMATION_TAG; // Assign a valid tag
        array[i].rnti = rnti_pool[random_index];
        rnti_pool[random_index] = rnti_pool[total_needed - i - 1];
    }

    for (uint32_t i = initial_count; i < total_needed; ++i) {
        array[i].ue_info_tag = RX_UE_INFORMATION_TAG; // Assign a valid tag
        array[i].rnti = RNTI_RANGE_START + rand() % (RNTI_RANGE_END - RNTI_RANGE_START + 1);
