        if (packets[i]->payload_size > MAX_PACKET_SIZE) {
            // Handle error: Packet too large
            continue;
        }

        if ((SIZE_MAX - allocated_memory) < packets[i]->payload_size) {
            // Handle error: Integer overflow risk
            break;
        }

        void* new_payload = realloc(packets[i]->payload, packets[i]->payload_size);
        if (new_payload == NULL) {
            // Handle error: Memory allocation failed
            continue;
        }

        packets[i]->payload = new_payload;
        allocated_memory += packets[i]->payload_size;

        if (allocated_memory > total_memory_limit) {
            // Handle error: Exceeded memory limit
            break;
        }
    }
