#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define MEMORY_LIMIT 1024 * 1024

typedef struct {
    int packet_size;
    void* payload;
} Packet;

typedef struct {
    pthread_mutex_t lock;
    size_t allocated_memory;
    int total_packets_processed;
    double total_payload_size;
} NetworkStats;

NetworkStats stats;

void init_stats() {
    pthread_mutex_init(&stats.lock, NULL);
    stats.allocated_memory = 0;
    stats.total_packets_processed = 0;
    stats.total_payload_size = 0;
}

void log_stats() {
    printf("Total Packets Processed: %d\n", stats.total_packets_processed);
    printf("Average Payload Size: %.2f\n", stats.total_payload_size / stats.total_packets_processed);
    printf("Allocated Memory: %zu bytes\n", stats.allocated_memory);
}

void* process_packet(void* arg) {
    Packet* packet = (Packet*)arg;
    if (packet->packet_size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Invalid packet size: %d\n", packet->packet_size);
        return NULL;
    }

    pthread_mutex_lock(&stats.lock);
    if (stats.allocated_memory + packet->packet_size > MEMORY_LIMIT) {
        fprintf(stderr, "Memory allocation limit exceeded\n");
        pthread_mutex_unlock(&stats.lock);
        return NULL;
    }

    stats.allocated_memory += packet->packet_size;
    stats.total_packets_processed++;
    stats.total_payload_size += packet->packet_size;
    pthread_mutex_unlock(&stats.lock);

    // Simulate processing payload
    printf("Processing packet with size: %d\n", packet->packet_size);
    free(packet->payload); // Free allocated memory for payload

    return NULL;
}

int main() {
    init_stats();

    Packet packets[] = {
        {128, malloc(128)},
        {256, malloc(256)},
        {300, malloc(300)},
        {1000, malloc(1000)} // Invalid packet size
    };

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, process_packet, &packets[i]);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    log_stats();
    return 0;
}
