#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_THREADS 10

typedef struct {
    char *filename;
    size_t size;
} FileData;

typedef struct {
    FileData files[MAX_THREADS];
    int count;
    size_t total_size;
    size_t memory_limit;
    pthread_mutex_t mutex;
} ThreadArgs;

void* process_file(void* arg) {
    ThreadArgs *args = (ThreadArgs*)arg;
    for (int i = 0; i < args->count; ++i) {
        FILE *file = fopen(args->files[i].filename, "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }
        fseek(file, 0, SEEK_END);
        size_t size = ftell(file);
        fseek(file, 0, SEEK_SET);

        pthread_mutex_lock(&args->mutex);
        if (args->total_size + size > args->memory_limit) {
            printf("Memory limit reached. Cannot process file: %s\n", args->files[i].filename);
            pthread_mutex_unlock(&args->mutex);
            fclose(file);
            continue;
        }

        void *payload = malloc(size);
        if (!payload) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&args->mutex);
            fclose(file);
            continue;
        }
        fread(payload, 1, size, file);
        // Process payload...
        free(payload);
        args->total_size += size;
        pthread_mutex_unlock(&args->mutex);
        fclose(file);
    }
    return NULL;
}

void process_files(ThreadArgs *args) {
    pthread_t threads[MAX_THREADS];
    int thread_count = (args->count + MAX_THREADS - 1) / MAX_THREADS;

    for (int i = 0; i < thread_count; ++i) {
        pthread_create(&threads[i], NULL, process_file, args);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    ThreadArgs args;
    args.count = 5;
    args.memory_limit = 1024 * 1024 * 10; // 10 MB
    pthread_mutex_init(&args.mutex, NULL);

    // Initialize files and sizes...
    for (int i = 0; i < args.count; ++i) {
        snprintf(args.files[i].filename, sizeof(args.files[i].filename), "file%d.dat", i);
        args.files[i].size = i * 1024 * 1024; // Simulated file sizes
    }

    process_files(&args);

    pthread_mutex_destroy(&args.mutex);
    return 0;
}
