#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    // Assuming these fields are already defined
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* free_list;
    size_t max_size;
    size_t current_size;
} CRC_LIST_MANAGER_T;

int initialize_crc_manager(CRC_LIST_MANAGER_T* manager, size_t max_size) {
    if (max_size > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Integer overflow detected
    }
    manager->max_size = max_size;
    manager->current_size = 0;
    manager->head = NULL;
    manager->free_list = NULL;

    pthread_mutex_init(&manager->lock, NULL);

    // Preallocate memory for the free list
    for (size_t i = 0; i < max_size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) return -2; // Memory allocation failed

        new_node->next = manager->free_list;
        manager->free_list = new_node;
    }

    return 0; // Success
}

void destroy_crc_manager(CRC_LIST_MANAGER_T* manager) {
    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T* node = manager->head;
    while (node) {
        NFAPI_CRC_INDICATION_PDU_T* temp = node;
        node = node->next;
        free(temp);
    }
    manager->head = NULL;

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
}

int add_crc_indication(CRC_LIST_MANAGER_T* manager, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_ind_tag) {
    pthread_mutex_lock(&manager->lock);

    if (manager->current_size >= manager->max_size) {
        // Prune the list to make space
        NFAPI_CRC_INDICATION_PDU_T* oldest = manager->head;
        manager->head = oldest->next;

        oldest->ue_info_tag = ue_info_tag;
        oldest->rnti = rnti;
        oldest->crc_ind_tag = crc_ind_tag;
        oldest->crcflag = rand() % 2; // Randomly set CRCFLAG

        oldest->next = manager->free_list;
        manager->free_list = oldest;

        pthread_mutex_unlock(&manager->lock);
        return -3; // List is full, pruned one entry
    }

    if (manager->free_list) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = manager->free_list;
        manager->free_list = new_node->next;

        new_node->ue_info_tag = ue_info_tag;
        new_node->rnti = rnti;
        new_node->crc_ind_tag = crc_ind_tag;
        new_node->crcflag = rand() % 2; // Randomly set CRCFLAG

        new_node->next = manager->head;
        manager->head = new_node;

        ++manager->current_size;
    } else {
        // Handle memory allocation failure
        pthread_mutex_unlock(&manager->lock);
        return -2; // Memory allocation failed
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Additional functions for pruning, error handling, and integration can be added here.
