typedef struct PacketMetadata {
    time_t timestamp;
    size_t size;
    int id;
    struct PacketMetadata* next;
} PacketMetadata;

PacketMetadata* create_packet_metadata(time_t timestamp, size_t size, int id) {
    if (timestamp == 0 || size == 0 || id < 0) {
        return NULL; // Invalid input
    }

    PacketMetadata* packet = (PacketMetadata*)malloc(sizeof(PacketMetadata));
    if (packet == NULL) {
        return NULL; // Memory allocation failed
    }

    packet->timestamp = timestamp;
    packet->size = size;
    packet->id = id;
    packet->next = NULL;

    return packet;
}

void add_packet_to_list(PacketMetadata** head, PacketMetadata* new_packet) {
    if (new_packet == NULL) {
        return; // Invalid packet
    }

    if (*head == NULL) {
        *head = new_packet;
        return;
    }

    PacketMetadata* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = new_packet;
}

void free_packet_list(PacketMetadata** head) {
    PacketMetadata* current = *head;
    PacketMetadata* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}
