NetworkPacket* create_packets(size_t packet_count, size_t total_payload_size) {
    if (packet_count > MAX_PACKET_COUNT || total_payload_size > SIZE_MAX / packet_count) {
        fprintf(stderr, "Error: Packet count or total payload size exceeds limits.\n");
        return NULL;
    }

    NetworkPacket* packets = malloc(packet_count * sizeof(NetworkPacket));
    if (!packets) {
        fprintf(stderr, "Error: Memory allocation failed for packets array.\n");
        return NULL;
    }

    void** payloads = malloc(total_payload_size);
    if (!payloads) {
        fprintf(stderr, "Error: Memory allocation failed for payloads array.\n");
        free(packets);
        return NULL;
    }

    size_t payload_offset = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        packets[i].length = rand() % (total_payload_size - payload_offset + 1); // Random payload size
        if (payload_offset + packets[i].length > total_payload_size) {
            fprintf(stderr, "Error: Invalid payload size calculation.\n");
            free(payloads);
            free(packets);
            return NULL;
        }
        packets[i].payload = payloads + payload_offset;
        payload_offset += packets[i].length;
    }

    return packets;
}

void destroy_packets(NetworkPacket* packets, size_t packet_count) {
    if (packets) {
        for (size_t i = 0; i < packet_count; ++i) {
            if (packets[i].payload) {
                // Free each payload if necessary
                free(packets[i].payload);
            }
        }
        free(packets);
    }
}

int main() {
    size_t packet_count = 10;
    size_t total_payload_size = 256;

    NetworkPacket* packets = create_packets(packet_count, total_payload_size);
    if (packets) {
        // Process packets
        destroy_packets(packets, packet_count);
    }

    return 0;
}
