int parse_integer_from_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    int value;
    char buffer[256];
    if (fgets(buffer, sizeof(buffer), file) != NULL) {
        errno = 0;
        value = strtol(buffer, NULL, 10);
        if ((errno == ERANGE && (value == LONG_MAX || value == LONG_MIN))
            || (errno != 0 && value == 0)) {
            perror("Invalid integer in configuration file");
            fclose(file);
            return -1;
        }
    } else {
        perror("Empty or invalid configuration file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return value;
}

