    if (!array) {
        FILE *log_file = fopen("allocation_errors.log", "a");
        if (log_file) {
            fprintf(log_file, "Memory allocation failed: %s\n", strerror(errno));
            fclose(log_file);
        } else {
            perror("Failed to open allocation errors log file");
        }
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return array;
}

int main() {
    int N = parse_integer_from_file(CONFIG_FILE_PATH);
    if (N < 0) {
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = allocate_NFAPI_CRC_INDICATION_PDU(N);
    if (!array) {
        return EXIT_FAILURE;
    }

    // Use the allocated array...

    free(array);
    return EXIT_SUCCESS;
}
