#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>

#define MAX_STRUCTS 10000
#define MEMORY_THRESHOLD 5 * 1024 * 1024 // 5 MB in bytes

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char* message) {
    FILE* log_file = fopen("allocation_errors.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        perror("Failed to open allocation_errors.log for logging.");
    }
}

int safe_atoi(const char* str, int* value) {
    char* end;
    errno = 0;
    *value = strtol(str, &end, 10);

    if (errno == ERANGE || (*end != '\0' && !isspace((unsigned char)*end))) {
        return -1; // Conversion error or non-numeric characters
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structures(const char* config_file, size_t* total_size) {
    FILE* file = fopen(config_file, "r");
    if (file == NULL) {
        perror("Failed to open crc_config.txt for reading.");
        return NULL;
    }

    int count;
    if (safe_atoi(fgets(buffer, sizeof(buffer), file), &count) != 0 || count < 1 || count > MAX_STRUCTS) {
        log_error("Invalid number of structures in crc_config.txt");
        fclose(file);
        return NULL;
    }

    size_t size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (size / count != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        // Handle integer overflow
        log_error("Integer overflow detected during memory allocation.");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(size);
    if (structures == NULL) {
        log_error("Memory allocation failed.");
        fclose(file);
        return NULL;
    }

    *total_size += size;

    if (*total_size > MEMORY_THRESHOLD) {
        printf("Warning: Memory usage exceeds threshold. Allocation halted.\n");
        free(structures);
        fclose(file);
        return NULL;
    }

    fclose(file);

    // Initialize structures with random values
    for (int i = 0; i < count; i++) {
        structures[i].RX_UE_INFORMATION_TAG = rand();
        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return structures;
}
