        }
        fclose(fp);
        return (int)count;
    }

    fprintf(stderr, "Failed to read image count from configuration file\n");
    fclose(fp);
    return -1;
}

IMAGE_DATA* allocate_image_memory(int image_count) {
    if (image_count <= 0 || image_count > MAX_IMAGE_COUNT) {
        fprintf(stderr, "Invalid image count: %d\n", image_count);
        return NULL;
    }

    IMAGE_DATA* images = (IMAGE_DATA*)malloc(image_count * sizeof(IMAGE_DATA));
    if (!images) {
        perror("Failed to allocate memory for image data");
        return NULL;
    }

    // Initialize each IMAGE_DATA structure
    for (int i = 0; i < image_count; i++) {
        images[i].WIDTH = 0;
        images[i].HEIGHT = 0;
        images[i].pixel_data = NULL;
    }

    return images;
}

void free_image_memory(IMAGE_DATA* images, int image_count) {
    if (!images || image_count <= 0) {
        fprintf(stderr, "Invalid input for freeing image memory\n");
        return;
    }

    // Free each pixel data
    for (int i = 0; i < image_count; i++) {
        free(images[i].pixel_data);
    }

    // Free the array of IMAGE_DATA structures
    free(images);
}

int main() {
    int image_count = parse_image_count(CONFIG_FILE_PATH);
    if (image_count == -1) {
        return EXIT_FAILURE;
    }

    IMAGE_DATA* images = allocate_image_memory(image_count);
    if (!images) {
        return EXIT_FAILURE;
    }

    // Use the allocated memory for storing image data

    free_image_memory(images, image_count);

    return EXIT_SUCCESS;
}
