#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    uint32_t RNTI;
    uint8_t CRC_ERROR_FLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *indication_list;
    size_t allocated_size;
    size_t used_count;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATOR_CONTEXT_T;

int populate_crc_indications(NFAPI_CRC_INDICATOR_CONTEXT_T *context, uint32_t rnti, int crc_error_flag, size_t max_structures) {
    pthread_mutex_lock(&context->mutex);

    if (max_structures > 0 && context->used_count + max_structures > context->allocated_size) {
        size_t new_size = context->allocated_size;
        while (new_size < context->used_count + max_structures) {
            new_size += 1024; // Increase in steps to avoid frequent reallocations
        }

        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(context->indication_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&context->mutex);
            return -1; // Memory allocation failed
        }

        context->indication_list = new_list;
        context->allocated_size = new_size;
    }

    if (context->used_count >= context->allocated_size) {
        pthread_mutex_unlock(&context->mutex);
        return -2; // Insufficient space for new structures
    }

    NFAPI_CRC_INDICATION_PDU_T *new_structure = &context->indication_list[context->used_count++];
    new_structure->RNTI = rnti;
    new_structure->CRC_ERROR_FLAG = crc_error_flag;

    pthread_mutex_unlock(&context->mutex);
    return 0; // Success
}

// Usage example:
int main() {
    NFAPI_CRC_INDICATOR_CONTEXT_T context = {NULL, 0, 0};
    if (pthread_mutex_init(&context.mutex, NULL) != 0) {
        // Handle error initializing mutex
    }

    // Populate the list with data from network interface
    if (populate_crc_indications(&context, 12345, 1, 10) == 0) {
        // Success
    } else {
        // Handle error
    }

    // Free allocated memory when done
    free(context.indication_list);
    pthread_mutex_destroy(&context.mutex);

    return 0;
}
```

