IMAGE_PROCESSING_CONTEXT* allocate_image_contexts(int N) {
    if (N < 1 || N > MAX_SIZE / sizeof(IMAGE_PROCESSING_CONTEXT)) {
        fprintf(stderr, "Invalid input. N must be between 1 and %d.\n", MAX_SIZE / sizeof(IMAGE_PROCESSING_CONTEXT));
        return NULL;
    }

    IMAGE_PROCESSING_CONTEXT* contexts = (IMAGE_PROCESSING_CONTEXT*)malloc(N * sizeof(IMAGE_PROCESSING_CONTEXT));
    if (contexts == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        contexts[i].header.width = rand() % 1024 + 1;
        contexts[i].header.height = rand() % 768 + 1;
        contexts[i].data = (unsigned char*)malloc(contexts[i].header.width * contexts[i].header.height);
        if (contexts[i].data == NULL) {
            fprintf(stderr, "Failed to allocate memory for image data.\n");
            // Clean up previously allocated structures
            for (int j = 0; j < i; j++) {
                free(contexts[j].data);
            }
            free(contexts);
            return NULL;
        }
        contexts[i].params.flag = rand() % 2;
    }

    return contexts;
}

void deallocate_image_contexts(IMAGE_PROCESSING_CONTEXT* contexts, int N) {
    for (int i = 0; i < N; i++) {
        free(contexts[i].data);
    }
    free(contexts);
