typedef struct {
    FrameHeader *headers;
    Payload *payloads;
    size_t num_frames;
    size_t payload_size_avg;
} DynamicFrameList;

DynamicFrameList* create_dynamic_frame_list(size_t initial_num_frames, size_t avg_payload_size) {
    if (initial_num_frames == 0 || avg_payload_size == 0) {
        return NULL; // Invalid input
    }

    // Calculate the total memory needed for headers and payloads
    size_t total_headers_size = sizeof(FrameHeader) * initial_num_frames;
    size_t total_payloads_size = sizeof(Payload) * initial_num_frames * avg_payload_size;

    // Check for integer overflow in total memory calculation
    if (total_headers_size / initial_num_frames != sizeof(FrameHeader) ||
        total_payloads_size / initial_num_frames / avg_payload_size != sizeof(Payload)) {
        return NULL; // Integer overflow detected
    }

    DynamicFrameList *list = (DynamicFrameList*)malloc(sizeof(DynamicFrameList));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    list->headers = (FrameHeader*)calloc(initial_num_frames, sizeof(FrameHeader));
    if (!list->headers) {
        free(list);
        return NULL; // Memory allocation failed for headers
    }

    list->payloads = (Payload*)calloc(total_payloads_size / avg_payload_size, sizeof(Payload));
    if (!list->payloads) {
        free(list->headers);
        free(list);
        return NULL; // Memory allocation failed for payloads
    }

    list->num_frames = initial_num_frames;
    list->payload_size_avg = avg_payload_size;

    return list;
}

void destroy_dynamic_frame_list(DynamicFrameList *list) {
    if (list) {
        free(list->headers);
        free(list->payloads);
        free(list);
    }
}
