#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

// Define a struct for a network header
typedef struct Header {
    int id;
    int length;
    char* data;
} Header;

// Define a struct for a packet
typedef struct Packet {
    int header_count;
    Header** headers;
} Packet;

// Function to calculate total size of headers in a packet
int calculate_total_header_size(Packet* packet) {
    if (packet->header_count > INT_MAX / sizeof(Header*)) return -1; // Check for integer overflow

    int total_size = packet->header_count * sizeof(Header*);
    for (int i = 0; i < packet->header_count; ++i) {
        Header* header = packet->headers[i];
        if (header->length > INT_MAX - total_size) return -1; // Check for integer overflow
        total_size += header->length;
    }

    return total_size;
}

// Function to process a stream of network packets
void process_packets(Packet** packets, int packet_count) {
    for (int i = 0; i < packet_count; ++i) {
        Packet* packet = packets[i];
        if (packet == NULL) continue;

        int total_size = calculate_total_header_size(packet);
        if (total_size < 0) {
            printf("Error: Integer overflow detected in packet %d\n", i);
            continue;
        }

        // Allocate memory for headers
        char* buffer = malloc(total_size);
        if (buffer == NULL) {
            printf("Error: Memory allocation failed for packet %d\n", i);
            continue;
        }

        // Parse and store headers
        char* ptr = buffer;
        for (int j = 0; j < packet->header_count; ++j) {
            Header* header = packet->headers[j];
            memcpy(ptr, &header->id, sizeof(header->id));
            ptr += sizeof(header->id);
            memcpy(ptr, &header->length, sizeof(header->length));
            ptr += sizeof(header->length);
            memcpy(ptr, header->data, header->length);
            ptr += header->length;
        }

        // Free allocated memory
        free(buffer);

        // Free individual headers
        for (int j = 0; j < packet->header_count; ++j) {
            Header* header = packet->headers[j];
            free(header->data);
            free(header);
        }
        free(packet->headers);
        free(packet);
    }

    free(packets);
}
