#include <atomic>
#include <mutex>
#include <condition_variable>

#define MAX_MEMORY 1024 * 1024 * 1024 // Example max memory limit in bytes

struct NFAPI_CRC_INDICATION_PDU_T {
    std::atomic<int> timestamp;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class MemoryManager {
private:
    size_t allocated_memory;
    std::mutex mutex;
    std::condition_variable cv;

public:
    MemoryManager() : allocated_memory(0) {}

    void* allocate(size_t size) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this]() { return allocated_memory + size <= MAX_MEMORY; });

        if (allocated_memory + size > MAX_MEMORY) {
            // Handle allocation failure gracefully
            printf("Memory allocation failed. Not enough memory available.\n");
            return nullptr;
        }

        void* ptr = malloc(size);
        if (ptr == nullptr) {
            printf("Failed to allocate memory.\n");
            return nullptr;
        }

        allocated_memory += size;
        return ptr;
    }

    void deallocate(void* ptr, size_t size) {
        std::lock_guard<std::mutex> lock(mutex);
        free(ptr);
        allocated_memory -= size;
        cv.notify_all();
    }
};

MemoryManager memory_manager;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(int N) {
    if (N <= 0) {
        printf("Invalid number of structures.\n");
        return nullptr;
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void* raw_memory = memory_manager.allocate(total_size);
    if (raw_memory == nullptr) {
        return nullptr;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(raw_memory);

    for (int i = 0; i < N; ++i) {
        array[i].timestamp.store(static_cast<int>(std::chrono::steady_clock::now().time_since_epoch().count()));
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example random value
        array[i].RNTI = rand() % 256; // Example random value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Example random value
    }

    return array;
}

void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array != nullptr && N > 0) {
        size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        memory_manager.deallocate(array, total_size);
    }
}
