    if (N <= 0 || MAX_MEMORY == 0 || rntiArray == NULL || rntiCount <= 0) {
        errno = EINVAL;
        return NULL;
    }

    // Filter and count valid RNTI values
    int validRntiCount = 0;
    for (int i = 0; i < rntiCount; ++i) {
        if (rntiArray[i] >= 0 && rntiArray[i] <= MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            validRntiCount++;
        }
    }

    if (N > validRntiCount || N * sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY) {
        errno = ENOMEM;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pduArray = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduArray == NULL) {
        errno = ENOMEM;
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0, rntiIndex = 0; i < N;) {
        if (rntiIndex >= validRntiCount) {
            free(pduArray);
            errno = EAGAIN; // No more valid RNTI values available
            return NULL;
        }
        int randomRNTI = rntiArray[rntiIndex];
        if (randomRNTI < 0 || randomRNTI > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            ++rntiIndex;
            continue;
