#include <stdio.h>
#include <stdlib.h>

#define MAX_PACKET_SIZE 1024

typedef struct Header {
    int field_id;
    char data[MAX_PACKET_SIZE];
    struct Header* next;
} Header;

Header* process_packet(const unsigned char* packet, size_t packet_size) {
    if (packet_size > MAX_PACKET_SIZE) {
        printf("Packet size exceeds maximum allowed.\n");
        return NULL;
    }

    Header* head = NULL;
    Header** last = &head;

    for (size_t i = 0; i < packet_size;) {
        int field_id = *(int*)&packet[i];
        size_t header_length = sizeof(int) + strlen((char*)&packet[i + sizeof(int)]) + 1;

        if (header_length > packet_size - i) {
            printf("Invalid header length detected.\n");
            break;
        }

        Header* new_header = malloc(sizeof(Header));
        if (new_header == NULL) {
            perror("Failed to allocate memory for header.");
            return head; // Return existing headers
        }

        new_header->field_id = field_id;
        strcpy(new_header->data, (char*)&packet[i + sizeof(int)]);
        new_header->next = NULL;

        *last = new_header;
        last = &new_header->next;

        i += header_length;
    }

    return head;
}

void free_headers(Header* head) {
    Header* current = head;
    while (current != NULL) {
        Header* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    // Example usage
    unsigned char packet[MAX_PACKET_SIZE] = {0};
    size_t packet_size = 10; // Example packet size

    // Populate packet with data...

    Header* headers = process_packet(packet, packet_size);

    if (headers != NULL) {
        // Process headers...
        free_headers(headers);
    }

    return 0;
}
