ImageMetadata* allocateImageMetadata(int maxImages, int width, int height, size_t initialFileSize) {
    if (maxImages <= 0 || width <= 0 || height <= 0 || initialFileSize == 0) {
        return NULL;
    }

    size_t totalMemoryNeeded = (size_t)maxImages * sizeof(ImageMetadata);
    if (totalMemoryNeeded / maxImages != sizeof(ImageMetadata)) {
        // Overflow check for total memory needed
        return NULL;
    }

    ImageMetadata* metadataArray = (ImageMetadata*)malloc(totalMemoryNeeded);
    if (!metadataArray) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < maxImages; ++i) {
        metadataArray[i].width = width;
        metadataArray[i].height = height;
        metadataArray[i].fileSize = initialFileSize;

        size_t imageDataSize = (size_t)width * (size_t)height;
        if (imageDataSize == 0 || imageDataSize / width != height) {
            // Overflow check for image data size
            free(metadataArray);
            return NULL;
        }

        metadataArray[i].imageData = (char*)malloc(imageDataSize);
        if (!metadataArray[i].imageData) {
            // Memory allocation failed for imageData
            for (int j = 0; j < i; ++j) {
                free(metadataArray[j].imageData);
            }
            free(metadataArray);
            return NULL;
        }

        // Initialize image data to zero or any default value
        memset(metadataArray[i].imageData, 0, imageDataSize);
    }

    return metadataArray;
}

void freeImageMetadata(ImageMetadata* metadataArray, int maxImages) {
    if (metadataArray != NULL) {
        for (int i = 0; i < maxImages; ++i) {
            free(metadataArray[i].imageData);
        }
        free(metadataArray);
    }
}
