#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IMAGE_WIDTH 1920
#define MAX_IMAGE_HEIGHT 1080
#define MEMORY_LIMIT 500 * 1024 * 1024 // 500MB

typedef struct ImageMetadata {
    char* filename;
    int width;
    int height;
    struct ImageMetadata* next;
} ImageMetadata;

ImageMetadata* create_image_metadata(const char* filename, int width, int height) {
    if (width > MAX_IMAGE_WIDTH || height > MAX_IMAGE_HEIGHT) return NULL; // Validate dimensions
    ImageMetadata* img = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (!img) return NULL; // Handle memory allocation failure gracefully

    img->filename = strdup(filename);
    img->width = width;
    img->height = height;
    img->next = NULL;

    return img;
}

void add_image_to_list(ImageMetadata** head, ImageMetadata* new_img) {
    if (*head == NULL) {
        *head = new_img;
    } else {
        ImageMetadata* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_img;
    }
}

ImageMetadata* process_directory(const char* directory, size_t* total_size) {
    DIR* dir = opendir(directory);
    if (!dir) return NULL; // Handle directory opening failure gracefully

    ImageMetadata* head = NULL;

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        const char* filename = entry->d_name;
        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, filename);

        // Simulate image processing
        int width = rand() % (MAX_IMAGE_WIDTH + 1);
        int height = rand() % (MAX_IMAGE_HEIGHT + 1);

        ImageMetadata* new_img = create_image_metadata(filename, width, height);
        if (!new_img) {
            closedir(dir);
            return NULL; // Handle memory allocation failure gracefully
        }

        *total_size += sizeof(ImageMetadata) + strlen(filename) + 1;
        if (*total_size > MEMORY_LIMIT) {
            free(new_img->filename);
            free(new_img);
            break; // Respect memory limit
        }

        add_image_to_list(&head, new_img);

        // Simulate large file scenario
        if (strlen(filename) == 500) break;
    }

    closedir(dir);
    return head;
}

void print_image_metadata(ImageMetadata* head) {
    ImageMetadata* temp = head;
    while (temp != NULL) {
        printf("File: %s, Width: %d, Height: %d\n", temp->filename, temp->width, temp->height);
        temp = temp->next;
    }
}

void free_image_metadata(ImageMetadata** head) {
    ImageMetadata* current;
    while (*head != NULL) {
        current = *head;
        *head = current->next;
        free(current->filename);
        free(current);
    }
}
