void processImageFiles(char** paths, int count) {
    ImageList imageList = {paths, NULL, (size_t)count};
    size_t totalSize = 0;

    // Calculate total memory requirement
    for (int i = 0; i < count; ++i) {
        struct stat fileStat;
        if (stat(paths[i], &fileStat) == -1) {
            perror("Failed to get file size");
            return;
        }
        totalSize += fileStat.st_size + sizeof(char*) + sizeof(size_t);
    }

    // Allocate memory for image sizes and paths
    imageList.fileSizes = (size_t*)malloc(totalSize);
    if (!imageList.fileSizes) {
        perror("Memory allocation failed");
        return;
    }

    void* ptr = (void*)(imageList.fileSizes + count);
    for (int i = 0; i < count; ++i) {
        imageList.filePaths[i] = (char*)ptr;
        strcpy(imageList.filePaths[i], paths[i]);
        ptr += strlen(paths[i]) + 1;

        struct stat fileStat;
        if (stat(imageList.filePaths[i], &fileStat) == -1) {
            perror("Failed to get file size");
            free(imageList.fileSizes);
            return;
        }
        imageList.fileSizes[i] = fileStat.st_size;
    }

    // Process images here
    printf("Total memory allocated: %zu bytes\n", totalSize);

    // Free allocated memory
    free(imageList.fileSizes);
}

int main() {
    char* filePaths[] = {"image1.bin", "image2.bin", "image3.bin"};
    processImageFiles(filePaths, 3);
    return 0;
