int read_config_file(const char* config_path, int* max_pdu_count) {
    FILE* file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char buffer[256];
    if (fgets(buffer, sizeof(buffer), file)) {
        *max_pdu_count = atoi(buffer);
        if (*max_pdu_count < 1 || *max_pdu_count > 100000) {
            fprintf(stderr, "Invalid max_pdu_count value: %d\n", *max_pdu_count);
            fclose(file);
            return -1;
        }
    } else {
        fprintf(stderr, "Configuration file is empty\n");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_array(int max_pdu_count) {
    if (max_pdu_count < 1 || max_pdu_count > 100000) {
        fprintf(stderr, "Invalid max_pdu_count value: %d\n", max_pdu_count);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_pdu_count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        perror("Failed to allocate memory for PDU array");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < max_pdu_count; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand();
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return pdu_array;
}

