#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <sys/stat.h>
#include <string.h>

typedef struct {
    char* filename;
    int width;
    int height;
    unsigned char* pixels;
} ImageMetadata;

ImageMetadata* process_images(const char* directory_path, int* num_files) {
    DIR* dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return NULL;
    }

    struct dirent* entry;
    ImageMetadata* images = NULL;
    *num_files = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) { // Regular file
            char filepath[1024];
            snprintf(filepath, sizeof(filepath), "%s/%s", directory_path, entry->d_name);

            struct stat file_stat;
            if (stat(filepath, &file_stat) != 0) {
                perror("Failed to get file statistics");
                closedir(dir);
                return NULL;
            }

            (*num_files)++;
            images = realloc(images, *num_files * sizeof(ImageMetadata));
            if (!images) {
                perror("Memory allocation failed");
                closedir(dir);
                return NULL;
            }

            images[*num_files - 1].filename = strdup(entry->d_name);
        }
    }

    closedir(dir);
    return images;
}

int main() {
    const char* directory_path = "/path/to/images";
    int num_files;

    ImageMetadata* images = process_images(directory_path, &num_files);
    if (!images) {
        printf("Failed to process images\n");
        return 1;
    }

    // Process images...

    for (int i = 0; i < num_files; i++) {
        free(images[i].filename);
        free(images[i].pixels);
    }
    free(images);

    return 0;
}
