#define MAX_LIST_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node_at_end(LinkedListNode** head, NFAPI_CRC_INDICATION_PDU_T data) {
    LinkedListNode* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        LinkedListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void free_list(LinkedListNode** head) {
    LinkedListNode* current = *head;
    while (current != NULL) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    int N = 1500; // Example input
    if (N < 0 || N > MAX_LIST_SIZE) {
        fprintf(stderr, "Invalid number of elements. Must be between 0 and %d.\n", MAX_LIST_SIZE);
        return EXIT_FAILURE;
    }

    LinkedListNode* head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T data = {i, rand() % 1024, rand() % 2}; // Random values
        insert_node_at_end(&head, data);
        pthread_mutex_unlock(&mutex);
    }

    free_list(&head);
    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}
