    if (dir == NULL) {
        perror("opendir");
        return NULL;
    }

    struct dirent* entry;
    size_t count = 0;
    ImageMetadata* metadata = NULL;

    while ((entry = readdir(dir)) != NULL) {
        // Check if the entry is a regular file and has an image extension
        const char* dot = strrchr(entry->d_name, '.');
        if (dot != NULL && (strcmp(dot + 1, "jpg") == 0 || strcmp(dot + 1, "jpeg") == 0 ||
                            strcmp(dot + 1, "png") == 0 || strcmp(dot + 1, "bmp") == 0)) {
            count++;
        }
    }

    closedir(dir);

    if (count == 0) {
        *num_images = 0;
        return NULL;
    }

    // Dynamically allocate memory for the metadata array
    metadata = malloc(count * sizeof(ImageMetadata));
    if (metadata == NULL) {
        perror("malloc");
        return NULL;
    }

    dir = opendir(directory_path);
