            // metadata[i].height = ...;
            // strcpy(metadata[i].format, "...");

            i++;
        }
    }

    closedir(dir);
    *num_images = count;

    return metadata;
}

int main() {
    size_t num_images = 0;
    ImageMetadata* metadata = process_directory("path/to/images", &num_images);

    if (metadata != NULL) {
        printf("Number of images: %zu\n", num_images);
        for (size_t i = 0; i < num_images; i++) {
            printf("Image %zu: %s, Width: %d, Height: %d, Format: %s\n",
                   i + 1, metadata[i].filename, metadata[i].width, metadata[i].height, metadata[i].format);
        }
        free(metadata);
    }

    return 0;
}
