typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* batch;
    size_t allocated_size;
    size_t used_size;
} BatchManager;

BatchManager* create_batch_manager(size_t initial_size, size_t max_batch_size) {
    BatchManager* manager = (BatchManager*)malloc(sizeof(BatchManager));
    if (!manager) {
        return NULL;
    }
    manager->batch = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->batch) {
        free(manager);
        return NULL;
    }
    manager->allocated_size = initial_size;
    manager->used_size = 0;
    return manager;
}

void destroy_batch_manager(BatchManager* manager) {
    if (manager) {
        free(manager->batch);
        free(manager);
    }
}

int add_pdu_to_batch(BatchManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu, size_t max_batch_size) {
    if (!manager || !manager->batch) {
        return -1;
    }

    if (manager->used_size >= manager->allocated_size) {
        size_t new_size = manager->allocated_size + max_batch_size;
        NFAPI_CRC_INDICATION_PDU_T* new_batch = realloc(manager->batch, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_batch) {
            return -1;
        }
        manager->batch = new_batch;
        manager->allocated_size = new_size;
    }

    manager->batch[manager->used_size++] = pdu;
    return 0;
}

void populate_random_pdus(BatchManager* manager, size_t max_batch_size) {
    if (!manager || !manager->batch) {
        return;
