// Define the structures for image_data_t and NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int length;
    char header[1024];
    char file_path[256];
} image_data_t;

typedef struct {
    // Define fields specific to NFAPI_CRC_INDICATION_PDU_T
    int pdu_length;
    char pdu_header[512];
    char pdu_file_path[256];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to process a dynamic list of binary data files
void process_files(char** file_paths, int num_files) {
    // Allocate memory for the array of structures
    image_data_t* image_data = (image_data_t*)malloc(num_files * sizeof(image_data_t));
    NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_files * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!image_data || !nfaapi_crc_data) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Process each file
    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", file_paths[i]);
            continue;
        }

        // Read metadata from the file header
        fread(&image_data[i].length, sizeof(int), 1, file);
        fread(image_data[i].header, sizeof(char), sizeof(image_data[i].header) - 1, file);
        image_data[i].file_path[0] = '\0';
        strncat(image_data[i].file_path, file_paths[i], sizeof(image_data[i].file_path) - 1);

        // Read metadata from the NFAPI CRC indication PDU
        fread(&nfaapi_crc_data[i].pdu_length, sizeof(int), 1, file);
        fread(nfaapi_crc_data[i].pdu_header, sizeof(char), sizeof(nfaapi_crc_data[i].pdu_header) - 1, file);
        nfaapi_crc_data[i].pdu_file_path[0] = '\0';
        strncat(nfaapi_crc_data[i].pdu_file_path, file_paths[i], sizeof(nfaapi_crc_data[i].pdu_file_path) - 1);

        fclose(file);
    }

    // Free allocated memory
    free(image_data);
    free(nfaapi_crc_data);
}

int main() {
    char* file_paths[] = {"file1.bin", "file2.bin", "file3.bin"};
    int num_files = sizeof(file_paths) / sizeof(file_paths[0]);

    process_files(file_paths, num_files);

    return 0;
}
```

