        offset += strlen(packets[i].payload) + 1;
    }

    // Assuming each packet metadata can be stored separately or in a different structure
    // For simplicity, let's assume the function only returns success

    // Free the combined memory when done processing
    free(combined_memory);

    return 0; // Success
