#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initializeAllocator();
void* allocateMemory(size_t size);
void deallocateMemory(void* ptr);

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)allocateMemory(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->count = 0;

    return list;
}

void destroyList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        deallocateMemory(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    deallocateMemory(list);
}

int insertNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->count >= MAX_NODES) return -1;

    Node* newNode = (Node*)allocateMemory(sizeof(Node));
    if (!newNode) return -2;

    newNode->data = data;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    list->count++;

    return 0;
}

int deleteNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI &&
            current->data.CRC_INDICATION_REL8_TAG == data.CRC_INDICATION_REL8_TAG) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            deallocateMemory(current);
            list->count--;
            return 0;
        }
        current = current->next;
    }
    return -1;
}

void traverseList(DoublyLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    Node* current = list->head;
    while (current) {
        pthread_mutex_lock(&list->lock);
        callback(current->data);
        pthread_mutex_unlock(&list->lock);
        current = current->next;
    }
}

