        log_error(sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    int supervisor_id = 123; // Replace with actual value
    rc = sqlite3_bind_int(stmt, 1, supervisor_id);
    if (rc != SQLITE_OK) {
        log_error(sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return 1;
    }

    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        printf("Name: %s, City: %s, Address: %s\n", 
               (char*)sqlite3_column_text(stmt, 0),
               (char*)sqlite3_column_text(stmt, 1),
               (char*)sqlite3_column_text(stmt, 2));
    }

    if (rc != SQLITE_DONE) {
        log_error(sqlite3_errmsg(db));
    }

