#define MAX_PACKET_SIZE 1500
#define POOL_SIZE 1024

typedef struct Packet {
    int size;
    char data[MAX_PACKET_SIZE];
    time_t timestamp;
    struct Packet *next;
} Packet;

typedef struct {
    Packet *head, *tail;
    pthread_mutex_t lock;
} PacketList;

typedef struct {
    size_t pool_size;
    size_t packet_size;
    Packet *pool;
    PacketList list;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t pool_size, size_t packet_size) {
    pool->pool_size = pool_size;
    pool->packet_size = packet_size;
    pool->pool = (Packet *)malloc(pool->pool_size * pool->packet_size);
    if (!pool->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&pool->list.lock, NULL);

    for (size_t i = 0; i < pool_size - 1; ++i) {
        pool->pool[i].next = &pool->pool[i + 1];
    }
    pool->pool[pool_size - 1].next = NULL;

    pool->list.head = pool->list.tail = NULL;
}

Packet *allocate_packet(MemoryPool *pool, const char *data, int size) {
    pthread_mutex_lock(&pool->list.lock);
    Packet *packet = pool->list.head;
    if (packet) {
        pool->list.head = packet->next;
        if (!pool->list.head) {
            pool->list.tail = NULL;
        }
    } else {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&pool->list.lock);
        return NULL;
    }

    memcpy(packet->data, data, size);
    packet->size = size;
    packet->timestamp = time(NULL);

    pthread_mutex_unlock(&pool->list.lock);
    return packet;
}

void free_packet(MemoryPool *pool, Packet *packet) {
    pthread_mutex_lock(&pool->list.lock);
    if (pool->list.tail) {
        pool->list.tail->next = packet;
    } else {
        pool->list.head = packet;
    }
    pool->list.tail = packet;
    packet->next = NULL;

    pthread_mutex_unlock(&pool->list.lock);
}

void process_packets(MemoryPool *pool, PacketList *output_list) {
    // Implement logic to reorder packets, discard old ones, and apply filters
    // Example:
    while (pool->list.head) {
        Packet *packet = pool->list.head;
        if (time(NULL) - packet->timestamp > 60) { // Discard old packets
            free_packet(pool, packet);
            continue;
        }
        // Apply filtering logic here

        // Add to output list for further processing
        packet->next = NULL;
        if (!output_list->head) {
            output_list->head = output_list->tail = packet;
        } else {
            output_list->tail->next = packet;
            output_list->tail = packet;
        }
    }
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, POOL_SIZE, sizeof(Packet));

    // Simulate receiving packets
    Packet *packet1 = allocate_packet(&pool, "Sample data 1", 15);
    Packet *packet2 = allocate_packet(&pool, "Sample data 2", 15);

    // Process packets
    PacketList output_list;
    process_packets(&pool, &output_list);

    // Free allocated memory
    free_packet(&pool, packet1);
    free_packet(&pool, packet2);

    pthread_mutex_destroy(&pool.list.lock);

