#include <stdlib.h>
#include <string.h>

typedef struct Packet {
    int metadata;
    char payload[];
} Packet;

typedef struct PacketQueue {
    size_t total_size;
    size_t used_size;
    Packet* packets;
} PacketQueue;

PacketQueue* create_packet_queue(size_t max_packets) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) return NULL;

    queue->total_size = 0;
    queue->used_size = 0;
    size_t required_size = sizeof(PacketQueue) + max_packets * sizeof(Packet);
    queue->packets = (Packet*)realloc(queue, required_size);
    if (!queue->packets) {
        free(queue);
        return NULL;
    }
    return queue;
}

int enqueue_packet(PacketQueue* queue, Packet* packet, size_t payload_size) {
    if (queue->used_size >= queue->total_size / sizeof(Packet)) {
        // Handle overflow or reallocation
        return -1; // Error: Queue is full
    }

    size_t packet_size = sizeof(Packet) + payload_size;
    memcpy((char*)queue->packets + queue->used_size * sizeof(Packet), packet, packet_size);
    queue->used_size++;
    return 0;
}

Packet* dequeue_packet(PacketQueue* queue) {
    if (queue->used_size == 0) {
        return NULL; // Queue is empty
    }

    Packet* packet = (Packet*)((char*)queue->packets + queue->used_size * sizeof(Packet));
    queue->used_size--;
    return packet;
}

void free_packet_queue(PacketQueue* queue) {
    free(queue->packets);
    free(queue);
}
