    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (pool != NULL) {
        pool->memory = malloc(size);
        if (pool->memory == NULL) {
            free(pool);
            return NULL;
        }
        pool->size = size;
        pool->block_size = block_size;
        pool->num_blocks = size / block_size;
        pool->free_index = 0;
        pthread_mutex_init(&pool->lock, NULL);
    }
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool) {
    void *block;
    pthread_mutex_lock(&pool->lock);
    if (pool->free_index < pool->num_blocks) {
        block = (char *)pool->memory + pool->free_index++ * pool->block_size;
    } else {
        block = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void memory_pool_free(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    if ((char *)block >= (char *)pool->memory && (char *)block < (char *)pool->memory + pool->size) {
        size_t index = (char *)block - (char *)pool->memory / pool->block_size;
        if (index < pool->free_index) {
            pool->free_index = index;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

