typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_doubly_linked_list(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle allocation failure
        return NULL;
    }
    new_node->data = *data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_node(DoublyLinkedList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        // Handle allocation failure
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    free(node);
    pthread_mutex_unlock(&list->lock);
}

void traverse_list(const DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG);
        current = current->next;
    }
}

void validate_list(const DoublyLinkedList* list) {
