#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint32_t packet_id;
    uint64_t timestamp;
    // Additional frame metadata here
} FrameData;

typedef struct FrameNode {
    FrameData frame;
    struct FrameNode* next;
} FrameNode;

typedef struct {
    FrameNode* head;
    FrameNode* tail;
} FrameList;

FrameList* process_packets(uint32_t packet_id, uint64_t timestamp, size_t num_frames) {
    if (num_frames == 0 || packet_id == 0 || timestamp == 0) {
        return NULL; // Input validation
    }

    FrameList* frame_list = (FrameList*)malloc(sizeof(FrameList));
    if (!frame_list) {
        return NULL; // Memory allocation failure
    }
    frame_list->head = NULL;
    frame_list->tail = NULL;

    for (size_t i = 0; i < num_frames; ++i) {
        FrameNode* new_node = (FrameNode*)malloc(sizeof(FrameNode));
        if (!new_node) {
            // Handle memory allocation failure
            free_frame_list(frame_list);
            return NULL;
        }

        // Initialize frame data
        new_node->frame.packet_id = packet_id;
        new_node->frame.timestamp = timestamp;
        // Initialize other frame metadata here

        new_node->next = NULL;

        if (frame_list->head == NULL) {
            frame_list->head = new_node;
            frame_list->tail = new_node;
        } else {
            frame_list->tail->next = new_node;
            frame_list->tail = new_node;
        }
    }

    return frame_list;
}

void free_frame_list(FrameList* frame_list) {
    FrameNode* current = frame_list->head;
    while (current != NULL) {
        FrameNode* next = current->next;
        free(current);
        current = next;
    }
    free(frame_list);
}
