// Companion function for processing network packets
typedef struct PacketBuffer {
    uint8_t* data;
    size_t size;
    size_t capacity;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_capacity) {
    PacketBuffer* buffer = (PacketBuffer*)malloc(sizeof(PacketBuffer));
    if (buffer == NULL) {
        perror("Failed to allocate memory for packet buffer");
        return NULL;
    }
    buffer->data = (uint8_t*)malloc(initial_capacity);
    if (buffer->data == NULL) {
        free(buffer);
        perror("Failed to allocate initial data for packet buffer");
        return NULL;
    }
    buffer->size = 0;
    buffer->capacity = initial_capacity;
    return buffer;
}

void resize_packet_buffer(PacketBuffer* buffer, size_t new_capacity) {
    uint8_t* new_data = (uint8_t*)realloc(buffer->data, new_capacity);
    if (new_data == NULL) {
        perror("Failed to reallocate memory for packet buffer");
        // Handle error, possibly by freeing the old data and exiting
        free(buffer->data);
        return;
    }
    buffer->data = new_data;
    buffer->capacity = new_capacity;
}

void process_network_packet(PacketBuffer* buffer, const uint8_t* packet_data, size_t packet_size) {
    if (buffer->size + packet_size > buffer->capacity) {
        resize_packet_buffer(buffer, buffer->capacity * 2);
    }
    memcpy(buffer->data + buffer->size, packet_data, packet_size);
    buffer->size += packet_size;
}

void free_packet_buffer(PacketBuffer* buffer) {
    if (buffer != NULL) {
        free(buffer->data);
        free(buffer);
    }
}
