#include "memory_budget.h"
#include "logging_system.h"

typedef struct {
    uint32_t header_size;
    uint8_t *payload;
} PacketHeader;

int process_packets(Packet *incoming_packets, int packet_count, PacketHeader **headers, size_t budget) {
    MemoryBudget *budget_manager = get_memory_budget();
    LogSystem *logger = get_logging_system();

    size_t total_payload_size = 0;
    for (int i = 0; i < packet_count; ++i) {
        total_payload_size += incoming_packets[i].payload_size;
    }

    if (total_payload_size > budget) {
        log_error(logger, "Exceeded memory budget by %zu bytes", total_payload_size - budget);
        return MEMORY_BUDGET_EXCEEDED;
    }

    size_t headers_size = packet_count * sizeof(PacketHeader);
    void *memory_block = allocate_memory(headers_size + total_payload_size);
    if (!memory_block) {
        log_error(logger, "Failed to allocate memory");
        return MEMORY_ALLOCATION_FAILED;
    }

    *headers = (PacketHeader *)memory_block;

    uint8_t *payloads_start = (uint8_t *)(*headers) + headers_size;

    for (int i = 0; i < packet_count; ++i) {
        (*headers)[i].header_size = incoming_packets[i].header_size;
        (*headers)[i].payload = payloads_start + i * incoming_packets[i].payload_size;
        memcpy((*headers)[i].payload, incoming_packets[i].payload, incoming_packets[i].payload_size);
    }

    log_info(logger, "Successfully processed %d packets", packet_count);

    return SUCCESS;
}
```

