#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PAYLOAD_SIZE 1024
#define TOTAL_MEMORY_LIMIT (1024 * 1024 * 5) // 5MB

typedef struct Payload {
    int size;
    char data[MAX_PAYLOAD_SIZE];
} Payload;

typedef struct Packet {
    Payload** payloads;
    int payload_count;
} Packet;

typedef struct ProcessingContext {
    pthread_mutex_t memory_lock;
    size_t current_allocated_size;
} ProcessingContext;

int validate_payload_size(int size) {
    return (size >= 0 && size <= MAX_PAYLOAD_SIZE);
}

void* process_packet(void* arg) {
    Packet* packet = (Packet*)arg;
    ProcessingContext* context = (ProcessingContext*)&packet->payloads[0][0]; // Assuming memory layout

    pthread_mutex_lock(&context->memory_lock);

    for (int i = 0; i < packet->payload_count; i++) {
        Payload* payload = packet->payloads[i];
        if (!validate_payload_size(payload->size)) {
            fprintf(stderr, "Payload size validation failed\n");
            pthread_mutex_unlock(&context->memory_lock);
            return NULL;
        }

        // Simulate processing logic
        printf("Processing payload of size %d\n", payload->size);

        // Allocate memory for payload if not already allocated
        if (payload->data == NULL) {
            payload->data = malloc(payload->size);
            if (payload->data == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                pthread_mutex_unlock(&context->memory_lock);
                return NULL;
            }

            // Update total allocated size
            context->current_allocated_size += payload->size;

            // Check memory limit
            if (context->current_allocated_size > TOTAL_MEMORY_LIMIT) {
                fprintf(stderr, "Memory limit exceeded\n");
                free(payload->data);
                payload->data = NULL;
                pthread_mutex_unlock(&context->memory_lock);
                return NULL;
            }
        }
    }

    pthread_mutex_unlock(&context->memory_lock);
    return NULL;
}

int main() {
    Packet packet;
    Payload payloads[10];
    ProcessingContext context;

    // Initialize structures
    for (int i = 0; i < 10; i++) {
        payloads[i].size = i * 100 + 50; // Example payload sizes
        payloads[i].data = NULL;
    }
    packet.payloads = payloads;
    packet.payload_count = 10;

    context.current_allocated_size = 0;
    pthread_mutex_init(&context.memory_lock, NULL);

    // Simulate processing multiple packets concurrently
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, process_packet, &packet);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < packet.payload_count; i++) {
        if (packet.payloads[i].data != NULL) {
            free(packet.payloads[i].data);
        }
    }

    pthread_mutex_destroy(&context.memory_lock);
    return 0;
}
