ImageMetadataArray* create_image_metadata_array(size_t initialCapacity, size_t memoryLimit) {
    ImageMetadataArray *array = (ImageMetadataArray*)malloc(sizeof(ImageMetadataArray));
    array->entries = (ImageMetaData**)malloc(initialCapacity * sizeof(ImageMetaData*));
    array->count = 0;
    array->capacity = initialCapacity;
    array->memoryLimit = memoryLimit;
    return array;
