    for (size_t i = 0; i < array->count; ++i) {
        free(array->entries[i]->path);
        free(array->entries[i]);
    }
    free(array->entries);
    free(array);
}

int add_image_metadata_entry(ImageMetadataArray *array, const char *filePath, size_t reportedSize, void *content) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity == 0 ? 1 : array->capacity * 2;
        ImageMetaData** newEntries = (ImageMetaData**)realloc(array->entries, newCapacity * sizeof(ImageMetaData*));
        if (newEntries == NULL) return -1; // Memory allocation failed
        array->entries = newEntries;
        array->capacity = newCapacity;
    }

    ImageMetaData *entry = (ImageMetaData*)malloc(sizeof(ImageMetaData));
    entry->path = strdup(filePath);
    entry->reportedSize = reportedSize;
    entry->content = content;

    array->entries[array->count++] = entry;

    return 0; // Success
}

