typedef struct {
    int memory_budget;
    int payload_limit;
    int current_memory_usage;
    pthread_mutex_t lock;
} MemoryBudget;

MemoryBudget budget;

void init_memory_budget(int initial_budget, int payload_limit) {
    budget.memory_budget = initial_budget;
    budget.payload_limit = payload_limit;
    budget.current_memory_usage = 0;
    pthread_mutex_init(&budget.lock, NULL);
}

int allocate_memory_for_payload(int size) {
    pthread_mutex_lock(&budget.lock);
    if (budget.current_memory_usage + size > budget.memory_budget) {
        printf("Memory allocation failed: Exceeds memory budget\n");
        pthread_mutex_unlock(&budget.lock);
        return -1;
    }
    budget.current_memory_usage += size;
    pthread_mutex_unlock(&budget.lock);
    return 0;
}

void free_memory_for_payload(int size) {
    pthread_mutex_lock(&budget.lock);
    budget.current_memory_usage -= size;
    pthread_mutex_unlock(&budget.lock);
}

int process_packet(Packet *packet, MemoryBudget *budget) {
    if (allocate_memory_for_payload(packet->header_size + packet->data[0]) != 0) {
        return -1;
    }

    // Process the packet
    printf("Processing packet with header size %d and payload size %d\n", packet->header_size, packet->data[0]);

    free_memory_for_payload(packet->header_size + packet->data[0]);
    return 0;
}

