typedef struct PacketHeader {
    int payloadSize;
    char *payload;
    struct PacketHeader *next;
} PacketHeader;

typedef struct MemoryPool {
    size_t blockSize;
    size_t poolSize;
    char *pool;
    char *freeBlock;
} MemoryPool;

PacketHeader* allocatePacket(MemoryPool *pool, int payloadSize) {
    if (pool->freeBlock + sizeof(PacketHeader) + payloadSize > pool->pool + pool->poolSize) {
        return NULL; // No more memory in the pool
    }
    PacketHeader *header = (PacketHeader *)pool->freeBlock;
    header->payloadSize = payloadSize;
    header->payload = (char *)(pool->freeBlock + sizeof(PacketHeader));
    header->next = NULL;

    pool->freeBlock += sizeof(PacketHeader) + payloadSize;
    return header;
}

void freePacket(MemoryPool *pool, PacketHeader *header) {
    // Simulate freeing by marking it as unused
    // In a real scenario, this would involve linking the block back to a free list
}

int fetchMetadataFromSource(int packetID, char **metadata) {
    // Simulated metadata fetching function
    *metadata = (char *)malloc(100); // Assume metadata is up to 100 characters
    snprintf(*metadata, 100, "Metadata for packet %d", packetID);
    return (*metadata == NULL) ? -1 : 0;
}

PacketHeader* processPackets(int *packetIDs, int numPackets, MemoryPool *pool, size_t memoryLimit) {
    PacketHeader *head = NULL;
    PacketHeader **tail = &head;

    for (int i = 0; i < numPackets; ++i) {
        char *metadata;
        if (fetchMetadataFromSource(packetIDs[i], &metadata) != 0) {
            fprintf(stderr, "Failed to fetch metadata for packet %d\n", packetIDs[i]);
            continue; // Skip this packet
        }

        int payloadSize = strlen(metadata);
        PacketHeader *newPacket = allocatePacket(pool, payloadSize);
        if (newPacket == NULL) {
            fprintf(stderr, "Memory limit exceeded while processing packet %d\n", packetIDs[i]);
            free(metadata); // Free the metadata as it's not used
            break; // Stop processing further packets
        }

        strcpy(newPacket->payload, metadata);
        free(metadata);

        *tail = newPacket;
        tail = &newPacket->next;

        if (pool->freeBlock - pool->pool > memoryLimit) {
            fprintf(stderr, "Memory limit reached after processing packet %d\n", packetIDs[i]);
            break; // Stop processing further packets
        }
    }

    *tail = NULL; // Null-terminate the list
    return head;
}

void freePacketList(PacketHeader *head) {
    while (head != NULL) {
        PacketHeader *next = head->next;
        free(head->payload);
        free(head);
        head = next;
    }
}

int main() {
    MemoryPool pool = {1024, 4096, (char *)malloc(4096), (char *)malloc(4096)};
    int packetIDs[] = {1, 2, 3};
    int numPackets = sizeof(packetIDs) / sizeof(packetIDs[0]);

    PacketHeader *packetList = processPackets(packetIDs, numPackets, &pool, pool.poolSize);

    freePacketList(packetList);
    free(pool.pool);

    return 0;
}
```

