        size_t pixel_data_size = (*images)[i].metadata.width * (*images)[i].metadata.height;
        if (pixel_data_size / (*images)[i].metadata.width != (*images)[i].metadata.height) {
            free(*images);
            return -4; // Integer overflow protection
