#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_PACKETS 10000
#define MAX_PAYLOAD_SIZE 128 * 1024 // 128 KB
#define BUFFER_SIZE 16 * 1024 * 1024 // 16 MB

typedef struct Packet {
    size_t payload_size;
    char* payload;
} Packet;

typedef struct BufferPool {
    Packet packets[MAX_PACKETS];
    int used_packets;
} BufferPool;

BufferPool buffer_pool = {0};

void initialize_buffer_pool() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        buffer_pool.packets[i].payload = NULL;
    }
}

void free_packet_payload(Packet* packet) {
    if (packet->payload != NULL) {
        free(packet->payload);
        packet->payload = NULL;
    }
}

Packet* allocate_packet(size_t payload_size) {
    if (buffer_pool.used_packets >= MAX_PACKETS) {
        return NULL; // Buffer pool is full
    }

    Packet* packet = &buffer_pool.packets[buffer_pool.used_packets];
    buffer_pool.used_packets++;

    if (payload_size > 0 && payload_size <= MAX_PAYLOAD_SIZE) {
        packet->payload = malloc(payload_size);
        if (packet->payload == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
        packet->payload_size = payload_size;
    } else {
        packet->payload = NULL;
        packet->payload_size = 0;
    }

    return packet;
}

void free_packet(Packet* packet) {
    if (packet != NULL && packet >= buffer_pool.packets && packet < &buffer_pool.packets[MAX_PACKETS]) {
        free_packet_payload(packet);
        // Optionally, reset the packet structure for reuse
        packet->payload = NULL;
        packet->payload_size = 0;
    }
}

int main() {
    initialize_buffer_pool();

    // Example usage:
    Packet* packet1 = allocate_packet(512 * 1024); // 512 KB payload
    if (packet1 != NULL) {
        // Process the packet
        free_packet(packet1);
    }

    return 0;
}
```

