// Define packet and frame structures
typedef struct {
    int num_frames;
    void **frames;  // Pointer array for frames
} Packet;

typedef struct {
    // Frame data members
    char *data;
    size_t size;
} Frame;

// Function to allocate memory for a new packet with 'num_frames' frames
Packet* create_packet(int num_frames) {
    if (num_frames <= 0) return NULL;

    Packet *packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->num_frames = num_frames;

    // Allocate memory for frame pointers
    packet->frames = (void**)calloc(num_frames, sizeof(void*));
    if (!packet->frames) {
        free(packet);
        return NULL;
    }

    // Initialize frames with default values or allocate them as needed
    for (int i = 0; i < num_frames; i++) {
        Frame *frame = (Frame*)malloc(sizeof(Frame));
        if (!frame) {
            // Handle memory allocation failure gracefully
            free_packet(packet);
            return NULL;
        }
        frame->data = NULL;
        frame->size = 0;
        packet->frames[i] = frame;
    }

    return packet;
}

// Function to free the allocated memory for a packet and its frames
void free_packet(Packet *packet) {
    if (!packet) return;

    // Free each frame's data
    for (int i = 0; i < packet->num_frames; i++) {
        Frame *frame = (Frame*)packet->frames[i];
        if (frame) {
            free(frame->data);
            free(frame);
        }
    }

    // Free the array of frame pointers and then the packet itself
    free(packet->frames);
    free(packet);
}

// Example usage
int main() {
    Packet *my_packet = create_packet(5);
    if (my_packet) {
        // Process packet...

        // Clean up memory when done
        free_packet(my_packet);
    }

    return 0;
}
