        if (!file) {
            continue;
        }

        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (total_memory_used + size > max_memory_bytes) {
            fclose(file);
            break;
        }

        ImageMetadata* img = &images[*num_loaded];
        strcpy(img->filename, file_paths[i]);

        // Simulate reading image dimensions
        fread(&img->width, sizeof(int), 1, file);
        fread(&img->height, sizeof(int), 1, file);

        // Allocate memory for image data
        img->data = (unsigned char*)malloc(size - sizeof(int) * 2);
        if (!img->data) {
            fclose(file);
            free(images);
            return NULL;
        }

        // Simulate loading image data
        fread(img->data, 1, size - sizeof(int) * 2, file);

        fclose(file);
        total_memory_used += size;
        (*num_loaded)++;
    }

    printf("Total memory used: %zu bytes\n", total_memory_used);
