typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t total_size;
    pthread_mutex_t lock;
} LinkedList;

void populateNfapiIndications(LinkedList* list, int max_entries, size_t max_size) {
    if (list == NULL || max_entries <= 0 || max_size == 0) {
        return; // Invalid input parameters
    }

    pthread_mutex_lock(&list->lock);

    while (list->total_size < max_size && list->head != NULL) {
        Node* current = list->head;
        NFAPI_CRC_INDICATION_PDU_T data;

        // Fetch data from external service
        if (!fetchDataFromService(&data)) {
            pthread_mutex_unlock(&list->lock);
            return; // Failed to fetch data, exit function
        }

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            logAllocationFailure();
            pthread_mutex_unlock(&list->lock);
            return; // Memory allocation failed
        }

        newNode->data = data;
        newNode->next = current->next;
        list->head = newNode;

        list->total_size += sizeof(Node);

        if (list->total_size >= max_size) {
            break; // Reached maximum size, stop adding more nodes
        }
    }

    pthread_mutex_unlock(&list->lock);
}

