NFAPI_CRC_INDICATION_PDU_T* create_NFAPI_CRC_INDICATION_PDU(int N, int* success_count, int* error_count) {
    if (N <= 0 || N > MAX_UE_INSTANCES) {
        fprintf(stderr, "Invalid number of UE instances: %d\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation failed");
        *error_count += 1;
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Initialize your structure fields here
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1024;
        pdu_list[i].RNTI = rand() % 16384;
        pdu_list[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;

        *success_count += 1;
    }

    return pdu_list;
}

void* concurrent_task(void* arg) {
    int N = *(int*)arg;
    int success_count = 0, error_count = 0;

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_NFAPI_CRC_INDICATION_PDU(N, &success_count, &error_count);
    if (!pdu_list) {
        printf("Concurrent task failed to allocate memory\n");
    } else {
        // Process the pdu_list here
        free(pdu_list);
    }

    printf("Concurrent task completed: Successes=%d, Errors=%d\n", success_count, error_count);

    return NULL;
}

int main() {
    pthread_t threads[MAX_UE_INSTANCES];
    int N = 5; // Number of UE instances for concurrent processing

    if (N > MAX_UE_INSTANCES) {
        fprintf(stderr, "Too many UE instances requested: %d\n", N);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, concurrent_task, &N);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
