Image* allocate_image_memory(char *metadata_file) {
    long estimated_size;
    int image_count = calculate_image_count(metadata_file, &estimated_size);

    if (image_count <= 0 || estimated_size <= 0) {
        return NULL;
    }

    // Allocate memory considering alignment requirements and system-specific constraints
    size_t aligned_size = ((estimated_size + sizeof(void*) - 1) / sizeof(void*)) * sizeof(void*);
    Image *images = aligned_alloc(sizeof(Image), aligned_size);

    if (!images) {
        perror("Failed to allocate memory for images");
        return NULL;
    }

    return images;
}

// Example usage
int main() {
    char metadata_file[] = "image_metadata.txt";
    Image *images = allocate_image_memory(metadata_file);

    if (images) {
        // Use the allocated images array
        free(images); // Don't forget to free memory when done
    }

    return 0;
}
