#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_PACKET_SIZE 1500
#define PAYLOAD_HEADER_SIZE 24

typedef struct {
    uint64_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    size_t packet_data_size;
    void* payload_header;
} PacketMetadata;

typedef struct Node {
    PacketMetadata metadata;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    size_t total_memory_used;
} PacketList;

void init_packet_list(PacketList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->total_memory_used = 0;
}

Node* create_node(const PacketMetadata* metadata) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) return NULL;

    node->metadata = *metadata;
    node->next = NULL;

    // Allocate memory for packet data
    node->metadata.packet_data_size = metadata->packet_data_size;
    node->metadata.payload_header = malloc(PAYLOAD_HEADER_SIZE);
    if (node->metadata.payload_header == NULL) {
        free(node);
        return NULL;
    }

    return node;
}

void add_packet(PacketList* list, const PacketMetadata* metadata) {
    Node* new_node = create_node(metadata);
    if (new_node == NULL) return;

    // Update total memory used
    list->total_memory_used += sizeof(Node) + metadata->packet_data_size + PAYLOAD_HEADER_SIZE;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
}

void process_packet_list(PacketList* list, void (*process_func)(const PacketMetadata*)) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;

        // Process each packet
        process_func(&current->metadata);

        // Free the node and its allocated memory
        free(current->metadata.payload_header);
        free(current);

        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->total_memory_used = 0;
}

void destroy_packet_list(PacketList* list) {
    process_packet_list(list, NULL);
}
