#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define MAX_BUFFER_SIZE 1024 * 1024
#define CACHE_SIZE 50

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t buffer_size;
    size_t count;
    pthread_mutex_t lock;
} NFAPICRCManager;

NFAPICRCManager crc_manager = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_crc_manager(size_t initial_size) {
    if (initial_size > MAX_BUFFER_SIZE || initial_size == 0) {
        fprintf(stderr, "Invalid initial size\n");
        exit(EXIT_FAILURE);
    }
    crc_manager.buffer_size = initial_size;
    crc_manager.count = 0;
    crc_manager.buffer = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_manager.buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void* allocate_crc_pdu(void *arg) {
    pthread_mutex_lock(&crc_manager.lock);
    if (crc_manager.count >= crc_manager.buffer_size) {
        size_t new_size = crc_manager.buffer_size + MAX_STRUCTS;
        if (new_size > MAX_BUFFER_SIZE) {
            pthread_mutex_unlock(&crc_manager.lock);
            fprintf(stderr, "Buffer size exceeded limit\n");
            return NULL;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_buffer = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_manager.buffer, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_buffer) {
            pthread_mutex_unlock(&crc_manager.lock);
            fprintf(stderr, "Memory reallocation failed\n");
            return NULL;
        }
        crc_manager.buffer = new_buffer;
        crc_manager.buffer_size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &crc_manager.buffer[crc_manager.count++];
    new_pdu->RX_UE_INFORMATION_TAG = (uint8_t)(rand() % 256);
    new_pdu->RNTI = (uint16_t)(rand() % 65536);
    new_pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
    new_pdu->CRCFLAG = (uint8_t)(rand() % 2);
    pthread_mutex_unlock(&crc_manager.lock);
    return new_pdu;
}

void log_buffer_resize(size_t old_size, size_t new_size) {
    printf("Buffer resized from %zu to %zu\n", old_size, new_size);
}

int main() {
    init_crc_manager(100); // Initialize with 100 structures
    for (size_t i = 0; i < MAX_STRUCTS; ++i) {
        allocate_crc_pdu(NULL);
    }
    return 0;
}
