#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PAYLOAD_SIZE 1024
#define CHECKSUM_SIZE sizeof(unsigned int)
#define BUFFER_REALLOCATION_FACTOR 2

typedef struct {
    unsigned char *payload;
    size_t payload_size;
} NetworkPacket;

typedef struct {
    unsigned char *buffer;
    size_t buffer_size;
    size_t used_space;
} Buffer;

unsigned int calculate_checksum(const unsigned char *data, size_t size) {
    // Simple checksum calculation for demonstration purposes
    unsigned int sum = 0;
    for (size_t i = 0; i < size; ++i) {
        sum += data[i];
    }
    return sum;
}

int verify_checksum(const NetworkPacket *packet, unsigned int expected_checksum) {
    unsigned int actual_checksum = calculate_checksum(packet->payload, packet->payload_size);
    return actual_checksum == expected_checksum;
}

int store_packet(Buffer *buffer, const NetworkPacket *packet) {
    if (buffer->used_space + packet->payload_size + CHECKSUM_SIZE > buffer->buffer_size) {
        size_t new_size = buffer->buffer_size * BUFFER_REALLOCATION_FACTOR;
        if (new_size < buffer->used_space + packet->payload_size + CHECKSUM_SIZE) {
            return -1; // Integer overflow or insufficient space
        }
        unsigned char *new_buffer = realloc(buffer->buffer, new_size);
        if (!new_buffer) {
            return -2; // Memory allocation failed
        }
        buffer->buffer = new_buffer;
        buffer->buffer_size = new_size;
    }

    memcpy(buffer->buffer + buffer->used_space, packet->payload, packet->payload_size);
    unsigned int checksum = calculate_checksum(packet->payload, packet->payload_size);
    memcpy(buffer->buffer + buffer->used_space + packet->payload_size, &checksum, CHECKSUM_SIZE);
    buffer->used_space += packet->payload_size + CHECKSUM_SIZE;

    return 0; // Success
}

void initialize_buffer(Buffer *buffer) {
    buffer->buffer = NULL;
    buffer->buffer_size = 0;
    buffer->used_space = 0;
}

void free_buffer(Buffer *buffer) {
    free(buffer->buffer);
    buffer->buffer = NULL;
    buffer->buffer_size = 0;
    buffer->used_space = 0;
}

// Example usage
int main() {
    Buffer buffer;
    initialize_buffer(&buffer);

    NetworkPacket packet1 = { .payload = (unsigned char *)"Hello", .payload_size = 5 };
    NetworkPacket packet2 = { .payload = (unsigned char *)"World!", .payload_size = 6 };

    store_packet(&buffer, &packet1);
    store_packet(&buffer, &packet2);

    printf("Buffer used space: %zu\n", buffer.used_space);

    free_buffer(&buffer);
    return 0;
}
