#define MAX_NAME_LEN 100
#define MAX_EMAIL_LEN 200
#define MAX_PASSWORD_LEN 100

typedef struct {
    char id[MAX_ID_LEN];
    char name[MAX_NAME_LEN];
    char email[MAX_EMAIL_LEN];
    char password[MAX_PASSWORD_LEN];
} UserAccount;

typedef enum {
    CREATE,
    UPDATE,
    DELETE
} SubAction;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure as per your requirements
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* userAccounts[MAX_STRUCTS];
int currentCount = 0;

int Validate(const char* id, const char* name, const char* email, const char* password, SubAction subAction) {
    // Implement validation logic here
    if (subAction == DELETE && (id == NULL || strlen(id) > MAX_ID_LEN)) return -1;
    if (strlen(name) > MAX_NAME_LEN || strlen(email) > MAX_EMAIL_LEN || strlen(password) > MAX_PASSWORD_LEN) return -1;
    return 0;
}

void Save(const NFAPI_CRC_INDICATION_PDU_T* account, SubAction subAction) {
    // Implement save logic here
    if (subAction == CREATE) {
        userAccounts[currentCount++] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(userAccounts[currentCount - 1], account, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else if (subAction == UPDATE) {
        for (int i = 0; i < currentCount; i++) {
            if (strcmp(((NFAPI_CRC_INDICATION_PDU_T*)userAccounts[i])->id, account->id) == 0) {
                memcpy(userAccounts[i], account, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                break;
            }
        }
    } else if (subAction == DELETE) {
        for (int i = 0; i < currentCount; i++) {
            if (strcmp(((NFAPI_CRC_INDICATION_PDU_T*)userAccounts[i])->id, account->id) == 0) {
                free(userAccounts[i]);
                for (int j = i; j < currentCount - 1; j++) {
                    userAccounts[j] = userAccounts[j + 1];
                }
                currentCount--;
                break;
            }
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* Get(const char* id) {
    // Implement get logic here
    for (int i = 0; i < currentCount; i++) {
        if (strcmp(((NFAPI_CRC_INDICATION_PDU_T*)userAccounts[i])->id, id) == 0) {
            return userAccounts[i];
        }
    }
    return NULL;
}

void create_or_update_user_account(const char* id, const char* name, const char* email, const char* password, SubAction subAction) {
    NFAPI_CRC_INDICATION_PDU_T account;
    strcpy(account.id, id);
    strcpy(account.name, name);
    strcpy(account.email, email);
    strcpy(account.password, password);

    if (Validate(id, name, email, password, subAction) != 0) {
        printf("Validation failed.\n");
        return;
    }

    Save(&account, subAction);

    printf("Operation successful.\n");
}
