typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} RX_UE_INFORMATION;

typedef struct {
    RX_UE_INFORMATION rx_ue_information;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(int N, size_t MAX_BUFFER_SIZE, size_t MAX_MEMORY_USAGE, unsigned int seed) {
    if (N <= 0 || MAX_BUFFER_SIZE <= 0 || MAX_MEMORY_USAGE <= 0) return NULL;

    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_memory_required = N * struct_size;

    if (total_memory_required > MAX_MEMORY_USAGE) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(total_memory_required);
    if (!array) return NULL;

    unsigned int rnti_range = 1000; // Example range for RNTI
    if ((size_t)rnti_range * sizeof(int) > MAX_MEMORY_USAGE / N) {
        free(array);
        return NULL;
    }

    bool* rnti_taken = (bool*)calloc(rnti_range, sizeof(bool));
    if (!rnti_taken) {
        free(array);
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < N; ++i) {
        int rnti;
        do {
            rnti = rand() % rnti_range + 1;
        } while (rnti_taken[rnti - 1]);

        array[i].rx_ue_information.RX_UE_INFORMATION_TAG = i;
        array[i].rx_ue_information.RNTI = rnti;
        array[i].CRCFLAG = (rand() % 2) == 0;

        rnti_taken[rnti - 1] = true;
    }

    free(rnti_taken);
    return array;
}
