typedef struct {
    int length;
    char source_ip[16];
    char destination_ip[16];
} PacketMetadata;

PacketMetadata* process_packets(void* packet_stream, size_t stream_size) {
    PacketMetadata* metadata = NULL;
    size_t buffer_size = INITIAL_BUFFER_SIZE;
    size_t packet_count = 0;

    metadata = (PacketMetadata*)malloc(buffer_size * sizeof(PacketMetadata));
    if (!metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    while (packet_stream < (char*)packet_stream + stream_size) {
        // Simulate reading packet length
        int packet_length = *(int*)packet_stream;
        packet_stream += sizeof(int);

        if (packet_length > MAX_PACKET_SIZE) {
            fprintf(stderr, "Packet size exceeds maximum allowed\n");
            break;
        }

        if (packet_count >= buffer_size) {
            buffer_size *= 2;
            PacketMetadata* new_metadata = (PacketMetadata*)realloc(metadata, buffer_size * sizeof(PacketMetadata));
            if (!new_metadata) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(metadata);
                return NULL;
            }
            metadata = new_metadata;
        }

        // Simulate reading IP addresses
        memcpy(metadata[packet_count].source_ip, packet_stream, 16);
        memcpy(metadata[packet_count].destination_ip, packet_stream + 16, 16);
        packet_stream += 32;

        metadata[packet_count].length = packet_length;
        packet_count++;
    }

    // Resize the array to fit exactly the data
    PacketMetadata* resized_metadata = (PacketMetadata*)realloc(metadata, packet_count * sizeof(PacketMetadata));
    if (resized_metadata) {
        metadata = resized_metadata;
    }

    return metadata;
}
