typedef struct {
    uint32_t payload_size;
} packet_header_t;

typedef struct {
    uint8_t data[0]; // Flexible array member
} payload_t;

typedef struct {
    payload_t** payloads;
    size_t total_payload_size;
    size_t allocated_packets;
} network_processor_t;

network_processor_t* init_network_processor() {
    network_processor_t* processor = (network_processor_t*)malloc(sizeof(network_processor_t));
    if (!processor) {
        return NULL;
    }
    processor->payloads = (payload_t**)calloc(MAX_PACKETS, sizeof(payload_t*));
    processor->total_payload_size = 0;
    processor->allocated_packets = 0;
    return processor;
}

void free_network_processor(network_processor_t* processor) {
    for (size_t i = 0; i < processor->allocated_packets; ++i) {
        free(processor->payloads[i]);
    }
    free(processor->payloads);
    free(processor);
}

int process_packet_header(network_processor_t* processor, packet_header_t* header) {
    if (processor->allocated_packets >= MAX_PACKETS) {
        return -1; // Too many packets
    }

    size_t new_payload_size = header->payload_size;
    if (new_payload_size > SIZE_MAX - processor->total_payload_size) {
        return -2; // Integer overflow
    }
    processor->total_payload_size += new_payload_size;

    payload_t* new_payload = (payload_t*)malloc(sizeof(payload_t) + new_payload_size);
    if (!new_payload) {
        return -3; // Memory allocation failed
    }

    processor->payloads[processor->allocated_packets++] = new_payload;
    return 0; // Success
}

size_t get_total_payload_size(network_processor_t* processor) {
    return processor->total_payload_size;
}
