#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_KB 1024 // Example maximum memory limit in kilobytes

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct MemoryPool {
    size_t allocated_size;
    void *pool_start;
};

struct MemoryPool memory_pool = {0, NULL};
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_memory(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (memory_pool.allocated_size + size > MAX_MEMORY_KB * 1024) {
        pthread_mutex_unlock(&pool_mutex);
        return -ENOMEM; // Memory allocation error
    }
    void *new_start = realloc(memory_pool.pool_start, memory_pool.allocated_size + size);
    if (!new_start) {
        pthread_mutex_unlock(&pool_mutex);
        return -ENOMEM; // Failed to allocate memory
    }
    memory_pool.pool_start = new_start;
    memory_pool.allocated_size += size;
    pthread_mutex_unlock(&pool_mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_pdu(int max_memory_kb) {
    if (allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        // Log memory allocation error
        return NULL; // Failed to allocate memory for NFAPI structure
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)memory_pool.pool_start;
    srand(time(0)); // Seed for random number generation
    pdu->rx_ue_information_tag = rand() % 1000; // Random RX_UE_INFORMATION_TAG
    pdu->rnti = rand() % 256; // Random RNTI
    pdu->crc_indication_rel8_tag = rand() % 100; // Random CRC_INDICATION_REL8_TAG
    pdu->crcflag = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

    return pdu;
}
