    for (int i = 0; i < num_headers; i++) {
        if ((total_memory_used + header_lengths[i]) > max_total_memory || header_lengths[i] <= 0) {
            free(packets);
            return NULL; // Exceeds memory limit or invalid payload length
        }

        packets[i].payload = malloc(header_lengths[i]);
        if (!packets[i].payload) {
            for (int j = 0; j < i; j++) {
                free(packets[j].payload);
            }
            free(packets);
            return NULL; // Memory allocation failed
        }

        total_memory_used += header_lengths[i];
    }

    return packets;
}

void cleanup_packets(Packet* packets, int num_headers) {
    for (int i = 0; i < num_headers; i++) {
        free(packets[i].payload);
    }
    free(packets);
}
