        perror("Failed to open file");
        return;
    }

    // Get file size
    fseek(file, 0, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    // Calculate expected number of structures
    size_t expectedStructures = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (expectedStructures > maxStructures) {
        fprintf(stderr, "File size exceeds maximum allowed structures\n");
        fclose(file);
        return;
    }

    // Allocate memory for structures
    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(expectedStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Failed to allocate memory");
        fclose(file);
        return;
    }

    // Deserialize data into structures
    size_t bytesRead = fread(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), expectedStructures, file);
    if (bytesRead != expectedStructures) {
        fprintf(stderr, "Error reading from file\n");
        free(structures);
        fclose(file);
        return;
    }

    // Validate structures
    for (size_t i = 0; i < bytesRead; ++i) {
        if (structures[i].RX_UE_INFORMATION_TAG == 0 || structures[i].RNTI == 0 || structures[i].CRC_INDICATION_REL8_TAG > 1) {
