typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
size_t current_memory_usage = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int add_structure(const NFAPI_CRC_INDICATION_PDU_T* new_data) {
    pthread_mutex_lock(&mutex);

    if (current_memory_usage + sizeof(Node) > MAX_MEMORY_LIMIT || node_count >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory limit reached
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&mutex);
        return -2; // Memory allocation failed
    }

    newNode->data = *new_data;
    newNode->next = head;
    head = newNode;

    current_memory_usage += sizeof(Node);

    pthread_mutex_unlock(&mutex);
    return 0;
}

void* stress_test(void* arg) {
