typedef struct {
    char path[MAX_PATH_LENGTH];
    int width;
    int height;
    long long pixel_count; // Using long long to handle potential overflows
} image_metadata_t;

void process_directory(const char *directory_path, image_metadata_t **metadata_array, size_t *count) {
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char full_path[MAX_PATH_LENGTH];
        snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);

        DIR *subdir = opendir(full_path);
        if (subdir != NULL) {
            closedir(subdir); // It's a subdirectory
            process_directory(full_path, metadata_array, count);
        } else {
            if (entry->d_type == DT_REG) { // It's a regular file
                (*count)++;
                if (*count > MAX_IMAGE_FILES) {
                    printf("Too many image files\n");
                    closedir(dir);
                    return;
                }

                *metadata_array = realloc(*metadata_array, (*count) * sizeof(image_metadata_t));
                if (*metadata_array == NULL) {
                    perror("Failed to allocate memory for metadata array");
                    closedir(dir);
                    return;
                }

                // Simulate loading image metadata (e.g., from file)
                (*metadata_array)[*count - 1].width = 800; // Example width
                (*metadata_array)[*count - 1].height = 600; // Example height
                (*metadata_array)[*count - 1].pixel_count = (*metadata_array)[*count - 1].width * (*metadata_array)[*count - 1].height;
                strncpy((*metadata_array)[*count - 1].path, full_path, MAX_PATH_LENGTH);
            }
        }
    }

    closedir(dir);
}

int main() {
    image_metadata_t *metadata = NULL;
    size_t count = 0;

    process_directory("/path/to/image/directory", &metadata, &count);

    // Process the metadata array as needed
    for (size_t i = 0; i < count; i++) {
        printf("Image %zu: Path=%s, Width=%d, Height=%d, Pixel Count=%lld\n",
               i, metadata[i].path, metadata[i].width, metadata[i].height, metadata[i].pixel_count);
    }

    free(metadata);
    return 0;
}
