    manager->memory_block = malloc(initial_size);
    if (manager->memory_block == NULL) {
        // Handle allocation failure
    }
    manager->allocated_size = initial_size;
    manager->used_size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
