    if (manager->used_size + size <= manager->allocated_size) {
        ptr = (char*)manager->memory_block + manager->used_size;
        manager->used_size += size;
    } else {
        // Handle memory limit reached
    }
    pthread_mutex_unlock(&manager->mutex);
    return ptr;
}

