#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define METADATA_SIZE 64

typedef struct {
    char metadata[METADATA_SIZE];
    size_t payload_size;
    char *payload;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int packet_count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PacketQueue;

PacketQueue packet_queue;

void init_packet_queue() {
    memset(&packet_queue, 0, sizeof(PacketQueue));
    pthread_mutex_init(&packet_queue.mutex, NULL);
    pthread_cond_init(&packet_queue.cond, NULL);
}

void enqueue_packet(const char *metadata, size_t payload_size, const char *payload) {
    pthread_mutex_lock(&packet_queue.mutex);
    while (packet_queue.packet_count >= MAX_PACKETS) {
        pthread_cond_wait(&packet_queue.cond, &packet_queue.mutex);
    }

    Packet *new_packet = &packet_queue.packets[packet_queue.packet_count++];
    memcpy(new_packet->metadata, metadata, METADATA_SIZE);
    new_packet->payload_size = payload_size;
    new_packet->payload = (char *)malloc(payload_size);
    if (new_packet->payload) {
        memcpy(new_packet->payload, payload, payload_size);
    }

    pthread_cond_signal(&packet_queue.cond);
    pthread_mutex_unlock(&packet_queue.mutex);
}

void *process_packets(void *arg) {
    while (1) {
        pthread_mutex_lock(&packet_queue.mutex);
        while (packet_queue.packet_count == 0) {
            pthread_cond_wait(&packet_queue.cond, &packet_queue.mutex);
        }

        Packet *current_packet = &packet_queue.packets[0];
        packet_queue.packet_count--;
        memmove(packet_queue.packets, packet_queue.packets + 1, packet_queue.packet_count * sizeof(Packet));

        pthread_mutex_unlock(&packet_queue.mutex);

        // Process the current packet
        printf("Processing packet with metadata: %s and payload size: %zu\n", current_packet->metadata, current_packet->payload_size);
        if (current_packet->payload) {
            free(current_packet->payload);
        }
    }

    return NULL;
}

void *report_payload_sizes(void *arg) {
    while (1) {
        pthread_mutex_lock(&packet_queue.mutex);

        size_t total_payload_size = 0;
        for (int i = 0; i < packet_queue.packet_count; i++) {
            total_payload_size += packet_queue.packets[i].payload_size;
        }

        printf("Total payload size across all packets: %zu\n", total_payload_size);

        pthread_mutex_unlock(&packet_queue.mutex);
        // Adjust sleep duration based on performance monitoring
        usleep(100000); // Sleep for 100ms
    }

    return NULL;
}
