#define MAX_MEMORY_SIZE (1024 * 1024 * 10) // 10 MB
#define MAX_THREAD_REQUEST_LIMIT 100

pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;
int currentMemoryUsage = 0;
int threadRequestCount = 0;

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndicationPDUs(int N, size_t maxStructSize) {
    if (N > MAX_THREAD_REQUEST_LIMIT) {
        pthread_mutex_lock(&memoryMutex);
        fprintf(stderr, "Request exceeds per-thread request limit. Request rejected.\n");
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    size_t totalMemoryRequired = N * maxStructSize;
    if ((INT_MAX - currentMemoryUsage) < (int)totalMemoryRequired) {
        pthread_mutex_lock(&memoryMutex);
        fprintf(stderr, "Memory allocation would exceed maximum limit. Request rejected.\n");
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(totalMemoryRequired);
    if (!list) {
        pthread_mutex_lock(&memoryMutex);
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    pthread_mutex_lock(&memoryMutex);
    currentMemoryUsage += totalMemoryRequired;
    threadRequestCount++;
    pthread_mutex_unlock(&memoryMutex);

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = (unsigned short)rand();
        list[i].CRCFLAG = (unsigned char)rand();
    }

    return list;
}

void freeNFAPICRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T* list, int N, size_t maxStructSize) {
    pthread_mutex_lock(&memoryMutex);
    currentMemoryUsage -= N * maxStructSize;
    threadRequestCount--;
    pthread_mutex_unlock(&memoryMutex);

    free(list);
}
