#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define CRC_INDICATION_TAG_SIZE 256

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG[CRC_INDICATION_TAG_SIZE];
    int priority;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int list_size = 0;
int allocated_size = 0;

void initialize_list() {
    list_size = MAX_ENTRIES;
    allocated_size = list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(allocated_size);
}

void add_entry(unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI, int priority) {
    if (list_size >= allocated_size) {
        // Double the size of the list
        allocated_size *= 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list, allocated_size);
        if (!new_list) {
            printf("Memory allocation failed\n");
            return;
        }
        list = new_list;
    }

    int i;
    for (i = 0; i < list_size; ++i) {
        if (list[i].priority <= priority) {
            memmove(&list[i + 1], &list[i], (list_size - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry = { RX_UE_INFORMATION_TAG, RNTI, "CRC Flag", priority };
    memcpy(&list[i], &new_entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++list_size;
}

void report_crc_indications() {
    int count = 0;
    for (int i = 0; i < list_size; ++i) {
        if (strncmp(list[i].CRC_INDICATION_REL8_TAG, "true", 4) == 0) {
            ++count;
        }
    }
    printf("Total CRC indications with true flag: %d\n", count);
}

void delete_entries_by_rnti(unsigned short RNTI) {
    int i;
    for (i = list_size - 1; i >= 0; --i) {
        if (list[i].RNTI == RNTI) {
            memmove(&list[i], &list[i + 1], (list_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --list_size;
        }
    }
}

void compact_list() {
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list, list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) {
        printf("Memory reallocation failed\n");
        return;
    }
    list = new_list;
}

int main() {
    srand(time(NULL));
    initialize_list();

    for (int i = 0; i < 100; ++i) {
        add_entry(rand(), rand(), rand() % 10);
    }

    report_crc_indications();
    delete_entries_by_rnti(42);

    compact_list();
    free(list);

    return 0;
}
