#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedList {
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t total_size;
    size_t max_memory_kb;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list(size_t max_memory_kb) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->total_size = 0;
    list->max_memory_kb = max_memory_kb * 1024; // Convert to bytes
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    if (!list) return;
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_element(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (!list) return;
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = rand(); // Randomly generate CRCFLAG
    new_node->next = NULL;

    if (!list->head) {
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    list->total_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (list->total_size > list->max_memory_kb) {
        // Handle memory limit exceeded
        free(new_node);
        list->total_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(LinkedList* list, int RX_UE_INFORMATION_TAG) {
    if (!list) return;
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    NFAPI_CRC_INDICATION_PDU_T* prev = NULL;

    while (current) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            list->total_size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void traverse_list(LinkedList* list) {
    if (!list) return;
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG, current->CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}
```

