int calculate_total_memory(int image_count, size_t metadata_size) {
    return image_count * (metadata_size + METADATA_HEADER_SIZE);
}

int is_within_max_memory(int total_memory_kb, int max_memory_kb) {
    return total_memory_kb <= max_memory_kb;
}

ImageMetadata* create_metadata_node(const char* file_path, int resolution, int file_size) {
    ImageMetadata* node = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    if (node == NULL) {
        perror("Failed to allocate memory for metadata node");
        return NULL;
    }
    strncpy(node->file_path, file_path, sizeof(node->file_path) - 1);
    node->resolution = resolution;
    node->file_size = file_size;
    node->next = NULL;
    return node;
}

void add_to_linked_list(ImageMetadata** head, ImageMetadata* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        ImageMetadata* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

int process_config_file(ConfigFile* config, int max_memory_kb, ImageMetadata** head) {
    size_t metadata_size = sizeof(ImageMetadata);
    int total_memory_kb = 0;

    for (int i = 0; i < config->directory_count; i++) {
        // Simulate reading image files from directory
        for (int j = 0; j < config->image_count[i]; j++) {
            char file_path[256];
            int resolution, file_size;
            // Read file path, resolution, and size from the directory

            ImageMetadata* new_node = create_metadata_node(file_path, resolution, file_size);
            if (new_node == NULL) {
                return -1; // Memory allocation failed
            }

            add_to_linked_list(head, new_node);

            total_memory_kb += calculate_total_memory(1, metadata_size);
            if (!is_within_max_memory(total_memory_kb, max_memory_kb)) {
                printf("Max memory limit exceeded. Terminating processing.\n");
                return -2; // Max memory limit reached
            }
        }
    }

    return 0; // Successfully processed all images within memory limits
}

int main() {
    ConfigFile config = { /* Initialize with actual directory and image counts */ };
    ImageMetadata* head = NULL;
    int max_memory_kb = 1024 * 1024; // Example: 1GB

    int result = process_config_file(&config, max_memory_kb, &head);
    if (result == 0) {
        printf("Image processing completed successfully.\n");
    } else if (result == -1) {
        printf("Memory allocation failed during image processing.\n");
    } else if (result == -2) {
        printf("Max memory limit reached during image processing.\n");
    }

    // Clean up allocated memory
    ImageMetadata* current = head;
    while (current != NULL) {
        ImageMetadata* next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
