#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 1024
#define MIN_BLOCK_SIZE 64

typedef struct {
    char *data;
    size_t length;
} Config;

typedef struct {
    Config **configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConfigList;

Config* create_config(const char *data, size_t length) {
    Config *config = malloc(sizeof(Config));
    if (config == NULL) return NULL;
    config->data = malloc(length + 1);
    if (config->data == NULL) {
        free(config);
        return NULL;
    }
    strncpy(config->data, data, length);
    config->data[length] = '\0';
    config->length = length;
    return config;
}

void destroy_config(Config *config) {
    if (config != NULL) {
        free(config->data);
        free(config);
    }
}

ConfigList* create_config_list() {
    ConfigList *list = malloc(sizeof(ConfigList));
    if (list == NULL) return NULL;
    list->configs = malloc(MAX_CONFIGS * sizeof(Config *));
    if (list->configs == NULL) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = MAX_CONFIGS;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_config_list(ConfigList *list) {
    if (list != NULL) {
        for (size_t i = 0; i < list->count; ++i) {
            destroy_config(list->configs[i]);
        }
        free(list->configs);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_config(ConfigList *list, const char *data, size_t length) {
    if (length > SIZE_MAX / 2 || length + sizeof(Config) > SIZE_MAX - list->count * sizeof(Config *)) return -1;
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Config **new_configs = realloc(list->configs, new_capacity * sizeof(Config *));
        if (new_configs == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->configs = new_configs;
        list->capacity = new_capacity;
    }
    Config *config = create_config(data, length);
    if (config == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->configs[list->count++] = config;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_config(ConfigList *list, size_t index) {
    if (index >= list->count) return -1;
    pthread_mutex_lock(&list->lock);
    destroy_config(list->configs[index]);
    memmove(&list->configs[index], &list->configs[index + 1], (list->count - index - 1) * sizeof(Config *));
    --list->count;
    pthread_mutex_unlock(&list->lock);
    return 0;
}
