typedef struct {
    ImageProcessingTask* tasks;
    size_t capacity;
    size_t count;
} TaskQueue;

void initialize_task_queue(TaskQueue* queue, size_t initial_capacity) {
    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->tasks = (ImageProcessingTask*)malloc(initial_capacity * sizeof(ImageProcessingTask));
}

void enqueue_task(TaskQueue* queue, ImageProcessingTask task) {
    if (queue->count >= queue->capacity) {
        // Double the capacity or handle overflow
        queue->capacity *= 2;
        queue->tasks = realloc(queue->tasks, queue->capacity * sizeof(ImageProcessingTask));
    }
    queue->tasks[queue->count++] = task;
}

void process_task_queue(TaskQueue* queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        ImageProcessingTask* task = &queue->tasks[i];
        // Perform processing here
        task->status = TASK_STATUS_COMPLETED;
    }
}

// Example usage:
int main() {
    TaskQueue image_processing_queue;
    initialize_task_queue(&image_processing_queue, IMAGE_COUNT * TASKS_PER_IMAGE);

    // Populate the queue with tasks...
    for (size_t i = 0; i < IMAGE_COUNT; ++i) {
        for (size_t j = 0; j < TASKS_PER_IMAGE; ++j) {
            ImageProcessingTask task;
            // Initialize task metadata and pixel data
