typedef struct {
    size_t *packet_lengths;
    size_t packet_count;
    size_t total_size;
    size_t capacity;
} PacketBuffer;

PacketBuffer* create_packet_buffer(size_t initial_capacity) {
    PacketBuffer *buffer = (PacketBuffer *)malloc(sizeof(PacketBuffer));
    buffer->packet_lengths = (size_t *)calloc(initial_capacity, sizeof(size_t));
    buffer->packet_count = 0;
    buffer->total_size = 0;
    buffer->capacity = initial_capacity;
    return buffer;
}

void free_packet_buffer(PacketBuffer *buffer) {
    free(buffer->packet_lengths);
    free(buffer);
}

int add_packet(PacketBuffer *buffer, size_t packet_length) {
    if (buffer->packet_count == buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        buffer->packet_lengths = (size_t *)realloc(buffer->packet_lengths, new_capacity * sizeof(size_t));
        if (buffer->packet_lengths == NULL) {
            return -1; // Memory allocation failed
        }
        buffer->capacity = new_capacity;
    }

    buffer->packet_lengths[buffer->packet_count] = packet_length;
    buffer->total_size += packet_length;
    buffer->packet_count++;
    return 0;
}

size_t get_total_packet_size(PacketBuffer *buffer) {
    return buffer->total_size;
}

int main() {
    PacketBuffer *buffer = create_packet_buffer(10);

    add_packet(buffer, 1500);
    add_packet(buffer, 2000);
    add_packet(buffer, 1024);

    printf("Total packet size: %zu\n", get_total_packet_size(buffer));

    free_packet_buffer(buffer);
    return 0;
}
