    PacketMetadata* metadata_list = NULL;
    size_t allocated_size = 0;
    size_t current_index = 0;

    // Allocate initial memory
    if (total_packets > 100000 || max_payload_size > 4 * 1024) {
        fprintf(stderr, "Error: Input values exceed maximum allowed.\n");
        return NULL;
    }
    allocated_size = total_packets * sizeof(PacketMetadata);
    metadata_list = (PacketMetadata*)malloc(allocated_size);
    if (!metadata_list) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Simulate packet processing
    for (int i = 0; i < total_packets; ++i) {
        metadata_list[i].timestamp = time(NULL);
        metadata_list[i].sequence_number = i;
        metadata_list[i].payload_length = rand() % max_payload_size + 1;

        // Check for integer overflow in allocation
        if (current_index + 1 > allocated_size / sizeof(PacketMetadata)) {
            PacketMetadata* new_metadata_list = (PacketMetadata*)realloc(metadata_list, allocated_size * 2);
            if (!new_metadata_list) {
                fprintf(stderr, "Memory reallocation failed.\n");
                free(metadata_list);
                return NULL;
            }
            metadata_list = new_metadata_list;
            allocated_size *= 2;
        }
    }

    // Return the list of packet metadata
    return metadata_list;
}

int main() {
    int total_packets = 50000; // Example value
    size_t max_payload_size = 4 * 1024; // Example value

