PacketBuffer* create_packet_buffer(NetworkStats *stats) {
    PacketBuffer *buf = (PacketBuffer *)malloc(sizeof(PacketBuffer));
    if (!buf) return NULL;

    buf->capacity = (size_t)(stats->typical_packets * stats->avg_packet_size * 1.5); // Add some margin
    buf->buffer = (unsigned char *)malloc(buf->capacity);
    if (!buf->buffer) {
        free(buf);
        return NULL;
    }

    buf->size = 0;
    buf->stats = *stats;

    return buf;
}

int add_packet(PacketBuffer *buf, const unsigned char *packet, size_t packet_size) {
    if (buf->size + packet_size > buf->capacity) {
        size_t new_capacity = buf->capacity * 2; // Double the buffer size
        unsigned char *new_buffer = (unsigned char *)realloc(buf->buffer, new_capacity);
        if (!new_buffer) return -1;

        buf->buffer = new_buffer;
        buf->capacity = new_capacity;
    }

    memcpy(&buf->buffer[buf->size], packet, packet_size);
    buf->size += packet_size;

    return 0;
}

void free_packet_buffer(PacketBuffer *buf) {
    if (buf->buffer) free(buf->buffer);
    free(buf);
}
