#define MAX_MEMORY_KB 1024 // Example maximum memory constraint

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct LinkedList {
    pthread_mutex_t lock;
    LinkedListNode* head;
    size_t allocated_memory;
    size_t max_memory_kb;
} LinkedList;

LinkedList* create_linked_list(size_t initial_memory_kb) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->allocated_memory = 0;
    list->max_memory_kb = initial_memory_kb * 1024; // Convert to bytes
    return list;
}

void destroy_linked_list(LinkedList* list) {
    LinkedListNode* current = list->head;
    while (current) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_to_list(LinkedList* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);

    if (list->allocated_memory >= list->max_memory_kb) {
        // Handle memory full condition
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }

    // Populate the structure with random data or from external sources
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = (unsigned char)rand(); // Example random flag

    new_node->next = list->head;
    list->head = new_node;
    list->allocated_memory += sizeof(LinkedListNode);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void monitor_memory_usage(LinkedList* list) {
    if (list->allocated_memory >= list->max_memory_kb * 0.9) {
        // Trigger notification or logging here
    }
}
