typedef struct Packet {
    size_t payload_size;
    char *payload;
} Packet;

typedef struct PacketBuffer {
    Packet *packets;
    size_t count;
    size_t capacity;
} PacketBuffer;

PacketBuffer* create_packet_buffer() {
    PacketBuffer *buffer = (PacketBuffer*)malloc(sizeof(PacketBuffer));
    if (!buffer) return NULL;
    buffer->packets = (Packet*)malloc(INITIAL_BUFFER_SIZE * sizeof(Packet));
    if (!buffer->packets) {
        free(buffer);
        return NULL;
    }
    buffer->count = 0;
    buffer->capacity = INITIAL_BUFFER_SIZE;
    return buffer;
}

void destroy_packet_buffer(PacketBuffer *buffer) {
    for (size_t i = 0; i < buffer->count; i++) {
        free(buffer->packets[i].payload);
    }
    free(buffer->packets);
    free(buffer);
}

int add_packet_to_buffer(PacketBuffer *buffer, Packet packet) {
    if (buffer->count >= buffer->capacity) {
        size_t new_capacity = buffer->capacity ? buffer->capacity * 2 : INITIAL_BUFFER_SIZE;
        Packet *new_packets = (Packet*)realloc(buffer->packets, new_capacity * sizeof(Packet));
        if (!new_packets) return -1; // Allocation failed
        buffer->packets = new_packets;
        buffer->capacity = new_capacity;
    }
    buffer->packets[buffer->count++] = packet;
    return 0;
}

Packet create_packet(size_t payload_size, const char *payload) {
    Packet packet;
    packet.payload_size = payload_size + sizeof(payload_size); // Including size of payload size in the header
    packet.payload = (char*)malloc(packet.payload_size);
    if (!packet.payload) exit(1); // Handle allocation failure
    memcpy(packet.payload, &payload_size, sizeof(payload_size));
    memcpy(packet.payload + sizeof(payload_size), payload, payload_size);
    return packet;
}

void process_packets(PacketBuffer *buffer) {
    for (size_t i = 0; i < buffer->count; i++) {
        // Process each packet here
        printf("Processing packet with size %zu\n", buffer->packets[i].payload_size - sizeof(size_t));
    }
}

int main() {
    PacketBuffer *packet_buffer = create_packet_buffer();
    if (!packet_buffer) return 1;

    char data[MAX_PACKET_SIZE];
    for (size_t i = 0; i < MAX_PACKET_SIZE; i++) {
        data[i] = 'A' + (i % 26);
    }

    Packet packet = create_packet(1024, data); // Example payload size
    if (add_packet_to_buffer(packet_buffer, packet) != 0) {
        printf("Failed to add packet to buffer\n");
        destroy_packet_buffer(packet_buffer);
        return 1;
    }

    process_packets(packet_buffer);

    destroy_packet_buffer(packet_buffer);
    return 0;
}
