#define MAX_LAYER_SIZE 1024 * 1024 * 1024 // Example limit: 1GB per layer
#define SYSTEM_MEMORY_LIMIT 1024 * 1024 * 1024 * 1024 // Example limit: 1TB

typedef struct {
    size_t max_layer_size;
    size_t total_memory_usage;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager memory_manager = {0, 0, PTHREAD_MUTEX_INITIALIZER};

void* process_image_file(void* arg) {
    size_t layer_size = *(size_t*)arg;

    if (layer_size > MAX_LAYER_SIZE) {
        fprintf(stderr, "Layer size exceeds maximum allowed limit.\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_manager.lock);
    if ((memory_manager.total_memory_usage + layer_size) > SYSTEM_MEMORY_LIMIT) {
        fprintf(stderr, "System memory limit exceeded.\n");
        pthread_mutex_unlock(&memory_manager.lock);
        return NULL;
    }
    memory_manager.total_memory_usage += layer_size;
    pthread_mutex_unlock(&memory_manager.lock);

    // Process the image file layers
    // ...

    return NULL;
}

int main() {
    size_t layer_sizes[] = {512 * 1024, 1024 * 1024, 2 * 1024 * 1024};
    int num_layers = sizeof(layer_sizes) / sizeof(layer_sizes[0]);

    pthread_t threads[num_layers];
    for (int i = 0; i < num_layers; i++) {
        if (pthread_create(&threads[i], NULL, process_image_file, &layer_sizes[i]) != 0) {
            fprintf(stderr, "Failed to create thread.\n");
            return 1;
        }
    }

    for (int i = 0; i < num_layers; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Total memory usage: %zu bytes\n", memory_manager.total_memory_usage);

    return 0;
}
```

