typedef struct PacketHeaderInfo {
    uint8_t header_type;
    void* header_data;
} PacketHeaderInfo;

typedef struct Packet {
    size_t max_headers;
    size_t current_headers;
    PacketHeaderInfo** headers;
} Packet;

Packet* create_packet(size_t max_headers) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL;

    packet->max_headers = max_headers;
    packet->current_headers = 0;
    packet->headers = (PacketHeaderInfo**)calloc(max_headers, sizeof(PacketHeaderInfo*));
    if (!packet->headers) {
        free(packet);
        return NULL;
    }

    return packet;
}

int add_header_to_packet(Packet* packet, uint8_t header_type, void* header_data) {
    if (!packet || packet->current_headers >= packet->max_headers) return -1;

    PacketHeaderInfo* new_header = (PacketHeaderInfo*)malloc(sizeof(PacketHeaderInfo));
    if (!new_header) return -2;

    new_header->header_type = header_type;
    new_header->header_data = header_data;

    packet->headers[packet->current_headers++] = new_header;
    return 0;
}

void free_packet(Packet* packet) {
    if (!packet) return;

    for (size_t i = 0; i < packet->current_headers; ++i) {
        if (packet->headers[i]) {
            free(packet->headers[i]);
        }
    }

    free(packet->headers);
    free(packet);
}
