#include <stdlib.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** list = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t current_size = 0;
size_t max_size = MAX_LIST_SIZE;

int allocate_list(size_t size) {
    if (size > max_size) {
        return -1;
    }

    pthread_mutex_lock(&mutex);
    if (current_size + size > max_size) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T** new_list = realloc(list, (current_size + size) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!new_list) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    list = new_list;
    current_size += size;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int free_list() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < current_size; ++i) {
        free(list[i]);
    }
    free(list);
    list = NULL;
    current_size = 0;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int add_element(const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (allocate_list(1) != 0) {
        return -1;
    }

    pthread_mutex_lock(&mutex);
    list[current_size - 1] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list[current_size - 1]) {
        free_list();
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    *list[current_size - 1] = *element;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int remove_element(size_t index) {
    if (index >= current_size || current_size == 0) {
        return -1;
    }

    pthread_mutex_lock(&mutex);
    free(list[index]);
    for (size_t i = index; i < current_size - 1; ++i) {
        list[i] = list[i + 1];
    }
    list[current_size - 1] = NULL;
    --current_size;
    pthread_mutex_unlock(&mutex);

    return 0;
}
