int calculateBufferSize(size_t file_size, size_t additional_space) {
    return (int)(file_size + additional_space > INT_MAX ? INT_MAX : file_size + additional_space);
}

void* readImageFile(const char *file_path, size_t file_size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int buffer_size = calculateBufferSize(file_size, 0);
    void *buffer = malloc(buffer_size);
    if (!buffer) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        free(buffer);
        fclose(file);
        perror("Failed to read file");
        return NULL;
    }

    fclose(file);
    return buffer;
}

void processImageFiles(const char *directory_path, int max_files) {
    DIR *dir = opendir(directory_path);
    if (!dir) {
        perror("Failed to open directory");
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && max_files > 0) {
        char full_path[1024];
        snprintf(full_path, sizeof(full_path), "%s/%s", directory_path, entry->d_name);

        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            processImageFiles(full_path, max_files);
        } else if (entry->d_type == DT_REG) {
            if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".png")) {
                FILE *file = fopen(full_path, "rb");
                if (!file) {
                    perror("Failed to open file");
                    continue;
                }

                fseek(file, 0, SEEK_END);
                size_t file_size = ftell(file);
                fclose(file);

                void *image_buffer = readImageFile(full_path, file_size);
                if (image_buffer) {
                    processImageFile(full_path);
                    free(image_buffer);
                }
            }
        }

        max_files--;
    }

    closedir(dir);
}
