#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1500
#define MEMORY_LIMIT 2 * 1024 * 1024 // 2MB

typedef struct Packet {
    void* payload;
    size_t payload_size;
    struct Packet* next;
} Packet;

Packet* packet_pool = NULL;
size_t total_allocated_memory = 0;

Packet* allocate_packet(size_t payload_size) {
    if (total_allocated_memory + sizeof(Packet) + payload_size > MEMORY_LIMIT) {
        return NULL; // Memory limit exceeded
    }

    Packet* new_packet = (Packet*)malloc(sizeof(Packet) + payload_size);
    if (!new_packet) {
        return NULL; // Allocation failed
    }

    new_packet->payload_size = payload_size;
    new_packet->payload = (void*)((char*)new_packet + sizeof(Packet));
    new_packet->next = packet_pool;

    packet_pool = new_packet;
    total_allocated_memory += sizeof(Packet) + payload_size;

    return new_packet;
}

void free_packet(Packet* packet) {
    if (!packet) {
        return;
    }

    Packet** prev = &packet_pool;
    while (*prev != packet) {
        prev = &(*prev)->next;
    }

    *prev = packet->next;

    total_allocated_memory -= sizeof(Packet) + packet->payload_size;
    free(packet);
}

void process_packets(void* parser_context, void (*parse_packet)(void*, Packet*)) {
    // Simulate incoming packets
    for (size_t i = 0; i < 1000; ++i) {
        size_t payload_size = rand() % MAX_PACKET_SIZE;
        Packet* packet = allocate_packet(payload_size);
        if (!packet) {
            fprintf(stderr, "Failed to allocate memory for packet\n");
            continue;
        }

        // Simulate parsing and processing the packet
        parse_packet(parser_context, packet);
        free_packet(packet);
    }
}
