    size_t chunkSize = 1024; // Example chunk size
    int numChunks = (maxStructures + chunkSize - 1) / chunkSize;

    for (int i = 0; i < numChunks && totalMemoryUsed <= maxMemoryBudget; ++i) {
        size_t chunkMemorySize = chunkSize * sizeof(NFAPI_CRC_INDICATION_PDU_T);
