typedef struct {
    int id;
    time_t timestamp;
    size_t payload_length;
} PacketHeader;

PacketHeader* packet_headers[MAX_PACKETS];
size_t packet_count = 0;
size_t allocated_memory = 0;
size_t memory_limit = 1024 * 1024; // 1 MB

int allocate_packet_header(size_t payload_size) {
    size_t required_memory = sizeof(PacketHeader) + payload_size;
    if (required_memory > memory_limit - allocated_memory) {
        return -1; // Out of memory
    }
    PacketHeader* header = malloc(required_memory);
    if (!header) {
        return -2; // Failed to allocate memory
    }
    header->payload_length = payload_size;
    packet_headers[packet_count++] = header;
    allocated_memory += required_memory;
    return 0;
}

void initialize_packet_header(int id, size_t payload_size) {
    PacketHeader* header = packet_headers[id];
    if (header) {
        header->id = id;
        header->timestamp = time(NULL);
        allocate_packet_header(payload_size);
    }
}

void process_network_traffic() {
    // Simulate receiving packets
    for (int i = 0; i < MAX_PACKETS; i++) {
        size_t payload_size = rand() % MAX_PAYLOAD_SIZE;
        initialize_packet_header(i, payload_size);
    }
}

void report_memory_usage() {
    printf("Allocated Memory: %zu bytes\n", allocated_memory);
    printf("Memory Limit: %zu bytes\n", memory_limit);
}

int main() {
    srand(time(NULL));
    process_network_traffic();
    report_memory_usage();
    return 0;
