BITMAP_FILE_HEADER** allocate_bitmap_headers(size_t N, size_t* capacity) {
    if (N == 0 || capacity == NULL) return NULL;

    BITMAP_FILE_HEADER** headers = malloc(N * sizeof(BITMAP_FILE_HEADER*));
    if (headers == NULL) return NULL; // Handle memory allocation failure

    for (size_t i = 0; i < N; ++i) {
        headers[i] = malloc(sizeof(BITMAP_FILE_HEADER));
        if (headers[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free(headers[j]);
            free(headers);
            return NULL; // Handle memory allocation failure
        }
    }

    *capacity = N;
    return headers;
}

void resize_bitmap_headers(BITMAP_FILE_HEADER*** headers, size_t* capacity, size_t new_capacity) {
    if (new_capacity <= *capacity) return;

    BITMAP_FILE_HEADER** new_headers = realloc(*headers, new_capacity * sizeof(BITMAP_FILE_HEADER*));
    if (new_headers == NULL) {
        // Handle memory allocation failure
        printf("Memory reallocation failed.\n");
        return;
    }

    for (size_t i = *capacity; i < new_capacity; ++i) {
        new_headers[i] = malloc(sizeof(BITMAP_FILE_HEADER));
        if (new_headers[i] == NULL) {
            // Handle memory allocation failure
            printf("Failed to allocate memory for a BITMAP_FILE_HEADER.\n");
            return;
        }
    }

    *headers = new_headers;
    *capacity = new_capacity;
}

void free_bitmap_headers(BITMAP_FILE_HEADER** headers, size_t N) {
    if (headers == NULL) return;

    for (size_t i = 0; i < N; ++i) {
        free(headers[i]);
    }
    free(headers);
