} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
    if (!array || new_capacity < array->size) return -1;

    NFAPI_CRC_INDICATION_PDU_T* newData = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) return -1;

    array->data = newData;
    array->capacity = new_capacity;

    return 0;
}

int add_to_dynamic_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        int result = resize_dynamic_array(array, array->capacity * 2);
        if (result != 0) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
    }

    array->data[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T get_from_dynamic_array(DynamicArray* array, size_t index) {
    if (!array || index >= array->size) return (NFAPI_CRC_INDICATION_PDU_T){0};

    pthread_mutex_lock(&array->mutex);
    NFAPI_CRC_INDICATION_PDU_T element = array->data[index];
    pthread_mutex_unlock(&array->mutex);

    return element;
}

int main() {
    // Example usage
    DynamicArray* my_array = create_dynamic_array(1000);
    if (my_array) {
        NFAPI_CRC_INDICATION_PDU_T new_element = {0};
        add_to_dynamic_array(my_array, new_element);
        NFAPI_CRC_INDICATION_PDU_T element = get_from_dynamic_array(my_array, 0);
