#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IMAGE_FILES 10000
#define MAX_FILE_PATH_LEN 256
#define MAX_DIMENSION 8192

typedef struct {
    char file_path[MAX_FILE_PATH_LEN];
    int width;
    int height;
} ImageMetadata;

typedef struct {
    ImageMetadata *metadata;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ImageDataStore;

void init_image_data_store(ImageDataStore *store, size_t initial_capacity) {
    store->metadata = (ImageMetadata *)malloc(initial_capacity * sizeof(ImageMetadata));
    if (store->metadata == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    store->count = 0;
    store->capacity = initial_capacity;
    pthread_mutex_init(&store->lock, NULL);
}

void destroy_image_data_store(ImageDataStore *store) {
    free(store->metadata);
    pthread_mutex_destroy(&store->lock);
}

int add_image_metadata(ImageDataStore *store, const char *file_path, int width, int height) {
    pthread_mutex_lock(&store->lock);

    if (store->count >= store->capacity - 1) {
        fprintf(stderr, "Maximum image files reached\n");
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    strcpy(store->metadata[store->count].file_path, file_path);
    store->metadata[store->count].width = width;
    store->metadata[store->count].height = height;

    if (width <= 0 || width > MAX_DIMENSION || height <= 0 || height > MAX_DIMENSION) {
        fprintf(stderr, "Invalid image dimensions\n");
        pthread_mutex_unlock(&store->lock);
        return -1;
    }

    store->count++;
    pthread_mutex_unlock(&store->lock);

    return 0;
}

void *process_image_files(void *arg) {
    ImageDataStore *store = (ImageDataStore *)arg;

    // Simulate processing image files
    for (size_t i = 0; i < store->count; i++) {
        printf("Processing image: %s, Width: %d, Height: %d\n",
               store->metadata[i].file_path,
               store->metadata[i].width,
               store->metadata[i].height);
    }

    return NULL;
}

int main() {
    ImageDataStore store;
    init_image_data_store(&store, MAX_IMAGE_FILES);

    // Example usage
    add_image_metadata(&store, "path/to/image1.jpg", 800, 600);
    add_image_metadata(&store, "path/to/image2.jpg", 400, 300);

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_image_files, &store) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        destroy_image_data_store(&store);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    destroy_image_data_store(&store);
    return EXIT_SUCCESS;
}
