}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool->pool) {
        free(pool->pool);
        pool->pool = NULL;
        pool->pool_size = 0;
        pool->used_memory = 0;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* pool, size_t num_elements) {
