        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* result = &pool->pool[pool->used_memory / sizeof(NFAPI_CRC_INDICATION_PDU_T)];
    pool->used_memory += num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);
