    IMAGE_FRAME_T** frames = (IMAGE_FRAME_T**)malloc(max_frames * sizeof(IMAGE_FRAME_T*));
    if (!frames) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    size_t total_memory_used = 0;
    int allocated_frames = 0;

    for (int i = 0; i < max_frames; ++i) {
        IMAGE_FRAME_T* frame = (IMAGE_FRAME_T*)malloc(sizeof(IMAGE_FRAME_T));
        if (!frame) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        size_t required_memory = sizeof(IMAGE_FRAME_T) + frame->pixel_data_size;
        if (total_memory_used + required_memory > memory_budget) {
            fprintf(stderr, "Memory budget exceeded for frame %d\n", i);
            free(frame);
            break;
        }

        frames[i] = frame;
        total_memory_used += required_memory;
        ++allocated_frames;

        // Simulate setting up the frame
        frame->width = 1920;
        frame->height = 1080;
        frame->pixel_data_size = (size_t)frame->width * frame->height * sizeof(uint32_t);
    }

