    free(tasks);

    return 0;
}

// Example usage with pthreads to demonstrate concurrency
void* thread_func(void* arg) {
    int tasks_per_thread = *(int*)arg;
    allocate_image_tasks(tasks_per_thread, 640, 480, 24);
    return NULL;
}

int main() {
    int total_tasks = 512;
    int num_threads = 4;
    pthread_t threads[num_threads];
    int tasks_per_thread = total_tasks / num_threads;

    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, thread_func, &tasks_per_thread) != 0) {
            perror("Error: Thread creation failed.");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
