#include <pthread.h>

#define MAX_CRC_INDICATIONS 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *pool[MAX_CRC_INDICATIONS];
int pool_index = 0;

void* allocate_from_pool() {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index < MAX_CRC_INDICATIONS) {
        NFAPI_CRC_INDICATION_PDU_T *ptr = pool[pool_index++];
        pthread_mutex_unlock(&pool_mutex);
        return ptr;
    }
    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}

void deallocate_to_pool(void* ptr) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index > 0 && pool[--pool_index] == ptr) {
        pthread_mutex_unlock(&pool_mutex);
    } else {
        pthread_mutex_unlock(&pool_mutex);
        // Handle error: trying to deallocate invalid memory
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication(int N) {
    if (N > MAX_CRC_INDICATIONS) {
        fprintf(stderr, "Error: Maximum number of CRC indications exceeded\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = allocate_from_pool();
    if (!indications) {
        fprintf(stderr, "Error: Failed to allocate memory from pool\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Initialize RX_UE_INFORMATION_TAG
        indications[i].ue_info = initialize_ue_information_tag();

        // Generate random RNTI (16-bit unsigned integer)
        indications[i].RNTI = rand() % UINT16_MAX;

        // Validate and set CRCFLAG within valid range [0, 1]
        uint8_t crc_flag;
        do {
            crc_flag = rand() % 2; // Simplified validation for demonstration
        } while (crc_flag > 1);
        indications[i].crc_indication.CRCFLAG = crc_flag;

        // Log the RNTI and CRCFLAG values
        printf("RNTI: %u, CRCFLAG: %u\n", indications[i].RNTI, indications[i].crc_indication.CRCFLAG);
    }

    return indications;
}

// Example usage:
int main() {
    srand(time(NULL)); // Seed the random number generator

    int N = 10; // Number of CRC indications to create
    NFAPI_CRC_INDICATION_PDU_T *indications = create_nfa_crc_indication(N);

    if (indications) {
        // Use the created indications...
        for (int i = 0; i < N; i++) {
            deallocate_to_pool(&indications[i]);
        }
    }

    return 0;
}
