#include <stdlib.h>
#include <stdio.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, int rx_tag, int rnti, int crc_flag) {
    Node* new_node = create_node(rx_tag, rnti, crc_flag);
    new_node->next = *head;
    *head = new_node;
}

void delete_node(Node** head, int rx_tag) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != rx_tag) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Node not found.\n");
        return;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
