#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    uint8_t protocol_version;
    uint32_t packet_length;
    uint64_t unique_identifier;
} PacketHeader;

#define MAX_PACKETS 10000
#define MAX_MEMORY_USAGE (10 * 1024 * 1024) // 10 MB

static PacketHeader* packet_headers = NULL;
static size_t packet_count = 0;
static size_t max_packet_count = MAX_PACKETS;
static size_t allocated_memory = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

bool allocate_memory(size_t count) {
    size_t required_memory = count * sizeof(PacketHeader);
    if (required_memory > MAX_MEMORY_USAGE - allocated_memory) {
        return false; // Insufficient memory
    }
    packet_headers = realloc(packet_headers, required_memory);
    if (!packet_headers) {
        return false; // Memory allocation failed
    }
    allocated_memory += required_memory;
    max_packet_count = count;
    return true;
}

void free_memory() {
    pthread_mutex_lock(&lock);
    free(packet_headers);
    packet_headers = NULL;
    packet_count = 0;
    allocated_memory = 0;
    max_packet_count = MAX_PACKETS;
    pthread_mutex_unlock(&lock);
}

bool process_packet_header(const PacketHeader* header) {
    if (packet_count >= max_packet_count) {
        return false; // No more space for packets
    }
    pthread_mutex_lock(&lock);
    packet_headers[packet_count++] = *header;
    pthread_mutex_unlock(&lock);
    return true;
}

void* handle_packets(void* arg) {
    // Simulate incoming packet headers
    PacketHeader headers[MAX_PACKETS];
    size_t header_count = MAX_PACKETS;

    for (size_t i = 0; i < header_count; ++i) {
        headers[i].protocol_version = rand() % 256;
        headers[i].packet_length = rand() % 1000 + 1;
        headers[i].unique_identifier = rand();
    }

    // Process each packet
    for (size_t i = 0; i < header_count; ++i) {
        if (!process_packet_header(&headers[i])) {
            free_memory();
            break;
        }
    }

    return NULL;
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, handle_packets, NULL);
    pthread_join(thread_id, NULL);

    return 0;
}
