NFAPI_CRC_INDICATION_PDU_T* processCRCIndications(int count) {
    if (count <= 0 || count > INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Invalid count or potential overflow");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = rand();
        indications[i].RNTI = rand();
        indications[i].CRCFLAG = rand() % 2;
    }

    return indications;
}

NFAPI_CRC_INDICATION_PDU_T* readNfareData(const char* filename, int* count) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0L, SEEK_SET);

    if (fileSize % sizeof(NFAPI_CRC_INDICATION_PDU_T) != 0) {
        perror("Invalid file format");
        fclose(file);
        return NULL;
    }

    *count = fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    size_t bytesRead = fread(data, sizeof(NFAPI_CRC_INDICATION_PDU_T), *count, file);
    if (bytesRead != *count) {
        perror("Failed to read data from file");
        free(data);
        fclose(file);
        return NULL;
    }

    fclose(file);

    // Check for potential overflow during memory allocation
    if ((long)(*count) * sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof(NFAPI_CRC_INDICATION_PDU_T) != *count) {
        perror("Potential overflow during memory allocation");
        free(data);
        return NULL;
    }

    return data;
}
