#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PATH_LENGTH 256
#define MIN_DIMENSION 0
#define MAX_DIMENSION 4096
#define MIN_RESOLUTION 1
#define MAX_RESOLUTION 32768

typedef struct {
    char file_path[MAX_PATH_LENGTH];
    int width;
    int height;
    int resolution_x;
    int resolution_y;
} ImageMetadataEntry;

typedef struct {
    ImageMetadataEntry *entries;
    size_t max_entries;
    size_t current_size;
    pthread_mutex_t lock;
} ImageMetadataList;

ImageMetadataList* create_image_metadata_list(size_t max_entries) {
    if (max_entries == 0 || max_entries > SIZE_MAX / sizeof(ImageMetadataEntry)) {
        fprintf(stderr, "Error: Invalid or too large max_entries\n");
        return NULL;
    }

    ImageMetadataList *list = malloc(sizeof(ImageMetadataList));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for image metadata list\n");
        return NULL;
    }

    list->entries = malloc(max_entries * sizeof(ImageMetadataEntry));
    if (!list->entries) {
        free(list);
        fprintf(stderr, "Error: Failed to allocate memory for image metadata entries\n");
        return NULL;
    }

    list->max_entries = max_entries;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_image_metadata_list(ImageMetadataList *list) {
    if (list) {
        free(list->entries);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_image_metadata_entry(ImageMetadataList *list, const char *file_path, int width, int height, int resolution_x, int resolution_y) {
    pthread_mutex_lock(&list->lock);

    if (list->current_size >= list->max_entries) {
        fprintf(stderr, "Error: Maximum number of entries reached\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (strlen(file_path) > MAX_PATH_LENGTH || width < MIN_DIMENSION || width > MAX_DIMENSION || height < MIN_DIMENSION || height > MAX_DIMENSION || resolution_x < MIN_RESOLUTION || resolution_x > MAX_RESOLUTION || resolution_y < MIN_RESOLUTION || resolution_y > MAX_RESOLUTION) {
        fprintf(stderr, "Error: Invalid metadata values\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    strcpy(list->entries[list->current_size].file_path, file_path);
    list->entries[list->current_size].width = width;
    list->entries[list->current_size].height = height;
    list->entries[list->current_size].resolution_x = resolution_x;
    list->entries[list->current_size].resolution_y = resolution_y;
    list->current_size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void clear_image_metadata_list(ImageMetadataList *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);
        list->current_size = 0;
        pthread_mutex_unlock(&list->lock);
    }
}
