#define MAX_PAYLOAD_SIZE 1024 * 1024 // 1 MB
#define MAX_PACKETS 10000

typedef struct {
    size_t payload_size;
    char* payload;
} Packet;

typedef struct {
    size_t total_packets_processed;
    size_t cumulative_payload_size;
    pthread_mutex_t lock;
} Metrics;

Metrics metrics = {0, 0, PTHREAD_MUTEX_INITIALIZER};

void log_error(const char* message) {
    // Log error to logging system
    printf("Error: %s\n", message);
}

int allocate_packet_payload(Packet* packet, size_t payload_size) {
    if (payload_size > MAX_PAYLOAD_SIZE) {
        log_error("Payload size exceeds maximum allowed.");
        return -1;
    }

    packet->payload = malloc(payload_size);
    if (!packet->payload) {
        log_error("Failed to allocate memory for payload.");
        return -1;
    }
    packet->payload_size = payload_size;

    return 0;
}

void process_packet(Packet* packet) {
    pthread_mutex_lock(&metrics.lock);
    metrics.total_packets_processed++;
    metrics.cumulative_payload_size += packet->payload_size;
    pthread_mutex_unlock(&metrics.lock);

    // Process packet payload
    // ...

    free(packet->payload);
    packet->payload = NULL;
}

int process_network_packets(Packet* packets, size_t num_packets) {
    if (num_packets > MAX_PACKETS) {
        log_error("Number of packets exceeds maximum allowed.");
        return -1;
    }

    for (size_t i = 0; i < num_packets; i++) {
        if (allocate_packet_payload(&packets[i], packets[i].payload_size) == 0) {
            process_packet(&packets[i]);
        }
    }

    return 0;
}
