void* create_and_populate_array(void* arg) {
    int N = *(int*)arg;
    if (N <= 0 || N > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Invalid number of structures: %d\n", N);
        return NULL;
