typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t *data;
} ImageFrameData;

void* process_image_file(void* arg) {
    char *file_path = (char*)arg;
    // Simulate reading configuration and parsing
    FILE *fp = fopen(file_path, "r");
    if (!fp) return NULL; // Error handling

    int num_frames;
    fread(&num_frames, sizeof(int), 1, fp);
    if (num_frames <= 0 || num_frames > 10000) {
        fclose(fp);
        return NULL; // Invalid frame count
    }

    ImageFrameData *frames = malloc(num_frames * sizeof(ImageFrameData));
    if (!frames) {
        fclose(fp);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_frames; ++i) {
        fread(&frames[i].width, sizeof(uint32_t), 1, fp);
        fread(&frames[i].height, sizeof(uint32_t), 1, fp);
        size_t frame_size = frames[i].width * frames[i].height;
        if (frame_size == 0 || frame_size > UINT_MAX / num_frames) {
            free(frames);
            fclose(fp);
            return NULL; // Invalid or too large frame size
        }
        frames[i].data = malloc(frame_size);
        if (!frames[i].data) {
            for (int j = 0; j < i; ++j) free(frames[j].data);
            free(frames);
            fclose(fp);
            return NULL; // Memory allocation failed for frame data
        }
        fread(frames[i].data, 1, frame_size, fp);
    }

    // Process frames...

    for (int i = 0; i < num_frames; ++i) free(frames[i].data);
    free(frames);
    fclose(fp);
    return NULL;
}

int main() {
    pthread_t threads[10];
    char *file_paths[] = {"image1.bin", "image2.bin", ...}; // Array of file paths

    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, process_image_file, (void*)file_paths[i])) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

