#define MAX_MEMORY_ALLOCATION 1024 * 1024 // 1 MB limit for simplicity

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t size;
    time_t timestamp;
} METADATA_TAG;

int initialize_metadata(NFAPI_CRC_INDICATION_PDU_T **array, METADATA_TAG **metadata_array, int count) {
    if (count <= 0 || count > MAX_MEMORY_ALLOCATION / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Invalid count or memory limit exceeded.\n");
        return -1;
    }

    size_t total_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T) + count * sizeof(METADATA_TAG);
    if (total_size > MAX_MEMORY_ALLOCATION) {
        fprintf(stderr, "Memory allocation limit exceeded.\n");
        return -2;
    }

    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        fprintf(stderr, "Failed to allocate memory for PDU array.\n");
        return -3;
    }

    *metadata_array = (METADATA_TAG *)malloc(count * sizeof(METADATA_TAG));
    if (*metadata_array == NULL) {
        free(*array);
        fprintf(stderr, "Failed to allocate memory for metadata array.\n");
        return -4;
    }

    for (int i = 0; i < count; i++) {
        (*metadata_array)[i].pdu = &(*array)[i];
        (*metadata_array)[i].size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        (*metadata_array)[i].timestamp = time(NULL);

        // Randomly set CRCFLAG for demonstration
        (*array)[i].CRCFLAG = rand() % 2;
    }

    return 0;
}

// Example usage:
int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    METADATA_TAG *metadata_array;

    int result = initialize_metadata(&pdu_array, &metadata_array, 100);
    if (result == 0) {
        printf("Metadata initialized successfully.\n");
        // Use the arrays for further processing...
        free(pdu_array);
        free(metadata_array);
    } else {
        printf("Failed to initialize metadata with error code: %d\n", result);
    }

    return 0;
}
