NFAPI_CRC_INDICATION_PDU_T* create_and_populate_nfaapi_pdu(int num_structures) {
    static int current_memory_usage = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;

    if (num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        log_error("Invalid number of structures requested");
        return NULL;
    }

    // Calculate required memory size
    int required_memory = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (required_memory + current_memory_usage > MEMORY_THRESHOLD) {
        log_warning("Memory allocation would exceed threshold. Requested: %d, Available: %d", 
                     required_memory, MEMORY_THRESHOLD - current_memory_usage);
        return NULL;
    }

    // Allocate memory
    pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)memory_alloc(required_memory);
    if (!pdu_array) {
        log_error("Failed to allocate memory for NFAPI PDU structures");
        return NULL;
    }

    srand(time(NULL));  // Seed for random number generation

    // Populate structures
    for (int i = 0; i < num_structures; i++) {
        pdu_array[i].rx_ue_information_tag = generate_rx_ue_info_tag();
        pdu_array[i].rnti = generate_random_rnti();
        pdu_array[i].crc_indication_rel8_tag.crcflag = rand() % 2 == 0 ? true : false;
    }

    // Update memory usage
    current_memory_usage += required_memory;

    log_info("Successfully created and populated NFAPI PDU structures. Memory used: %d", current_memory_usage);

    return pdu_array;
}

void free_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int num_structures) {
    static int current_memory_usage = 0;

    if (pdu_array == NULL || num_structures <= 0) {
        log_error("Invalid parameters for freeing NFAPI PDU structures");
        return;
    }

    // Calculate required memory size
    int required_memory = num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Free memory
    memory_free(pdu_array, required_memory);

    // Update memory usage
    current_memory_usage -= required_memory;

    log_info("Successfully freed NFAPI PDU structures. Memory remaining: %d", current_memory_usage);
}
