class Nfademo {
public:
    using random_int_distribution = std::uniform_int_distribution<int>;
    using random_float_distribution = std::uniform_real_distribution<float>;

    Nfademo(int min_val, int max_val) : rng(std::random_device{}()), dist(min_val, max_val) {}

    int generateRandomInt() {
        return dist(rng);
    }

    float generateRandomFloat() {
        return distFloat(rng);
    }

private:
    std::mt19937 rng;
    random_int_distribution dist;
    random_float_distribution distFloat = random_float_distribution(0.0f, 1.0f);
