        throw std::invalid_argument("Number of elements must be greater than zero");
    }

    // Estimate the size of the structure
    size_t struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (struct_size == 0) {
        throw std::runtime_error("Invalid structure size");
    }

    // Calculate required memory for the list
    size_t required_memory = static_cast<size_t>(N) * struct_size;
    if (required_memory / N != struct_size) {
        throw std::overflow_error("Memory calculation overflow");
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> list(N);
    Nfademo nfaDemo(0, 1); // Assuming CRCFLAG is a boolean and can be generated as an integer

    for (auto& pdu : list) {
