        pdu.RNTI = nfaDemo.generateRandomInt();
        pdu.CRC_INDICATION_REL8_TAG = nfaDemo.generateRandomInt();
        pdu.CRCFLAG = nfaDemo.generateRandomInt() % 2 == 0; // Convert integer to boolean
    }

    return list;
}

