        int N = 1000000;
        std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList = populateNFAPIList(N);
        // Further processing can be done here
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
