#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_NFAPIS 1024
#define DNS_TIMEOUT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_circ_buffer[MAX_NFAPIS];
int head = 0, tail = 0, count = 0;

void enqueue(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (count >= MAX_NFAPIS) {
        printf("Buffer overflow\n");
        return;
    }
    nfapi_circ_buffer[head++] = pdu;
    head %= MAX_NFAPIS;
    count++;
}

NFAPI_CRC_INDICATION_PDU_T *dequeue() {
    if (count == 0) {
        printf("Buffer underflow\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = nfapi_circ_buffer[tail++];
    tail %= MAX_NFAPIS;
    count--;
    return pdu;
}

int resolve_dns(const char *hostname, u_char **ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if ((status = getnameinfo(p->ai_addr, p->ai_addrlen,
                                *ip_address, INET6_ADDRSTRLEN, NULL, 0,
                                NI_NUMERICHOST)) != 0) {
            fprintf(stderr, "getnameinfo: %s\n", gai_strerror(status));
            freeaddrinfo(res);
            return -1;
        }
    }

    freeaddrinfo(res);
    return 0;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Memory allocation failed\n");
        return 1;
    }

    pdu->RX_UE_INFORMATION_TAG = 12345;
    pdu->RNTI = 67890;
    pdu->CRC_INDICATION_REL8_TAG = 54321;
    pdu->CRCFLAG = 'Y';

    enqueue(pdu);

    NFAPI_CRC_INDICATION_PDU_T *dequeued_pdu = dequeue();
    if (dequeued_pdu) {
        free(dequeued_pdu);
    }

    u_char ip_address[INET6_ADDRSTRLEN];
    if (resolve_dns("example.com", &ip_address) == 0) {
        printf("IP Address: %s\n", ip_address);
    } else {
        printf("DNS resolution failed\n");
    }

    return 0;
}
