int process_image_filenames(image_data** images, char* filenames[], int num_files) {
    for (int i = 0; i < num_files; ++i) {
        if (strlen(filenames[i]) >= MAX_FILENAME_LENGTH) {
            fprintf(stderr, "Error: Filename too long\n");
            return -1;
        }

        struct image_processing_library_image* lib_image = load_image_from_file(filenames[i]);
        if (!lib_image) {
            fprintf(stderr, "Error: Failed to load image %s\n", filenames[i]);
            continue;
        }

        if (lib_image->width <= 0 || lib_image->height <= 0) {
            fprintf(stderr, "Error: Invalid image dimensions in %s\n", filenames[i]);
            free_image_processing_library_image(lib_image);
            continue;
        }

        size_t required_size = (size_t)lib_image->width * (size_t)lib_image->height * 3; // Assuming RGB format
        if (required_size / lib_image->width != (size_t)lib_image->height || required_size > SIZE_MAX) {
            fprintf(stderr, "Error: Integer overflow in memory allocation calculation for %s\n", filenames[i]);
            free_image_processing_library_image(lib_image);
            continue;
        }

        images[i] = malloc(sizeof(image_data));
        if (!images[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for image data\n");
            free_image_processing_library_image(lib_image);
            return -1;
        }

        images[i]->data = malloc(required_size);
        if (!images[i]->data) {
            fprintf(stderr, "Error: Failed to allocate memory for image data in %s\n", filenames[i]);
            free(images[i]);
            free_image_processing_library_image(lib_image);
            return -1;
        }

        memcpy(images[i]->data, lib_image->data, required_size);
        images[i]->width = lib_image->width;
        images[i]->height = lib_image->height;

        free_image_processing_library_image(lib_image);
    }
    return 0;
}

// Example usage:
int main() {
    char* filenames[] = {"image1.jpg", "image2.png", "image3.bmp"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);
    image_data** images = malloc(num_files * sizeof(image_data*));

    if (process_image_filenames(images, filenames, num_files) != 0) {
        fprintf(stderr, "Failed to process image files\n");
