Packet* create_packet(int size) {
    if (size <= 0 || size > MAX_PACKET_SIZE) {
        return NULL; // Handle invalid sizes
    }
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) {
        LOG_ERROR("Failed to allocate memory for packet header");
        return NULL;
    }
    packet->payload_size = size;
    packet->payload = (char*)calloc(size, sizeof(char));
    if (!packet->payload) {
        free(packet);
        LOG_ERROR("Failed to allocate memory for packet payload");
        return NULL;
    }
    return packet;
}

void destroy_packet(Packet* packet) {
    if (packet) {
        free(packet->payload);
        free(packet);
    }
}

int process_packets(int max_packets, size_t total_memory_limit) {
    Packet** packets = (Packet**)malloc(max_packets * sizeof(Packet*));
    if (!packets) {
        LOG_ERROR("Failed to allocate memory for packet array");
        return -1;
    }

    int current_memory_usage = 0;
    int processed_packets = 0;

    while (processed_packets < max_packets && current_memory_usage < total_memory_limit) {
        // Simulate reading packet size from high-speed pipe
        int packet_size = read_packet_size_from_pipe();
        if (packet_size <= 0) {
            break; // No more packets or error
        }

        Packet* packet = create_packet(packet_size);
        if (!packet) {
            continue; // Skip invalid packets
        }

        packets[processed_packets++] = packet;

        current_memory_usage += sizeof(Packet) + packet_size;
    }

    for (int i = 0; i < processed_packets; i++) {
        destroy_packet(packets[i]);
    }
    free(packets);

    return processed_packets;
}

// Simulated function to read packet size from pipe
int read_packet_size_from_pipe() {
    // Implementation details depend on actual data source
    return rand() % (MAX_PACKET_SIZE / 1024); // Random size between 0 and 1024 packets
}
