#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    void* data;
    size_t size;
} Packet;

void process_packets(int socket, size_t initial_alloc_size) {
    Packet* packets = (Packet*)malloc(initial_alloc_size * sizeof(Packet));
    if (!packets) {
        perror("Failed to allocate memory for packets");
        return;
    }

    size_t packet_count = 0;
    size_t total_memory_used = 0;
    int delimiter_received = 0;

    while (!delimiter_received && (total_memory_used < initial_alloc_size)) {
        // Simulate reading a packet from the network
        size_t packet_size;
        if (read(socket, &packet_size, sizeof(packet_size)) != sizeof(packet_size)) {
            perror("Failed to read packet size");
            free(packets);
            return;
        }

        if (packet_size == 0) { // Assuming 0 as the delimiter
            delimiter_received = 1;
            continue;
        }

        packets[packet_count].data = malloc(packet_size);
        if (!packets[packet_count].data) {
            perror("Failed to allocate memory for packet data");
            free(packets);
            return;
        }
        packets[packet_count].size = packet_size;

        // Simulate reading the packet data
        if (read(socket, packets[packet_count].data, packet_size) != packet_size) {
            perror("Failed to read packet data");
            for (size_t i = 0; i <= packet_count; ++i) {
                free(packets[i].data);
            }
            free(packets);
            return;
        }

        total_memory_used += packets[packet_count].size;
        ++packet_count;

        // Periodic garbage collection
        if (total_memory_used > initial_alloc_size / 2) {
            Packet* new_packets = (Packet*)realloc(packets, initial_alloc_size * sizeof(Packet));
            if (!new_packets) {
                perror("Failed to reallocate memory for packets");
                for (size_t i = 0; i <= packet_count; ++i) {
                    free(packets[i].data);
                }
                free(packets);
                return;
            }
            packets = new_packets;
            initial_alloc_size *= 2;
        }
    }

    // Process the collected packets
    for (size_t i = 0; i < packet_count; ++i) {
        // Process each packet
        printf("Packet %zu: Size = %zu\n", i, packets[i].size);
        free(packets[i].data);
    }
    free(packets);
}
