typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_Crc_Indication_Array;

void initNFAPI_Crc_Indication_Array(NFAPI_Crc_Indication_Array* arr, size_t initialCapacity) {
    arr->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initialCapacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void freeNFAPI_Crc_Indication_Array(NFAPI_Crc_Indication_Array* arr) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->array) {
        free(arr->array);
        arr->array = NULL;
    }
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_unlock(&arr->mutex);
    pthread_mutex_destroy(&arr->mutex);
}

int resizeNFAPI_Crc_Indication_Array(NFAPI_Crc_Indication_Array* arr, size_t newCapacity) {
    if (newCapacity <= arr->capacity) return 0;

    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        fprintf(stderr, "Memory reallocation failed\n");
        return -1;
    }
    arr->array = newArray;
    arr->capacity = newCapacity;

    // Initialize the newly allocated elements
    for (size_t i = arr->size; i < arr->capacity; ++i) {
        pthread_mutex_lock(&arr->mutex);
        // Initialize each structure element here
        pthread_mutex_unlock(&arr->mutex);
    }

    return 0;
}

int addNFAPI_Crc_Indication_PDU(NFAPI_Crc_Indication_Array* arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (arr->size >= arr->capacity) {
        size_t newCapacity = arr->capacity == 0 ? 1 : arr->capacity * 2;
        if (resizeNFAPI_Crc_Indication_Array(arr, newCapacity) != 0) return -1;
    }

    pthread_mutex_lock(&arr->mutex);
    arr->array[arr->size++] = pdu;
    pthread_mutex_unlock(&arr->mutex);

    return 0;
}

// Example usage
int main() {
    NFAPI_Crc_Indication_Array crcArray;
    initNFAPI_Crc_Indication_Array(&crcArray, 10);

