typedef struct Packet {
    size_t payload_size;
    char *payload;
} Packet;

typedef struct Stream {
    int id;
    pthread_t thread_id;
    int running;
    Packet packets[MAX_CONCURRENT_STREAMS];
} Stream;

Stream streams[MAX_CONCURRENT_STREAMS];

void* process_packets(void* arg) {
    Stream* stream = (Stream*)arg;
    while (stream->running) {
        // Simulate reading packet from data pipe
        Packet packet;
        // Assume packet.payload_size and packet.payload are populated here

        if (packet.payload_size > 0 && packet.payload_size <= MAX_PACKET_SIZE) {
            packet.payload = malloc(packet.payload_size);
            if (packet.payload == NULL) {
                // Handle memory allocation failure
                continue;
            }
            // Process packet payload
            free(packet.payload);
        } else {
            // Handle invalid packet size
        }
    }
    return NULL;
}

void initialize_streams() {
    for (int i = 0; i < MAX_CONCURRENT_STREAMS; i++) {
        streams[i].id = i;
        streams[i].running = 1;
        pthread_create(&streams[i].thread_id, NULL, process_packets, &streams[i]);
    }
}

void cleanup_streams() {
    for (int i = 0; i < MAX_CONCURRENT_STREAMS; i++) {
        streams[i].running = 0;
        pthread_join(streams[i].thread_id, NULL);
        // Free any remaining allocated resources
    }
}

int main() {
    initialize_streams();
    // Simulate running the application for a period of time
    sleep(60);
    cleanup_streams();
    return 0;
}
