    NFAPI_CRC_INDICATION_PDU_T *item = &list->list[list->count++];
    item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    item->RNTI = RNTI;
    item->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    item->CRCFLAG = (rand() % 2) == 0; // Randomly set CRCFLAG
