        if (item->RX_UE_INFORMATION_TAG <= 0 || item->RNTI == 0 || !item->CRC_INDICATION_REL8_TAG) {
            fprintf(stderr, "Invalid item in list at index %zu\n", i);
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    NFAPI_LIST_T *list = create_nfaip_list(100, MAX_LIMIT);
    if (!list) {
