#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PacketNode* next;
} PacketNode;

typedef struct MemoryPool {
    size_t blockSize;
    size_t poolSize;
    void* freeList;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t poolSize) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->blockSize = blockSize;
    pool->poolSize = poolSize;
    pool->freeList = malloc(blockSize * poolSize);
    if (pool->freeList == NULL) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < poolSize - 1; ++i) {
        ((PacketNode*)(((char*)pool->freeList) + i * blockSize))->next = 
            (PacketNode*)((char*)pool->freeList + (i + 1) * blockSize);
    }
    ((PacketNode*)((char*)pool->freeList + (poolSize - 1) * blockSize))->next = NULL;

    return pool;
}

void* allocateFromPool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    void* block = pool->freeList;
    if (block != NULL) {
        pool->freeList = ((PacketNode*)block)->next;
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void freeToPool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    ((PacketNode*)block)->next = pool->freeList;
    pool->freeList = block;
    pthread_mutex_unlock(&pool->lock);
}

