#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct Packet {
    int length;
    char data[MAX_PACKET_SIZE];
    struct Packet* next;
} Packet;

typedef struct PacketQueue {
    Packet* head;
    Packet* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int max_packets;
    int current_packets;
} PacketQueue;

PacketQueue* create_packet_queue(int max_packets) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    if (!queue) {
        perror("Failed to allocate memory for packet queue");
        return NULL;
    }
    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->max_packets = max_packets;
    queue->current_packets = 0;
    return queue;
}

void destroy_packet_queue(PacketQueue* queue) {
    Packet* current = queue->head;
    while (current) {
        Packet* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

void enqueue_packet(PacketQueue* queue, Packet* packet) {
    pthread_mutex_lock(&queue->lock);
    while (queue->current_packets >= queue->max_packets) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    if (!queue->head) {
        queue->head = packet;
    } else {
        queue->tail->next = packet;
    }
    queue->tail = packet;
    queue->current_packets++;
    pthread_mutex_unlock(&queue->lock);
    pthread_cond_signal(&queue->cond);
}

Packet* dequeue_packet(PacketQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (!queue->head) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    Packet* packet = queue->head;
    queue->head = queue->head->next;
    if (!queue->head) {
        queue->tail = NULL;
    }
    queue->current_packets--;
    pthread_mutex_unlock(&queue->lock);
    return packet;
}

void free_packet(Packet* packet) {
    free(packet);
}

// Example usage
int main() {
    PacketQueue* queue = create_packet_queue(100);
    if (!queue) {
        return 1;
    }

    // Simulate receiving packets and processing them
    for (int i = 0; i < 150; i++) {
        Packet* packet = (Packet*)malloc(sizeof(Packet));
        if (!packet) {
            perror("Failed to allocate memory for packet");
            continue;
        }
        packet->length = rand() % MAX_PACKET_SIZE;
        memset(packet->data, 0, MAX_PACKET_SIZE);
        enqueue_packet(queue, packet);
    }

    // Process packets
    while (1) {
        Packet* packet = dequeue_packet(queue);
        if (!packet) {
            break; // No more packets to process
        }
        // Process the packet data here
        printf("Processing packet of length %d\n", packet->length);
        free_packet(packet);
    }

    destroy_packet_queue(queue);
    return 0;
}
```

