['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define DEFAULT_BUFFER_SIZE 100

typedef struct Packet {
    uint32_t packetID;
    time_t timestamp;
    size_t payloadSize;
    char payload[MAX_PACKET_SIZE];
} Packet;

typedef struct CircularBuffer {
    Packet* packets;
    int head;
    int tail;
    int count;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} CircularBuffer;

CircularBuffer* createCircularBuffer(int size) {
    if (size <= 0 || size > INT_MAX / sizeof(Packet)) return NULL; // Check for integer overflow
    CircularBuffer* cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    cb->packets = (Packet*)calloc(size, sizeof(Packet));
    cb->head = cb->tail = cb->count = 0;
    cb->capacity = size;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
    return cb;
}

void destroyCircularBuffer(CircularBuffer* cb) {
    free(cb->packets);
    pthread_mutex_destroy(&cb->mutex);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int enqueuePacket(CircularBuffer* cb, Packet packet) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }
    int next = (cb->head + cb->count) % cb->capacity;
    cb->packets[next] = packet;
    cb->count++;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int dequeuePacket(CircularBuffer* cb, Packet* packet) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->mutex);
    }
    int next = (cb->tail + cb->count - 1) % cb->capacity;
    *packet = cb->packets[next];
    cb->count--;
    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int processPackets(CircularBuffer* cb, int maxPacketCount, time_t discardThreshold) {
    Packet packet;
    while (1) {
        if (dequeuePacket(cb, &packet) == 0) {
            if (time(NULL) - packet.timestamp > discardThreshold) continue; // Discard old packets
            // Process the packet here
            printf("Processed packet with ID: %u\n", packet.packetID);
        }
    }
}

int main() {
    CircularBuffer* cb = createCircularBuffer(DEFAULT_BUFFER_SIZE);
    if (cb == NULL) {
        fprintf(stderr, "Failed to create circular buffer.\n");
        return 1;
    }

    // Simulate receiving packets
    for (int i = 0; i < 100; i++) {
        Packet packet;
        packet.packetID = i;
        packet.timestamp = time(NULL);
        packet.payloadSize = rand() % MAX_PACKET_SIZE;
        memset(packet.payload, 'A' + i % 26, packet.payloadSize);
        enqueuePacket(cb, packet);
    }

    processPackets(cb, DEFAULT_BUFFER_SIZE, 10); // Process packets for 10 seconds

    destroyCircularBuffer(cb);
    return 0;
}
