#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Packet {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Packet* next;
    time_t timestamp;
} Packet;

Packet* packet_pool[MAX_PACKETS];
int pool_index = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void init_packet_pool() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        packet_pool[i] = malloc(sizeof(Packet));
    }
}

Packet* get_packet() {
    pthread_mutex_lock(&pool_lock);
    if (pool_index == MAX_PACKETS) {
        pthread_mutex_unlock(&pool_lock);
        return NULL;
    }
    Packet* packet = packet_pool[pool_index++];
    pthread_mutex_unlock(&pool_lock);
    return packet;
}

void free_packet(Packet* packet) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < MAX_PACKETS) {
        packet_pool[pool_index++] = packet;
    } else {
        free(packet);
    }
    pthread_mutex_unlock(&pool_lock);
}

int validate_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Validation logic here
    return 1; // Assuming all packets are valid for simplicity
}

void process_packet(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Packet* packet = get_packet();
    if (packet == NULL) {
        printf("Packet pool exhausted\n");
        return;
    }
    packet->pdu = *pdu;
    packet->timestamp = time(NULL);
    if (!validate_packet(&packet->pdu)) {
        free_packet(packet);
        return;
    }
    // Process the packet
    free_packet(packet);
}

void* packet_processor(void* arg) {
    while (1) {
        // Simulate receiving packets
        NFAPI_CRC_INDICATION_PDU_T pdu;
        process_packet(&pdu);
    }
    return NULL;
}

int main() {
    init_packet_pool();
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, packet_processor, NULL);
    }
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
