        crcList[i].RNTI = rand() % 10000; // Example range
        snprintf(crcList[i].CRC_INDICATION_REL8_TAG, sizeof(crcList[i].CRC_INDICATION_REL8_TAG), "%d", randomStringHash(strToHash) % 100);
    }

    return crcList;
}

char* modifyFileExtension(const char *filename) {
    if (filename == NULL || strlen(filename) > MAX_FILENAME_LENGTH - 6) { // Considering new extension ".123"
        return NULL;
    }

    char *newFilename = malloc(MAX_FILENAME_LENGTH);
    if (newFilename == NULL) {
        return NULL;
    }

    const char *dotPos = strrchr(filename, '.');
    if (dotPos != NULL) {
        strncpy(newFilename, filename, dotPos - filename + 1);
        newFilename[dotPos - filename + 1] = '\0';
    } else {
        strcpy(newFilename, filename);
    }

    int digits = randomStringHash(filename) % 100; // Dynamically determine number of digits
    snprintf(newFilename + strlen(newFilename), MAX_FILENAME_LENGTH - strlen(newFilename),
             ".%03d.txt", digits); // Example file type .txt

    return newFilename;
