import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Random;

public class NASSignalingProcessor {

    private static final String C_LIBRARY_PATH = "/path/to/your/c/library";
    private static final int MAX_N = 1000; // Example limit, adjust as needed

    public void executeNASCommand(int N) {
        if (N < 0 || N > MAX_N) {
            throw new IllegalArgumentException("Invalid value for N: " + N);
        }

        String[] command = {"gcc", "-o", "nas_command", C_LIBRARY_PATH + "/signaling_lib.c"};
        File workingDir = new File(C_LIBRARY_PATH);

        try {
            Process process = Runtime.getRuntime().exec(command, null, workingDir);
            int exitCode = process.waitFor();
            if (exitCode == 0) {
                System.out.println("NAS command executed successfully.");
            } else {
                System.err.println("NAS command execution failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing NAS command: " + e.getMessage());
        }

        // Execute the compiled C program
        executeCompiledCommand(N, workingDir);
    }

    private void executeCompiledCommand(int N, File workingDir) {
        String[] command = {"./nas_command", String.valueOf(N)};
        try {
            Process process = Runtime.getRuntime().exec(command, null, workingDir);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Output: " + line);
            }

            int exitCode = process.waitFor();
            if (exitCode == 0) {
                System.out.println("Compiled NAS command executed successfully.");
            } else {
                System.err.println("Compiled NAS command execution failed with exit code: " + exitCode);
            }
        } catch (IOException | InterruptedException e) {
            System.err.println("Error executing compiled NAS command: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        NASSignalingProcessor processor = new NASSignalingProcessor();
        Random random = new Random();
        int N = random.nextInt(MAX_N); // Generate a random number for N
        processor.executeNASCommand(N);
    }
}
