int allocate_and_fill_NFAPI(PDU** pdus, int num_structs) {
    if (num_structs > MAX_STRUCTS) {
        return -1; // Error: Exceeds maximum limit
    }

    *pdus = NULL;
    int total_chunks = (num_structs + CHUNK_SIZE - 1) / CHUNK_SIZE;

    for (int i = 0; i < total_chunks; ++i) {
        PDU* new_chunk = realloc(*pdus, (i + 1) * CHUNK_SIZE * sizeof(PDU));
        if (!new_chunk) {
            free(*pdus); // Free previously allocated memory
            return -2; // Error: Memory allocation failed
        }
        *pdus = new_chunk;

        for (int j = i * CHUNK_SIZE; j < (i + 1) * CHUNK_SIZE && j < num_structs; ++j) {
            (*pdus)[j].RX_UE_INFORMATION_TAG = rand() % 1000;
            (*pdus)[j].RNTI = rand() % 256;
            (*pdus)[j].CRC_INDICATION_REL8_TAG = rand() % 1000;
            (*pdus)[j].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
        }
    }

    return 0; // Success
}

int main() {
    srand(time(NULL));
    PDU* pdus = NULL;
    int num_structs = 500;

    if (allocate_and_fill_NFAPI(&pdus, num_structs) == 0) {
        printf("Successfully allocated and filled %d structures.\n", num_structs);
        // Free the allocated memory when done
        free(pdus);
    } else {
        printf("Failed to allocate or fill structures.\n");
    }

    return 0;
}
