typedef struct {
    int source_type;
    int payload_length;
} Packet;

void process_packets(Packet packets[], int num_packets) {
    if (num_packets > 10000) {
        printf("Error: Number of packets exceeds limit.\n");
        return;
    }

    int total_memory = 0;
    int reallocations = 0;

    for (int i = 0; i < num_packets; i++) {
        int current_memory = packets[i].payload_length + sizeof(int); // Add space for payload length
        if ((total_memory % 1024) > (current_memory % 1024)) { // Check for reallocation needed
            printf("Reallocating memory...\n");
            reallocations++;
        }
        total_memory += current_memory;
    }

    printf("Total allocated memory: %d bytes\n", total_memory);
    printf("Number of reallocations: %d\n", reallocations);

    // Simulate processing of packets
    for (int i = 0; i < num_packets; i++) {
        // Allocate memory dynamically based on payload length and source type
        int* payload = malloc(packets[i].payload_length);
        if (payload == NULL) {
            printf("Error: Memory allocation failed.\n");
            return;
        }
        // Initialize payload with data from network source
        for (int j = 0; j < packets[i].payload_length; j++) {
            payload[j] = i + j;
        }
        // Process packet payload
        free(payload); // Free allocated memory after processing
    }
}

int main() {
    Packet packets[1000];
    int num_packets = 5;

    // Populate packet array with data
    for (int i = 0; i < num_packets; i++) {
        packets[i].source_type = i % 3; // Simulate different source types
        packets[i].payload_length = (i + 1) * 1024; // Variable payload length
    }

    process_packets(packets, num_packets);

    return 0;
}
