    int numChannels;
    ChannelData *channels;
    struct FrameMetaData *next;
} FrameMetaData;

int parseConfigFile(const char *filename, int **frameCounts, int *numFrames) {
    // Implementation to parse the configuration file and fill in the frame counts
    return 0; // Return 0 on success, non-zero on failure
}

FrameMetaData* initializeLinkedList(int numFrames, const int *frameCounts) {
    FrameMetaData *head = NULL;
    FrameMetaData *current = NULL;

    for (int i = 0; i < numFrames; ++i) {
        FrameMetaData *newNode = malloc(sizeof(FrameMetaData));
        if (!newNode) {
            // Handle memory allocation failure
            return head; // Return the partially created list
        }
        newNode->frameNumber = i;
        newNode->timestamp = time(NULL);
        newNode->numChannels = frameCounts[i];
        newNode->channels = malloc(newNode->numChannels * sizeof(ChannelData));
        if (!newNode->channels) {
            // Handle memory allocation failure
            free(newNode);
            return head; // Return the partially created list
        }
        memset(newNode->channels, 0, newNode->numChannels * sizeof(ChannelData));
        newNode->next = NULL;

        if (i == 0) {
            head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    return head;
}

void freeLinkedList(FrameMetaData *head) {
    FrameMetaData *current = head;
    while (current != NULL) {
        Free(current->channels);
        FrameMetaData *temp = current;
        current = current->next;
        Free(temp);
    }
}

int main() {
    const char *configFile = "path_to_config_file.txt";
    int *frameCounts;
    int numFrames;

    if (parseConfigFile(configFile, &frameCounts, &numFrames) != 0) {
        fprintf(stderr, "Error parsing configuration file.\n");
        return EXIT_FAILURE;
    }

    FrameMetaData *head = initializeLinkedList(numFrames, frameCounts);

    // Use the linked list for data processing and updates

    freeLinkedList(head);
    Free(frameCounts);

    return EXIT_SUCCESS;
}
