#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_NFAPI_PDUS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduManager;

int pdu_manager_init(PduManager *manager) {
    manager->count = 0;
    manager->capacity = 16; // Start with a small capacity
    manager->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        return -1; // Allocation failed
    }
    pthread_mutex_init(&manager->lock, NULL);
    return 0;
}

int pdu_manager_add_pdu(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Reallocation failed
        }
        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[manager->count];
    pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF; // Random value for demonstration
    pdu->RNTI = (uint16_t)(rand() % 0xFFFF); // Random value for demonstration
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256; // Random value for demonstration

    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void pdu_manager_free(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->pdus);
    manager->pdus = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
```

