fn create_directory(nfapi_count: usize) -> Result<String, Box<dyn std::error::Error>> {
    let default_path = "/tmp/nfapi_dir";
    let nfapi_dir = env::var("NFAPI_DIR")
        .ok()
        .and_then(|path| fs::metadata(&path).map_or(None, |_| Some(path)))
        .unwrap_or_else(|| {
            let new_dir_path = format!("{}/nfapi_{}", default_path, nfapi_count);
            fs::create_dir_all(&new_dir_path)?;
            env::set_var("NFAPI_DIR", &new_dir_path);
            new_dir_path
        });

    if !Path::new(&nfapi_dir).is_dir() {
        return Err("NFAPI_DIR is not a directory".into());
    }

    if !fs::metadata(&nfapi_dir)?.permissions().write() {
        return Err("NFAPI_DIR is not writable".into());
    }

    let total_size = nfapi_count.checked_mul(std::mem::size_of::<NFAPI_CRC_INDICATION_PDU_T>()) {
        return Err("Integer overflow calculating memory size".into());
    };

    let file_path = format!("{}/nfapi_data.bin", &nfapi_dir);
    let mut file = BufWriter::new(File::create(&file_path)?);

    let rng = rand::thread_rng();
    for _ in 0..nfapi_count {
        let mut pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: rng.next_u32(),
            rnti: rng.next_u16(),
            crc_indication_rel8_tag: rng.next_u16(),
            crcflag: rng.next_u8(),
        };
        file.write_all(unsafe { std::slice::from_raw_parts(&pdu as *const _ as *const u8, std::mem::size_of::<NFAPI_CRC_INDICATION_PDU_T>()) })?;
    }

    Ok(nfapi_dir)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let nfapi_count = 1000;
    let directory_path = create_directory(nfapi_count)?;
    println!("Directory created at: {}", directory_path);
    Ok(())
}
