    while ((entry = readdir(dir)) != nullptr) {
        std::string filePath = directoryPath + "/" + entry->d_name;

        struct stat fileStat;
        if (stat(filePath.c_str(), &fileStat) == -1) {
            std::cerr << "Failed to get file stats: " << filePath << std::endl;
            continue;
        }

        if (S_ISREG(fileStat.st_mode)) {
            ImageMetadata metadata;
            metadata.filePath = filePath;

            // Read image dimensions and calculate checksum here
            // For simplicity, assume these values are obtained through other means

            // Example: metadata.width = ...
            // Example: metadata.height = ...
            // Example: metadata.checksum = calculateChecksum(filePath);

            imageMetadataList.push_back(metadata);
        }
    }

    closedir(dir);

    return imageMetadataList;
}

// Helper function to calculate MD5 checksum
std::string calculateChecksum(const std::string& filePath) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    std::ifstream file(filePath, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        return "";
    }

    size_t fileSize = file.tellg();
    file.seekg(0);

    MD5_CTX md5;
    MD5_Init(&md5);

    char buffer[4096];
    while (file.good()) {
        file.read(buffer, sizeof(buffer));
        MD5_Update(&md5, buffer, file.gcount());
    }

    MD5_Final(hash, &md5);

    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(hash[i]);
    }

    return ss.str();
}
