use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::Duration;

const DEFAULT_PATH: &str = "/tmp/nfapi_dir";
const NFAPI_COUNT: usize = 1000; // Example value

#[derive(Debug)]
struct NFAPICRCIndicationPDU {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: u8,
}

fn create_directory(path: &str) -> io::Result<()> {
    fs::create_dir_all(path)?;
    fs::set_permissions(path, fs::Permissions::from_mode(0o755))?;
    Ok(())
}

fn get_or_create_nfaapi_dir() -> String {
    if let Some(dir_path) = env::var_os("NFAPI_DIR") {
        let path = Path::new(&dir_path);
        if path.exists() && path.is_dir() {
            return dir_path.into_string().unwrap();
        }
    }

    let mut default_path = PathBuf::from(DEFAULT_PATH);
    if !default_path.exists() {
        create_directory(default_path.as_os_str().to_str().unwrap()).unwrap();
    }

    env::set_var("NFAPI_DIR", default_path.display());
    env::var("NFAPI_DIR").unwrap()
}

fn allocate_memory(count: usize) -> Vec<NFAPICRCIndicationPDU> {
    let mut data = vec![];
    for _ in 0..count {
        data.push(NFAPICRCIndicationPDU {
            rx_ue_information_tag: rand::random(),
            rnti: rand::random(),
            crc_indication_rel8_tag: rand::random(),
        });
    }
    data
}

fn write_to_directory(data: &[NFAPICRCIndicationPDU], dir_path: &str) -> io::Result<()> {
    let mut rate_limiter = RateLimiter::new(10, Duration::from_secs(1));
    for pdu in data {
        if !rate_limiter.try_acquire() {
            continue;
        }
        let file_path = Path::new(dir_path).join(format!("pdu_{}.bin", pdu.rx_ue_information_tag));
        let mut file = File::create(&file_path)?;
        file.write_all(&serde_cbor::to_vec(pdu)?)?;
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let dir_path = get_or_create_nfaapi_dir();
    let data = allocate_memory(NFAPI_COUNT);
    write_to_directory(&data, &dir_path)?;
    Ok(())
}
