#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 500000

typedef struct {
    uint8_t *data;
    size_t length;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int head, tail;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty, not_full;
} PacketQueue;

PacketQueue packet_queue;

void init_packet_queue() {
    memset(&packet_queue, 0, sizeof(PacketQueue));
    pthread_mutex_init(&packet_queue.mutex, NULL);
    pthread_cond_init(&packet_queue.not_empty, NULL);
    pthread_cond_init(&packet_queue.not_full, NULL);
}

int enqueue_packet(const Packet *packet) {
    pthread_mutex_lock(&packet_queue.mutex);
    while ((packet_queue.tail + 1) % MAX_PACKETS == packet_queue.head)
        pthread_cond_wait(&packet_queue.not_full, &packet_queue.mutex);
    if ((packet_queue.tail + 1) % MAX_PACKETS == packet_queue.head) {
        pthread_mutex_unlock(&packet_queue.mutex);
        return -1; // Queue full
    }
    memcpy(packet_queue.packets[packet_queue.tail], packet, sizeof(Packet));
    packet_queue.tail = (packet_queue.tail + 1) % MAX_PACKETS;
    pthread_cond_signal(&packet_queue.not_empty);
    pthread_mutex_unlock(&packet_queue.mutex);
    return 0;
}

int dequeue_packet(Packet *packet) {
    pthread_mutex_lock(&packet_queue.mutex);
    while (packet_queue.head == packet_queue.tail)
        pthread_cond_wait(&packet_queue.not_empty, &packet_queue.mutex);
    if (packet_queue.head == packet_queue.tail) {
        pthread_mutex_unlock(&packet_queue.mutex);
        return -1; // Queue empty
    }
    memcpy(packet, &packet_queue.packets[packet_queue.head], sizeof(Packet));
    packet_queue.head = (packet_queue.head + 1) % MAX_PACKETS;
    pthread_cond_signal(&packet_queue.not_full);
    pthread_mutex_unlock(&packet_queue.mutex);
    return 0;
}

