NFAPI_CRC_INDICATION_PDU_T* create_and_populate_ndus(int *error_code) {
    FILE *config_file = fopen("config.txt", "r");
    if (!config_file) {
        *error_code = 1; // File not found
        return NULL;
    }

    int N;
    fscanf(config_file, "%d", &N);
    if (ferror(config_file)) {
        fclose(config_file);
        *error_code = 2; // Reading error from file
        return NULL;
    }
    clearerr(config_file);

    if (N > MAX_N) {
        fclose(config_file);
        *error_code = 3; // Integer overflow or excessive memory request
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *ndus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ndus) {
        fclose(config_file);
        *error_code = 4; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        // Populate RX_UE_INFORMATION_TAG and RNTI fields here
        ndus[i].rnti = rand() % 65536;

        // Randomly set CRCFLAG
        ndus[i].crc_indication.CRCFLAG = (rand() % 2 == 0);
    }

    fclose(config_file);
    *error_code = 0; // Success
    return ndus;
}
