#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IMAGE_DIM 10000

typedef struct ImageMetaData {
    char* filePath;
    int width;
    int height;
} ImageMetaData;

typedef struct MemoryPool {
    void* pool;
    size_t blockSize;
    size_t poolSize;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t blockSize, size_t numBlocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->poolSize = blockSize * numBlocks;
    pool->pool = malloc(pool->poolSize);
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocateFromPool(MemoryPool* pool) {
    void* block;
    pthread_mutex_lock(&pool->lock);
    if (pool->used + pool->blockSize > pool->poolSize) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    block = ((char*)pool->pool) + pool->used;
    pool->used += pool->blockSize;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void freePool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->pool);
    free(pool);
}

int processImageFiles(char** filePaths, int numFiles, MemoryPool* pool, FILE* logFile) {
    for (int i = 0; i < numFiles; i++) {
        ImageMetaData* metaData = (ImageMetaData*)allocateFromPool(pool);
        if (!metaData) {
            fprintf(logFile, "Error: Failed to allocate memory for image metadata\n");
            return -1;
        }

        // Simulate reading file metadata
        strcpy(metaData->filePath, filePaths[i]);
        metaData->width = rand() % MAX_IMAGE_DIM + 1;
        metaData->height = rand() % MAX_IMAGE_DIM + 1;

        if (metaData->width > MAX_IMAGE_DIM || metaData->height > MAX_IMAGE_DIM) {
            fprintf(logFile, "Error: Image dimensions too large\n");
            free(metaData);
            return -1;
        }

        // Simulate processing image
        printf("Processing image %s with dimensions %dx%d\n", filePaths[i], metaData->width, metaData->height);

        // Write metadata to file
        fprintf(logFile, "Processed image: %s, Dimensions: %dx%d\n", filePaths[i], metaData->width, metaData->height);
    }
    return 0;
}

int main() {
    char* files[] = {"image1.jpg", "image2.jpg", "image3.jpg"};
    int numFiles = sizeof(files) / sizeof(files[0]);

    MemoryPool* pool = createMemoryPool(sizeof(ImageMetaData), numFiles);
    if (!pool) return -1;

    FILE* logFile = fopen("log.txt", "w");
    if (!logFile) {
        freePool(pool);
        return -1;
    }

    int result = processImageFiles(files, numFiles, pool, logFile);
    if (result != 0) {
        fprintf(logFile, "Error: Processing images failed\n");
    } else {
        fprintf(logFile, "All images processed successfully\n");
    }

    fclose(logFile);
    freePool(pool);
    return 0;
}
