#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILE_SIZE 1024 * 1024 // 1MB limit for configuration file

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* read_config_file(const char* filename, size_t* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size > MAX_FILE_SIZE) {
        fprintf(stderr, "Configuration file exceeds maximum allowed size\n");
        fclose(file);
        return NULL;
    }

    char* buffer = (char*)malloc(file_size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for configuration file content");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        fprintf(stderr, "Error reading configuration file\n");
        free(buffer);
        fclose(file);
        return NULL;
    }
    buffer[file_size] = '\0';

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    char* token = strtok(buffer, "\n");
    size_t parsed_count = 0;

    while (token != NULL && parsed_count < file_size) {
        NFAPI_CRC_INDICATION_PDU_T new_item;
        sscanf(token, "%d %d %d", &new_item.RX_UE_INFORMATION_TAG, &new_item.RNTI, &new_item.CRC_INDICATION_REL8_TAG);

        if (head == NULL) {
            head = current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else {
            current->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current = current->next;
        }

        if (!current) {
            fprintf(stderr, "Failed to allocate memory for new configuration item\n");
            free(buffer);
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T* temp = head;
                head = head->next;
                free(temp);
            }
            fclose(file);
            return NULL;
        }

        *current = new_item;

        token = strtok(NULL, "\n");
        parsed_count++;
    }

    *count = parsed_count;
    fclose(file);
    free(buffer);

    current->next = NULL; // Null-terminate the list
    return head;
}
