typedef struct Packet {
    int payload_size;
} Packet;

int calculate_total_payload_size(Packet *packets, int num_packets) {
    if (num_packets > INT_MAX / sizeof(int)) return -1; // Check for integer overflow

    int total_size = 0;
    for (int i = 0; i < num_packets; i++) {
        total_size += packets[i].payload_size;
        if (total_size < 0) return -1; // Check for integer overflow
    }

    return total_size;
}

void allocate_buffer(Packet *packets, int num_packets, char **buffer, size_t *buffer_size) {
    *buffer_size = calculate_total_payload_size(packets, num_packets);
    if (*buffer_size == -1) {
        // Handle error: memory allocation failed due to overflow or other issues
        *buffer = NULL;
        return;
    }

    *buffer = (char *)malloc(*buffer_size);
    if (!*buffer) {
        // Handle error: malloc failed
        *buffer_size = 0;
        return;
    }
}

void process_packets(Packet *packets, int num_packets, char *buffer) {
    for (int i = 0; i < num_packets; i++) {
        memcpy(buffer, packets[i].payload, packets[i].payload_size);
        buffer += packets[i].payload_size;
    }
}
