#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define MIN_BUFFER_SIZE 1024
#define DEFAULT_COMPRESSION_LEVEL 5

typedef struct {
    int packet_count;
    size_t* packet_sizes;
    char** payloads;
} PacketBatch;

typedef struct {
    size_t buffer_size;
    char* buffer;
    int compression_level;
    pthread_mutex_t lock;
} BufferManager;

BufferManager* init_buffer_manager(int initial_size, int compression_level) {
    BufferManager* manager = (BufferManager*)malloc(sizeof(BufferManager));
    if (!manager) return NULL;

    manager->buffer_size = initial_size > MIN_BUFFER_SIZE ? initial_size : MIN_BUFFER_SIZE;
    manager->buffer = (char*)calloc(manager->buffer_size, sizeof(char));
    if (!manager->buffer) {
        free(manager);
        return NULL;
    }

    manager->compression_level = compression_level < 0 ? 0 : (compression_level > 9 ? 9 : compression_level);
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_buffer_manager(BufferManager* manager) {
    if (!manager) return;

    free(manager->buffer);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int calculate_total_size(PacketBatch* batch) {
    size_t total_size = 0;
    for (int i = 0; i < batch->packet_count; ++i) {
        if (batch->payloads[i]) {
            total_size += batch->packet_sizes[i];
        }
    }

    return total_size > SIZE_MAX ? -1 : (int)total_size;
}

void* process_packets(void* arg) {
    BufferManager* manager = (BufferManager*)arg;

    pthread_mutex_lock(&manager->lock);
    // Simulate processing packets and updating the buffer
    printf("Processing packets...\n");
    pthread_mutex_unlock(&manager->lock);

    return NULL;
}

int main() {
    PacketBatch batch;
    batch.packet_count = 5;
    batch.packet_sizes = (size_t*)calloc(batch.packet_count, sizeof(size_t));
    batch.payloads = (char**)malloc(batch.packet_count * sizeof(char*));

    for (int i = 0; i < batch.packet_count; ++i) {
        batch.payloads[i] = (char*)malloc(i * 10 + 1);
        snprintf(batch.payloads[i], i * 10 + 1, "Packet %d", i);
        batch.packet_sizes[i] = strlen(batch.payloads[i]);
    }

    BufferManager* manager = init_buffer_manager(calculate_total_size(&batch), DEFAULT_COMPRESSION_LEVEL);

    pthread_t thread;
    if (pthread_create(&thread, NULL, process_packets, manager) != 0) {
        printf("Failed to create thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    destroy_buffer_manager(manager);
    for (int i = 0; i < batch.packet_count; ++i) {
        free(batch.payloads[i]);
    }
    free(batch.payloads);
    free(batch.packet_sizes);

    return 0;
}
