typedef struct PacketHeader {
    int payloadSize;            // Variable-length field indicating the payload size
} PacketHeader;

int processPacketHeaders(PacketHeader* headers, int numHeaders, int maxMemoryUsage, int* totalBytesAllocated) {
    *totalBytesAllocated = 0;
    for (int i = 0; i < numHeaders; i++) {
        if (headers[i].payloadSize < MIN_PAYLOAD_SIZE || headers[i].payloadSize > MAX_PACKET_SIZE) {
            // Handle malformed header gracefully
            printf("Malformed header at index %d, payload size: %d\n", i, headers[i].payloadSize);
            continue;
        }

        // Calculate the memory needed for this packet's payload
        int payloadMemory = sizeof(char) * headers[i].payloadSize;

        if (*totalBytesAllocated + payloadMemory > maxMemoryUsage) {
            // Handle memory allocation limit reached
            printf("Memory allocation limit reached after processing %d packets\n", i);
            break;
        }

        // Dynamically allocate memory for the payload
        char* payload = (char*)malloc(payloadMemory);
        if (payload == NULL) {
            // Handle memory allocation failure
            printf("Failed to allocate memory for packet at index %d, payload size: %d\n", i, headers[i].payloadSize);
            break;
        }

        // Process the payload (e.g., initialize or copy data)
        // ...

        // Free the allocated memory after processing (if needed)
        free(payload);

        *totalBytesAllocated += payloadMemory;
    }

    if (*totalBytesAllocated == 0) {
        return -1; // No successful allocations
    } else {
        return 0; // Success
    }
}

int main() {
    // Example usage
    PacketHeader headers[] = {
        {512},
        {1024},
        {2048}
    };

