    int maxMemoryUsage = 3 * MAX_PACKET_SIZE;
    int totalBytesAllocated;

    if (processPacketHeaders(headers, numHeaders, maxMemoryUsage, &totalBytesAllocated) == 0) {
        printf("Total bytes allocated: %d\n", totalBytesAllocated);
    } else {
        printf("Failed to process packet headers.\n");
    }

    return 0;
}
