typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t count;
} LinkedList;

int createLinkedList(LinkedList** list, size_t N) {
    // Initialize the linked list
    *list = (LinkedList*)malloc(sizeof(LinkedList));
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed for LinkedList\n");
        return -1;
    }
    (*list)->head = (*list)->tail = NULL;
    (*list)->count = 0;

    // Create and populate the linked list
    for (size_t i = 0; i < N; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            fprintf(stderr, "Memory allocation failed for new Node\n");
            cleanLinkedList(*list);
            return -1;
        }

        // Populate the node with valid data
        // Example: newNode->data.RX_UE_INFORMATION_TAG = ...
        // Example: newNode->data.RNTI = (uint16_t)i; // Random or unique RNTI
        // Example: newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRC flag

        newNode->next = NULL;
        if ((*list)->head == NULL) {
            (*list)->head = newNode;
        } else {
            (*list)->tail->next = newNode;
        }
        (*list)->tail = newNode;
        ++(*list)->count;
    }

    return 0;
}

void cleanLinkedList(LinkedList* list) {
    // Free all allocated memory for the linked list
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = list->tail = NULL;
    list->count = 0;
}

int adjustListCapacity(LinkedList** list, size_t newCapacity) {
    // Adjust the maximum number of elements in the linked list
    if (newCapacity < (*list)->count) {
        fprintf(stderr, "New capacity cannot be less than current count\n");
        return -1;
    }

    // Optionally, implement dynamic resizing logic here
    // For now, simply allocate memory for new capacity
    Node* newNode = (Node*)realloc((*list)->head, newCapacity * sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        cleanLinkedList(*list);
        return -1;
    }
    (*list)->head = newNode;
    (*list)->tail = &newNode[newCapacity - 1];
    (*list)->count = newCapacity;

    return 0;
}
