#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PACKET_SIZE 1024 // Define a maximum packet size for simplicity

typedef struct Packet {
    int data_len;
    char* data;
} Packet;

typedef struct DataBuffer {
    int total_len;
    int max_size;
    Packet** packets;
    int packet_count;
} DataBuffer;

DataBuffer* create_data_buffer(int max_size) {
    DataBuffer* buffer = (DataBuffer*)malloc(sizeof(DataBuffer));
    if (buffer == NULL) {
        perror("Failed to allocate memory for DataBuffer");
        return NULL;
    }
    buffer->total_len = 0;
    buffer->max_size = max_size;
    buffer->packets = (Packet**)malloc(max_size * sizeof(Packet*));
    if (buffer->packets == NULL) {
        perror("Failed to allocate memory for packets array");
        free(buffer);
        return NULL;
    }
    buffer->packet_count = 0;
    return buffer;
}

void add_packet(DataBuffer* buffer, char* data, int len) {
    if (len > MAX_PACKET_SIZE) {
        fprintf(stderr, "Packet too large to process\n");
        return;
    }

    if ((buffer->total_len + len) > buffer->max_size) {
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }

    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (packet == NULL) {
        perror("Failed to allocate memory for Packet");
        return;
    }
    packet->data_len = len;
    packet->data = (char*)malloc(len);
    if (packet->data == NULL) {
        perror("Failed to allocate memory for data");
        free(packet);
        return;
    }
    memcpy(packet->data, data, len);

    buffer->packets[buffer->packet_count++] = packet;
    buffer->total_len += len;
}

void log_buffer_info(DataBuffer* buffer) {
    printf("Total packets processed: %d\n", buffer->packet_count);
    printf("Total data length: %d bytes\n", buffer->total_len);
}

void free_data_buffer(DataBuffer* buffer) {
    for (int i = 0; i < buffer->packet_count; i++) {
        free(buffer->packets[i]->data);
        free(buffer->packets[i]);
    }
    free(buffer->packets);
    free(buffer);
}
```

