    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

void initializeLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(LinkedList* list, char src_ip[], NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    strcpy(newNode->src_ip, src_ip);
    memcpy(&newNode->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
}

NFAPI_CRC_INDICATION_PDU_T* getNode(LinkedList* list, char src_ip[]) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        if (strcmp(current->src_ip, src_ip) == 0) {
            NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(data, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void* packetHandler(void* arg) {
    LinkedList* list = (LinkedList*)arg;
