        NFAPI_CRC_INDICATION_PDU_T data;
        // Populate data with random values
        insertNode(list, src_ip, data);
    }
    return NULL;
}

int main() {
    LinkedList list;
    initializeLinkedList(&list);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, packetHandler, &list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up and monitor system performance
    return 0;
}
