#define MAX_IMAGES 1000
#define MAX_PIXELS 1024*1024

typedef struct {
    int width;
    int height;
    unsigned char *data;
} Image;

Image* create_image_list(const char *config_file, size_t max_memory) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) return NULL;

    json_object *root = json_tokener_parse_from_file(fp);
    fclose(fp);

    if (!json_is_array(root)) {
        json_object_put(root);
        return NULL;
    }

    int num_images = json_array_length(root);
    if (num_images > MAX_IMAGES || num_images <= 0) {
        json_object_put(root);
        return NULL;
    }

    Image *images = malloc(num_images * sizeof(Image));
    if (!images) {
        json_object_put(root);
        return NULL;
    }

    size_t total_memory = 0;
    for (int i = 0; i < num_images; i++) {
        json_object *obj = json_array_get_idx(root, i);
        if (!json_is_object(obj)) continue;

        int width = -1, height = -1;
        const char *data = NULL;
        size_t data_size = 0;

        if (json_object_object_get_ex(obj, "width", &jso) && json_is_integer(jso))
            width = json_integer_value(jso);
        if (json_object_object_get_ex(obj, "height", &jso) && json_is_integer(jso))
            height = json_integer_value(jso);
        if (json_object_object_get_ex(obj, "data", &jso) && json_is_string(jso))
            data = json_string_value(jso), data_size = strlen(data);

        if (width <= 0 || width > MAX_PIXELS ||
            height <= 0 || height > MAX_PIXELS ||
            data_size != width * height) {
            free(images);
            json_object_put(root);
            return NULL;
        }

        size_t image_memory = sizeof(Image) + width * height * sizeof(unsigned char);
        if (total_memory + image_memory > max_memory) {
            free(images);
            json_object_put(root);
            return NULL;
        }

        images[i].width = width;
        images[i].height = height;
        images[i].data = malloc(width * height * sizeof(unsigned char));
        memcpy(images[i].data, data, data_size);

        total_memory += image_memory;
    }

    json_object_put(root);
    return images;
}
