ImageData* process_image_directory(const char* directory_path, int max_frames_per_file) {
    DIR* dir;
    struct dirent* entry;
    ImageData* image_data = NULL;
    size_t total_memory_required = 0;

    if ((dir = opendir(directory_path)) == NULL) {
        fprintf(stderr, "Error opening directory: %s\n", directory_path);
        return NULL;
    }

    image_data = (ImageData*)malloc(sizeof(ImageData));
    if (!image_data) {
        perror("Failed to allocate memory for ImageData");
        closedir(dir);
        return NULL;
    }
    image_data->frame_sizes = NULL;
    image_data->num_frames = 0;

    while ((entry = readdir(dir)) != NULL) {
        char file_path[MAX_FILENAME_LENGTH];
        snprintf(file_path, sizeof(file_path), "%s/%s", directory_path, entry->d_name);

