        if (num_frames_in_file <= 0) {
            fprintf(stderr, "Failed to read frame count from file: %s\n", file_path);
            free_image_data(image_data);
            closedir(dir);
            return NULL;
        }

        if (num_frames_in_file > max_frames_per_file) {
            num_frames_in_file = max_frames_per_file;
        }

        total_memory_required += sizeof(int) * num_frames_in_file;
        if ((total_memory_required / 1024) >= sysconf(_SC_PHYS_PAGES)) {
            fprintf(stderr, "Memory allocation would exceed system limits.\n");
            free_image_data(image_data);
            closedir(dir);
            return NULL;
        }

        image_data->num_frames += num_frames_in_file;

        // Simulate memory allocation for frame sizes
        int* new_frame_sizes = realloc(image_data->frame_sizes, sizeof(int) * image_data->num_frames);
        if (!new_frame_sizes) {
            perror("Failed to reallocate memory for frame sizes");
            free_image_data(image_data);
            closedir(dir);
            return NULL;
        }
        image_data->frame_sizes = new_frame_sizes;

        // Simulate reading and storing frame sizes
        for (int i = 0; i < num_frames_in_file; ++i) {
            int frame_size = read_frame_size(file_path, i);
            if (frame_size <= 0) {
                fprintf(stderr, "Failed to read frame size from file: %s\n", file_path);
                free_image_data(image_data);
                closedir(dir);
                return NULL;
            }
            image_data->frame_sizes[image_data->num_frames - 1 - i] = frame_size;
        }
    }

    closedir(dir);
    return image_data;
}

void free_image_data(ImageData* image_data) {
    if (image_data->frame_sizes) {
        free(image_data->frame_sizes);
    }
    free(image_data);
}
