#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2
#define MIN_LOG_LEVEL 1
#define MAX_LOG_LEVEL 3

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_length;
} PacketMetadata;

typedef struct {
    PacketMetadata *metadata;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    int log_level;
} PacketProcessor;

void init_packet_processor(PacketProcessor *pp, int initial_capacity, int log_level) {
    pp->metadata = (PacketMetadata *)malloc(initial_capacity * sizeof(PacketMetadata));
    if (!pp->metadata) {
        fprintf(stderr, "Failed to allocate memory for packet metadata.\n");
        exit(EXIT_FAILURE);
    }
    pp->capacity = initial_capacity;
    pp->count = 0;
    pthread_mutex_init(&pp->mutex, NULL);
    pp->log_level = log_level;
}

void free_packet_processor(PacketProcessor *pp) {
    free(pp->metadata);
    pthread_mutex_destroy(&pp->mutex);
}

int resize_metadata_array(PacketProcessor *pp) {
    size_t new_capacity = pp->capacity * GROWTH_FACTOR;
    PacketMetadata *new_metadata = (PacketMetadata *)realloc(pp->metadata, new_capacity * sizeof(PacketMetadata));
    if (!new_metadata) {
        fprintf(stderr, "Failed to reallocate memory for packet metadata.\n");
        return -1;
    }
    pp->metadata = new_metadata;
    pp->capacity = new_capacity;
    return 0;
}

int add_packet(PacketProcessor *pp, int id, time_t timestamp, size_t payload_length) {
    pthread_mutex_lock(&pp->mutex);
    if (pp->count >= pp->capacity) {
        if (resize_metadata_array(pp) == -1) {
            pthread_mutex_unlock(&pp->mutex);
            return -1;
        }
    }
    pp->metadata[pp->count].id = id;
    pp->metadata[pp->count].timestamp = timestamp;
    pp->metadata[pp->count].payload_length = payload_length;
    ++pp->count;
    pthread_mutex_unlock(&pp->mutex);
    return 0;
}

void log_message(PacketProcessor *pp, int level, const char *message) {
    if (level >= pp->log_level) {
        printf("%s\n", message);
    }
}

int main() {
    PacketProcessor processor;
    init_packet_processor(&processor, INITIAL_CAPACITY, MIN_LOG_LEVEL);

    // Simulate adding packets
    for (int i = 0; i < 15000; ++i) {
        add_packet(&processor, i, time(NULL), rand() % 1024);
    }

    free_packet_processor(&processor);
    return 0;
}
```

