int process_image_directory(const char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (!dir) {
        perror("Failed to open directory");
        return -1;
    }

    int total_frames = 0;
    int current_capacity = INITIAL_CAPACITY;
    int *frames_per_file = (int *)malloc(current_capacity * sizeof(int));
    if (!frames_per_file) {
        perror("Failed to allocate memory for frames per file");
        closedir(dir);
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strlen(entry->d_name) < MAX_FILE_NAME) {
            char file_path[MAX_FILE_NAME + 1];
            snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);

            // Simulate reading the header to determine the number of frames
            int frames = read_header_for_frames(file_path);
            if (frames == -1) {
                printf("Failed to read header for file: %s\n", file_path);
                continue;
            }

            total_frames += frames;

            if (total_frames > current_capacity * 2) {
                // Resize the array if needed
                int new_capacity = current_capacity * 2;
                int *new_frames_per_file = (int *)realloc(frames_per_file, new_capacity * sizeof(int));
                if (!new_frames_per_file) {
                    perror("Failed to reallocate memory for frames per file");
                    free(frames_per_file);
                    closedir(dir);
                    return -1;
                }
                frames_per_file = new_frames_per_file;
                current_capacity = new_capacity;
            }

            frames_per_file[total_frames / 2] = frames; // Store the frame count
        }
    }

    closedir(dir);
    free(frames_per_file);

    printf("Total frames: %d\n", total_frames);
    return total_frames;
}

int read_header_for_frames(const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    // Simulate reading the header
    int frames;
    if (fread(&frames, sizeof(int), 1, file) != 1) {
        printf("Failed to read frame count from file: %s\n", file_path);
        fclose(file);
        return -1;
    }

    fclose(file);
    return frames;
}

int main() {
    const char *directory = "path_to_image_directory";
    process_image_directory(directory);
    return 0;
}
