        } else {
            int parsed_rnti = json_object_get_int(json_num_structures);
            if (parsed_rnti < 1 || parsed_rnti > MAX_RNTI) {
                fprintf(stderr, "Invalid RNTI value in JSON\n");
                free(pdus);
                json_object_put(parsed_json);
