#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int num_structures) {
    if (num_structures <= 0 || num_structures > MAX_STRUCTURES) {
        fprintf(stderr, "Invalid number of structures: %d\n", num_structures);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current_ptr = &head;

    for (int i = 0; i < num_structures; i++) {
        pthread_mutex_lock(&list_mutex);

        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for structure %d\n", i + 1);
            pthread_mutex_unlock(&list_mutex);
            continue;
        }

        new_node->RX_UE_INFORMATION_TAG = rand() % 1000; // Random value
        new_node->RNTI = rand(); // Random value
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2; // Random value (0 or 1)
        new_node->next = NULL;

        *current_ptr = new_node;
        current_ptr = &new_node->next;

        pthread_mutex_unlock(&list_mutex);
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int num_structures;

    printf("Enter the number of structures to create: ");
    scanf("%d", &num_structures);

    NFAPI_CRC_INDICATION_PDU_T* head = create_linked_list(num_structures);

    if (head != NULL) {
        printf("Linked list created successfully with %d structures.\n", num_structures);
        free_linked_list(head);
    }

    return 0;
}
