void* createAndPopulateNfadbs(int N, int maxStructures, int memoryLimit, int batchSize, int timeWindow, FILE* logFile) {
    pthread_mutex_lock(&mutex);
    if (N > maxStructures) {
        fprintf(stderr, "Error: Requested structures exceed maximum allowed.\n");
        return NULL;
