        if (current_structures > 0) {
            --N;
        } else {
            fprintf(stderr, "Error: Memory constraints detected.\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    for (int i = 0; i < N; ++i) {
        structures[current_structures] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structures[current_structures]) {
