#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *structures[MAX_STRUCTURES];
    int count;
    pthread_mutex_t mutex;
} NFAPI_CRC_MANAGEMENT_CONTEXT_T;

NFAPI_CRC_MANAGEMENT_CONTEXT_T crc_context = {0};

void initialize_crc_context() {
    pthread_mutex_init(&crc_context.mutex, NULL);
}

void cleanup_crc_context() {
    pthread_mutex_lock(&crc_context.mutex);
    for (int i = 0; i < crc_context.count; i++) {
        free(crc_context.structures[i]);
    }
    pthread_mutex_unlock(&crc_context.mutex);
    pthread_mutex_destroy(&crc_context.mutex);
}

int allocate_crc_structure(RX_UE_INFORMATION_TAG ue_info, uint16_t rnti) {
    pthread_mutex_lock(&crc_context.mutex);
    if (crc_context.count >= MAX_STRUCTURES) {
        log_error("Out of memory: Maximum structures reached.");
        pthread_mutex_unlock(&crc_context.mutex);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        log_error("Memory allocation failed.");
        pthread_mutex_unlock(&crc_context.mutex);
        return -2;
    }

    new_struct->ue_info = ue_info;
    new_struct->rnti = rnti;
    new_struct->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    crc_context.structures[crc_context.count++] = new_struct;
    pthread_mutex_unlock(&crc_context.mutex);

    log_debug("Allocated structure, total: %d", crc_context.count);
    return crc_context.count - 1;
}

void free_crc_structure(int index) {
    if (index < 0 || index >= crc_context.count) {
        log_error("Invalid structure index.");
        return;
    }

    pthread_mutex_lock(&crc_context.mutex);
    NFAPI_CRC_INDICATION_PDU_T *to_free = crc_context.structures[index];
    memmove(crc_context.structures + index, crc_context.structures + index + 1, (crc_context.count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    crc_context.count--;

    free(to_free);
    pthread_mutex_unlock(&crc_context.mutex);

    log_debug("Freed structure, remaining: %d", crc_context.count);
}
