typedef struct MemoryPoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct MemoryPoolNode* next;
} MemoryPoolNode;

MemoryPoolNode* poolHead = NULL;
pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;
int totalStructuresCreated = 0;

void logMessage(int level, const char* message) {
    if (level == 1) printf("INFO: %s\n", message);
    else if (level == 2) printf("WARNING: %s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* allocateStructure() {
    NFAPI_CRC_INDICATION_PDU_T* newStruct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newStruct) {
        logMessage(1, "Failed to allocate memory for new structure.");
        return NULL;
    }

    pthread_mutex_lock(&poolMutex);
    MemoryPoolNode* newNode = (MemoryPoolNode*)malloc(sizeof(MemoryPoolNode));
    if (!newNode) {
        logMessage(2, "Failed to allocate memory for pool node.");
        free(newStruct);
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    newNode->data = *newStruct;
    newNode->next = poolHead;
    poolHead = newNode;
    totalStructuresCreated++;
    pthread_mutex_unlock(&poolMutex);

    return newStruct;
}

void* allocateFromPool() {
    pthread_mutex_lock(&poolMutex);
    if (!poolHead) {
        logMessage(2, "Memory pool is empty.");
        pthread_mutex_unlock(&poolMutex);
        return NULL;
    }

    MemoryPoolNode* node = poolHead;
    NFAPI_CRC_INDICATION_PDU_T* data = &node->data;
    poolHead = node->next;
    free(node);
    pthread_mutex_unlock(&poolMutex);

    return data;
}

void evictOldStructures(int targetSize) {
    while (totalStructuresCreated > targetSize) {
        NFAPI_CRC_INDICATION_PDU_T* oldStruct = allocateFromPool();
        if (!oldStruct) break;

        // Free or reuse the old structure
        free(oldStruct);
    }
}

int main() {
    srand(time(NULL));

    for (int i = 0; i < MAX_POOL_SIZE + 10; i++) {
        NFAPI_CRC_INDICATION_PDU_T* newStruct = allocateStructure();
        if (!newStruct) break;

        // Simulate setting random values
        newStruct->RX_UE_INFORMATION_TAG = rand() % 1000;
        newStruct->RNTI = rand() % 65535;
        newStruct->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0;

        // Simulate processing
        printf("Processed structure with RNTI: %d\n", newStruct->RNTI);
    }

    evictOldStructures(MAX_POOL_SIZE - 50);

    logMessage(1, "Total structures created: %d\n", totalStructuresCreated);

    return 0;
}
