#include <pthread.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t current_memory_usage;
    pthread_mutex_t lock;
} LinkedList;

void initialize_list(LinkedList* list) {
    list->head = NULL;
    list->current_memory_usage = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data, size_t new_data_size) {
    if (pthread_mutex_lock(&list->lock) != 0) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    *new_node = (Node){data, NULL};
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (list->current_memory_usage + new_data_size > MAX_MEMORY_LIMIT) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->current_memory_usage += new_data_size;

    new_node->next = list->head;
    list->head = new_node;

    if (pthread_mutex_unlock(&list->lock) != 0) return -1;

    return 0;
}

void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
