#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_FILES 1000
#define MAX_RECORDS_PER_FILE 10000

typedef struct {
    char timestamp[20];
    char level[10];
    char message[256];
} LogEntry;

LogEntry** process_log_files(const char* file_paths[], int num_files, int* total_entries) {
    LogEntry **entries = (LogEntry**)malloc(num_files * sizeof(LogEntry*));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *total_entries = 0;
    for (int i = 0; i < num_files; i++) {
        FILE *file = fopen(file_paths[i], "r");
        if (!file) {
            fprintf(stderr, "Failed to open file %s\n", file_paths[i]);
            continue;
        }

        entries[i] = (LogEntry*)malloc(MAX_RECORDS_PER_FILE * sizeof(LogEntry));
        if (!entries[i]) {
            fprintf(stderr, "Memory allocation failed for file %s\n", file_paths[i]);
            fclose(file);
            continue;
        }

        char line[256];
        while (fgets(line, sizeof(line), file)) {
            LogEntry *entry = &entries[i][(*total_entries)++];
            sscanf(line, "%19[^ ] %9[^ ] %[^\n]", entry->timestamp, entry->level, entry->message);
        }

        fclose(file);
    }

    return entries;
}

int main() {
    const char* file_paths[MAX_LOG_FILES] = { "file1.log", "file2.log" };
    int num_files = 2;
    int total_entries;

    LogEntry** log_entries = process_log_files(file_paths, num_files, &total_entries);

    for (int i = 0; i < num_files; i++) {
        for (int j = 0; j < total_entries; j++) {
            printf("Timestamp: %s, Level: %s, Message: %s\n", log_entries[i][j].timestamp, log_entries[i][j].level, log_entries[i][j].message);
        }
        free(log_entries[i]);
    }
    free(log_entries);

    return 0;
}
