#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_FILES 1024
#define MAX_PATH_LENGTH 256

typedef struct {
    char fileName[MAX_PATH_LENGTH];
    size_t fileSize;
    time_t lastModTime;
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
} FileMetadata;

void* processFile(void* arg) {
    char* filePath = (char*)arg;
    FileMetadata metadata;
    struct stat fileStat;

    if (stat(filePath, &fileStat) == 0) {
        strncpy(metadata.fileName, filePath, MAX_PATH_LENGTH);
        metadata.fileSize = fileStat.st_size;
        metadata.lastModTime = fileStat.st_mtime;

        srand(time(NULL));
        metadata.RX_UE_INFORMATION_TAG = rand();
        metadata.RNTI = (unsigned short)rand();
        metadata.CRC_INDICATION_REL8_TAG = (unsigned char)(rand() % 2);

        // Simulate metadata processing
        printf("Processed file: %s\n", filePath);
    } else {
        fprintf(stderr, "Failed to access file: %s\n", filePath);
    }

    return &metadata;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    pthread_t threads[MAX_FILES];
    FileMetadata* metadataArray[MAX_FILES];

    for (int i = 1; i < argc && i < MAX_FILES; ++i) {
        if (pthread_create(&threads[i - 1], NULL, processFile, argv[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file: %s\n", argv[i]);
            return 1;
        }
    }

    for (int i = 0; i < argc - 1 && i < MAX_FILES; ++i) {
        if (pthread_join(threads[i], (void**)&metadataArray[i]) != 0) {
            fprintf(stderr, "Failed to join thread for file: %s\n", argv[i]);
            return 1;
        }
    }

    // Output metadata
    for (int i = 0; i < argc - 1 && i < MAX_FILES; ++i) {
        printf("File Name: %s\n", metadataArray[i]->fileName);
        printf("File Size: %zu bytes\n", metadataArray[i]->fileSize);
        printf("Last Mod Time: %ld\n", metadataArray[i]->lastModTime);
        printf("RX_UE_INFORMATION_TAG: 0x%08X\n", metadataArray[i]->RX_UE_INFORMATION_TAG);
        printf("RNTI: 0x%04X\n", metadataArray[i]->RNTI);
        printf("CRC_INDICATION_REL8_TAG: 0x%02X\n", metadataArray[i]->CRC_INDICATION_REL8_TAG);
    }

    return 0;
}
```

