#define MAX_PAYLOAD_SIZE 4096

typedef struct NetworkPacket {
    int header_size;
    char payload[MAX_PAYLOAD_SIZE];
} NetworkPacket;

NetworkPacket* process_packet(int header_size, const char* payload) {
    if (header_size > sizeof(NetworkPacket).payload) {
        printf("Error: Payload size exceeds maximum allowed.\n");
        return NULL;
    }

    NetworkPacket* packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!packet) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    packet->header_size = header_size;
    strncpy(packet->payload, payload, header_size);
    packet->payload[header_size] = '\0'; // Null-terminate the payload

    return packet;
}

void free_packet(NetworkPacket* packet) {
    if (packet) {
        free(packet);
    }
}

int main() {
    const char* payload_data = "Example Payload Data";
    int header_size = strlen(payload_data);

    NetworkPacket* packet = process_packet(header_size, payload_data);
    if (packet) {
        printf("Processed Packet - Header Size: %d, Payload: %s\n", packet->header_size, packet->payload);
        free_packet(packet);
    }

    return 0;
}
```

