#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_N 10000

typedef struct {
    // Define the structure members as per NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPoolManager;

MemoryPoolManager* create_memory_pool(size_t initial_capacity) {
    MemoryPoolManager *manager = (MemoryPoolManager*)malloc(sizeof(MemoryPoolManager));
    if (!manager) return NULL;

    manager->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pool) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int allocate_from_pool(MemoryPoolManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        // Handle pool full scenario
        pthread_mutex_unlock(&manager->lock);
        return -1; // Return error code for pool full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_element = &manager->pool[manager->count];
    new_element->RX_UE_INFORMATION_TAG = generate_tag(); // Implement generate_tag()
    new_element->RNTI = get_random_rnti(); // Implement get_random_rnti()
    new_element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return (int)(new_element - manager->pool); // Return index of allocated element
}

void free_memory_pool(MemoryPoolManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->pool);
        free(manager);
    }
}
