typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t capacity;
    size_t size;
    size_t memory_limit;
} DynamicList;

DynamicList* init_list(size_t initial_capacity, size_t memory_limit) {
    // Allocate memory for the list structure
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    // Initialize the list with the provided parameters
    list->capacity = initial_capacity;
    list->size = 0;
    list->memory_limit = memory_limit;

    // Allocate memory for the initial capacity of the list elements
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }

    return list;
}

void resize_list(DynamicList* list, size_t new_capacity) {
    // Allocate memory for the new capacity of the list elements
    NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_list) return;

    // Update the list with the new capacity
    list->list = new_list;
    list->capacity = new_capacity;
}

void add_element(DynamicList* list) {
    // Check if resizing is needed
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > list->memory_limit) return;

        resize_list(list, new_capacity);
    }

    // Initialize the new element with random values
    NFAPI_CRC_INDICATION_PDU_T* new_element = &list->list[list->size];
    new_element->RX_UE_INFORMATION_TAG = rand();
    new_element->RNTI = rand();
    new_element->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

    list->size++;
}

void free_list(DynamicList* list) {
    // Free the allocated memory
    if (list->list) free(list->list);
    if (list) free(list);
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Create a dynamic list with an initial capacity and memory limit
    DynamicList* my_list = init_list(10, 1024 * 1024); // 1MB memory limit
    if (!my_list) return -1;

    // Add elements to the list
    for (size_t i = 0; i < 100; i++) {
        add_element(my_list);
    }

    // Free the list when done
    free_list(my_list);

    return 0;
}
